package com.kingodogo.buildscape.api;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.api.model.CosmeticData;
import net.minecraft.client.Minecraft;

import java.util.concurrent.CompletableFuture;

/**
 * Manages one-time authentication at game launch for cosmetic data.
 * Authentication happens once when the game starts, and the data is cached
 * for the entire game session.
 */
public class CosmeticAuthManager {
    private static final CosmeticAuthManager INSTANCE = new CosmeticAuthManager();

    private volatile boolean authenticated = false;
    private volatile CosmeticData cachedCosmetics = null;
    private volatile long authTimestamp = 0;
    private volatile boolean authenticationInProgress = false;

    private CosmeticAuthManager() {
    }

    public static CosmeticAuthManager getInstance() {
        return INSTANCE;
    }

    /**
     * Authenticate once at game launch and cache the cosmetic data.
     * This method is thread-safe and ensures authentication only happens once.
     *
     * @return CompletableFuture with CosmeticData, or null if authentication fails
     */
    public CompletableFuture<CosmeticData> authenticateOnLaunch() {
        // Return cached data if already authenticated
        if (authenticated && cachedCosmetics != null) {
            BuildScape.getLogger().debug("CosmeticAuthManager: Returning cached cosmetic data");
            return CompletableFuture.completedFuture(cachedCosmetics);
        }

        // Prevent concurrent authentication attempts
        if (authenticationInProgress) {
            BuildScape.getLogger().debug("CosmeticAuthManager: Authentication already in progress, waiting...");
            return waitForAuthentication();
        }

        synchronized (this) {
            // Double-check after acquiring lock
            if (authenticated && cachedCosmetics != null) {
                return CompletableFuture.completedFuture(cachedCosmetics);
            }

            if (authenticationInProgress) {
                return waitForAuthentication();
            }

            authenticationInProgress = true;

            // Get UUID and access token from Minecraft
            Minecraft mc = Minecraft.getInstance();
            if (mc.getUser() == null) {
                BuildScape.getLogger().warn("CosmeticAuthManager: No user available, cannot authenticate");
                authenticationInProgress = false;
                return CompletableFuture.completedFuture(null);
            }

            String uuid = mc.getUser().getUuid();
            String accessToken = mc.getUser().getAccessToken();

            if (uuid == null || uuid.isEmpty()) {
                BuildScape.getLogger().warn("CosmeticAuthManager: UUID is null or empty");
                authenticationInProgress = false;
                return CompletableFuture.completedFuture(null);
            }

            if (accessToken == null || accessToken.isEmpty()) {
                BuildScape.getLogger().warn("CosmeticAuthManager: Access token is null or empty");
                authenticationInProgress = false;
                return CompletableFuture.completedFuture(null);
            }

            BuildScape.getLogger().info("CosmeticAuthManager: Starting authentication for UUID: " + uuid);

            // Call the secure API
            return SupportersApiClient.getInstance()
                    .authenticate(uuid, accessToken)
                    .thenApply(response -> {
                        if (response == null) {
                            BuildScape.getLogger().error("CosmeticAuthManager: Authentication returned null");
                            return null;
                        }

                        if (response.isError()) {
                            BuildScape.getLogger().error("CosmeticAuthManager: Authentication failed - " +
                                    response.getCode() + ": " + response.getError());
                            return null;
                        }

                        // Convert response to CosmeticData
                        CosmeticData cosmeticData = response.toCosmeticData();

                        // Cache the result
                        this.cachedCosmetics = cosmeticData;
                        this.authenticated = true;
                        this.authTimestamp = System.currentTimeMillis();

                        BuildScape.getLogger().info("CosmeticAuthManager: Authentication successful, " +
                                "unlocked " + (cosmeticData.getUnlocked() != null ? cosmeticData.getUnlocked().size() : 0) + " cosmetics");

                        return cosmeticData;
                    })
                    .exceptionally(throwable -> {
                        BuildScape.getLogger().error("CosmeticAuthManager: Authentication failed with exception", throwable);
                        return null;
                    })
                    .whenComplete((result, throwable) -> {
                        authenticationInProgress = false;
                    });
        }
    }

    /**
     * Wait for an ongoing authentication to complete.
     */
    private CompletableFuture<CosmeticData> waitForAuthentication() {
        return CompletableFuture.supplyAsync(() -> {
            int attempts = 0;
            while (authenticationInProgress && attempts < 100) {
                try {
                    Thread.sleep(100);
                    attempts++;
                } catch (InterruptedException e) {
                    Thread.currentThread().interrupt();
                    return null;
                }
            }
            return cachedCosmetics;
        });
    }

    /**
     * Check if authentication has been completed successfully.
     */
    public boolean isAuthenticated() {
        return authenticated;
    }

    /**
     * Get the cached cosmetic data.
     * Returns null if authentication hasn't completed yet.
     */
    public CosmeticData getCachedCosmetics() {
        return cachedCosmetics;
    }

    /**
     * Get the timestamp of successful authentication.
     */
    public long getAuthTimestamp() {
        return authTimestamp;
    }

    /**
     * Clear the authentication cache.
     * This should only be called when the game is shutting down.
     */
    public void clearCache() {
        synchronized (this) {
            this.authenticated = false;
            this.cachedCosmetics = null;
            this.authTimestamp = 0;
            this.authenticationInProgress = false;
        }
    }

    /**
     * Force re-authentication on next call to authenticateOnLaunch().
     * Use with caution - this will trigger a new API call.
     */
    public void forceReauthentication() {
        synchronized (this) {
            this.authenticated = false;
            this.cachedCosmetics = null;
            this.authTimestamp = 0;
        }
    }
}

package com.kingodogo.buildscape.api.model;

public class ApiResponse {
    private boolean success;
    private String message;
    private String error;
    
    public ApiResponse() {
    }
    
    public ApiResponse(boolean success, String message) {
        this.success = success;
        this.message = message;
    }
    
    public boolean isSuccess() {
        return success;
    }
    
    public void setSuccess(boolean success) {
        this.success = success;
    }
    
    public String getMessage() {
        return message;
    }
    
    public void setMessage(String message) {
        this.message = message;
    }
    
    public String getError() {
        return error;
    }
    
    public void setError(String error) {
        this.error = error;
    }
}

package com.kingodogo.buildscape.api.model;

/**
 * Request body for the secure authenticate endpoint.
 * POST /api/minecraft
 */
public class AuthenticateRequest {
    private String action;
    private String uuid;
    private String accessToken;

    public AuthenticateRequest() {
    }

    public AuthenticateRequest(String action, String uuid, String accessToken) {
        this.action = action;
        this.uuid = uuid;
        this.accessToken = accessToken;
    }

    public String getAction() {
        return action;
    }

    public void setAction(String action) {
        this.action = action;
    }

    public String getUuid() {
        return uuid;
    }

    public void setUuid(String uuid) {
        this.uuid = uuid;
    }

    public String getAccessToken() {
        return accessToken;
    }

    public void setAccessToken(String accessToken) {
        this.accessToken = accessToken;
    }

    /**
     * Create a standard authenticate request.
     */
    public static AuthenticateRequest createAuthenticate(String uuid, String accessToken) {
        return new AuthenticateRequest("authenticate", uuid, accessToken);
    }
}

package com.kingodogo.buildscape.api.model;

import java.util.List;
import java.util.Map;

/**
 * Response from the secure authenticate endpoint.
 * POST /api/minecraft
 */
public class AuthenticateResponse {
    private List<String> defaultCosmetics;
    private List<String> unlockedCosmetics;
    private Map<String, String> selectedCosmetics;

    // Error fields (when authentication fails)
    private String error;
    private String code;

    public AuthenticateResponse() {
    }

    public List<String> getDefaultCosmetics() {
        return defaultCosmetics;
    }

    public void setDefaultCosmetics(List<String> defaultCosmetics) {
        this.defaultCosmetics = defaultCosmetics;
    }

    public List<String> getUnlockedCosmetics() {
        return unlockedCosmetics;
    }

    public void setUnlockedCosmetics(List<String> unlockedCosmetics) {
        this.unlockedCosmetics = unlockedCosmetics;
    }

    public Map<String, String> getSelectedCosmetics() {
        return selectedCosmetics;
    }

    public void setSelectedCosmetics(Map<String, String> selectedCosmetics) {
        this.selectedCosmetics = selectedCosmetics;
    }

    public String getError() {
        return error;
    }

    public void setError(String error) {
        this.error = error;
    }

    public String getCode() {
        return code;
    }

    public void setCode(String code) {
        this.code = code;
    }

    /**
     * Check if the response indicates an error.
     */
    public boolean isError() {
        return error != null && !error.isEmpty();
    }

    /**
     * Convert this response to CosmeticData format.
     */
    public CosmeticData toCosmeticData() {
        CosmeticData data = new CosmeticData();
        data.setDefaultCosmetics(this.defaultCosmetics);
        data.setUnlockedCosmetics(this.unlockedCosmetics);
        data.setSelectedCosmetics(this.selectedCosmetics);
        data.adaptFromSecureResponse();
        return data;
    }
}

package com.kingodogo.buildscape.api.model;

import java.util.List;
import java.util.Map;

/**
 * Response model for cosmetics API endpoint.
 * Supports both legacy format (GET /api/v1/supporters/cosmetics/{uuid})
 * and secure format (POST /api/minecraft with authentication).
 *
 * Arrays contain cosmetic IDs in format:
 * - "item:namespace:item_id" (e.g., "item:minecraft:diamond_sword")
 * - "block:namespace:block_id" (e.g., "block:minecraft:gold_block")
 * - "nbt:custom_data" - NBT-based cosmetic
 * - "type:armor_set_1" - Type-based cosmetic
 */
public class CosmeticData {
    // Legacy fields (backward compatibility)
    private List<String> unlocked;
    private List<String> locked;
    private List<String> equipped;

    // New secure API fields
    private List<String> defaultCosmetics;
    private List<String> unlockedCosmetics;
    private Map<String, String> selectedCosmetics;

    public CosmeticData() {
    }

    public CosmeticData(List<String> unlocked, List<String> locked, List<String> equipped) {
        this.unlocked = unlocked;
        this.locked = locked;
        this.equipped = equipped;
    }

    // Legacy getters/setters
    public List<String> getUnlocked() {
        return unlocked;
    }

    public void setUnlocked(List<String> unlocked) {
        this.unlocked = unlocked;
    }

    public List<String> getLocked() {
        return locked;
    }

    public void setLocked(List<String> locked) {
        this.locked = locked;
    }

    public List<String> getEquipped() {
        return equipped;
    }

    public void setEquipped(List<String> equipped) {
        this.equipped = equipped;
    }

    // New secure API getters/setters
    public List<String> getDefaultCosmetics() {
        return defaultCosmetics;
    }

    public void setDefaultCosmetics(List<String> defaultCosmetics) {
        this.defaultCosmetics = defaultCosmetics;
    }

    public List<String> getUnlockedCosmetics() {
        return unlockedCosmetics;
    }

    public void setUnlockedCosmetics(List<String> unlockedCosmetics) {
        this.unlockedCosmetics = unlockedCosmetics;
    }

    public Map<String, String> getSelectedCosmetics() {
        return selectedCosmetics;
    }

    public void setSelectedCosmetics(Map<String, String> selectedCosmetics) {
        this.selectedCosmetics = selectedCosmetics;
    }

    /**
     * Adapter method to populate legacy fields from new secure API response.
     * Call this after receiving data from the new API.
     */
    public void adaptFromSecureResponse() {
        // Populate unlocked from unlockedCosmetics (combines defaults + unlocked)
        if (this.unlockedCosmetics != null) {
            this.unlocked = this.unlockedCosmetics;
        }

        // Populate equipped from selectedCosmetics values
        if (this.selectedCosmetics != null && !this.selectedCosmetics.isEmpty()) {
            this.equipped = this.selectedCosmetics.values()
                    .stream()
                    .filter(id -> id != null && !id.isEmpty())
                    .toList();
        }

        // locked is not provided by new API, leave as null/empty
        this.locked = List.of();
    }

    /**
     * Check if this data came from the secure API (new format).
     */
    public boolean isSecureFormat() {
        return this.unlockedCosmetics != null || this.selectedCosmetics != null;
    }
}

