import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

public class CloverBlock extends BushBlock implements BonemealableBlock {

    public static final IntegerProperty FLOWER_AMOUNT = IntegerProperty.create(
            "flower_amount",
            1,
            4
    );
    public static final DirectionProperty FACING =
            BlockStateProperties.HORIZONTAL_FACING;

    private static SoundType cachedSoundType = null;

    private static SoundType getFlowerBedSounds() {
        if (cachedSoundType == null) {
            cachedSoundType =
                    com.kingodogo.buildscape.sound.ModSounds.FLOWER_BED_SOUNDS();
        }
        return cachedSoundType;
    }

    private static final VoxelShape SHAPE_1_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            8.0D,
            3.0D,
            8.0D
    );
    private static final VoxelShape SHAPE_2_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            8.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_3_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    private static final VoxelShape COLLISION_SHAPE = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    private static final VoxelShape SHAPE_1_NORTH = Block.box(
            8.0D,
            0.0D,
            8.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_2_NORTH = Block.box(
            8.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_3_NORTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_NORTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    private static final VoxelShape SHAPE_1_EAST = Block.box(
            0.0D,
            0.0D,
            8.0D,
            8.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_2_EAST = Block.box(
            0.0D,
            0.0D,
            8.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_3_EAST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_EAST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    private static final VoxelShape SHAPE_1_WEST = Block.box(
            8.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            8.0D
    );
    private static final VoxelShape SHAPE_2_WEST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            8.0D
    );
    private static final VoxelShape SHAPE_3_WEST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_WEST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    public CloverBlock(BlockBehaviour.Properties properties) {
        super(properties);
        this.registerDefaultState(
                this.stateDefinition.any()
                        .setValue(FLOWER_AMOUNT, 1)
                        .setValue(FACING, Direction.SOUTH)
        );
    }

    @Override
    public SoundType getSoundType(BlockState state) {
        return getFlowerBedSounds();
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        builder.add(FLOWER_AMOUNT, FACING);
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        int stage = state.getValue(FLOWER_AMOUNT);
        Direction facing = state.getValue(FACING);

        return switch (facing) {
            case NORTH -> switch (stage) {
                case 1 -> SHAPE_1_NORTH;
                case 2 -> SHAPE_2_NORTH;
                case 3 -> SHAPE_3_NORTH;
                default -> SHAPE_4_NORTH;
            };
            case EAST -> switch (stage) {
                case 1 -> SHAPE_1_EAST;
                case 2 -> SHAPE_2_EAST;
                case 3 -> SHAPE_3_EAST;
                default -> SHAPE_4_EAST;
            };
            case WEST -> switch (stage) {
                case 1 -> SHAPE_1_WEST;
                case 2 -> SHAPE_2_WEST;
                case 3 -> SHAPE_3_WEST;
                default -> SHAPE_4_WEST;
            };
            default -> switch (stage) {
                case 1 -> SHAPE_1_SOUTH;
                case 2 -> SHAPE_2_SOUTH;
                case 3 -> SHAPE_3_SOUTH;
                default -> SHAPE_4_SOUTH;
            };
        };
    }

    @Override
    public VoxelShape getCollisionShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return Shapes.empty();
    }

    @Override
    public void entityInside(
            BlockState state,
            Level level,
            BlockPos pos,
            Entity entity
    ) {
        if (
                entity instanceof Player player &&
                        player.isOnGround() &&
                        level.isClientSide
        ) {
            float stepInterval = 2.0f;
            int currentStep = (int) (player.walkDist / stepInterval);
            int lastStep = (int) (player.walkDistO / stepInterval);

            if (currentStep != lastStep && player.walkDist > player.walkDistO) {
                SoundType sounds = getFlowerBedSounds();
                float volume = 0.25f;
                float pitch = 1.2f;
                if (sounds instanceof CustomSoundType customSounds) {
                    volume = customSounds.getStepVolume();
                    pitch = customSounds.getStepPitch();
                }

                level.playLocalSound(
                        pos.getX() + 0.5,
                        pos.getY() + 0.5,
                        pos.getZ() + 0.5,
                        sounds.getStepSound(),
                        SoundSource.BLOCKS,
                        volume,
                        pitch,
                        false
                );
            }
        }
        super.entityInside(state, level, pos, entity);
    }

    @Override
    protected boolean mayPlaceOn(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        return (
                state.isFaceSturdy(level, pos, Direction.UP) &&
                        state.getMaterial().isSolid() &&
                        !state.getMaterial().isReplaceable()
        );
    }

    @Override
    public boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        BlockPos belowPos = pos.below();
        BlockState belowState = level.getBlockState(belowPos);
        return this.mayPlaceOn(belowState, level, belowPos);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        BlockState state = super.getStateForPlacement(context);
        if (
                state != null &&
                        this.canSurvive(state, context.getLevel(), context.getClickedPos())
        ) {
            Direction playerFacing = context.getHorizontalDirection();
            return state.setValue(FLOWER_AMOUNT, 1).setValue(FACING, playerFacing);
        }
        return null;
    }

    @Override
    public BlockState rotate(BlockState state, Rotation rotation) {
        return state.setValue(FACING, rotation.rotate(state.getValue(FACING)));
    }

    @Override
    public BlockState mirror(BlockState state, Mirror mirror) {
        return state.rotate(mirror.getRotation(state.getValue(FACING)));
    }

    @Override
    public InteractionResult use(
            BlockState state,
            Level level,
            BlockPos pos,
            Player player,
            InteractionHand hand,
            BlockHitResult hit
    ) {
        ItemStack itemStack = player.getItemInHand(hand);

        if (
                itemStack.getItem() == com.kingodogo.buildscape.item.ModItems.CLOVER.get()
        ) {
            int currentAmount = state.getValue(FLOWER_AMOUNT);
            if (currentAmount < 4) {
                if (!level.isClientSide) {
                    level.setBlock(
                            pos,
                            state.setValue(FLOWER_AMOUNT, currentAmount + 1),
                            3
                    );
                    if (!player.getAbilities().instabuild) {
                        itemStack.shrink(1);
                    }
                }
                SoundType sounds = getFlowerBedSounds();
                level.playSound(
                        player,
                        pos,
                        sounds.getPlaceSound(),
                        SoundSource.BLOCKS,
                        sounds.getVolume(),
                        sounds.getPitch()
                );
                return InteractionResult.sidedSuccess(level.isClientSide);
            }
        }

        return InteractionResult.PASS;
    }

    @Override
    public boolean isValidBonemealTarget(
            BlockGetter level,
            BlockPos pos,
            BlockState state,
            boolean isClient
    ) {
        return true;
    }

    @Override
    public boolean isBonemealSuccess(
            Level level,
            Random random,
            BlockPos pos,
            BlockState state
    ) {
        return true;
    }

    @Override
    public void performBonemeal(
            ServerLevel level,
            Random random,
            BlockPos pos,
            BlockState state
    ) {
        int currentStage = state.getValue(FLOWER_AMOUNT);

        if (currentStage < 4) {
            level.setBlock(pos, state.setValue(FLOWER_AMOUNT, currentStage + 1), 3);
        } else {
            ItemStack cloverStack = new ItemStack(
                    com.kingodogo.buildscape.item.ModItems.CLOVER.get(),
                    1
            );
            ItemEntity itemEntity = new ItemEntity(
                    level,
                    pos.getX() + 0.5D,
                    pos.getY() + 0.5D,
                    pos.getZ() + 0.5D,
                    cloverStack
            );
            itemEntity.setDefaultPickUpDelay();
            level.addFreshEntity(itemEntity);
        }
    }

    @Override
    public List<ItemStack> getDrops(
            BlockState state,
            LootContext.Builder builder
    ) {
        int stage = state.getValue(FLOWER_AMOUNT);
        return Collections.singletonList(
                new ItemStack(com.kingodogo.buildscape.item.ModItems.CLOVER.get(), stage)
        );
    }
}

package com.kingodogo.buildscape.block;

import com.mojang.math.Vector3f;

import java.util.Random;

import net.minecraft.core.BlockPos;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.SporeBlossomBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;

public class ColoredSporeBlossomBlock
        extends net.minecraft.world.level.block.SporeBlossomBlock {

    private final Vector3f particleColor;
    private final int particleColorRGB;

    public ColoredSporeBlossomBlock(
            BlockBehaviour.Properties properties,
            Vector3f particleColor,
            int particleColorRGB
    ) {
        super(properties);
        this.particleColor = particleColor;
        this.particleColorRGB = particleColorRGB;
    }

    @Override
    public void animateTick(
            BlockState state,
            Level level,
            BlockPos pos,
            Random random
    ) {
        int i = pos.getX();
        int j = pos.getY();
        int k = pos.getZ();

        String colorHex = String.format("#%06x", particleColorRGB);

        if (level.isClientSide) {
            double centerX = (double) i + 0.5D;
            double centerY = (double) j + 0.5D;
            double centerZ = (double) k + 0.5D;

            if (random.nextFloat() < 0.50F) {
                int centerParticleCount = 1 + random.nextInt(3);
                for (int c = 0; c < centerParticleCount; c++) {
                    double offsetX = (random.nextDouble() - 0.5D) * 1.6D;
                    double offsetZ = (random.nextDouble() - 0.5D) * 1.6D;
                    double spawnX = centerX + offsetX;
                    double spawnZ = centerZ + offsetZ;

                    double driftX = (random.nextDouble() - 0.5D) * 0.02D;
                    double driftZ = (random.nextDouble() - 0.5D) * 0.02D;
                    double fallSpeed = -0.007D - random.nextDouble() * 0.006D;

                    if (level.isClientSide) {
                        com.kingodogo.buildscape.particle.TintedDripParticle.registerColorForPosition(
                                spawnX,
                                centerY,
                                spawnZ,
                                colorHex
                        );
                    }
                    level.addParticle(
                            com.kingodogo.buildscape.particle.ModParticles.TINTED_DRIP_FALL.get(),
                            spawnX,
                            centerY,
                            spawnZ,
                            driftX,
                            fallSpeed,
                            driftZ
                    );
                }
            }

            if (random.nextFloat() < 0.60F) {
                int spreadParticleCount = 10 + random.nextInt(25);
                for (int p = 0; p < spreadParticleCount; p++) {
                    double distance = 3.0D + random.nextDouble() * 16.0D;
                    double angle = random.nextDouble() * 2.0D * Math.PI;

                    double spreadX = centerX + Math.cos(angle) * distance;
                    double spreadZ = centerZ + Math.sin(angle) * distance;
                    double spreadY = centerY + (random.nextDouble() * 9.0D - 3.0D);

                    double velocityX = (random.nextDouble() - 0.5D) * 0.04D;
                    double velocityY = (random.nextDouble() - 0.125D) * 0.04D;
                    double velocityZ = (random.nextDouble() - 0.5D) * 0.04D;

                    if (level.isClientSide) {
                        com.kingodogo.buildscape.particle.TintedDripParticle.registerColorForPosition(
                                spreadX,
                                spreadY,
                                spreadZ,
                                colorHex
                        );
                    }
                    level.addParticle(
                            com.kingodogo.buildscape.particle.ModParticles.TINTED_DRIP_FALL.get(),
                            spreadX,
                            spreadY,
                            spreadZ,
                            velocityX,
                            velocityY,
                            velocityZ
                    );
                }
            }
        }
    }

    public int getParticleColorRGB() {
        return particleColorRGB;
    }

    public Vector3f getParticleColor() {
        return particleColor;
    }

    public static Vector3f hexToVector3f(String hex) {
        hex = hex.replace("#", "");

        int r = Integer.parseInt(hex.substring(0, 2), 16);
        int g = Integer.parseInt(hex.substring(2, 4), 16);
        int b = Integer.parseInt(hex.substring(4, 6), 16);

        return new Vector3f(r / 255.0f, g / 255.0f, b / 255.0f);
    }

    public static int hexToRGB(String hex) {
        hex = hex.replace("#", "");

        int r = Integer.parseInt(hex.substring(0, 2), 16);
        int g = Integer.parseInt(hex.substring(2, 4), 16);
        int b = Integer.parseInt(hex.substring(4, 6), 16);

        return (r << 16) | (g << 8) | b;
    }
}

package com.kingodogo.buildscape.block;

import com.kingodogo.buildscape.sound.ModSounds;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BooleanProperty;

public abstract class CopperBulbBlock extends Block {

    public static final BooleanProperty LIT = BooleanProperty.create("lit");
    public static final BooleanProperty POWERED = BooleanProperty.create(
            "powered"
    );
    private final int lightLevel;

    public CopperBulbBlock(Properties properties, int lightLevel) {
        super(properties);
        this.lightLevel = lightLevel;
        this.registerDefaultState(
                this.stateDefinition.any().setValue(LIT, false).setValue(POWERED, false)
        );
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        builder.add(LIT, POWERED);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        return this.defaultBlockState()
                .setValue(LIT, false)
                .setValue(POWERED, false);
    }

    @Override
    public int getLightEmission(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        return state.getValue(LIT) ? lightLevel : 0;
    }

    @Override
    public boolean isSignalSource(BlockState state) {
        return false;
    }

    @Override
    public int getSignal(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            Direction direction
    ) {
        return 0;
    }

    @Override
    public boolean canConnectRedstone(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            Direction direction
    ) {
        return false;
    }

    @Override
    public void neighborChanged(
            BlockState state,
            net.minecraft.world.level.Level level,
            BlockPos pos,
            Block block,
            BlockPos fromPos,
            boolean isMoving
    ) {
        if (!level.isClientSide) {
            boolean powered = level.hasNeighborSignal(pos);
            boolean wasPowered = state.getValue(POWERED);
            boolean currentlyLit = state.getValue(LIT);

            if (powered && !wasPowered) {
                BlockState newState = state
                        .setValue(LIT, !currentlyLit)
                        .setValue(POWERED, true);
                level.setBlock(pos, newState, 2);
                level.playSound(
                        null,
                        pos,
                        ModSounds.COPPER_BULB_TOGGLE.get(),
                        SoundSource.BLOCKS,
                        0.5f,
                        1.0f
                );
            } else if (!powered && wasPowered) {
                level.setBlock(pos, state.setValue(POWERED, false), 2);
            }
        }
    }

    @Override
    public void onPlace(
            BlockState state,
            net.minecraft.world.level.Level level,
            BlockPos pos,
            BlockState oldState,
            boolean isMoving
    ) {
        if (!level.isClientSide) {
            boolean powered = level.hasNeighborSignal(pos);
            level.setBlock(pos, state.setValue(POWERED, powered), 2);
        }
    }

    @Override
    public boolean hasAnalogOutputSignal(BlockState state) {
        return true;
    }

    @Override
    public int getAnalogOutputSignal(
            BlockState state,
            net.minecraft.world.level.Level level,
            BlockPos pos
    ) {
        return state.getValue(LIT) ? 15 : 0;
    }

    @Override
    public float getDestroyProgress(
            BlockState state,
            Player player,
            BlockGetter level,
            BlockPos pos
    ) {
        float destroySpeed = state.getDestroySpeed(level, pos);
        if (destroySpeed == -1.0F) {
            return 0.0F;
        }

        int efficiencyLevel =
                net.minecraft.world.item.enchantment.EnchantmentHelper.getBlockEfficiency(
                        player
                );
        ItemStack tool = player.getMainHandItem();

        float speedMultiplier = 1.0F;
        if (!tool.isEmpty()) {
            speedMultiplier = tool.getDestroySpeed(state);
        }

        if (speedMultiplier > 1.0F) {
            int efficiencyBonus = efficiencyLevel > 0
                    ? efficiencyLevel * efficiencyLevel + 1
                    : 0;
            speedMultiplier += (float) efficiencyBonus;
        }

        float difficultyModifier = player.hasCorrectToolForDrops(state)
                ? 30.0F
                : 100.0F;
        return speedMultiplier / destroySpeed / difficultyModifier;
    }
}

package com.kingodogo.buildscape.block;

import java.util.function.Supplier;

import net.minecraft.sounds.SoundEvent;
import net.minecraft.world.level.block.SoundType;
import net.minecraftforge.common.util.ForgeSoundType;

public class CustomSoundType extends ForgeSoundType {

    private final float breakVolume;
    private final float breakPitch;
    private final float stepVolume;
    private final float stepPitch;
    private final float placeVolume;
    private final float placePitch;
    private final float hitVolume;
    private final float hitPitch;
    private final float fallVolume;
    private final float fallPitch;

    public CustomSoundType(
            float breakVolume,
            float breakPitch,
            float stepVolume,
            float stepPitch,
            float placeVolume,
            float placePitch,
            float hitVolume,
            float hitPitch,
            float fallVolume,
            float fallPitch,
            Supplier<SoundEvent> breakSound,
            Supplier<SoundEvent> stepSound,
            Supplier<SoundEvent> placeSound,
            Supplier<SoundEvent> hitSound,
            Supplier<SoundEvent> fallSound
    ) {
        super(1.0f, 1.0f, breakSound, stepSound, placeSound, hitSound, fallSound);
        this.breakVolume = breakVolume;
        this.breakPitch = breakPitch;
        this.stepVolume = stepVolume;
        this.stepPitch = stepPitch;
        this.placeVolume = placeVolume;
        this.placePitch = placePitch;
        this.hitVolume = hitVolume;
        this.hitPitch = hitPitch;
        this.fallVolume = fallVolume;
        this.fallPitch = fallPitch;
    }

    @Override
    public float getVolume() {
        return breakVolume;
    }

    @Override
    public float getPitch() {
        return breakPitch;
    }

    public float getStepVolume() {
        return stepVolume;
    }

    public float getStepPitch() {
        return stepPitch;
    }

    public float getPlaceVolume() {
        return placeVolume;
    }

    public float getPlacePitch() {
        return placePitch;
    }

    public float getHitVolume() {
        return hitVolume;
    }

    public float getHitPitch() {
        return hitPitch;
    }

    public float getFallVolume() {
        return fallVolume;
    }

    public float getFallPitch() {
        return fallPitch;
    }
}

