import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.block.state.properties.DirectionProperty;
import net.minecraft.world.level.gameevent.GameEvent;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;

import java.util.List;

public class FestiveStockingBlock
        extends Block
        implements EntityBlock, SimpleWaterloggedBlock {

    public static final BooleanProperty WATERLOGGED =
            BlockStateProperties.WATERLOGGED;
    public static final DirectionProperty FACING = BlockStateProperties.FACING;
    public static final BooleanProperty FLIPPED = BooleanProperty.create(
            "flipped"
    );

    private static final VoxelShape SHAPE_NORTH = Block.box(
            0.0D,
            0.0D,
            15.0D,
            16.0D,
            16.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            16.0D,
            1.0D
    );
    private static final VoxelShape SHAPE_EAST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            1.0D,
            16.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_WEST = Block.box(
            15.0D,
            0.0D,
            0.0D,
            16.0D,
            16.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_UP = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            1.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_DOWN = Block.box(
            0.0D,
            15.0D,
            0.0D,
            16.0D,
            16.0D,
            16.0D
    );

    private final String colorVariant;

    public FestiveStockingBlock(
            BlockBehaviour.Properties properties,
            String color
    ) {
        super(properties);
        this.colorVariant = color;
        this.registerDefaultState(
                this.stateDefinition.any()
                        .setValue(FACING, Direction.NORTH)
                        .setValue(FLIPPED, false)
                        .setValue(WATERLOGGED, false)
        );
    }

    public String getColorVariant() {
        return colorVariant;
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        builder.add(FACING, FLIPPED, WATERLOGGED);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        FluidState fluidstate = context
                .getLevel()
                .getFluidState(context.getClickedPos());
        Direction clickedFace = context.getClickedFace();
        BlockPos attachPos = context
                .getClickedPos()
                .relative(clickedFace.getOpposite());
        if (canAttachTo(context.getLevel(), attachPos, clickedFace)) {
            return this.defaultBlockState()
                    .setValue(FACING, clickedFace)
                    .setValue(FLIPPED, false)
                    .setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
        }

        for (Direction direction : Direction.values()) {
            attachPos = context.getClickedPos().relative(direction.getOpposite());
            if (canAttachTo(context.getLevel(), attachPos, direction)) {
                return this.defaultBlockState()
                        .setValue(FACING, direction)
                        .setValue(FLIPPED, false)
                        .setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
            }
        }

        return this.defaultBlockState()
                .setValue(FACING, Direction.NORTH)
                .setValue(FLIPPED, false)
                .setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
    }

    @Override
    public boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        Direction facing = state.getValue(FACING);
        BlockPos attachPos = pos.relative(facing.getOpposite());
        return canAttachTo(level, attachPos, facing);
    }

    private boolean canAttachTo(
            LevelReader level,
            BlockPos pos,
            Direction direction
    ) {
        BlockState state = level.getBlockState(pos);
        return state.isFaceSturdy(level, pos, direction);
    }

    @Override
    public BlockState updateShape(
            BlockState state,
            Direction direction,
            BlockState neighborState,
            LevelAccessor level,
            BlockPos pos,
            BlockPos neighborPos
    ) {
        if (state.getValue(WATERLOGGED)) {
            level.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }

        Direction facing = state.getValue(FACING);
        if (direction == facing.getOpposite()) {
            if (!canSurvive(state, level, pos)) {
                return Blocks.AIR.defaultBlockState();
            }
        }
        return super.updateShape(
                state,
                direction,
                neighborState,
                level,
                pos,
                neighborPos
        );
    }

    @Override
    public FluidState getFluidState(BlockState state) {
        return state.getValue(WATERLOGGED)
                ? Fluids.WATER.getSource(false)
                : super.getFluidState(state);
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        Direction facing = state.getValue(FACING);
        switch (facing) {
            case NORTH:
                return SHAPE_NORTH;
            case SOUTH:
                return SHAPE_SOUTH;
            case EAST:
                return SHAPE_EAST;
            case WEST:
                return SHAPE_WEST;
            case UP:
                return SHAPE_UP;
            case DOWN:
                return SHAPE_DOWN;
            default:
                return SHAPE_NORTH;
        }
    }

    @Override
    public void neighborChanged(
            BlockState state,
            Level level,
            BlockPos pos,
            Block block,
            BlockPos fromPos,
            boolean isMoving
    ) {
        if (!canSurvive(state, level, pos)) {
            level.destroyBlock(pos, true);
        }
    }

    @Override
    public RenderShape getRenderShape(BlockState state) {
        return RenderShape.ENTITYBLOCK_ANIMATED;
    }

    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return new FestiveStockingBlockEntity(pos, state);
    }

    @Override
    public <
            T extends BlockEntity
            > net.minecraft.world.level.block.entity.BlockEntityTicker<T> getTicker(
            Level level,
            BlockState state,
            net.minecraft.world.level.block.entity.BlockEntityType<T> type
    ) {
        return null;
    }

    @Override
    public boolean hasAnalogOutputSignal(BlockState state) {
        return true;
    }

    @Override
    public int getAnalogOutputSignal(
            BlockState state,
            Level level,
            BlockPos pos
    ) {
        BlockEntity be = level.getBlockEntity(pos);
        if (be instanceof FestiveStockingBlockEntity) {
            FestiveStockingBlockEntity stockingEntity =
                    (FestiveStockingBlockEntity) be;
            return stockingEntity.getComparatorOutput();
        }
        return 0;
    }

    @Override
    public InteractionResult use(
            BlockState state,
            Level level,
            BlockPos pos,
            Player player,
            InteractionHand hand,
            BlockHitResult hit
    ) {
        BlockEntity be = level.getBlockEntity(pos);
        if (be instanceof FestiveStockingBlockEntity) {
            FestiveStockingBlockEntity stockingEntity =
                    (FestiveStockingBlockEntity) be;
            ItemStack heldItem = player.getItemInHand(hand);

            if (
                    heldItem.isEmpty() &&
                            !player.isShiftKeyDown() &&
                            !stockingEntity.isEmpty()
            ) {
                if (!level.isClientSide) {
                    ItemStack stored = stockingEntity.getStoredItem().copy();
                    stockingEntity.setStoredItem(ItemStack.EMPTY, true);

                    if (!player.getInventory().add(stored)) {
                        ItemEntity itemEntity = new ItemEntity(
                                level,
                                pos.getX() + 0.5,
                                pos.getY() + 0.5,
                                pos.getZ() + 0.5,
                                stored
                        );
                        itemEntity.setDefaultPickUpDelay();
                        level.addFreshEntity(itemEntity);
                    }
                    level.playSound(
                            null,
                            pos,
                            SoundEvents.ITEM_FRAME_REMOVE_ITEM,
                            SoundSource.BLOCKS,
                            0.5f,
                            1.0f
                    );
                    level.gameEvent(player, GameEvent.BLOCK_CHANGE, pos);
                }
                return InteractionResult.sidedSuccess(level.isClientSide);
            }

            if (heldItem.isEmpty() && player.isShiftKeyDown()) {
                if (!level.isClientSide) {
                    boolean currentFlipped = state.getValue(FLIPPED);
                    level.setBlock(pos, state.setValue(FLIPPED, !currentFlipped), 3);
                    level.playSound(
                            null,
                            pos,
                            SoundEvents.ITEM_FRAME_ROTATE_ITEM,
                            SoundSource.BLOCKS,
                            1.0f,
                            1.0f
                    );
                    level.gameEvent(player, GameEvent.BLOCK_CHANGE, pos);
                }
                return InteractionResult.sidedSuccess(level.isClientSide);
            }

            if (
                    player.isShiftKeyDown() &&
                            !heldItem.isEmpty() &&
                            !stockingEntity.isEmpty()
            ) {
                if (!level.isClientSide) {
                    ItemStack stored = stockingEntity.getStoredItem().copy();
                    stockingEntity.setStoredItem(ItemStack.EMPTY, true);

                    if (!player.getInventory().add(stored)) {
                        ItemEntity itemEntity = new ItemEntity(
                                level,
                                pos.getX() + 0.5,
                                pos.getY() + 0.5,
                                pos.getZ() + 0.5,
                                stored
                        );
                        itemEntity.setDefaultPickUpDelay();
                        level.addFreshEntity(itemEntity);
                    }
                    level.playSound(
                            null,
                            pos,
                            SoundEvents.ITEM_FRAME_REMOVE_ITEM,
                            SoundSource.BLOCKS,
                            0.5f,
                            1.0f
                    );
                    level.gameEvent(player, GameEvent.BLOCK_CHANGE, pos);
                }
                return InteractionResult.sidedSuccess(level.isClientSide);
            }

            if (!heldItem.isEmpty()) {
                if (heldItem.getItem() instanceof net.minecraft.world.item.BlockItem) {
                    net.minecraft.world.item.BlockItem blockItem =
                            (net.minecraft.world.item.BlockItem) heldItem.getItem();
                    if (blockItem.getBlock() instanceof FestiveStockingBlock) {
                        return InteractionResult.PASS;
                    }
                }

                ItemStack stored = stockingEntity.getStoredItem();

                if (stored.isEmpty()) {
                    if (!level.isClientSide) {
                        ItemStack toStore = heldItem.copy();
                        int maxStack = toStore.getMaxStackSize();
                        int toTake = player.isShiftKeyDown()
                                ? Math.min(heldItem.getCount(), maxStack)
                                : 1;
                        toStore.setCount(toTake);
                        stockingEntity.setStoredItem(toStore, true);
                        heldItem.shrink(toTake);
                        if (heldItem.isEmpty()) {
                            player.setItemInHand(hand, ItemStack.EMPTY);
                        }
                        level.playSound(
                                null,
                                pos,
                                ModSounds.DECORATED_POT_INSERT_ITEM.get(),
                                SoundSource.BLOCKS,
                                0.5f,
                                1.0f
                        );
                        level.gameEvent(player, GameEvent.BLOCK_CHANGE, pos);
                    }
                    return InteractionResult.sidedSuccess(level.isClientSide);
                } else if (
                        stored.sameItem(heldItem) &&
                                stored.getCount() < stored.getMaxStackSize()
                ) {
                    if (!level.isClientSide) {
                        int maxStack = stored.getMaxStackSize();
                        int spaceAvailable = maxStack - stored.getCount();
                        int toAdd = player.isShiftKeyDown()
                                ? Math.min(heldItem.getCount(), spaceAvailable)
                                : 1;
                        int canAdd = Math.min(toAdd, spaceAvailable);
                        stored.grow(canAdd);
                        stockingEntity.setStoredItem(stored, true);
                        heldItem.shrink(canAdd);
                        if (heldItem.isEmpty()) {
                            player.setItemInHand(hand, ItemStack.EMPTY);
                        }
                        level.playSound(
                                null,
                                pos,
                                ModSounds.DECORATED_POT_INSERT_ITEM.get(),
                                SoundSource.BLOCKS,
                                0.5f,
                                1.0f
                        );
                        level.gameEvent(player, GameEvent.BLOCK_CHANGE, pos);
                    }
                    return InteractionResult.sidedSuccess(level.isClientSide);
                } else {
                    if (!level.isClientSide) {
                        level.playSound(
                                null,
                                pos,
                                ModSounds.DECORATED_POT_INSERT_FAIL.get(),
                                SoundSource.BLOCKS,
                                0.5f,
                                1.0f
                        );
                    }
                    return InteractionResult.sidedSuccess(level.isClientSide);
                }
            }
        }

        return InteractionResult.PASS;
    }

    @Override
    public void playerWillDestroy(
            Level level,
            BlockPos pos,
            BlockState state,
            Player player
    ) {
        BlockEntity be = level.getBlockEntity(pos);
        if (be instanceof FestiveStockingBlockEntity) {
            FestiveStockingBlockEntity stockingEntity =
                    (FestiveStockingBlockEntity) be;
            if (!stockingEntity.isEmpty()) {
                ItemStack tool = player.getMainHandItem();
                boolean hasSilkTouch =
                        EnchantmentHelper.getItemEnchantmentLevel(
                                Enchantments.SILK_TOUCH,
                                tool
                        ) >
                                0;

                if (!hasSilkTouch) {
                    ItemStack stored = stockingEntity.getStoredItem().copy();
                    ItemEntity itemEntity = new ItemEntity(
                            level,
                            pos.getX() + 0.5,
                            pos.getY() + 0.5,
                            pos.getZ() + 0.5,
                            stored
                    );
                    itemEntity.setDefaultPickUpDelay();
                    level.addFreshEntity(itemEntity);
                }
            }
        }
        super.playerWillDestroy(level, pos, state, player);
    }

    @Override
    public List<ItemStack> getDrops(
            BlockState state,
            LootContext.Builder builder
    ) {
        LootContext ctx = builder
                .withParameter(
                        net.minecraft.world.level.storage.loot.parameters.LootContextParams.BLOCK_STATE,
                        state
                )
                .create(
                        net.minecraft.world.level.storage.loot.parameters.LootContextParamSets.BLOCK
                );
        ItemStack tool = ctx.getParamOrNull(
                net.minecraft.world.level.storage.loot.parameters.LootContextParams.TOOL
        );
        BlockEntity be = ctx.getParamOrNull(
                net.minecraft.world.level.storage.loot.parameters.LootContextParams.BLOCK_ENTITY
        );
        ItemStack result = new ItemStack(this);

        if (
                tool != null &&
                        !tool.isEmpty() &&
                        EnchantmentHelper.getItemEnchantmentLevel(Enchantments.SILK_TOUCH, tool) >
                                0 &&
                        be instanceof FestiveStockingBlockEntity
        ) {
            FestiveStockingBlockEntity stockingEntity =
                    (FestiveStockingBlockEntity) be;
            if (!stockingEntity.isEmpty()) {
                CompoundTag tag = result.getOrCreateTag();
                CompoundTag storedTag = new CompoundTag();
                stockingEntity.getStoredItem().save(storedTag);
                tag.put("StoredItem", storedTag);
            }
        }

        return List.of(result);
    }
}

package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.world.WorldlyContainer;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

import javax.annotation.Nullable;

public class FestiveStockingBlockEntity
        extends BlockEntity
        implements WorldlyContainer {

    private ItemStack storedItem = ItemStack.EMPTY;

    private static final int[] SLOTS = new int[]{0};

    public FestiveStockingBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.FESTIVE_STOCKING_BLOCK_ENTITY.get(), pos, state);
    }

    public ItemStack getStoredItem() {
        return storedItem;
    }

    public void setStoredItem(ItemStack stack) {
        setStoredItem(stack, true);
    }

    public void setStoredItem(ItemStack stack, boolean sendUpdate) {
        this.storedItem = stack.isEmpty() ? ItemStack.EMPTY : stack.copy();
        this.setChanged();
        if (sendUpdate && level != null && !level.isClientSide) {
            level.sendBlockUpdated(
                    worldPosition,
                    getBlockState(),
                    getBlockState(),
                    3
            );
        }
    }

    public boolean isEmpty() {
        return storedItem.isEmpty();
    }

    @Override
    public int[] getSlotsForFace(Direction side) {
        return SLOTS;
    }

    @Override
    public boolean canPlaceItemThroughFace(
            int slot,
            ItemStack stack,
            @Nullable Direction direction
    ) {
        if (stack.getItem() instanceof net.minecraft.world.item.BlockItem) {
            net.minecraft.world.item.BlockItem blockItem =
                    (net.minecraft.world.item.BlockItem) stack.getItem();
            if (blockItem.getBlock() instanceof FestiveStockingBlock) {
                return false;
            }
        }

        if (storedItem.isEmpty()) {
            return true;
        }
        return (
                storedItem.sameItem(stack) &&
                        storedItem.getCount() < storedItem.getMaxStackSize()
        );
    }

    @Override
    public boolean canTakeItemThroughFace(
            int slot,
            ItemStack stack,
            Direction direction
    ) {
        return !storedItem.isEmpty();
    }

    @Override
    public int getContainerSize() {
        return 1;
    }

    @Override
    public boolean stillValid(Player player) {
        return true;
    }

    @Override
    public ItemStack getItem(int slot) {
        return slot == 0 ? storedItem : ItemStack.EMPTY;
    }

    @Override
    public ItemStack removeItem(int slot, int amount) {
        if (slot != 0 || storedItem.isEmpty()) {
            return ItemStack.EMPTY;
        }

        int toRemove = Math.min(amount, storedItem.getCount());
        ItemStack result = storedItem.copy();
        result.setCount(toRemove);
        storedItem.shrink(toRemove);

        if (storedItem.isEmpty()) {
            storedItem = ItemStack.EMPTY;
        }

        setChanged();
        if (level != null && !level.isClientSide) {
            level.gameEvent(
                    null,
                    net.minecraft.world.level.gameevent.GameEvent.BLOCK_CHANGE,
                    worldPosition
            );
            level.sendBlockUpdated(
                    worldPosition,
                    getBlockState(),
                    getBlockState(),
                    3
            );
        }
        return result;
    }

    @Override
    public ItemStack removeItemNoUpdate(int slot) {
        if (slot != 0 || storedItem.isEmpty()) {
            return ItemStack.EMPTY;
        }
        ItemStack result = storedItem.copy();
        storedItem = ItemStack.EMPTY;
        return result;
    }

    @Override
    public void setItem(int slot, ItemStack stack) {
        if (slot == 0) {
            storedItem = stack.isEmpty() ? ItemStack.EMPTY : stack.copy();
            setChanged();
            if (level != null && !level.isClientSide) {
                level.gameEvent(
                        null,
                        net.minecraft.world.level.gameevent.GameEvent.BLOCK_CHANGE,
                        worldPosition
                );
                level.sendBlockUpdated(
                        worldPosition,
                        getBlockState(),
                        getBlockState(),
                        3
                );
            }
        }
    }

    @Override
    public void clearContent() {
        storedItem = ItemStack.EMPTY;
        setChanged();
    }

    public int getComparatorOutput() {
        if (storedItem.isEmpty()) {
            return 0;
        }
        float fillRatio =
                (float) storedItem.getCount() / (float) storedItem.getMaxStackSize();
        return Math.max(1, (int) Math.ceil(fillRatio * 15.0f));
    }

    @Override
    public void load(CompoundTag tag) {
        super.load(tag);
        if (tag.contains("StoredItem", 10)) {
            this.storedItem = ItemStack.of(tag.getCompound("StoredItem"));
        } else {
            this.storedItem = ItemStack.EMPTY;
        }
    }

    @Override
    protected void saveAdditional(CompoundTag tag) {
        super.saveAdditional(tag);
        if (!storedItem.isEmpty()) {
            tag.put("StoredItem", storedItem.save(new CompoundTag()));
        }
    }

    @Override
    public CompoundTag getUpdateTag() {
        CompoundTag tag = super.getUpdateTag();
        tag.put(
                "StoredItem",
                storedItem.isEmpty()
                        ? ItemStack.EMPTY.save(new CompoundTag())
                        : storedItem.save(new CompoundTag())
        );
        return tag;
    }

    @Override
    public Packet<ClientGamePacketListener> getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }
}

