package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.CauldronBlock;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityTicker;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

import javax.annotation.Nullable;

public class IcicleCauldronBlock extends CauldronBlock implements EntityBlock {

    private static final VoxelShape INSIDE = Block.box(
            2.0D,
            4.0D,
            2.0D,
            14.0D,
            16.0D,
            14.0D
    );
    protected static final VoxelShape SHAPE = Shapes.join(
            Shapes.block(),
            INSIDE,
            net.minecraft.world.phys.shapes.BooleanOp.ONLY_FIRST
    );

    public IcicleCauldronBlock(BlockBehaviour.Properties properties) {
        super(properties);
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return SHAPE;
    }

    @Override
    public RenderShape getRenderShape(BlockState state) {
        return RenderShape.ENTITYBLOCK_ANIMATED;
    }

    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return new IcicleCauldronBlockEntity(pos, state);
    }

    @Nullable
    @Override
    public <T extends BlockEntity> BlockEntityTicker<T> getTicker(
            Level level,
            BlockState state,
            BlockEntityType<T> type
    ) {
        return null;
    }

    @Override
    public InteractionResult use(
            BlockState state,
            Level level,
            BlockPos pos,
            Player player,
            InteractionHand hand,
            BlockHitResult hit
    ) {
        BlockEntity blockEntity = level.getBlockEntity(pos);
        if (blockEntity instanceof IcicleCauldronBlockEntity) {
            IcicleCauldronBlockEntity cauldronEntity =
                    (IcicleCauldronBlockEntity) blockEntity;
            ItemStack heldItem = player.getItemInHand(hand);
            ItemStack storedIcicle = cauldronEntity.getStoredIcicle();

            boolean isIcicleBlock =
                    heldItem.getItem() ==
                            com.kingodogo.buildscape.item.ModItems.ICICLE_BLOCK.get();
            if (isIcicleBlock && storedIcicle.isEmpty()) {
                if (!level.isClientSide) {
                    cauldronEntity.setStoredIcicle(heldItem.copy().split(1));
                    if (!player.getAbilities().instabuild) {
                        heldItem.shrink(1);
                    }
                    level.playSound(
                            null,
                            pos,
                            SoundEvents.BUCKET_EMPTY,
                            SoundSource.BLOCKS,
                            1.0f,
                            1.0f
                    );
                }
                return InteractionResult.sidedSuccess(level.isClientSide);
            }

            if (!storedIcicle.isEmpty()) {
                if (!level.isClientSide) {
                    ItemStack extracted = storedIcicle.copy();
                    if (heldItem.isEmpty()) {
                        player.setItemInHand(hand, extracted);
                    } else if (!player.getInventory().add(extracted)) {
                        player.drop(extracted, false);
                    }
                    cauldronEntity.setStoredIcicle(ItemStack.EMPTY);
                    level.playSound(
                            null,
                            pos,
                            SoundEvents.ITEM_PICKUP,
                            SoundSource.BLOCKS,
                            0.2f,
                            1.0f
                    );
                }
                return InteractionResult.sidedSuccess(level.isClientSide);
            }
        }

        return InteractionResult.PASS;
    }

    @Override
    public boolean hasAnalogOutputSignal(BlockState state) {
        return true;
    }

    @Override
    public int getAnalogOutputSignal(
            BlockState state,
            Level level,
            BlockPos pos
    ) {
        BlockEntity blockEntity = level.getBlockEntity(pos);
        if (blockEntity instanceof IcicleCauldronBlockEntity) {
            IcicleCauldronBlockEntity cauldronEntity =
                    (IcicleCauldronBlockEntity) blockEntity;
            return cauldronEntity.hasIcicle() ? 15 : 0;
        }
        return 0;
    }

    @Override
    public void onRemove(
            BlockState state,
            Level level,
            BlockPos pos,
            BlockState newState,
            boolean isMoving
    ) {
        if (!state.is(newState.getBlock()) && !level.isClientSide) {
            BlockEntity blockEntity = level.getBlockEntity(pos);
            if (blockEntity instanceof IcicleCauldronBlockEntity) {
                IcicleCauldronBlockEntity cauldronEntity =
                        (IcicleCauldronBlockEntity) blockEntity;
                ItemStack storedIcicle = cauldronEntity.getStoredIcicle();
                if (!storedIcicle.isEmpty()) {
                    ItemEntity itemEntity = new ItemEntity(
                            level,
                            pos.getX() + 0.5,
                            pos.getY() + 0.5,
                            pos.getZ() + 0.5,
                            storedIcicle.copy()
                    );
                    itemEntity.setDefaultPickUpDelay();
                    level.addFreshEntity(itemEntity);
                }
            }
        }
        super.onRemove(state, level, pos, newState, isMoving);
    }
}

package com.kingodogo.buildscape.block;

import javax.annotation.Nullable;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientGamePacketListener;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.world.Container;
import net.minecraft.world.WorldlyContainer;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;

public class IcicleCauldronBlockEntity
        extends BlockEntity
        implements WorldlyContainer {

    private ItemStack storedIcicle = ItemStack.EMPTY;

    private static final int[] SLOTS = new int[]{0};

    public IcicleCauldronBlockEntity(BlockPos pos, BlockState state) {
        super(ModBlockEntities.ICICLE_CAULDRON_BLOCK_ENTITY.get(), pos, state);
    }

    public ItemStack getStoredIcicle() {
        return storedIcicle;
    }

    public void setStoredIcicle(ItemStack stack) {
        boolean wasEmpty = this.storedIcicle.isEmpty();
        this.storedIcicle = stack.isEmpty() ? ItemStack.EMPTY : stack.copy();
        this.setChanged();
        if (level != null && !level.isClientSide) {
            if (this.storedIcicle.isEmpty() && !wasEmpty) {
                convertToRegularCauldron();
            } else if (!this.storedIcicle.isEmpty()) {
                level.sendBlockUpdated(
                        worldPosition,
                        getBlockState(),
                        getBlockState(),
                        3
                );
            }
        }
    }

    private void convertToRegularCauldron() {
        if (level != null && !level.isClientSide) {
            level.setBlock(
                    worldPosition,
                    net.minecraft.world.level.block.Blocks.CAULDRON.defaultBlockState(),
                    3
            );
        }
    }

    public boolean hasIcicle() {
        return !storedIcicle.isEmpty();
    }

    @Override
    public int[] getSlotsForFace(Direction side) {
        return SLOTS;
    }

    @Override
    public boolean canPlaceItemThroughFace(
            int slot,
            ItemStack stack,
            @Nullable Direction direction
    ) {
        if (direction != Direction.UP) {
            return false;
        }
        if (
                stack.getItem() !=
                        com.kingodogo.buildscape.item.ModItems.ICICLE_BLOCK.get()
        ) {
            return false;
        }
        return storedIcicle.isEmpty();
    }

    @Override
    public boolean canTakeItemThroughFace(
            int slot,
            ItemStack stack,
            @Nullable Direction direction
    ) {
        return !storedIcicle.isEmpty();
    }

    @Override
    public int getContainerSize() {
        return 1;
    }

    @Override
    public boolean isEmpty() {
        return storedIcicle.isEmpty();
    }

    @Override
    public ItemStack getItem(int slot) {
        return slot == 0 ? storedIcicle : ItemStack.EMPTY;
    }

    @Override
    public ItemStack removeItem(int slot, int amount) {
        if (slot == 0 && !storedIcicle.isEmpty()) {
            ItemStack result = storedIcicle.split(amount);
            if (storedIcicle.isEmpty()) {
                storedIcicle = ItemStack.EMPTY;
                this.setChanged();
                if (level != null && !level.isClientSide) {
                    convertToRegularCauldron();
                }
            } else {
                this.setChanged();
            }
            return result;
        }
        return ItemStack.EMPTY;
    }

    @Override
    public ItemStack removeItemNoUpdate(int slot) {
        if (slot == 0) {
            ItemStack result = storedIcicle;
            storedIcicle = ItemStack.EMPTY;
            this.setChanged();
            if (level != null && !level.isClientSide) {
                convertToRegularCauldron();
            }
            return result;
        }
        return ItemStack.EMPTY;
    }

    @Override
    public void setItem(int slot, ItemStack stack) {
        if (slot == 0) {
            setStoredIcicle(stack);
        }
    }

    @Override
    public boolean stillValid(Player player) {
        if (level == null || level.getBlockEntity(worldPosition) != this) {
            return false;
        }
        return (
                player.distanceToSqr(
                        (double) worldPosition.getX() + 0.5D,
                        (double) worldPosition.getY() + 0.5D,
                        (double) worldPosition.getZ() + 0.5D
                ) <=
                        64.0D
        );
    }

    @Override
    public void clearContent() {
        storedIcicle = ItemStack.EMPTY;
        this.setChanged();
    }

    @Override
    protected void saveAdditional(CompoundTag tag) {
        super.saveAdditional(tag);
        if (!storedIcicle.isEmpty()) {
            tag.put("Icicle", storedIcicle.save(new CompoundTag()));
        }
    }

    @Override
    public void load(CompoundTag tag) {
        super.load(tag);
        if (tag.contains("Icicle")) {
            storedIcicle = ItemStack.of(tag.getCompound("Icicle"));
        } else {
            storedIcicle = ItemStack.EMPTY;
        }
    }

    @Override
    public Packet<ClientGamePacketListener> getUpdatePacket() {
        return ClientboundBlockEntityDataPacket.create(this);
    }

    @Override
    public CompoundTag getUpdateTag() {
        return saveWithoutMetadata();
    }
}

package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.RotatedPillarBlock;
import net.minecraft.world.level.block.SimpleWaterloggedBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

public class LargeChainBlock
        extends RotatedPillarBlock
        implements SimpleWaterloggedBlock {

    public static final BooleanProperty WATERLOGGED =
            BlockStateProperties.WATERLOGGED;
    private static final VoxelShape SHAPE_Y = Block.box(
            4.0D,
            0.0D,
            4.0D,
            12.0D,
            16.0D,
            12.0D
    );
    private static final VoxelShape SHAPE_X = Block.box(
            0.0D,
            4.0D,
            4.0D,
            16.0D,
            12.0D,
            12.0D
    );
    private static final VoxelShape SHAPE_Z = Block.box(
            4.0D,
            4.0D,
            0.0D,
            12.0D,
            12.0D,
            16.0D
    );

    private static final VoxelShape COLLISION_SHAPE_Y = Block.box(
            7.0D,
            0.0D,
            7.0D,
            9.0D,
            16.0D,
            9.0D
    );
    private static final VoxelShape COLLISION_SHAPE_X = Block.box(
            0.0D,
            4.0D,
            4.0D,
            16.0D,
            12.0D,
            12.0D
    );
    private static final VoxelShape COLLISION_SHAPE_Z = Block.box(
            4.0D,
            4.0D,
            0.0D,
            12.0D,
            12.0D,
            16.0D
    );

    public LargeChainBlock(BlockBehaviour.Properties properties) {
        super(properties);
        this.registerDefaultState(
                this.stateDefinition.any().setValue(WATERLOGGED, false)
        );
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        super.createBlockStateDefinition(builder);
        builder.add(WATERLOGGED);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        FluidState fluidstate = context
                .getLevel()
                .getFluidState(context.getClickedPos());
        BlockState state = super.getStateForPlacement(context);
        if (state != null) {
            state = state.setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
        }

        Direction clickedFace = context.getClickedFace();

        if (clickedFace == Direction.DOWN) {
            BlockPos placePos = context.getClickedPos().above();
            BlockState aboveState = context
                    .getLevel()
                    .getBlockState(context.getClickedPos());

            if (
                    Block.isFaceFull(
                            aboveState.getCollisionShape(
                                    context.getLevel(),
                                    context.getClickedPos()
                            ),
                            Direction.DOWN
                    )
            ) {
                if (context.getLevel().getBlockState(placePos).canBeReplaced(context)) {
                    return (state != null ? state : this.defaultBlockState()).setValue(
                            AXIS,
                            Direction.Axis.Y
                    );
                }
            }
        }

        return state;
    }

    @Override
    public BlockState updateShape(
            BlockState state,
            Direction direction,
            BlockState neighborState,
            LevelAccessor level,
            BlockPos pos,
            BlockPos neighborPos
    ) {
        if (state.getValue(WATERLOGGED)) {
            level.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }
        return super.updateShape(
                state,
                direction,
                neighborState,
                level,
                pos,
                neighborPos
        );
    }

    @Override
    public FluidState getFluidState(BlockState state) {
        return state.getValue(WATERLOGGED)
                ? Fluids.WATER.getSource(false)
                : super.getFluidState(state);
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        Direction.Axis axis = state.getValue(AXIS);
        switch (axis) {
            case X:
                return SHAPE_X;
            case Z:
                return SHAPE_Z;
            case Y:
            default:
                return SHAPE_Y;
        }
    }

    @Override
    public VoxelShape getCollisionShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        if (
                context instanceof
                        net.minecraft.world.phys.shapes.EntityCollisionContext entityContext
        ) {
            net.minecraft.world.entity.Entity entity = entityContext.getEntity();
            if (
                    entity != null &&
                            !(entity instanceof net.minecraft.world.entity.player.Player)
            ) {
                return Shapes.empty();
            }
        }

        Direction.Axis axis = state.getValue(AXIS);
        switch (axis) {
            case X:
                return COLLISION_SHAPE_X;
            case Z:
                return COLLISION_SHAPE_Z;
            case Y:
            default:
                return COLLISION_SHAPE_Y;
        }
    }

    @Override
    public VoxelShape getVisualShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return Shapes.empty();
    }

    @Override
    public boolean isLadder(
            BlockState state,
            LevelReader level,
            BlockPos pos,
            LivingEntity entity
    ) {
        return (
                entity instanceof net.minecraft.world.entity.player.Player &&
                        state.getValue(AXIS) == Direction.Axis.Y
        );
    }

    @Override
    public boolean isPathfindable(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            net.minecraft.world.level.pathfinder.PathComputationType type
    ) {
        return true;
    }

    @Override
    public boolean useShapeForLightOcclusion(BlockState state) {
        return false;
    }

    @Override
    public int getLightBlock(BlockState state, BlockGetter level, BlockPos pos) {
        return 0;
    }

    @Override
    public boolean propagatesSkylightDown(
            BlockState state,
            BlockGetter reader,
            BlockPos pos
    ) {
        return true;
    }

    @Override
    public float getShadeBrightness(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        return 1.0F;
    }

    @Override
    public boolean skipRendering(
            BlockState state,
            BlockState adjacentBlockState,
            Direction side
    ) {
        return (
                adjacentBlockState.is(this) ||
                        super.skipRendering(state, adjacentBlockState, side)
        );
    }

    @Override
    public boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        Direction.Axis axis = state.getValue(AXIS);

        if (axis == Direction.Axis.Y) {
            BlockPos below = pos.below();
            BlockState belowState = level.getBlockState(below);
            boolean canHangFromBelow =
                    Block.isFaceFull(
                            belowState.getCollisionShape(level, below),
                            Direction.UP
                    ) ||
                            belowState.getBlock() instanceof
                                    net.minecraft.world.level.block.ChainBlock ||
                            belowState.getBlock() instanceof ClimbableChainBlock ||
                            belowState.getBlock() instanceof LargeChainBlock;

            BlockPos above = pos.above();
            BlockState aboveState = level.getBlockState(above);
            boolean canHangFromAbove =
                    Block.isFaceFull(
                            aboveState.getCollisionShape(level, above),
                            Direction.DOWN
                    ) ||
                            aboveState.getBlock() instanceof
                                    net.minecraft.world.level.block.ChainBlock ||
                            aboveState.getBlock() instanceof ClimbableChainBlock ||
                            aboveState.getBlock() instanceof LargeChainBlock;

            return canHangFromBelow || canHangFromAbove;
        } else {
            Direction dir1 = Direction.get(Direction.AxisDirection.POSITIVE, axis);
            Direction dir2 = Direction.get(Direction.AxisDirection.NEGATIVE, axis);

            BlockPos pos1 = pos.relative(dir1);
            BlockPos pos2 = pos.relative(dir2);
            BlockState state1 = level.getBlockState(pos1);
            BlockState state2 = level.getBlockState(pos2);

            boolean side1Valid =
                    Block.isFaceFull(
                            state1.getCollisionShape(level, pos1),
                            dir1.getOpposite()
                    ) ||
                            state1.getBlock() instanceof
                                    net.minecraft.world.level.block.ChainBlock ||
                            state1.getBlock() instanceof ClimbableChainBlock ||
                            state1.getBlock() instanceof LargeChainBlock;

            boolean side2Valid =
                    Block.isFaceFull(
                            state2.getCollisionShape(level, pos2),
                            dir2.getOpposite()
                    ) ||
                            state2.getBlock() instanceof
                                    net.minecraft.world.level.block.ChainBlock ||
                            state2.getBlock() instanceof ClimbableChainBlock ||
                            state2.getBlock() instanceof LargeChainBlock;

            return side1Valid || side2Valid;
        }
    }
}

package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.sounds.SoundSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.SoundType;
import net.minecraft.world.level.block.WallBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;
import net.minecraftforge.registries.RegistryObject;

public class LeafHedgeBlock extends WallBlock {

    @SuppressWarnings("unused")
    private final RegistryObject<?> dropItem;

    public LeafHedgeBlock(
            BlockBehaviour.Properties properties,
            RegistryObject<?> dropItem
    ) {
        super(properties);
        this.dropItem = dropItem;
    }

    @Override
    public void stepOn(
            Level level,
            BlockPos pos,
            BlockState state,
            Entity entity
    ) {
        if (entity instanceof Player) {
            Player player = (Player) entity;
            if (player.isOnGround() && level.isClientSide) {
                BlockPos playerBlockPos = entity.blockPosition();
                BlockPos blockBelowPlayer = playerBlockPos.below();
                BlockState blockBelow = level.getBlockState(blockBelowPlayer);
                if (blockBelow.getBlock() == this) {
                    playStepSound(level, blockBelowPlayer, blockBelow, player);
                }
            }
        }
        super.stepOn(level, pos, state, entity);
    }

    @Override
    public void entityInside(
            BlockState state,
            Level level,
            BlockPos pos,
            Entity entity
    ) {
        if (entity instanceof Player) {
            Player player = (Player) entity;
            if (player.isOnGround() && level.isClientSide) {
                BlockPos playerBlockPos = entity.blockPosition();
                boolean isInside = playerBlockPos.getY() == pos.getY();

                BlockPos blockBelowPlayer = playerBlockPos.below();
                BlockState blockBelow = level.getBlockState(blockBelowPlayer);
                boolean isOnTop = blockBelow.getBlock() == this;

                if (!isOnTop) {
                    for (int dx = -1; dx <= 1; dx++) {
                        for (int dz = -1; dz <= 1; dz++) {
                            BlockPos checkPos = blockBelowPlayer.offset(dx, 0, dz);
                            BlockState checkState = level.getBlockState(checkPos);
                            if (checkState.getBlock() == this) {
                                isOnTop = true;
                                blockBelowPlayer = checkPos;
                                blockBelow = checkState;
                                break;
                            }
                        }
                        if (isOnTop) break;
                    }
                }

                if (isOnTop || isInside) {
                    BlockPos soundPos = isOnTop ? blockBelowPlayer : pos;
                    BlockState soundState = isOnTop ? blockBelow : state;
                    playStepSound(level, soundPos, soundState, player);
                }
            }
        }
        super.entityInside(state, level, pos, entity);
    }

    private void playStepSound(
            Level level,
            BlockPos pos,
            BlockState state,
            Player player
    ) {
        float stepInterval = 2.0f;
        int currentStep = (int) (player.walkDist / stepInterval);
        int lastStep = (int) (player.walkDistO / stepInterval);

        if (currentStep != lastStep && player.walkDist > player.walkDistO) {
            SoundType sounds = this.getSoundType(state);
            net.minecraft.sounds.SoundEvent stepSound = sounds.getStepSound();
            float volume = 0.15f;
            float pitch = 1.0f;

            if (sounds instanceof CustomSoundType) {
                CustomSoundType customSounds = (CustomSoundType) sounds;
                volume = customSounds.getStepVolume();
                pitch = customSounds.getStepPitch();
            }

            level.playLocalSound(
                    pos.getX() + 0.5,
                    pos.getY() + 0.5,
                    pos.getZ() + 0.5,
                    stepSound,
                    SoundSource.BLOCKS,
                    volume,
                    pitch,
                    false
            );
        }
    }

    @Override
    public float getDestroyProgress(
            BlockState state,
            Player player,
            BlockGetter level,
            BlockPos pos
    ) {
        float destroySpeed = state.getDestroySpeed(level, pos);
        if (destroySpeed == -1.0F) {
            return 0.0F;
        }

        int efficiencyLevel =
                net.minecraft.world.item.enchantment.EnchantmentHelper.getBlockEfficiency(
                        player
                );
        ItemStack tool = player.getMainHandItem();

        float speedMultiplier = 1.0F;
        if (!tool.isEmpty()) {
            speedMultiplier = tool.getDestroySpeed(state);
        }

        if (speedMultiplier > 1.0F) {
            int efficiencyBonus = efficiencyLevel > 0
                    ? efficiencyLevel * efficiencyLevel + 1
                    : 0;
            speedMultiplier += (float) efficiencyBonus;
        }

        float difficultyModifier = player.hasCorrectToolForDrops(state)
                ? 30.0F
                : 100.0F;
        return speedMultiplier / destroySpeed / difficultyModifier;
    }

    @Override
    public boolean skipRendering(
            BlockState state,
            BlockState adjacentBlockState,
            Direction side
    ) {
        if (adjacentBlockState.is(this)) {
            return true;
        }

        return super.skipRendering(state, adjacentBlockState, side);
    }

    @Override
    public VoxelShape getVisualShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return Shapes.empty();
    }

    @Override
    public boolean useShapeForLightOcclusion(BlockState state) {
        return false;
    }
}

