package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.SlabBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.properties.SlabType;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;

public class MudSlabBlock extends SlabBlock {

    protected static final VoxelShape BOTTOM_SHAPE = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            8.0D,
            16.0D
    );
    protected static final VoxelShape TOP_SHAPE = Block.box(
            0.0D,
            8.0D,
            0.0D,
            16.0D,
            15.0D,
            16.0D
    );
    protected static final VoxelShape DOUBLE_SHAPE = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            15.0D,
            16.0D
    );

    public MudSlabBlock(BlockBehaviour.Properties properties) {
        super(properties);
    }

    @Override
    public VoxelShape getCollisionShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        SlabType type = state.getValue(TYPE);
        if (type == SlabType.TOP) {
            return TOP_SHAPE;
        } else if (type == SlabType.DOUBLE) {
            return DOUBLE_SHAPE;
        } else {
            return BOTTOM_SHAPE;
        }
    }
}

package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.SimpleWaterloggedBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

import javax.annotation.Nullable;

public class MulticolorGlowLightsBlock
        extends net.minecraft.world.level.block.VineBlock
        implements EntityBlock, SimpleWaterloggedBlock {

    public static final BooleanProperty LIT = BlockStateProperties.LIT;
    public static final BooleanProperty WATERLOGGED =
            BlockStateProperties.WATERLOGGED;
    public static final BooleanProperty DOWN = BlockStateProperties.DOWN;

    private static final VoxelShape SHAPE_NORTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            16.0D,
            1.0D
    );
    private static final VoxelShape SHAPE_SOUTH = Block.box(
            0.0D,
            0.0D,
            15.0D,
            16.0D,
            16.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_EAST = Block.box(
            15.0D,
            0.0D,
            0.0D,
            16.0D,
            16.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_WEST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            1.0D,
            16.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_UP = Block.box(
            0.0D,
            15.0D,
            0.0D,
            16.0D,
            16.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_DOWN = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            1.0D,
            16.0D
    );

    public MulticolorGlowLightsBlock(BlockBehaviour.Properties properties) {
        super(properties);
        this.registerDefaultState(
                this.stateDefinition.any()
                        .setValue(net.minecraft.world.level.block.VineBlock.NORTH, false)
                        .setValue(net.minecraft.world.level.block.VineBlock.EAST, false)
                        .setValue(net.minecraft.world.level.block.VineBlock.SOUTH, false)
                        .setValue(net.minecraft.world.level.block.VineBlock.WEST, false)
                        .setValue(net.minecraft.world.level.block.VineBlock.UP, false)
                        .setValue(DOWN, false)
                        .setValue(WATERLOGGED, false)
                        .setValue(LIT, true)
        );
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        super.createBlockStateDefinition(builder);
        builder.add(DOWN, WATERLOGGED, LIT);
    }

    @Override
    public int getLightEmission(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        return state.getValue(LIT) ? 15 : 0;
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        VoxelShape shape = Shapes.empty();
        if (state.getValue(net.minecraft.world.level.block.VineBlock.NORTH)) shape =
                Shapes.or(shape, SHAPE_NORTH);
        if (state.getValue(net.minecraft.world.level.block.VineBlock.SOUTH)) shape =
                Shapes.or(shape, SHAPE_SOUTH);
        if (state.getValue(net.minecraft.world.level.block.VineBlock.EAST)) shape =
                Shapes.or(shape, SHAPE_EAST);
        if (state.getValue(net.minecraft.world.level.block.VineBlock.WEST)) shape =
                Shapes.or(shape, SHAPE_WEST);
        if (state.getValue(net.minecraft.world.level.block.VineBlock.UP)) shape =
                Shapes.or(shape, SHAPE_UP);
        if (state.getValue(DOWN)) shape = Shapes.or(shape, SHAPE_DOWN);
        return shape.isEmpty() ? Shapes.block() : shape;
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        BlockPos clickedPos = context.getClickedPos();
        BlockState blockState = context.getLevel().getBlockState(clickedPos);
        boolean isExistingGlowLight =
                blockState.getBlock() instanceof MulticolorGlowLightsBlock ||
                        blockState.getBlock() instanceof GlowLightsBlock;

        Direction clickedFace = context.getClickedFace();
        Direction attachDirection = clickedFace.getOpposite();

        if (
                isExistingGlowLight &&
                        context.getPlayer() != null &&
                        context.getPlayer().isShiftKeyDown()
        ) {
            return null;
        }

        if (
                isExistingGlowLight &&
                        !(context.getPlayer() != null && context.getPlayer().isShiftKeyDown())
        ) {
            if (blockState.getBlock() == this) {
                BooleanProperty property = attachDirection == Direction.DOWN
                        ? DOWN
                        : net.minecraft.world.level.block.VineBlock.getPropertyForFace(
                        attachDirection
                );
                if (
                        property != null &&
                                blockState.hasProperty(property) &&
                                blockState.getValue(property)
                ) {
                    return null;
                }
            }
        }

        if (!isExistingGlowLight) {
            BlockPos originalPos = clickedPos.relative(clickedFace.getOpposite());
            BlockState originalState = context.getLevel().getBlockState(originalPos);
            if (
                    originalState.getBlock() instanceof MulticolorGlowLightsBlock ||
                            originalState.getBlock() instanceof GlowLightsBlock
            ) {
                Direction attachToGlow = clickedFace.getOpposite();
                BooleanProperty attachProperty = attachToGlow == Direction.DOWN
                        ? DOWN
                        : net.minecraft.world.level.block.VineBlock.getPropertyForFace(
                        attachToGlow
                );

                if (
                        attachProperty != null &&
                                originalState.hasProperty(attachProperty) &&
                                originalState.getValue(attachProperty)
                ) {
                    return null;
                }

                BlockState state = this.defaultBlockState();
                if (state.hasProperty(attachProperty)) {
                    state = state.setValue(attachProperty, true);
                }
                BlockPos placePos = context
                        .getClickedPos()
                        .relative(context.getClickedFace());
                FluidState fluidState = context.getLevel().getFluidState(placePos);
                return state
                        .setValue(LIT, true)
                        .setValue(WATERLOGGED, fluidState.getType() == Fluids.WATER);
            }
        }

        if (clickedFace == Direction.UP) {
            BlockState state = this.defaultBlockState();
            state = state.setValue(DOWN, true);
            BlockPos placePos = context
                    .getClickedPos()
                    .relative(context.getClickedFace());
            FluidState fluidState = context.getLevel().getFluidState(placePos);
            return state
                    .setValue(LIT, true)
                    .setValue(WATERLOGGED, fluidState.getType() == Fluids.WATER);
        }

        if (clickedFace == Direction.DOWN) {
            BlockState state = this.defaultBlockState();
            state = state.setValue(
                    net.minecraft.world.level.block.VineBlock.UP,
                    true
            );
            BlockPos placePos = context
                    .getClickedPos()
                    .relative(context.getClickedFace());
            FluidState fluidState = context.getLevel().getFluidState(placePos);
            return state
                    .setValue(LIT, true)
                    .setValue(WATERLOGGED, fluidState.getType() == Fluids.WATER);
        }

        BlockState state = this.defaultBlockState();
        BlockState parentState = super.getStateForPlacement(context);
        if (parentState != null && parentState.is(this)) {
            state = parentState;
        }

        BlockPos placePos = context
                .getClickedPos()
                .relative(context.getClickedFace());
        FluidState fluidState = context.getLevel().getFluidState(placePos);
        return state
                .setValue(LIT, true)
                .setValue(WATERLOGGED, fluidState.getType() == Fluids.WATER);
    }

    @Override
    public BlockState updateShape(
            BlockState state,
            Direction direction,
            BlockState neighborState,
            LevelAccessor level,
            BlockPos pos,
            BlockPos neighborPos
    ) {
        if (state.getValue(WATERLOGGED)) {
            level.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }

        BooleanProperty faceProperty =
                net.minecraft.world.level.block.VineBlock.getPropertyForFace(direction);
        if (
                faceProperty != null &&
                        state.hasProperty(faceProperty) &&
                        state.getValue(faceProperty)
        ) {
            if (
                    !canAttachTo(level, neighborState, neighborPos, direction.getOpposite())
            ) {
                state = state.setValue(faceProperty, false);
            }
        }
        if (direction == Direction.DOWN && state.getValue(DOWN)) {
            if (
                    !canAttachTo(level, neighborState, neighborPos, direction.getOpposite())
            ) {
                state = state.setValue(DOWN, false);
            }
        }

        if (!hasAnyFace(state)) {
            return net.minecraft.world.level.block.Blocks.AIR.defaultBlockState();
        }

        return state;
    }

    @Override
    public FluidState getFluidState(BlockState state) {
        return state.getValue(WATERLOGGED)
                ? Fluids.WATER.getSource(false)
                : super.getFluidState(state);
    }

    @Override
    public boolean canSurvive(
            BlockState state,
            net.minecraft.world.level.LevelReader level,
            BlockPos pos
    ) {
        return hasAnyFace(state);
    }

    @Override
    public boolean canBeReplaced(BlockState state, BlockPlaceContext context) {
        net.minecraft.world.item.Item heldItem = context.getItemInHand().getItem();
        if (heldItem instanceof net.minecraft.world.item.BlockItem) {
            net.minecraft.world.level.block.Block heldBlock =
                    ((net.minecraft.world.item.BlockItem) heldItem).getBlock();

            if (
                    !(heldBlock instanceof MulticolorGlowLightsBlock ||
                            heldBlock instanceof GlowLightsBlock)
            ) {
                return false;
            }

            if (context.getPlayer() != null && context.getPlayer().isShiftKeyDown()) {
                return false;
            }

            Direction clickedFace = context.getClickedFace();
            Direction attachDirection = clickedFace.getOpposite();
            BooleanProperty property = attachDirection == Direction.DOWN
                    ? DOWN
                    : net.minecraft.world.level.block.VineBlock.getPropertyForFace(
                    attachDirection
            );

            if (
                    property != null &&
                            (state.getBlock() == heldBlock ||
                                    (state.getBlock() instanceof GlowLightsBlock &&
                                            heldBlock instanceof MulticolorGlowLightsBlock) ||
                                    (state.getBlock() instanceof MulticolorGlowLightsBlock &&
                                            heldBlock instanceof GlowLightsBlock))
            ) {
                return !state.hasProperty(property) || !state.getValue(property);
            }

            return true;
        }

        return false;
    }

    private boolean hasAnyFace(BlockState state) {
        return (
                state.getValue(net.minecraft.world.level.block.VineBlock.NORTH) ||
                        state.getValue(net.minecraft.world.level.block.VineBlock.EAST) ||
                        state.getValue(net.minecraft.world.level.block.VineBlock.SOUTH) ||
                        state.getValue(net.minecraft.world.level.block.VineBlock.WEST) ||
                        state.getValue(net.minecraft.world.level.block.VineBlock.UP) ||
                        state.getValue(DOWN)
        );
    }

    private boolean canAttachTo(
            BlockGetter level,
            BlockState state,
            BlockPos pos,
            Direction direction
    ) {
        if (state.isAir()) {
            return false;
        }
        if (state.isFaceSturdy(level, pos, direction)) {
            return true;
        }
        if (Block.isFaceFull(state.getCollisionShape(level, pos), direction)) {
            return true;
        }
        return !state.getMaterial().isReplaceable();
    }

    @Override
    public InteractionResult use(
            BlockState state,
            Level level,
            BlockPos pos,
            Player player,
            InteractionHand hand,
            BlockHitResult hit
    ) {
        if (level.isClientSide) {
            return InteractionResult.SUCCESS;
        }

        ItemStack heldItem = player.getItemInHand(hand);

        if (heldItem.isEmpty()) {
            boolean currentLit = state.getValue(LIT);
            BlockState newState = state.setValue(LIT, !currentLit);
            level.setBlock(pos, newState, 3);

            if (currentLit) {
                level.playSound(
                        null,
                        pos,
                        net.minecraft.sounds.SoundEvents.STONE_BUTTON_CLICK_OFF,
                        net.minecraft.sounds.SoundSource.BLOCKS,
                        0.3f,
                        1.0f
                );
            } else {
                level.playSound(
                        null,
                        pos,
                        net.minecraft.sounds.SoundEvents.STONE_BUTTON_CLICK_ON,
                        net.minecraft.sounds.SoundSource.BLOCKS,
                        0.3f,
                        1.0f
                );
            }

            return InteractionResult.SUCCESS;
        }

        return InteractionResult.PASS;
    }

    @Nullable
    @Override
    public BlockEntity newBlockEntity(BlockPos pos, BlockState state) {
        return null;
    }
}

package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.Mirror;
import net.minecraft.world.level.block.Rotation;
import net.minecraft.world.level.block.SimpleWaterloggedBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.block.state.properties.DirectionProperty;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

public class MushroomShelvesBlock
        extends Block
        implements SimpleWaterloggedBlock {

    public static final BooleanProperty WATERLOGGED =
            BlockStateProperties.WATERLOGGED;
    public static final DirectionProperty FACING =
            BlockStateProperties.HORIZONTAL_FACING;

    private static final VoxelShape SHAPE_SOUTH = Shapes.or(
            Block.box(7, 13, 13, 15, 13.25, 16),
            Block.box(8, 3, 13, 16, 3.25, 16),
            Block.box(0, 8, 12, 10, 8.25, 16)
    );

    private static final VoxelShape SHAPE_NORTH = Shapes.or(
            Block.box(1, 13, 0, 9, 13.25, 3),
            Block.box(0, 3, 0, 8, 3.25, 3),
            Block.box(6, 8, 0, 16, 8.25, 4)
    );

    private static final VoxelShape SHAPE_EAST = Shapes.or(
            Block.box(13, 13, 1, 16, 13.25, 9),
            Block.box(13, 3, 0, 16, 3.25, 8),
            Block.box(12, 8, 6, 16, 8.25, 16)
    );

    private static final VoxelShape SHAPE_WEST = Shapes.or(
            Block.box(0, 13, 7, 3, 13.25, 15),
            Block.box(0, 3, 8, 3, 3.25, 16),
            Block.box(0, 8, 0, 4, 8.25, 10)
    );

    public MushroomShelvesBlock(Properties properties) {
        super(properties);
        this.registerDefaultState(
                this.stateDefinition.any()
                        .setValue(FACING, Direction.NORTH)
                        .setValue(WATERLOGGED, false)
        );
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        builder.add(FACING, WATERLOGGED);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        FluidState fluidstate = context
                .getLevel()
                .getFluidState(context.getClickedPos());
        Direction clickedFace = context.getClickedFace();

        if (clickedFace.getAxis().isHorizontal()) {
            return this.defaultBlockState()
                    .setValue(FACING, clickedFace.getOpposite())
                    .setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
        }

        return this.defaultBlockState()
                .setValue(FACING, context.getHorizontalDirection().getOpposite())
                .setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
    }

    @Override
    public BlockState updateShape(
            BlockState state,
            Direction direction,
            BlockState neighborState,
            LevelAccessor level,
            BlockPos pos,
            BlockPos neighborPos
    ) {
        if (state.getValue(WATERLOGGED)) {
            level.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }
        return super.updateShape(
                state,
                direction,
                neighborState,
                level,
                pos,
                neighborPos
        );
    }

    @Override
    public FluidState getFluidState(BlockState state) {
        return state.getValue(WATERLOGGED)
                ? Fluids.WATER.getSource(false)
                : super.getFluidState(state);
    }

    @Override
    public BlockState rotate(BlockState state, Rotation rotation) {
        return state.setValue(FACING, rotation.rotate(state.getValue(FACING)));
    }

    @Override
    public BlockState mirror(BlockState state, Mirror mirror) {
        return state.rotate(mirror.getRotation(state.getValue(FACING)));
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter worldIn,
            BlockPos pos,
            CollisionContext context
    ) {
        return switch (state.getValue(FACING)) {
            case NORTH -> SHAPE_NORTH;
            case SOUTH -> SHAPE_SOUTH;
            case EAST -> SHAPE_EAST;
            case WEST -> SHAPE_WEST;
            default -> SHAPE_SOUTH;
        };
    }

    @Override
    public VoxelShape getCollisionShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return getShape(state, level, pos, context);
    }

    @Override
    public VoxelShape getVisualShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return Shapes.empty();
    }

    @Override
    public float getShadeBrightness(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        return 1.0F;
    }

    @Override
    public boolean propagatesSkylightDown(
            BlockState state,
            BlockGetter reader,
            BlockPos pos
    ) {
        return true;
    }

    @Override
    public int getLightBlock(BlockState state, BlockGetter level, BlockPos pos) {
        return 0;
    }

    @Override
    public boolean useShapeForLightOcclusion(BlockState state) {
        return false;
    }

    @Override
    public boolean skipRendering(
            BlockState state,
            BlockState adjacentBlockState,
            Direction side
    ) {
        return (
                adjacentBlockState.is(this) ||
                        super.skipRendering(state, adjacentBlockState, side)
        );
    }

    private boolean isMushroomShelf(BlockState state) {
        return state.getBlock() instanceof MushroomShelvesBlock;
    }

    private boolean hasVerticalStacking(LevelReader level, BlockPos pos) {
        BlockPos posAbove = pos.above();
        BlockPos posBelow = pos.below();

        BlockState stateAbove = level.getBlockState(posAbove);
        BlockState stateBelow = level.getBlockState(posBelow);

        return isMushroomShelf(stateAbove) || isMushroomShelf(stateBelow);
    }

    private boolean hasNoHorizontalShelves(LevelReader level, BlockPos pos) {
        for (Direction dir : Direction.Plane.HORIZONTAL) {
            BlockPos adjacentPos = pos.relative(dir);
            BlockState adjacentState = level.getBlockState(adjacentPos);

            if (isMushroomShelf(adjacentState)) {
                return false;
            }
        }

        return true;
    }

    @Override
    public boolean isLadder(
            BlockState state,
            LevelReader level,
            BlockPos pos,
            LivingEntity entity
    ) {
        if (!hasVerticalStacking(level, pos)) {
            return false;
        }

        if (!hasNoHorizontalShelves(level, pos)) {
            return false;
        }

        return true;
    }
}

package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.util.StringRepresentable;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.block.state.properties.DirectionProperty;
import net.minecraft.world.level.block.state.properties.EnumProperty;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.VoxelShape;

public class OrnamentBlock
        extends AbstractGlassBlock
        implements SimpleWaterloggedBlock {

    public static final BooleanProperty WATERLOGGED =
            BlockStateProperties.WATERLOGGED;
    public static final EnumProperty<AttachmentType> ATTACHMENT =
            EnumProperty.create("attachment", AttachmentType.class);
    public static final DirectionProperty FACING =
            BlockStateProperties.HORIZONTAL_FACING;
    public static final EnumProperty<StringColor> STRING_COLOR =
            EnumProperty.create("string_color", StringColor.class);
    public static final net.minecraft.world.level.block.state.properties.BooleanProperty LIT =
            net.minecraft.world.level.block.state.properties.BlockStateProperties.LIT;

    private static final VoxelShape SHAPE_FLOOR = Block.box(5, 0, 5, 11, 6, 11);

    private static final VoxelShape SHAPE_CEILING = Block.box(
            5,
            5,
            5,
            11,
            11,
            11
    );

    private static final VoxelShape SHAPE_WALL_NORTH = Block.box(
            5,
            4,
            9,
            11,
            10,
            15
    );
    private static final VoxelShape SHAPE_WALL_SOUTH = Block.box(
            5,
            4,
            1,
            11,
            10,
            7
    );
    private static final VoxelShape SHAPE_WALL_EAST = Block.box(
            1,
            4,
            5,
            7,
            10,
            11
    );
    private static final VoxelShape SHAPE_WALL_WEST = Block.box(
            9,
            4,
            5,
            15,
            10,
            11
    );

    public enum AttachmentType implements StringRepresentable {
        FLOOR("floor"),
        CEILING("ceiling"),
        WALL("wall");

        private final String name;

        AttachmentType(String name) {
            this.name = name;
        }

        @Override
        public String getSerializedName() {
            return this.name;
        }
    }

    public enum StringColor implements StringRepresentable {
        WHITE("white", 0xFFFFFF, "White"),
        ORANGE("orange", 0xFF9800, "Orange"),
        MAGENTA("magenta", 0xC74EBD, "Magenta"),
        LIGHT_BLUE("light_blue", 0x3AB3DA, "Light Blue"),
        YELLOW("yellow", 0xFED83D, "Yellow"),
        LIME("lime", 0x80C71F, "Lime"),
        PINK("pink", 0xF38BAA, "Pink"),
        GRAY("gray", 0x474F52, "Gray"),
        LIGHT_GRAY("light_gray", 0x9D9D97, "Light Gray"),
        CYAN("cyan", 0x169C9C, "Cyan"),
        PURPLE("purple", 0x8932B8, "Purple"),
        BLUE("blue", 0x3C44AA, "Blue"),
        BROWN("brown", 0x835432, "Brown"),
        GREEN("green", 0x5E7C16, "Green"),
        RED("red", 0xB02E26, "Red"),
        BLACK("black", 0x1D1D21, "Black");

        private final String name;
        private final int color;
        private final String displayName;

        StringColor(String name, int color, String displayName) {
            this.name = name;
            this.color = color;
            this.displayName = displayName;
        }

        @Override
        public String getSerializedName() {
            return this.name;
        }

        public int getColor() {
            return color;
        }

        public String getDisplayName() {
            return displayName;
        }
    }

    public OrnamentBlock(BlockBehaviour.Properties properties) {
        super(properties);
        this.registerDefaultState(
                this.stateDefinition.any()
                        .setValue(ATTACHMENT, AttachmentType.FLOOR)
                        .setValue(FACING, Direction.NORTH)
                        .setValue(STRING_COLOR, StringColor.WHITE)
                        .setValue(LIT, true)
                        .setValue(WATERLOGGED, false)
        );
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        builder.add(ATTACHMENT, FACING, STRING_COLOR, LIT, WATERLOGGED);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        Direction clickedFace = context.getClickedFace();
        BlockPos clickedPos = context.getClickedPos();
        LevelReader level = context.getLevel();

        Direction playerFacing = context.getHorizontalDirection().getOpposite();

        BlockPos placePos;
        AttachmentType attachment;
        Direction facing;

        if (clickedFace == Direction.UP) {
            placePos = clickedPos.relative(clickedFace);
            attachment = AttachmentType.FLOOR;
            facing = playerFacing;
        } else if (clickedFace == Direction.DOWN) {
            placePos = clickedPos.relative(clickedFace);
            attachment = AttachmentType.CEILING;
            facing = playerFacing;
        } else {
            placePos = clickedPos.relative(clickedFace);
            attachment = AttachmentType.WALL;
            facing = playerFacing;
        }

        BlockState placeState = level.getBlockState(placePos);
        if (
                placeState.isAir() ||
                        placeState.canBeReplaced(context) ||
                        placeState.is(this)
        ) {
            FluidState fluidstate = context.getLevel().getFluidState(placePos);
            return this.defaultBlockState()
                    .setValue(ATTACHMENT, attachment)
                    .setValue(FACING, facing)
                    .setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
        }

        return null;
    }

    private boolean canAttachTo(
            LevelReader level,
            BlockPos pos,
            Direction direction
    ) {
        BlockState state = level.getBlockState(pos);
        if (state.is(this)) {
            return true;
        }
        if (
                state.getBlock() instanceof FenceBlock ||
                        state.getBlock() instanceof LeafHedgeBlock
        ) {
            return true;
        }
        if (
                state.getMaterial().isSolid() &&
                        !state.isAir() &&
                        !state.is(Blocks.BARRIER)
        ) {
            return true;
        }
        return state.isFaceSturdy(level, pos, direction);
    }

    @Override
    public boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        AttachmentType attachment = state.getValue(ATTACHMENT);

        switch (attachment) {
            case FLOOR:
                return canAttachTo(level, pos.below(), Direction.UP);
            case CEILING:
                return canAttachTo(level, pos.above(), Direction.DOWN);
            case WALL:
                Direction facing = state.getValue(FACING);
                BlockPos wallPos = pos.relative(facing.getOpposite());
                Direction wallFaceDirection = facing;
                return canAttachTo(level, wallPos, wallFaceDirection);
            default:
                return false;
        }
    }

    @Override
    public BlockState updateShape(
            BlockState state,
            Direction direction,
            BlockState neighborState,
            LevelAccessor level,
            BlockPos pos,
            BlockPos neighborPos
    ) {
        if (state.getValue(WATERLOGGED)) {
            level.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }

        if (!canSurvive(state, level, pos)) {
            if (level instanceof net.minecraft.server.level.ServerLevel) {
                ((net.minecraft.server.level.ServerLevel) level).scheduleTick(
                        pos,
                        this,
                        1
                );
            }
        }
        return super.updateShape(
                state,
                direction,
                neighborState,
                level,
                pos,
                neighborPos
        );
    }

    @Override
    public FluidState getFluidState(BlockState state) {
        return state.getValue(WATERLOGGED)
                ? Fluids.WATER.getSource(false)
                : super.getFluidState(state);
    }

    @Override
    public BlockState rotate(BlockState state, Rotation rotation) {
        if (state.getValue(ATTACHMENT) == AttachmentType.WALL) {
            return state.setValue(FACING, rotation.rotate(state.getValue(FACING)));
        }
        return state;
    }

    @Override
    public BlockState mirror(BlockState state, Mirror mirror) {
        if (state.getValue(ATTACHMENT) == AttachmentType.WALL) {
            return state.rotate(mirror.getRotation(state.getValue(FACING)));
        }
        return state;
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        AttachmentType attachment = state.getValue(ATTACHMENT);

        if (attachment == AttachmentType.CEILING) {
            return SHAPE_CEILING;
        } else if (attachment == AttachmentType.WALL) {
            Direction facing = state.getValue(FACING);
            switch (facing) {
                case NORTH:
                    return SHAPE_WALL_NORTH;
                case SOUTH:
                    return SHAPE_WALL_SOUTH;
                case EAST:
                    return SHAPE_WALL_EAST;
                case WEST:
                    return SHAPE_WALL_WEST;
                default:
                    return SHAPE_FLOOR;
            }
        } else {
            return SHAPE_FLOOR;
        }
    }

    @Override
    public VoxelShape getCollisionShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return getShape(state, level, pos, context);
    }

    @Override
    public int getLightEmission(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        if (!state.getValue(LIT)) {
            return 0;
        }

        if (
                state.getBlock() ==
                        com.kingodogo.buildscape.block.ModBlocks.TINTED_GLASS_ORNAMENT.get()
        ) {
            return 4;
        }

        return 15;
    }

    @Override
    public boolean useShapeForLightOcclusion(BlockState state) {
        return false;
    }

    @Override
    public boolean skipRendering(
            BlockState state,
            BlockState adjacentBlockState,
            Direction side
    ) {
        return (
                adjacentBlockState.is(this) ||
                        super.skipRendering(state, adjacentBlockState, side)
        );
    }

    @Override
    public InteractionResult use(
            BlockState state,
            Level level,
            BlockPos pos,
            Player player,
            InteractionHand hand,
            BlockHitResult hit
    ) {
        if (level.isClientSide) {
            return InteractionResult.SUCCESS;
        }

        ItemStack heldItem = player.getItemInHand(hand);

        if (!heldItem.isEmpty()) {
            StringColor dyeColor = getDyeColor(heldItem);
            if (dyeColor != null) {
                BlockState newState = state.setValue(STRING_COLOR, dyeColor);
                level.setBlock(pos, newState, 3);

                if (!player.getAbilities().instabuild) {
                    heldItem.shrink(1);
                }

                level.playSound(
                        null,
                        pos,
                        net.minecraft.sounds.SoundEvents.DYE_USE,
                        net.minecraft.sounds.SoundSource.BLOCKS,
                        1.0f,
                        1.0f
                );

                net.minecraft.network.chat.TextComponent message =
                        new net.minecraft.network.chat.TextComponent(
                                "String colored: " + dyeColor.getDisplayName()
                        );
                message.withStyle(net.minecraft.ChatFormatting.GREEN);
                if (player instanceof net.minecraft.server.level.ServerPlayer) {
                    com.kingodogo.buildscape.network.ModMessages.INSTANCE.send(
                            net.minecraftforge.network.PacketDistributor.PLAYER.with(() ->
                                    (net.minecraft.server.level.ServerPlayer) player
                            ),
                            new com.kingodogo.buildscape.network.ActionBarMessagePacket(message)
                    );
                }

                return InteractionResult.SUCCESS;
            }
        }

        boolean currentLit = state.getValue(LIT);
        BlockState newState = state.setValue(LIT, !currentLit);
        level.setBlock(pos, newState, 3);

        level.playSound(
                null,
                pos,
                currentLit
                        ? net.minecraft.sounds.SoundEvents.STONE_BUTTON_CLICK_OFF
                        : net.minecraft.sounds.SoundEvents.STONE_BUTTON_CLICK_ON,
                net.minecraft.sounds.SoundSource.BLOCKS,
                0.3f,
                1.0f
        );

        return InteractionResult.SUCCESS;
    }

    private StringColor getDyeColor(ItemStack stack) {
        if (stack == null || stack.isEmpty()) {
            return null;
        }

        net.minecraft.world.item.Item item = stack.getItem();

        if (item == net.minecraft.world.item.Items.WHITE_DYE) {
            return StringColor.WHITE;
        } else if (item == net.minecraft.world.item.Items.ORANGE_DYE) {
            return StringColor.ORANGE;
        } else if (item == net.minecraft.world.item.Items.MAGENTA_DYE) {
            return StringColor.MAGENTA;
        } else if (item == net.minecraft.world.item.Items.LIGHT_BLUE_DYE) {
            return StringColor.LIGHT_BLUE;
        } else if (item == net.minecraft.world.item.Items.YELLOW_DYE) {
            return StringColor.YELLOW;
        } else if (item == net.minecraft.world.item.Items.LIME_DYE) {
            return StringColor.LIME;
        } else if (item == net.minecraft.world.item.Items.PINK_DYE) {
            return StringColor.PINK;
        } else if (item == net.minecraft.world.item.Items.GRAY_DYE) {
            return StringColor.GRAY;
        } else if (item == net.minecraft.world.item.Items.LIGHT_GRAY_DYE) {
            return StringColor.LIGHT_GRAY;
        } else if (item == net.minecraft.world.item.Items.CYAN_DYE) {
            return StringColor.CYAN;
        } else if (item == net.minecraft.world.item.Items.PURPLE_DYE) {
            return StringColor.PURPLE;
        } else if (item == net.minecraft.world.item.Items.BLUE_DYE) {
            return StringColor.BLUE;
        } else if (item == net.minecraft.world.item.Items.BROWN_DYE) {
            return StringColor.BROWN;
        } else if (item == net.minecraft.world.item.Items.GREEN_DYE) {
            return StringColor.GREEN;
        } else if (item == net.minecraft.world.item.Items.RED_DYE) {
            return StringColor.RED;
        } else if (item == net.minecraft.world.item.Items.BLACK_DYE) {
            return StringColor.BLACK;
        }

        return null;
    }
}

