public class PetalBlock extends BushBlock implements BonemealableBlock {

    public static final IntegerProperty FLOWER_AMOUNT = IntegerProperty.create(
            "flower_amount",
            1,
            4
    );
    public static final DirectionProperty FACING =
            BlockStateProperties.HORIZONTAL_FACING;

    private static SoundType cachedSoundType = null;

    private static SoundType getFlowerBedSounds() {
        if (cachedSoundType == null) {
            cachedSoundType =
                    com.kingodogo.buildscape.sound.ModSounds.FLOWER_BED_SOUNDS();
        }
        return cachedSoundType;
    }

    private static final VoxelShape SHAPE_1_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            8.0D,
            3.0D,
            8.0D
    );
    private static final VoxelShape SHAPE_2_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            8.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_3_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_SOUTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    private static final VoxelShape COLLISION_SHAPE = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape INSIDE_SHAPE = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            16.0D,
            16.0D
    );

    private static final VoxelShape SHAPE_1_NORTH = Block.box(
            8.0D,
            0.0D,
            8.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_2_NORTH = Block.box(
            8.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_3_NORTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_NORTH = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    private static final VoxelShape SHAPE_1_EAST = Block.box(
            0.0D,
            0.0D,
            8.0D,
            8.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_2_EAST = Block.box(
            0.0D,
            0.0D,
            8.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_3_EAST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_EAST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    private static final VoxelShape SHAPE_1_WEST = Block.box(
            8.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            8.0D
    );
    private static final VoxelShape SHAPE_2_WEST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            8.0D
    );
    private static final VoxelShape SHAPE_3_WEST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );
    private static final VoxelShape SHAPE_4_WEST = Block.box(
            0.0D,
            0.0D,
            0.0D,
            16.0D,
            3.0D,
            16.0D
    );

    public PetalBlock(BlockBehaviour.Properties properties) {
        super(properties);
        this.registerDefaultState(
                this.stateDefinition.any()
                        .setValue(FLOWER_AMOUNT, 1)
                        .setValue(FACING, Direction.SOUTH)
        );
    }

    @Override
    public SoundType getSoundType(BlockState state) {
        return getFlowerBedSounds();
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        builder.add(FLOWER_AMOUNT, FACING);
    }

    @Override
    public VoxelShape getShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        int stage = state.getValue(FLOWER_AMOUNT);
        Direction facing = state.getValue(FACING);

        return switch (facing) {
            case NORTH -> switch (stage) {
                case 1 -> SHAPE_1_NORTH;
                case 2 -> SHAPE_2_NORTH;
                case 3 -> SHAPE_3_NORTH;
                default -> SHAPE_4_NORTH;
            };
            case EAST -> switch (stage) {
                case 1 -> SHAPE_1_EAST;
                case 2 -> SHAPE_2_EAST;
                case 3 -> SHAPE_3_EAST;
                default -> SHAPE_4_EAST;
            };
            case WEST -> switch (stage) {
                case 1 -> SHAPE_1_WEST;
                case 2 -> SHAPE_2_WEST;
                case 3 -> SHAPE_3_WEST;
                default -> SHAPE_4_WEST;
            };
            default -> switch (stage) {
                case 1 -> SHAPE_1_SOUTH;
                case 2 -> SHAPE_2_SOUTH;
                case 3 -> SHAPE_3_SOUTH;
                default -> SHAPE_4_SOUTH;
            };
        };
    }

    @Override
    public VoxelShape getCollisionShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return Shapes.empty();
    }

    @Override
    public void entityInside(
            BlockState state,
            Level level,
            BlockPos pos,
            Entity entity
    ) {
        if (
                entity instanceof Player player &&
                        player.isOnGround() &&
                        level.isClientSide
        ) {
            float stepInterval = 2.0f;
            int currentStep = (int) (player.walkDist / stepInterval);
            int lastStep = (int) (player.walkDistO / stepInterval);

            if (currentStep != lastStep && player.walkDist > player.walkDistO) {
                SoundType sounds = getFlowerBedSounds();
                float volume = 0.25f;
                float pitch = 1.2f;
                if (sounds instanceof CustomSoundType customSounds) {
                    volume = customSounds.getStepVolume();
                    pitch = customSounds.getStepPitch();
                }

                level.playLocalSound(
                        pos.getX() + 0.5,
                        pos.getY() + 0.5,
                        pos.getZ() + 0.5,
                        sounds.getStepSound(),
                        SoundSource.BLOCKS,
                        volume,
                        pitch,
                        false
                );
            }
        }
        super.entityInside(state, level, pos, entity);
    }

    @Override
    protected boolean mayPlaceOn(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        return (
                state.isFaceSturdy(level, pos, Direction.UP) &&
                        state.getMaterial().isSolid() &&
                        !state.getMaterial().isReplaceable()
        );
    }

    @Override
    public boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        BlockPos belowPos = pos.below();
        BlockState belowState = level.getBlockState(belowPos);
        return this.mayPlaceOn(belowState, level, belowPos);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        BlockState state = super.getStateForPlacement(context);
        if (
                state != null &&
                        this.canSurvive(state, context.getLevel(), context.getClickedPos())
        ) {
            Direction playerFacing = context.getHorizontalDirection();
            return state.setValue(FLOWER_AMOUNT, 1).setValue(FACING, playerFacing);
        }
        return null;
    }

    @Override
    public BlockState rotate(BlockState state, Rotation rotation) {
        return state.setValue(FACING, rotation.rotate(state.getValue(FACING)));
    }

    @Override
    public BlockState mirror(BlockState state, Mirror mirror) {
        return state.rotate(mirror.getRotation(state.getValue(FACING)));
    }

    @Override
    public InteractionResult use(
            BlockState state,
            Level level,
            BlockPos pos,
            Player player,
            InteractionHand hand,
            BlockHitResult hit
    ) {
        ItemStack itemStack = player.getItemInHand(hand);

        if (itemStack.getItem() instanceof BlockItem) {
            BlockItem blockItem = (BlockItem) itemStack.getItem();
            if (
                    blockItem.getBlock() instanceof PetalBlock &&
                            blockItem.getBlock() == this
            ) {
                int currentAmount = state.getValue(FLOWER_AMOUNT);
                if (currentAmount < 4) {
                    if (!level.isClientSide) {
                        level.setBlock(
                                pos,
                                state.setValue(FLOWER_AMOUNT, currentAmount + 1),
                                3
                        );
                        if (!player.getAbilities().instabuild) {
                            itemStack.shrink(1);
                        }
                    }
                    SoundType sounds = getFlowerBedSounds();
                    level.playSound(
                            player,
                            pos,
                            sounds.getPlaceSound(),
                            SoundSource.BLOCKS,
                            sounds.getVolume(),
                            sounds.getPitch()
                    );
                    return InteractionResult.sidedSuccess(level.isClientSide);
                }
            }
        }

        return InteractionResult.PASS;
    }

    @Override
    public boolean isValidBonemealTarget(
            BlockGetter level,
            BlockPos pos,
            BlockState state,
            boolean isClient
    ) {
        return true;
    }

    @Override
    public boolean isBonemealSuccess(
            Level level,
            Random random,
            BlockPos pos,
            BlockState state
    ) {
        return true;
    }

    @Override
    public void performBonemeal(
            ServerLevel level,
            Random random,
            BlockPos pos,
            BlockState state
    ) {
        int currentStage = state.getValue(FLOWER_AMOUNT);

        if (currentStage < 4) {
            level.setBlock(pos, state.setValue(FLOWER_AMOUNT, currentStage + 1), 3);
        } else {
            ItemStack petalStack = new ItemStack(this, 1);
            ItemEntity itemEntity = new ItemEntity(
                    level,
                    pos.getX() + 0.5D,
                    pos.getY() + 0.5D,
                    pos.getZ() + 0.5D,
                    petalStack
            );
            itemEntity.setDefaultPickUpDelay();
            level.addFreshEntity(itemEntity);
        }
    }

    @Override
    public List<ItemStack> getDrops(
            BlockState state,
            LootContext.Builder builder
    ) {
        int stage = state.getValue(FLOWER_AMOUNT);
        return Collections.singletonList(new ItemStack(this, stage));
    }

    @Override
    public VoxelShape getVisualShape(
            BlockState state,
            BlockGetter level,
            BlockPos pos,
            CollisionContext context
    ) {
        return Shapes.empty();
    }

    @Override
    public boolean useShapeForLightOcclusion(BlockState state) {
        return false;
    }

    @Override
    public int getLightBlock(BlockState state, BlockGetter level, BlockPos pos) {
        return 0;
    }

    @Override
    public boolean propagatesSkylightDown(
            BlockState state,
            BlockGetter reader,
            BlockPos pos
    ) {
        return true;
    }

    @Override
    public float getShadeBrightness(
            BlockState state,
            BlockGetter level,
            BlockPos pos
    ) {
        return 1.0F;
    }

    @Override
    public boolean skipRendering(
            BlockState state,
            BlockState adjacentBlockState,
            Direction side
    ) {
        return (
                adjacentBlockState.is(this) ||
                        super.skipRendering(state, adjacentBlockState, side)
        );
    }
}

package com.kingodogo.buildscape.block;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.context.BlockPlaceContext;
import net.minecraft.world.level.BlockGetter;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.LevelAccessor;
import net.minecraft.world.level.LevelReader;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.RenderShape;
import net.minecraft.world.level.block.SimpleWaterloggedBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.block.state.StateDefinition;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.block.state.properties.BooleanProperty;
import net.minecraft.world.level.block.state.properties.EnumProperty;
import net.minecraft.world.level.material.FluidState;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.level.storage.loot.LootContext;
import net.minecraft.world.phys.shapes.CollisionContext;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

import java.util.List;

public class PillarBlock
        extends Block
        implements EntityBlock, SimpleWaterloggedBlock {

    public static final BooleanProperty WATERLOGGED =
            BlockStateProperties.WATERLOGGED;
    private static final ThreadLocal<Float> PLACING_PLAYER_YAW =
            new ThreadLocal<>();

    private static final VoxelShape SHAPE_SINGLE = Shapes.or(
            Block.box(2, 0, 2, 14, 2, 14),
            Block.box(3, 2, 3, 13, 14, 13),
            Block.box(0, 14, 0, 16, 16, 16)
    );
    private static final VoxelShape SHAPE_BOTTOM = Shapes.or(
            Block.box(2, 0, 2, 14, 2, 14),
            Block.box(3, 2, 3, 13, 16, 13)
    );
    private static final VoxelShape SHAPE_MIDDLE = Block.box(3, 0, 3, 13, 16, 13);
    private static final VoxelShape SHAPE_TOP = Shapes.or(
            Block.box(3, 0, 3, 13, 14, 13),
            Block.box(0, 14, 0, 16, 16, 16)
    );
    public static final EnumProperty<PillarPart> PART = EnumProperty.create(
            "part",
            PillarPart.class
    );

    public PillarBlock(Properties properties) {
        super(properties);
        this.registerDefaultState(
                this.stateDefinition.any()
                        .setValue(PART, PillarPart.SINGLE)
                        .setValue(WATERLOGGED, false)
        );
    }

    @Override
    protected void createBlockStateDefinition(
            StateDefinition.Builder<Block, BlockState> builder
    ) {
        builder.add(PART, WATERLOGGED);
    }

    @Override
    public BlockState getStateForPlacement(BlockPlaceContext context) {
        Level level = context.getLevel();
        BlockPos pos = context.getClickedPos();
        BlockState above = level.getBlockState(pos.above());
        BlockState below = level.getBlockState(pos.below());

        if (!level.isClientSide) {
            net.minecraft.world.entity.player.Player player = context.getPlayer();
            if (player != null) {
                float playerYaw = player.getYRot();
                float facingYaw = (playerYaw + 180.0f) % 360.0f;
                if (facingYaw < 0) {
                    facingYaw += 360.0f;
                }
                PLACING_PLAYER_YAW.set(facingYaw);
            } else {
                PLACING_PLAYER_YAW.set(null);
            }
        }

        boolean hasAbove = above.getBlock() instanceof PillarBlock;
        boolean hasBelow = below.getBlock() instanceof PillarBlock;

        if (!level.isClientSide) {
            if (hasBelow && !hasAbove) {
                if (
                        level.getBlockEntity(pos.below()) instanceof PillarBlockEntity be &&
                                be.hasDisplayItem()
                ) {
                    ItemStack item = be.getDisplayedItem().copy();
                    be.setDisplayedItem(ItemStack.EMPTY);
                    net.minecraft.world.entity.item.ItemEntity itemEntity =
                            new net.minecraft.world.entity.item.ItemEntity(
                                    level,
                                    pos.getX() + 0.5,
                                    pos.getY() + 0.5,
                                    pos.getZ() + 0.5,
                                    item
                            );
                    itemEntity.setDefaultPickUpDelay();
                    level.addFreshEntity(itemEntity);
                }
            } else if (hasAbove && !hasBelow) {
                if (
                        level.getBlockEntity(pos.above()) instanceof PillarBlockEntity be &&
                                be.hasDisplayItem()
                ) {
                    ItemStack item = be.getDisplayedItem().copy();
                    be.setDisplayedItem(ItemStack.EMPTY);
                    net.minecraft.world.entity.item.ItemEntity itemEntity =
                            new net.minecraft.world.entity.item.ItemEntity(
                                    level,
                                    pos.getX() + 0.5,
                                    pos.getY() + 0.5,
                                    pos.getZ() + 0.5,
                                    item
                            );
                    itemEntity.setDefaultPickUpDelay();
                    level.addFreshEntity(itemEntity);
                }
            }
        }

        PillarPart part;
        if (hasAbove && hasBelow) {
            part = PillarPart.MIDDLE;
        } else if (hasBelow) {
            part = PillarPart.TOP;
        } else if (hasAbove) {
            part = PillarPart.BOTTOM;
        } else {
            part = PillarPart.SINGLE;
        }

        FluidState fluidstate = context
                .getLevel()
                .getFluidState(context.getClickedPos());
        return this.defaultBlockState()
                .setValue(PART, part)
                .setValue(WATERLOGGED, fluidstate.getType() == Fluids.WATER);
    }

    @Override
    public BlockState updateShape(
            BlockState state,
            Direction direction,
            BlockState neighborState,
            LevelAccessor level,
            BlockPos pos,
            BlockPos neighborPos
    ) {
        if (state.getValue(WATERLOGGED)) {
            level.scheduleTick(pos, Fluids.WATER, Fluids.WATER.getTickDelay(level));
        }

        if (direction == Direction.UP || direction == Direction.DOWN) {
            BlockState below = level.getBlockState(pos.below());
            BlockState above = level.getBlockState(pos.above());
            boolean hasAbove = above.getBlock() instanceof PillarBlock;
            boolean hasBelow = below.getBlock() instanceof PillarBlock;

            PillarPart newPart;
            if (hasAbove && hasBelow) {
                newPart = PillarPart.MIDDLE;
            } else if (hasBelow) {
                newPart = PillarPart.TOP;
            } else if (hasAbove) {
                newPart = PillarPart.BOTTOM;
            } else {
                newPart = PillarPart.SINGLE;
            }

            return state.setValue(PART, newPart);
        }
        return super.updateShape(
                state,
                direction,
                neighborState,
                level,
                pos,
                neighborPos
        );
    }

    @Override
    public boolean canSurvive(BlockState state, LevelReader level, BlockPos pos) {
        return super.canSurvive(state, level, pos);
    }

    @Override
    public void onPlace(
            BlockState state,
            Level level,
            BlockPos pos,
            BlockState oldState,
            boolean isMoving
    ) {

        if (!level.isClientSide) {
            BlockEntity be = level.getBlockEntity(pos);
            if (be instanceof PillarBlockEntity pillarBE) {
                Float storedYaw = PLACING_PLAYER_YAW.get();
                if (storedYaw != null) {
                    pillarBE.setFacingYaw(storedYaw);
                    PLACING_PLAYER_YAW.set(null);
                }
            }

            enforceSingleItemPerStack(level, pos);

            syncNewPillarWithStack(level, pos);

            BlockPos above = pos.above();
            BlockPos below = pos.below();
            if (level.getBlockState(above).getBlock() instanceof PillarBlock) {
                level.sendBlockUpdated(
                        above,
                        level.getBlockState(above),
                        level.getBlockState(above),
                        3
                );
            }
            if (level.getBlockState(below).getBlock() instanceof PillarBlock) {
                level.sendBlockUpdated(
                        below,
                        level.getBlockState(below),
                        level.getBlockState(below),
                        3
                );
            }
        }
    }

    private void syncNewPillarWithStack(Level level, BlockPos pos) {
        if (
                !level.isClientSide &&
                        !com.kingodogo.buildscape.BuildScape.isServerFullyInitialized()
        ) {
            return;
        }

        if (
                !level.isClientSide &&
                        (level.getServer() == null ||
                                !level.getServer().isRunning() ||
                                level.getServer().getPlayerList().getPlayerCount() == 0)
        ) {
            return;
        }

        BlockEntity be = level.getBlockEntity(pos);
        if (!(be instanceof PillarBlockEntity newPillarBE)) return;

        BlockPos above = pos.above();
        BlockPos below = pos.below();
        PillarBlockEntity existingPillar = null;

        try {
            if (!level.isClientSide) {
                if (level.hasChunkAt(above)) {
                    net.minecraft.world.level.chunk.ChunkAccess chunk = level.getChunk(
                            above
                    );
                    if (
                            chunk instanceof net.minecraft.world.level.chunk.LevelChunk &&
                                    chunk
                                            .getStatus()
                                            .isOrAfter(net.minecraft.world.level.chunk.ChunkStatus.FULL)
                    ) {
                        if (level.getBlockState(above).getBlock() instanceof PillarBlock) {
                            BlockEntity aboveBE = level.getBlockEntity(above);
                            if (
                                    aboveBE instanceof PillarBlockEntity pillarBE &&
                                            pillarBE.hasCustomColors()
                            ) {
                                existingPillar = pillarBE;
                            }
                        }
                    }
                }

                if (existingPillar == null && level.hasChunkAt(below)) {
                    net.minecraft.world.level.chunk.ChunkAccess chunk = level.getChunk(
                            below
                    );
                    if (
                            chunk instanceof net.minecraft.world.level.chunk.LevelChunk &&
                                    chunk
                                            .getStatus()
                                            .isOrAfter(net.minecraft.world.level.chunk.ChunkStatus.FULL)
                    ) {
                        if (level.getBlockState(below).getBlock() instanceof PillarBlock) {
                            BlockEntity belowBE = level.getBlockEntity(below);
                            if (
                                    belowBE instanceof PillarBlockEntity pillarBE &&
                                            pillarBE.hasCustomColors()
                            ) {
                                existingPillar = pillarBE;
                            }
                        }
                    }
                }
            } else {
                if (level.getBlockState(above).getBlock() instanceof PillarBlock) {
                    BlockEntity aboveBE = level.getBlockEntity(above);
                    if (
                            aboveBE instanceof PillarBlockEntity pillarBE &&
                                    pillarBE.hasCustomColors()
                    ) {
                        existingPillar = pillarBE;
                    }
                }
                if (
                        existingPillar == null &&
                                level.getBlockState(below).getBlock() instanceof PillarBlock
                ) {
                    BlockEntity belowBE = level.getBlockEntity(below);
                    if (
                            belowBE instanceof PillarBlockEntity pillarBE &&
                                    pillarBE.hasCustomColors()
                    ) {
                        existingPillar = pillarBE;
                    }
                }
            }
        } catch (Exception e) {
            return;
        }

        if (existingPillar != null) {
            String stackId = existingPillar.getPillarId();
            java.util.List<String> stackColors = existingPillar.getParticleColors();

            if (stackId != null && stackColors != null && !stackColors.isEmpty()) {
                if (
                        !level.isClientSide &&
                                com.kingodogo.buildscape.BuildScape.isServerFullyInitialized()
                ) {
                    com.kingodogo.buildscape.config.PillarIdManager manager =
                            com.kingodogo.buildscape.config.PillarIdManager.get();
                    com.kingodogo.buildscape.config.PillarIdManager.PillarData data =
                            manager.getPillarData(stackId);

                    if (data != null) {
                        BlockPos bottom = findBottomBlock(level, pos);
                        data.x = bottom.getX();
                        data.y = bottom.getY();
                        data.z = bottom.getZ();
                        manager.saveImmediate();
                    }
                }

                newPillarBE.forceSetColors(stackColors, stackId);
            }
        }
    }

    @Override
    public List<ItemStack> getDrops(
            BlockState state,
            LootContext.Builder builder
    ) {
        List<ItemStack> drops = super.getDrops(state, builder);

        LootContext lootContext = builder
                .withParameter(
                        net.minecraft.world.level.storage.loot.parameters.LootContextParams.BLOCK_STATE,
                        state
                )
                .create(
                        net.minecraft.world.level.storage.loot.parameters.LootContextParamSets.BLOCK
                );

        net.minecraft.world.phys.Vec3 origin = lootContext.getParamOrNull(
                net.minecraft.world.level.storage.loot.parameters.LootContextParams.ORIGIN
        );
        if (origin != null) {
            BlockPos pos = new BlockPos(origin);
            net.minecraft.world.level.Level level = lootContext.getLevel();
            if (level != null) {
                BlockEntity be = level.getBlockEntity(pos);
                if (
                        be instanceof PillarBlockEntity pillarBE && pillarBE.hasDisplayItem()
                ) {
                    ItemStack displayedItem = pillarBE.getDisplayedItem().copy();
                    if (!displayedItem.isEmpty()) {
                        drops.add(displayedItem);
                    }
                }
            }
        }

        return drops;
    }

    @Override
    public void onRemove(
            BlockState state,
            Level level,
            BlockPos pos,
            BlockState newState,
            boolean isMoving
    ) {
        if (
                !level.isClientSide &&
                        !state.is(newState.getBlock()) &&
                        com.kingodogo.buildscape.BuildScape.isServerFullyInitialized()
        ) {
            BlockEntity be = level.getBlockEntity(pos);
            String pillarIdToPreserve = null;
            java.util.List<String> colorsToPreserve = null;

            if (be instanceof PillarBlockEntity pillarBE) {
                pillarIdToPreserve = pillarBE.getPillarId();
                colorsToPreserve = pillarBE.getParticleColors();

                if (pillarBE.hasDisplayItem()) {
                    ItemStack displayedItem = pillarBE.getDisplayedItem().copy();
                    if (!displayedItem.isEmpty()) {
                        net.minecraft.world.entity.item.ItemEntity itemEntity =
                                new net.minecraft.world.entity.item.ItemEntity(
                                        level,
                                        pos.getX() + 0.5,
                                        pos.getY() + 0.5,
                                        pos.getZ() + 0.5,
                                        displayedItem
                                );
                        itemEntity.setDefaultPickUpDelay();
                        level.addFreshEntity(itemEntity);
                    }
                }

                pillarBE.clearLocalStateOnly();
            }

            BlockPos bottom = findBottomBlock(level, pos);
            BlockPos top = findTopBlock(level, pos);
            boolean hasOtherPillars = false;
            BlockPos firstRemainingPillar = null;

            BlockPos current = bottom;
            while (level.getBlockState(current).getBlock() instanceof PillarBlock) {
                if (!current.equals(pos)) {
                    hasOtherPillars = true;
                    if (firstRemainingPillar == null) {
                        firstRemainingPillar = current;
                    }
                }
                if (current.equals(top)) break;
                current = current.above();
            }

            if (hasOtherPillars && firstRemainingPillar != null) {
                BlockEntity remainingBe = level.getBlockEntity(firstRemainingPillar);
                if (remainingBe instanceof PillarBlockEntity remainingPillarBE) {
                    if (
                            colorsToPreserve != null &&
                                    !colorsToPreserve.isEmpty() &&
                                    pillarIdToPreserve != null
                    ) {
                        remainingPillarBE.forceSetColors(
                                colorsToPreserve,
                                pillarIdToPreserve
                        );

                        com.kingodogo.buildscape.config.PillarIdManager manager =
                                com.kingodogo.buildscape.config.PillarIdManager.get();
                        com.kingodogo.buildscape.config.PillarIdManager.PillarData data =
                                manager.getPillarData(pillarIdToPreserve);
                        if (data != null) {
                            data.x = firstRemainingPillar.getX();
                            data.y = firstRemainingPillar.getY();
                            data.z = firstRemainingPillar.getZ();
                            manager.saveImmediate();
                        }

                        current = bottom;
                        while (
                                level.getBlockState(current).getBlock() instanceof PillarBlock
                        ) {
                            if (!current.equals(pos)) {
                                BlockEntity currentBe = level.getBlockEntity(current);
                                if (
                                        currentBe instanceof PillarBlockEntity stackPillarBE &&
                                                !current.equals(firstRemainingPillar)
                                ) {
                                    stackPillarBE.forceSetColors(
                                            colorsToPreserve,
                                            pillarIdToPreserve
                                    );
                                }
                            }
                            if (current.equals(top)) break;
                            current = current.above();
                        }
                    }
                }

                com.kingodogo.buildscape.config.PillarIdManager manager =
                        com.kingodogo.buildscape.config.PillarIdManager.get();
                manager.removePillarByPosition(level, pos);
            } else {
                com.kingodogo.buildscape.config.PillarIdManager manager =
                        com.kingodogo.buildscape.config.PillarIdManager.get();
                if (pillarIdToPreserve != null && !pillarIdToPreserve.isEmpty()) {
                    manager.removePillar(pillarIdToPreserve);
                }
                manager.removePillarByPosition(level, pos);
            }
        }

        super.onRemove(state, level, pos, newState, isMoving);

        if (!level.isClientSide) {
            BlockPos above = pos.above();
            BlockPos below = pos.below();
            BlockState aboveState = level.getBlockState(above);
            BlockState belowState = level.getBlockState(below);

            if (aboveState.getBlock() instanceof PillarBlock) {
                level.sendBlockUpdated(above, aboveState, aboveState, 3);
            }
            if (belowState.getBlock() instanceof PillarBlock) {
                level.sendBlockUpdated(below, belowState, belowState, 3);
            }
        }
    }

    @Override
    public void neighborChanged(
            BlockState state,
            Level level,
            BlockPos pos,
            Block block,
            BlockPos neighborPos,
            boolean isMoving
    ) {
        if (neighborPos.equals(pos.above()) || neighborPos.equals(pos.below())) {
            if (!level.isClientSide) {
                BlockState below = level.getBlockState(pos.below());
                BlockState above = level.getBlockState(pos.above());
                boolean hasAbove = above.getBlock() instanceof PillarBlock;
                boolean hasBelow = below.getBlock() instanceof PillarBlock;

                PillarPart newPart;
                if (hasAbove && hasBelow) {
                    newPart = PillarPart.MIDDLE;
                } else if (hasBelow) {
                    newPart = PillarPart.TOP;
                } else if (hasAbove) {
                    newPart = PillarPart.BOTTOM;
                } else {
                    newPart = PillarPart.SINGLE;
                }

                if (state.getValue(PART) != newPart) {
                    level.setBlock(pos, state.setValue(PART, newPart), 3);
                }

                enforceSingleItemPerStack(level, pos);
            }
        }
    }

