            if (idToRemove != null && !idToRemove.isEmpty()) {
                manager.removePillar(idToRemove);
            }

            manager.removePillarByPosition(level, worldPosition);

            level.sendBlockUpdated(
                    worldPosition,
                    getBlockState(),
                    getBlockState(),
                    3
            );
        }
    }

