import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.ClientPlayerNetworkEvent;
import net.minecraftforge.client.event.RenderGameOverlayEvent;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.world.WorldEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(
        modid = com.kingodogo.buildscape.BuildScape.MODID,
        bus = Mod.EventBusSubscriber.Bus.FORGE,
        value = Dist.CLIENT
)
public class ClientEvents {

    private static boolean wasPressed = false;
    private static boolean wasZoomKeyPressed = false;

    private static Component overlayMessage = null;
    private static long overlayMessageTime = 0;
    private static final long OVERLAY_DURATION = 5000;

    private static int lastHedgeStep = -1;

    public static void setOverlayMessage(Component message) {
        overlayMessage = message;
        overlayMessageTime = System.currentTimeMillis();
    }

    public static void resetAllPillarParticles() {
        Minecraft mc = Minecraft.getInstance();
        if (mc.level == null || mc.player == null) return;

        net.minecraft.core.BlockPos playerPos = mc.player.blockPosition();
        int chunkX = playerPos.getX() >> 4;
        int chunkZ = playerPos.getZ() >> 4;

        for (int x = -8; x <= 8; x++) {
            for (int z = -8; z <= 8; z++) {
                net.minecraft.world.level.chunk.LevelChunk chunk = mc.level.getChunk(
                        chunkX + x,
                        chunkZ + z
                );
                if (chunk != null) {
                    for (BlockEntity be : chunk.getBlockEntities().values()) {
                        if (
                                be instanceof PillarBlockEntity pillarBE &&
                                        pillarBE.hasDisplayItem()
                        ) {
                            pillarBE.resetParticleTick(true);
                        }
                    }
                }
            }
        }
    }

    public static void initializeConfigCallback() {
        PillarParticleConfig.addConfigReloadCallback((isRemote) -> {
            if (Minecraft.getInstance().level != null) {
                Minecraft.getInstance()
                        .execute(() -> {
                            resetAllPillarParticles();
                        });
            }
        });
    }

    @SubscribeEvent
    public static void onRenderGameOverlay(RenderGameOverlayEvent.Post event) {
        if (event.getType() != RenderGameOverlayEvent.ElementType.ALL) return;

        int screenWidth = event.getWindow().getGuiScaledWidth();
        int screenHeight = event.getWindow().getGuiScaledHeight();

        renderOverlay(event.getMatrixStack(), screenWidth, screenHeight);
    }

    public static void renderOverlay(com.mojang.blaze3d.vertex.PoseStack poseStack, int screenWidth, int screenHeight) {
        Minecraft mc = Minecraft.getInstance();

        if (overlayMessage != null) {
            long currentTime = System.currentTimeMillis();
            long elapsed = currentTime - overlayMessageTime;

            // 5 seconds duration (5000 ms)
            if (elapsed > 5000) {
                overlayMessage = null;
                return;
            }

            int x = screenWidth / 2;
            int y = screenHeight / 2;

            poseStack.pushPose();
            poseStack.translate(0, 0, 500); // Translate Z first to be safe

            // Pop animation
            float elapsedSeconds = elapsed / 1000.0f;
            float scale = 1.0f;

            if (elapsedSeconds < 0.25f) {
                // Pop in (0 to 0.25s)
                scale = (elapsedSeconds / 0.25f) * 1.2f;
            } else if (elapsedSeconds < 0.4f) {
                // Settle back to 1.0 (0.25s to 0.4s)
                scale = 1.2f - ((elapsedSeconds - 0.25f) / 0.15f) * 0.2f;
            }

            poseStack.translate(x, y, 0);
            poseStack.scale(scale, scale, 1.0f);
            poseStack.translate(-x, -y, 0);

            com.mojang.blaze3d.systems.RenderSystem.disableDepthTest();
            GuiComponent.drawCenteredString(
                    poseStack,
                    mc.font,
                    overlayMessage,
                    x,
                    y,
                    0xFFFF5555 // Red with full Alpha 
            );
            com.mojang.blaze3d.systems.RenderSystem.enableDepthTest();

            poseStack.popPose();
        }
    }

    @SubscribeEvent
    public static void onClientTick(TickEvent.ClientTickEvent event) {
        if (event.phase != TickEvent.Phase.END) {
            return;
        }

        Minecraft mc = Minecraft.getInstance();
        if (mc.level == null || mc.player == null || mc.isPaused()) {
            return;
        }

        net.minecraft.world.entity.player.Player player = mc.player;
        if (player.isOnGround()) {
            BlockPos playerBlockPos = player.blockPosition();
            BlockPos blockBelowPlayer = playerBlockPos.below();
            BlockState blockBelow = mc.level.getBlockState(blockBelowPlayer);

            if (blockBelow.getBlock() instanceof LeafHedgeBlock) {
                double playerY = player.getY();
                double blockTopY = blockBelowPlayer.getY() + 1.0;

                if (playerY >= blockTopY - 0.3 && playerY <= blockTopY + 0.5) {
                    float stepInterval = 2.0f;
                    int currentStep = (int) (player.walkDist / stepInterval);

                    if (
                            currentStep != lastHedgeStep && player.walkDist > player.walkDistO
                    ) {
                        lastHedgeStep = currentStep;

                        SoundType sounds = blockBelow.getSoundType();
                        net.minecraft.sounds.SoundEvent stepSound = sounds.getStepSound();
                        float volume = 0.15f;
                        float pitch = 1.0f;

                        if (
                                sounds instanceof com.kingodogo.buildscape.block.CustomSoundType
                        ) {
                            com.kingodogo.buildscape.block.CustomSoundType customSounds =
                                    (com.kingodogo.buildscape.block.CustomSoundType) sounds;
                            volume = customSounds.getStepVolume();
                            pitch = customSounds.getStepPitch();
                        }

                        mc.level.playLocalSound(
                                blockBelowPlayer.getX() + 0.5,
                                blockBelowPlayer.getY() + 0.5,
                                blockBelowPlayer.getZ() + 0.5,
                                stepSound,
                                SoundSource.BLOCKS,
                                volume,
                                pitch,
                                false
                        );
                    }
                }
            } else {
                if (lastHedgeStep != -1) {
                    lastHedgeStep = -1;
                }
            }
        }
    }

    @SubscribeEvent
    public static void onClientDisconnect(
            ClientPlayerNetworkEvent.LoggedOutEvent event
    ) {
        overlayMessage = null;
        overlayMessageTime = 0;
        wasPressed = false;
        lastHedgeStep = -1;

        wasZoomKeyPressed = false;

        // Reset SupportersTabState on logout
        com.kingodogo.buildscape.client.screen.tabs.supporters.SupportersTabState.getInstance().setPlayerUuid(null);

        // Clear particle trail tracking
        com.kingodogo.buildscape.client.ParticleTrailHandler.clearTracking();

        com.kingodogo.buildscape.config.PillarParticleConfig.clearServerConfig();
    }

    @SubscribeEvent
    public static void onClientJoin(ClientPlayerNetworkEvent.LoggedInEvent event) {
        // LoggedInEvent is good for triggering, but we might need mc.player to be ready
        // We'll also check in onClientTick or use another event to be sure
    }

    @SubscribeEvent
    public static void onEntityJoinWorld(net.minecraftforge.event.entity.EntityJoinWorldEvent event) {
        if (event.getWorld().isClientSide && event.getEntity() == Minecraft.getInstance().player) {
            // Local player has joined the world - initialize cosmetics
            Minecraft mc = Minecraft.getInstance();
            if (mc.player != null) {
                com.kingodogo.buildscape.client.screen.tabs.supporters.SupportersTabState.getInstance()
                        .setPlayerUuid(mc.player.getUUID());
            }
        }
    }

    @SubscribeEvent
    public static void onClientWorldUnload(WorldEvent.Unload event) {
        overlayMessage = null;
        overlayMessageTime = 0;
        wasPressed = false;
        wasZoomKeyPressed = false;
        lastHedgeStep = -1;

        // Clear particle trail tracking
        com.kingodogo.buildscape.client.ParticleTrailHandler.clearTracking();

        try {
            com.kingodogo.buildscape.client.renderer.PillarBlockEntityRenderer.clearEntityCache();
            com.kingodogo.buildscape.particle.TintedDripParticle.clearColorCache();
            com.kingodogo.buildscape.event.ItemFrameParticleHandler.clearCaches();
            com.kingodogo.buildscape.config.PillarParticleConfig.clearServerConfig();
        } catch (Exception e) {
            System.err.println(
                    "BuildScape: Error clearing caches on world unload: " + e.getMessage()
            );
        }
    }
}

package com.kingodogo.buildscape.client;

import com.kingodogo.buildscape.config.CosmeticsConfig;
import com.kingodogo.buildscape.cosmetics.CosmeticRegistry;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.Minecraft;
import net.minecraft.client.model.geom.builders.PartDefinition;
import net.minecraft.client.player.AbstractClientPlayer;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.entity.player.PlayerRenderer;
import net.minecraft.world.entity.EquipmentSlot;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.RenderLevelStageEvent;
import net.minecraftforge.client.event.RenderLivingEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import java.util.Map;

/**
 * Handles rendering of cosmetic items as overlays on the player.
 * Cosmetics render on top of vanilla armor as a separate layer.
 * Supports a toggle to render only cosmetics (hide vanilla armor).
 */
@Mod.EventBusSubscriber(modid = com.kingodogo.buildscape.BuildScape.MODID, bus = Mod.EventBusSubscriber.Bus.FORGE, value = Dist.CLIENT)
public class CosmeticRenderHandler {

    // Toggle for cosmetics-only mode (hide vanilla armor)
    private static boolean renderCosmeticsOnly = false;

    // Flag to prevent recursive rendering
    private static final ThreadLocal<Boolean> isRenderingCosmetics = new ThreadLocal<>();

    // Store cosmetics to render as overlay (per frame)
    private static final ThreadLocal<Map<Integer, String>> cosmeticsToRender = new ThreadLocal<>();

    /**
     * Set whether to render only cosmetics (hide vanilla armor).
     */
    public static void setRenderCosmeticsOnly(boolean only) {
        renderCosmeticsOnly = only;
    }

    /**
     * Get whether to render only cosmetics.
     */
    public static boolean isRenderCosmeticsOnly() {
        return renderCosmeticsOnly;
    }

    // Cache for builders hat model part to avoid recreating it every frame
    private static net.minecraft.client.model.geom.ModelPart buildersHatModelPart = null;

    /**
     * Render cosmetics as overlay on top of vanilla armor after player rendering.
     * This creates a separate layer that renders on top of everything.
     */
    @SubscribeEvent
    public static void onRenderPlayerPost(RenderLivingEvent.Post<? extends LivingEntity, ?> event) {
        if (!(event.getEntity() instanceof AbstractClientPlayer player)) {
            return;
        }

        // Skip if we're already rendering cosmetics overlay (prevents recursion)
        if (Boolean.TRUE.equals(isRenderingCosmetics.get())) {
            return;
        }

        // Only render for the local player
        Minecraft mc = Minecraft.getInstance();
        if (player != mc.player) {
            return;
        }

        // Get cosmetics to render
        Map<Integer, String> equippedCosmetics = cosmeticsToRender.get();
        if (equippedCosmetics == null || equippedCosmetics.isEmpty()) {
            cosmeticsToRender.remove();
            return;
        }

        // Render cosmetics overlay on top of vanilla gear without removing vanilla
        renderCosmeticsOverlay(event, player, equippedCosmetics);

        cosmeticsToRender.remove();
    }

    /**
     * Prepare for player rendering.
     * Store cosmetics and vanilla armor.
     * If "cosmetics only" mode, hide vanilla armor.
     * Otherwise, keep vanilla armor and render cosmetics as overlay in Post.
     */
    @SubscribeEvent
    public static void onRenderPlayerPre(RenderLivingEvent.Pre<? extends LivingEntity, ?> event) {
        if (!(event.getEntity() instanceof AbstractClientPlayer player)) {
            return;
        }

        // Ensure cosmetics-only toggle is off (UI toggle removed).
        renderCosmeticsOnly = false;

        // Skip if we're already rendering cosmetics overlay (prevents recursion)
        if (Boolean.TRUE.equals(isRenderingCosmetics.get())) {
            return;
        }

        // Only apply cosmetics for the local player
        Minecraft mc = Minecraft.getInstance();
        if (player != mc.player) {
            return;
        }

        // Prefer the current tab state (reflects immediate GUI equips); fall back to
        // config
        Map<Integer, String> equippedCosmetics = com.kingodogo.buildscape.client.screen.tabs.supporters.SupportersTabState
                .getInstance()
                .getEquippedCosmeticsBySlot();
        if (equippedCosmetics == null || equippedCosmetics.isEmpty()) {
            CosmeticsConfig config = CosmeticsConfig.get();
            equippedCosmetics = config.getEquippedCosmetics(player.getUUID());
        }

        if (equippedCosmetics.isEmpty()) {
            return;
        }

        // Store cosmetics for overlay rendering
        cosmeticsToRender.set(equippedCosmetics);
    }

    /**
     * Render cosmetics as overlay using RenderLevelStageEvent.
     * This happens after all entities are rendered, so we can render cosmetics on
     * top.
     */
    @SubscribeEvent
    public static void onRenderLevelStage(RenderLevelStageEvent event) {
        // No-op: overlay is now handled entirely in the Post event
    }

    /**
     * Restore original equipment.
     */
    private static void renderCosmeticsOverlay(RenderLivingEvent.Post<? extends LivingEntity, ?> event,
                                               AbstractClientPlayer player,
                                               Map<Integer, String> equippedCosmetics) {
        Minecraft mc = Minecraft.getInstance();
        net.minecraft.client.renderer.entity.EntityRenderDispatcher dispatcher = mc.getEntityRenderDispatcher();
        PlayerRenderer playerRenderer = (PlayerRenderer) dispatcher.getRenderer(player);
        if (playerRenderer == null)
            return;

        // Store current equipment (vanilla)
        ItemStack[] original = new ItemStack[4];
        original[0] = player.getItemBySlot(EquipmentSlot.HEAD).copy();
        original[1] = player.getItemBySlot(EquipmentSlot.CHEST).copy();
        original[2] = player.getItemBySlot(EquipmentSlot.LEGS).copy();
        original[3] = player.getItemBySlot(EquipmentSlot.FEET).copy();

        // Apply cosmetics into slots (temporarily)
        CosmeticRegistry registry = CosmeticRegistry.getInstance();
        com.kingodogo.buildscape.cosmetics.CosmeticManager cosmeticManager = com.kingodogo.buildscape.cosmetics.CosmeticManager
                .getInstance();

        // Track custom head cosmetics to render separately
        String customHeadCosmetic = null;

        // FIRST: Clear head slot if we have a custom HEAD cosmetic to prevent any
        // helmet from showing
        for (Map.Entry<Integer, String> entry : equippedCosmetics.entrySet()) {
            String cosmeticId = entry.getValue();
            if (cosmeticId == null || cosmeticId.isEmpty())
                continue;

            // Check if this is a custom HEAD cosmetic
            com.kingodogo.buildscape.cosmetics.CosmeticManager.CosmeticMetadata metadata = cosmeticManager
                    .getMetadata(cosmeticId);
            if (metadata != null
                    && metadata.type() == com.kingodogo.buildscape.cosmetics.CosmeticManager.CosmeticType.HEAD) {
                if (entry.getKey() == 0) { // Slot 0 is head
                    customHeadCosmetic = cosmeticId;
                    // CRITICAL: Clear head slot IMMEDIATELY to prevent any helmet from rendering
                    setItemSlotSilent(player, EquipmentSlot.HEAD, ItemStack.EMPTY);
                    break; // Found custom head cosmetic, exit early
                }
            }
        }

        // SECOND: Apply all other cosmetics (non-HEAD cosmetics)
        for (Map.Entry<Integer, String> entry : equippedCosmetics.entrySet()) {
            String cosmeticId = entry.getValue();
            if (cosmeticId == null || cosmeticId.isEmpty())
                continue;

            // Skip custom HEAD cosmetics - they're handled separately
            com.kingodogo.buildscape.cosmetics.CosmeticManager.CosmeticMetadata metadata = cosmeticManager
                    .getMetadata(cosmeticId);
            if (metadata != null
                    && metadata.type() == com.kingodogo.buildscape.cosmetics.CosmeticManager.CosmeticType.HEAD) {
                continue; // Skip ItemStack resolution for custom head cosmetics
            }

            ItemStack cosmeticStack = registry.resolveToItemStack(cosmeticId);
            if (cosmeticStack == null || cosmeticStack.isEmpty())
                continue;
            EquipmentSlot slot = getSlotForIndex(entry.getKey());
            if (slot != null) {
                setItemSlotSilent(player, slot, cosmeticStack);
            }
        }

        try {
            isRenderingCosmetics.set(true);

            PoseStack poseStack = event.getPoseStack();
            MultiBufferSource.BufferSource bufferSource = mc.renderBuffers().bufferSource();
            int packedLight = dispatcher.getPackedLightCoords(player, event.getPartialTick());
            float partialTick = event.getPartialTick();

            poseStack.pushPose();

            // Render as a second layer: keep depth test AND depth writes so the layer
            // correctly occludes with the world and particles. Blend stays enabled for
            // semi-transparent pieces but we write depth to avoid "behind-screen"
            // artifacts.
            com.mojang.blaze3d.systems.RenderSystem.enableDepthTest();
            com.mojang.blaze3d.systems.RenderSystem.depthMask(true);
            com.mojang.blaze3d.systems.RenderSystem.enableBlend();
            com.mojang.blaze3d.systems.RenderSystem.defaultBlendFunc();

            playerRenderer.render(player, player.getYRot(), partialTick, poseStack, bufferSource, packedLight);

            // Render custom head cosmetics after player render
            if (customHeadCosmetic != null) {
                com.kingodogo.buildscape.BuildScape.getLogger()
                        .debug("Rendering custom head cosmetic: " + customHeadCosmetic);
                renderCustomHeadCosmetic(player, customHeadCosmetic, poseStack, bufferSource, packedLight, partialTick);
            }

            bufferSource.endBatch();
            poseStack.popPose();

            com.mojang.blaze3d.systems.RenderSystem.disableBlend();
            com.mojang.blaze3d.systems.RenderSystem.disableDepthTest();

        } catch (Exception e) {
            com.kingodogo.buildscape.BuildScape.getLogger()
                    .debug("Failed to render cosmetic overlay: " + e.getMessage());
        } finally {
            isRenderingCosmetics.remove();
            // Restore original vanilla equipment
            setItemSlotSilent(player, EquipmentSlot.HEAD, original[0]);
            setItemSlotSilent(player, EquipmentSlot.CHEST, original[1]);
            setItemSlotSilent(player, EquipmentSlot.LEGS, original[2]);
            setItemSlotSilent(player, EquipmentSlot.FEET, original[3]);
        }
    }

    /**
     * Get EquipmentSlot from slot index.
     */
    private static EquipmentSlot getSlotForIndex(int slotIndex) {
        switch (slotIndex) {
            case 0:
                return EquipmentSlot.HEAD;
            case 1:
                return EquipmentSlot.CHEST;
            case 2:
                return EquipmentSlot.LEGS;
            case 3:
                return EquipmentSlot.FEET;
            default:
                return null;
        }
    }

    /**
     * Set item slot silently without triggering sounds or events.
     * Directly modifies the inventory array to bypass sound triggers.
     */
    private static void setItemSlotSilent(AbstractClientPlayer player, EquipmentSlot slot, ItemStack stack) {
        if (player == null)
            return;

        // Use direct inventory access to avoid triggering sounds
        net.minecraft.world.entity.player.Inventory inventory = player.getInventory();

        switch (slot) {
            case HEAD:
                inventory.armor.set(3, stack); // Head is index 3 in armor list
                break;
            case CHEST:
                inventory.armor.set(2, stack); // Chest is index 2 in armor list
                break;
            case LEGS:
                inventory.armor.set(1, stack); // Legs is index 1 in armor list
                break;
            case FEET:
                inventory.armor.set(0, stack); // Feet is index 0 in armor list
                break;
            case MAINHAND:
                // For main hand, set the selected hotbar slot
                inventory.setItem(inventory.selected, stack);
                break;
            default:
                break;
        }
    }

    /**
     * Render a custom head cosmetic model.
     */
    private static void renderCustomHeadCosmetic(
            AbstractClientPlayer player,
            String cosmeticId,
            com.mojang.blaze3d.vertex.PoseStack poseStack,
            MultiBufferSource bufferSource,
            int packedLight,
            float partialTick) {
        try {
            // Get the model from the entity render dispatcher
            Minecraft mc = Minecraft.getInstance();
            net.minecraft.client.renderer.entity.EntityRenderDispatcher dispatcher = mc.getEntityRenderDispatcher();

            // Create or get cached model part
            if (buildersHatModelPart == null) {
                com.kingodogo.buildscape.BuildScape.getLogger().info("Creating builders hat model part...");
                try {
                    // In 1.18.2, we need to access EntityModels through a player renderer
                    net.minecraft.client.renderer.entity.player.PlayerRenderer playerRenderer = (net.minecraft.client.renderer.entity.player.PlayerRenderer) dispatcher
                            .getRenderer(player);
                    if (playerRenderer != null) {
                        com.kingodogo.buildscape.BuildScape.getLogger()
                                .info("PlayerRenderer found, attempting to create model...");
                        // Try to bake the layer using the player renderer's EntityModels
                        // PlayerRenderer has access to EntityModels through its context
                        try {
                            // Use reflection to access the EntityModels from PlayerRenderer
                            java.lang.reflect.Field entityModelsField = null;
                            try {
                                entityModelsField = net.minecraft.client.renderer.entity.player.PlayerRenderer.class
                                        .getDeclaredField("entityModels");
                                entityModelsField.setAccessible(true);
                            } catch (NoSuchFieldException e) {
                                // Try alternative field names
                                try {
                                    entityModelsField = net.minecraft.client.renderer.entity.player.PlayerRenderer.class
                                            .getDeclaredField("modelSet");
                                    entityModelsField.setAccessible(true);
                                } catch (NoSuchFieldException e2) {
                                    // Field not found, try direct access through context
                                }
                            }

                            if (entityModelsField != null) {
                                net.minecraft.client.model.geom.EntityModelSet entityModels = (net.minecraft.client.model.geom.EntityModelSet) entityModelsField
                                        .get(playerRenderer);
                                if (entityModels != null) {
                                    net.minecraft.client.model.geom.ModelPart root = entityModels.bakeLayer(
                                            com.kingodogo.buildscape.client.model.BuildersHatModel.LAYER_LOCATION);
                                    if (root != null) {
                                        buildersHatModelPart = root.getChild("Head");
                                    }
                                }
                            }

                            // If reflection failed, recreate the model structure directly from
                            // MeshDefinition
                            if (buildersHatModelPart == null) {
                                // Recreate the MeshDefinition structure exactly as in
                                // BuildersHatModel.createBodyLayer()
                                try {
                                    net.minecraft.client.model.geom.builders.MeshDefinition meshdefinition = new net.minecraft.client.model.geom.builders.MeshDefinition();
                                    PartDefinition partdefinition = meshdefinition.getRoot();

                                    PartDefinition Head = partdefinition.addOrReplaceChild("Head",
                                            net.minecraft.client.model.geom.builders.CubeListBuilder.create(),
                                            net.minecraft.client.model.geom.PartPose.offset(0.0F, 0.0F, 0.0F));

                                    Head.addOrReplaceChild("bone",
                                            net.minecraft.client.model.geom.builders.CubeListBuilder.create()
                                                    .texOffs(0, 0).addBox(-14.0F, -5.0F, 0.0F, 11.0F, 0.0F, 16.0F,
                                                            new net.minecraft.client.model.geom.builders.CubeDeformation(
                                                                    0.0F))
                                                    .texOffs(0, 17).addBox(-13.0F, -10.0F, 5.0F, 9.0F, 5.0F, 9.0F,
                                                            new net.minecraft.client.model.geom.builders.CubeDeformation(
                                                                    0.0F))
                                                    .texOffs(0, 32).addBox(-10.0F, -11.0F, 4.0F, 3.0F, 6.0F, 11.0F,
                                                            new net.minecraft.client.model.geom.builders.CubeDeformation(
                                                                    0.0F)),
                                            net.minecraft.client.model.geom.PartPose.offset(8.5F, -1.0F, -9.75F));

                                    // Bake the root PartDefinition to get ModelPart
                                    net.minecraft.client.model.geom.ModelPart root = partdefinition.bake(64, 64);
                                    if (root != null) {
                                        buildersHatModelPart = root.getChild("Head");
                                        if (buildersHatModelPart != null) {
                                            com.kingodogo.buildscape.BuildScape.getLogger()
                                                    .info("Successfully created builders hat model part!");
                                        } else {
                                            com.kingodogo.buildscape.BuildScape.getLogger()
                                                    .warn("Root ModelPart created but 'Head' child not found!");
                                        }
                                    } else {
                                        com.kingodogo.buildscape.BuildScape.getLogger()
                                                .warn("Failed to bake root ModelPart!");
                                    }
                                } catch (Exception e3) {
                                    com.kingodogo.buildscape.BuildScape.getLogger().error(
                                            "Failed to create builders hat model: " + e3.getMessage(), e3);
                                }
                            }
                        } catch (Exception e2) {
                            com.kingodogo.buildscape.BuildScape.getLogger().warn(
                                    "Failed to create builders hat model: " + e2.getMessage());
                            return;
                        }
                    } else {
                        return; // Can't get player renderer
                    }
                } catch (Exception e) {
                    com.kingodogo.buildscape.BuildScape.getLogger().debug(
                            "Builders hat model layer not registered, cannot render custom head cosmetic: "
                                    + e.getMessage());
                    return;
                }
            }

            if (buildersHatModelPart == null) {
                com.kingodogo.buildscape.BuildScape.getLogger().warn("buildersHatModelPart is null, cannot render!");
                return; // Model not created
            }

            // Get texture location
            net.minecraft.resources.ResourceLocation texture = new net.minecraft.resources.ResourceLocation(
                    com.kingodogo.buildscape.BuildScape.MODID,
                    "textures/cosmatics/builders_hat.png");
            com.kingodogo.buildscape.BuildScape.getLogger().debug("Rendering builders hat with texture: " + texture);

            // Get vertex consumer for the texture
            com.mojang.blaze3d.vertex.VertexConsumer vertexConsumer = bufferSource.getBuffer(
                    net.minecraft.client.renderer.RenderType.entityCutoutNoCull(texture));

            // Position the model on the player's head
            poseStack.pushPose();

            // Get player head rotation
            float headYaw = player.getYHeadRot();
            float headPitch = player.getXRot();

            // Translate to head position (player head is at y=0.0, but model needs
            // adjustment)
            poseStack.translate(0.0, 0.0, 0.0);

            // Apply head rotation
            poseStack.mulPose(com.mojang.math.Vector3f.YP.rotationDegrees(headYaw));
            poseStack.mulPose(com.mojang.math.Vector3f.XP.rotationDegrees(headPitch));

            // Render the model
            buildersHatModelPart.render(poseStack, vertexConsumer, packedLight,
                    net.minecraft.client.renderer.texture.OverlayTexture.NO_OVERLAY,
                    1.0f, 1.0f, 1.0f, 1.0f);

            poseStack.popPose();
        } catch (Exception e) {
            com.kingodogo.buildscape.BuildScape.getLogger()
                    .debug("Failed to render custom head cosmetic: " + e.getMessage());
        }
    }
}

package com.kingodogo.buildscape.client;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.entity.ColoredItemFrameEntity;
import com.kingodogo.buildscape.item.ModItems;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import com.mojang.math.Matrix3f;
import com.mojang.math.Matrix4f;
import net.minecraft.client.Camera;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.decoration.ItemFrame;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.RenderLevelStageEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import java.util.List;

@Mod.EventBusSubscriber(
        modid = BuildScape.MODID,
        bus = Mod.EventBusSubscriber.Bus.FORGE,
        value = Dist.CLIENT
)
public class InvisibleFrameOverlayRenderer {

    private static final double SEARCH_RANGE = 16.0; // 1 chunk

    @SubscribeEvent
    public static void onRenderLevelStage(RenderLevelStageEvent event) {
        if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_PARTICLES) {
            return;
        }

        Minecraft mc = Minecraft.getInstance();
        if (mc.player == null || mc.level == null) {
            return;
        }

        Player player = mc.player;

        // Must be sneaking and holding an invisible item frame
        if (!player.isShiftKeyDown()) {
            return;
        }

        ItemStack mainHand = player.getMainHandItem();
        ItemStack offHand = player.getOffhandItem();
        boolean holdingInvisibleFrame =
                (!mainHand.isEmpty() && mainHand.getItem() == ModItems.INVISIBLE_ITEM_FRAME.get()) ||
                        (!offHand.isEmpty() && offHand.getItem() == ModItems.INVISIBLE_ITEM_FRAME.get());

        if (!holdingInvisibleFrame) {
            return;
        }

        // Find all invisible item frames within 1 chunk range (vanilla + modded)
        AABB searchBox = player.getBoundingBox().inflate(SEARCH_RANGE);
        List<ItemFrame> vanillaFrames = mc.level.getEntitiesOfClass(
                ItemFrame.class, searchBox, Entity::isInvisible
        );
        List<ColoredItemFrameEntity> moddedFrames = mc.level.getEntitiesOfClass(
                ColoredItemFrameEntity.class, searchBox, Entity::isInvisible
        );

        if (vanillaFrames.isEmpty() && moddedFrames.isEmpty()) {
            return;
        }

        Camera camera = event.getCamera();
        Vec3 cameraPos = camera.getPosition();
        PoseStack poseStack = event.getPoseStack();
        MultiBufferSource.BufferSource bufferSource = mc.renderBuffers().bufferSource();

        VertexConsumer lineBuffer = bufferSource.getBuffer(RenderType.lines());

        for (ItemFrame frame : vanillaFrames) {
            renderOutline(poseStack, lineBuffer, cameraPos, frame.getBoundingBox());
        }
        for (ColoredItemFrameEntity frame : moddedFrames) {
            renderOutline(poseStack, lineBuffer, cameraPos, frame.getBoundingBox());
        }

        bufferSource.endBatch(RenderType.lines());
    }

    private static void renderOutline(PoseStack poseStack, VertexConsumer buffer,
                                      Vec3 cameraPos, AABB bb) {
        float minX = (float) (bb.minX - cameraPos.x);
        float minY = (float) (bb.minY - cameraPos.y);
        float minZ = (float) (bb.minZ - cameraPos.z);
        float maxX = (float) (bb.maxX - cameraPos.x);
        float maxY = (float) (bb.maxY - cameraPos.y);
        float maxZ = (float) (bb.maxZ - cameraPos.z);

        // Light cyan color: R=0, G=200, B=255, A=255
        int r = 0;
        int g = 200;
        int b = 255;
        int a = 255;

        Matrix4f pose = poseStack.last().pose();
        Matrix3f normal = poseStack.last().normal();

        // Bottom face edges
        drawLine(buffer, pose, normal, minX, minY, minZ, maxX, minY, minZ, r, g, b, a);
        drawLine(buffer, pose, normal, maxX, minY, minZ, maxX, minY, maxZ, r, g, b, a);
        drawLine(buffer, pose, normal, maxX, minY, maxZ, minX, minY, maxZ, r, g, b, a);
        drawLine(buffer, pose, normal, minX, minY, maxZ, minX, minY, minZ, r, g, b, a);

        // Top face edges
        drawLine(buffer, pose, normal, minX, maxY, minZ, maxX, maxY, minZ, r, g, b, a);
        drawLine(buffer, pose, normal, maxX, maxY, minZ, maxX, maxY, maxZ, r, g, b, a);
        drawLine(buffer, pose, normal, maxX, maxY, maxZ, minX, maxY, maxZ, r, g, b, a);
        drawLine(buffer, pose, normal, minX, maxY, maxZ, minX, maxY, minZ, r, g, b, a);

        // Vertical edges
        drawLine(buffer, pose, normal, minX, minY, minZ, minX, maxY, minZ, r, g, b, a);
        drawLine(buffer, pose, normal, maxX, minY, minZ, maxX, maxY, minZ, r, g, b, a);
        drawLine(buffer, pose, normal, maxX, minY, maxZ, maxX, maxY, maxZ, r, g, b, a);
        drawLine(buffer, pose, normal, minX, minY, maxZ, minX, maxY, maxZ, r, g, b, a);
    }

    private static void drawLine(VertexConsumer buffer, Matrix4f pose, Matrix3f normal,
                                 float x1, float y1, float z1,
                                 float x2, float y2, float z2,
                                 int r, int g, int b, int a) {
        buffer.vertex(pose, x1, y1, z1)
                .color(r, g, b, a)
                .normal(normal, 0, 1, 0)
                .endVertex();
        buffer.vertex(pose, x2, y2, z2)
                .color(r, g, b, a)
                .normal(normal, 0, 1, 0)
                .endVertex();
    }
}

