/**
 * Handles particle trails for player cosmetics.
 * Spawns particles (like stars) behind the player when they walk.
 */
@Mod.EventBusSubscriber(modid = com.kingodogo.buildscape.BuildScape.MODID, bus = Mod.EventBusSubscriber.Bus.FORGE, value = Dist.CLIENT)
@OnlyIn(Dist.CLIENT)
public class ParticleTrailHandler {

    // Track last position for each player
    private static final Map<UUID, Vec3> lastPositions = new HashMap<>();

    // Track last particle spawn time to control spawn rate
    private static final Map<UUID, Long> lastSpawnTimes = new HashMap<>();

    // Particle spawn rate (milliseconds between spawns)
    private static final long SPAWN_INTERVAL_MS = 50; // Spawn every 50ms (20 particles per second)

    /**
     * Get spawn amount for a cosmetic ID.
     * Controls density/frequency.
     * < 1.0 : Chance to spawn (e.g. 0.8 = 80% chance)
     * >= 1.0 : Number of particles to spawn
     */
    private static float getSpawnAmount(String cosmeticId) {
        if (cosmeticId == null)
            return 1.0f;
        String idLower = cosmeticId.toLowerCase();

        // Cherry-related and Cake trails spawn slightly less often (80% chance per tick)
        if (idLower.contains("cherry") || idLower.contains("cake")) {
            return 0.8f;
        }

        return 1.0f;
    }

    /**
     * Get velocity multiplier for a cosmetic ID.
     * Controls how far the particles go (spread/speed).
     */
    private static float getVelocityMultiplier(String cosmeticId) {
        return 1.0f; // Default multiplier
    }

    // Minimum movement distance to spawn particles (prevents spawning when standing
    // still)
    private static final double MIN_MOVEMENT_DISTANCE = 0.01;

    /**
     * Check if a cosmetic ID is a particle trail cosmetic.
     */
    private static boolean isParticleTrail(String cosmeticId) {
        return CosmeticManager.getInstance().isParticleTrail(cosmeticId);
    }

    /**
     * Get particle type for a cosmetic ID based on shape.
     * Returns different particle types based on particle shape.
     */
    private static ParticleOptions getParticleType(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return ModParticles.GLOW_LIME_SPARKLE.get();
        }

        CosmeticManager manager = CosmeticManager.getInstance();
        String shape = manager.getParticleShape(cosmeticId);

        // Return different particle types based on shape
        switch (shape) {
            case "bubble":
                return ModParticles.BUBBLE.get();
            case "cherry_leaves":
                return ModParticles.CHERRY.get();
            case "heart":
                return ModParticles.TINTABLE_HEART.get();
            case "note":
                return ModParticles.TRAIL_NOTE.get();
            case "snowflake":
                return ModParticles.SNOWFLAKE.get();
            case "firework":
                // Use actual firework particle
                return ParticleTypes.FIREWORK;
            case "cake":
                return ModParticles.CAKE.get();
            case "cherry":
                return ModParticles.CHERRY.get();
            case "sparkle":
            default:
                return ModParticles.GLOW_LIME_SPARKLE.get();
        }
    }

    /**
     * Get color for particle trail based on cosmetic ID.
     * Returns RGB values (0.0-1.0).
     */
    public static float[] getParticleColor(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return new float[] { 1.0f, 1.0f, 1.0f }; // White
        }

        String idLower = cosmeticId.toLowerCase();

        // Snowflake trail - white/light blue
        if (idLower.contains("snowflake")) {
            return new float[] { 0.9f, 0.95f, 1.0f }; // White/light blue
        }

        // Heart trail - red
        if (idLower.contains("heart")) {
            return new float[] { 1.0f, 0.0f, 0.0f }; // Red
        }

        // Cherry/Cherry Leaves trail - Pink
        if (idLower.contains("cherry")) {
            return new float[] { 1.0f, 0.7f, 0.8f }; // Pink
        }

        // Cake trail - Cream/White
        if (idLower.contains("cake")) {
            return new float[] { 1.0f, 0.9f, 0.8f }; // Creamy White
        }

        // Default - Blue sparkle (as requested)
        return new float[] { 0.2f, 0.5f, 1.0f }; // Blue
    }

    /**
     * Spawn particles behind the player.
     */
    @SubscribeEvent
    public static void onClientTick(TickEvent.ClientTickEvent event) {
        if (event.phase != TickEvent.Phase.END)
            return;

        Minecraft mc = Minecraft.getInstance();
        if (mc.player == null || mc.level == null)
            return;

        Player player = mc.player;
        UUID playerUuid = player.getUUID();

        // Get equipped cosmetics from SupportersTabState (includes both slots and
        // non-slot cosmetics)
        // This is the source of truth for what's currently equipped
        com.kingodogo.buildscape.client.screen.tabs.supporters.SupportersTabState state = com.kingodogo.buildscape.client.screen.tabs.supporters.SupportersTabState
                .getInstance();

        // Get all equipped cosmetics (both slot-based and non-slot like particle
        // trails)
        Set<String> equippedCosmeticsSet = state.getEquippedCosmetics();

        // Also check slot-based cosmetics from config (for backwards compatibility)
        CosmeticsConfig config = CosmeticsConfig.get();
        Map<Integer, String> equippedCosmeticsBySlot = config.getEquippedCosmetics(playerUuid);

        // Check if player has any particle trail cosmetics
        // Check equipped set first (includes all equipped cosmetics)
        boolean hasParticleTrail = false;
        String particleTrailId = null;

        for (String cosmeticId : equippedCosmeticsSet) {
            if (isParticleTrail(cosmeticId)) {
                hasParticleTrail = true;
                particleTrailId = cosmeticId;
                break;
            }
        }

        // Also check slot-based cosmetics (for backwards compatibility)
        if (!hasParticleTrail) {
            for (String cosmeticId : equippedCosmeticsBySlot.values()) {
                if (isParticleTrail(cosmeticId)) {
                    hasParticleTrail = true;
                    particleTrailId = cosmeticId;
                    break;
                }
            }
        }

        if (!hasParticleTrail) {
            // Clear tracking if no particle trail equipped
            lastPositions.remove(playerUuid);
            lastSpawnTimes.remove(playerUuid);
            return;
        }

        // Get current position
        Vec3 currentPos = player.position();
        Vec3 lastPos = lastPositions.get(playerUuid);

        // Initialize last position if first time
        if (lastPos == null) {
            lastPositions.put(playerUuid, currentPos);
            return;
        }

        // Check if player has moved enough
        double distance = currentPos.distanceTo(lastPos);
        if (distance < MIN_MOVEMENT_DISTANCE) {
            // Update last position but don't spawn particles
            lastPositions.put(playerUuid, currentPos);
            return;
        }

        // Check if player is climbing (don't spawn particles)
        if (player.onClimbable()) {
            lastPositions.put(playerUuid, currentPos);
            return;
        }

        // Check if moving forward (only spawn when walking/sprinting forward)
        // We need to check input for local player
        if (player instanceof net.minecraft.client.player.LocalPlayer localPlayer) {
            if (localPlayer.input.forwardImpulse <= 0) {
                // Not moving forward (could be backwards, strafing only, or standing still)
                lastPositions.put(playerUuid, currentPos);
                return;
            }
        }

        // Check spawn rate limit
        long currentTime = System.currentTimeMillis();
        Long lastSpawnTime = lastSpawnTimes.get(playerUuid);
        if (lastSpawnTime != null && (currentTime - lastSpawnTime) < SPAWN_INTERVAL_MS) {
            // Update last position but don't spawn particles yet
            lastPositions.put(playerUuid, currentPos);
            return;
        }

        // Calculate spawn position (behind player, at feet level)
        // Use player's look vector for direction if moving forward
        Vec3 lookVec = player.getLookAngle();
        Vec3 direction = new Vec3(lookVec.x, 0, lookVec.z).normalize();
        Vec3 spawnPos = lastPos.add(0, 0.1, 0); // Slightly above ground

        // Add some randomness to spawn position
        Random random = mc.level.random;
        double offsetX = (random.nextDouble() - 0.5) * 0.3;
        double offsetZ = (random.nextDouble() - 0.5) * 0.3;
        spawnPos = spawnPos.add(offsetX, 0, offsetZ);

        // Get particle type and color
        ParticleOptions particleType = getParticleType(particleTrailId);

        // Get stored color from config, or use default color
        CosmeticsConfig cosmeticsConfig = CosmeticsConfig.get();
        String storedColor = cosmeticsConfig.getCosmeticColor(playerUuid, particleTrailId);
        float[] color;

        if (storedColor != null && !storedColor.isEmpty()) {
            // Parse stored hex color
            try {
                String hex = storedColor.startsWith("#") ? storedColor.substring(1) : storedColor;
                int rgb = Integer.parseInt(hex, 16);
                int r = (rgb >> 16) & 0xFF;
                int g = (rgb >> 8) & 0xFF;
                int b = rgb & 0xFF;
                color = new float[] { r / 255.0f, g / 255.0f, b / 255.0f };
            } catch (NumberFormatException e) {
                // Invalid color, use default
                color = getParticleColor(particleTrailId);
            }
        } else {
            // Use default color based on cosmetic ID
            color = getParticleColor(particleTrailId);
        }

        // Get spawn amount and velocity parameters
        float spawnAmount = getSpawnAmount(particleTrailId);
        float velocityMult = getVelocityMultiplier(particleTrailId);

        // Spawn particle with velocity opposite to movement direction
        // This makes particles spread behind the player
        // Particles glow up first, then fall down (pulsing effect)
        double velocityX = (-direction.x * 0.1 + (random.nextDouble() - 0.5) * 0.05) * velocityMult;
        double velocityY = (0.08 + random.nextDouble() * 0.05) * velocityMult; // Start with upward velocity (glow up)
        double velocityZ = (-direction.z * 0.1 + (random.nextDouble() - 0.5) * 0.05) * velocityMult;

        // Queue color for the particle (if supported)
        CosmeticManager manager = CosmeticManager.getInstance();
        if (manager.supportsColor(particleTrailId)) {
            String colorCode = String.format("#%02X%02X%02X",
                    (int) (color[0] * 255),
                    (int) (color[1] * 255),
                    (int) (color[2] * 255));

            if (particleType == ModParticles.GLOW_LIME_SPARKLE.get()) {
                com.kingodogo.buildscape.particle.PillarSparkleParticle.queueColor(
                        spawnPos.x, spawnPos.y, spawnPos.z, colorCode);
            } else if (particleType == ModParticles.TINTABLE_HEART.get()) {
                com.kingodogo.buildscape.particle.TintableHeartParticle.queueColor(
                        spawnPos.x, spawnPos.y, spawnPos.z, colorCode);
            } else if (particleType == ModParticles.TRAIL_NOTE.get()) {
                com.kingodogo.buildscape.particle.TrailNoteParticle.queueColor(
                        spawnPos.x, spawnPos.y, spawnPos.z, colorCode);
            }
        }

        // Determine number of particles to spawn based on spawnAmount
        int count = (int) spawnAmount;
        // Handle fractional part as probability
        if (random.nextFloat() < (spawnAmount - count)) {
            count++;
        }

        // Spawn the particle(s)
        try {
            for (int i = 0; i < count; i++) {
                // Slightly randomize spawn position for multiple particles
                double px = spawnPos.x;
                double pz = spawnPos.z;
                
                if (count > 1) {
                    px += (random.nextDouble() - 0.5) * 0.1;
                    pz += (random.nextDouble() - 0.5) * 0.1;
                }

                // Standard single particle for all types (including bubble, note, and cherry)
                // Cherry particles will randomize their shape internally (in CherryParticle class)
                mc.level.addParticle(particleType,
                        px, spawnPos.y, pz,
                        velocityX, velocityY, velocityZ);
            }
        } catch (Exception e) {
            com.kingodogo.buildscape.BuildScape.getLogger().warn("Failed to spawn particle trail: " + e.getMessage());
        }

        // Update tracking
        lastPositions.put(playerUuid, currentPos);
        lastSpawnTimes.put(playerUuid, currentTime);
    }

    /**
     * Clear tracking when player disconnects or world unloads.
     */
    public static void clearTracking() {
        lastPositions.clear();
        lastSpawnTimes.clear();
    }
}

package com.kingodogo.buildscape.client;

import net.minecraft.core.BlockPos;
import net.minecraft.world.level.Level;
import java.util.HashMap;
import java.util.Map;
import java.util.Iterator;

/**
 * Client-side manager to track marked pillars that should display blinking borders.
 * Marks expire after 15 seconds.
 */
public class PillarMarkerManager {
    private static final PillarMarkerManager INSTANCE = new PillarMarkerManager();
    private static final long MARK_DURATION_MS = 4500; // 4.5 seconds
    
    private final Map<String, MarkedPillar> markedPillars = new HashMap<>();
    
    public static PillarMarkerManager get() {
        return INSTANCE;
    }
    
    public static class MarkedPillar {
        public final String pillarId;
        public final BlockPos pos;
        public final String dimension;
        public final long markTime;
        
        public MarkedPillar(String pillarId, BlockPos pos, String dimension) {
            this.pillarId = pillarId;
            this.pos = pos;
            this.dimension = dimension;
            this.markTime = System.currentTimeMillis();
        }
        
        public boolean isExpired() {
            return System.currentTimeMillis() - markTime > MARK_DURATION_MS;
        }
        
        public float getBlinkAlpha() {
            long elapsed = System.currentTimeMillis() - markTime;
            // Blink every 500ms (on/off cycle)
            boolean isOn = (elapsed / 500) % 2 == 0;
            return isOn ? 1.0f : 0.3f;
        }
        
        /**
         * Get the color for the gradient (yellow to red)
         * Returns a value from 0.0 (yellow) to 1.0 (red) based on elapsed time
         */
        public float getGradientProgress() {
            long elapsed = System.currentTimeMillis() - markTime;
            // Gradually transition from yellow (0.0) to red (1.0) over the duration
            return Math.min(1.0f, elapsed / (float)MARK_DURATION_MS);
        }
    }
    
    /**
     * Mark a pillar to display blinking borders.
     */
    public void markPillar(String pillarId, BlockPos pos, String dimension) {
        markedPillars.put(pillarId, new MarkedPillar(pillarId, pos, dimension));
    }
    
    /**
     * Check if a pillar at the given position is marked.
     */
    public MarkedPillar getMarkedPillar(Level level, BlockPos pos) {
        String dimension = level.dimension().location().toString();
        
        // Clean up expired marks first
        cleanupExpired();
        
        for (MarkedPillar marked : markedPillars.values()) {
            if (marked.dimension.equals(dimension) &&
                marked.pos.getX() == pos.getX() &&
                marked.pos.getY() == pos.getY() &&
                marked.pos.getZ() == pos.getZ()) {
                if (!marked.isExpired()) {
                    return marked;
                }
            }
        }
        return null;
    }
    
    /**
     * Get all marked pillars in the given dimension.
     */
    public Map<String, MarkedPillar> getMarkedPillars(String dimension) {
        cleanupExpired();
        Map<String, MarkedPillar> result = new HashMap<>();
        for (Map.Entry<String, MarkedPillar> entry : markedPillars.entrySet()) {
            if (entry.getValue().dimension.equals(dimension) && !entry.getValue().isExpired()) {
                result.put(entry.getKey(), entry.getValue());
            }
        }
        return result;
    }
    
    /**
     * Remove expired marks.
     */
    private void cleanupExpired() {
        Iterator<Map.Entry<String, MarkedPillar>> it = markedPillars.entrySet().iterator();
        while (it.hasNext()) {
            if (it.next().getValue().isExpired()) {
                it.remove();
            }
        }
    }
    
    /**
     * Clear all marks (useful for testing or cleanup).
     */
    public void clearAll() {
        markedPillars.clear();
    }
}

package com.kingodogo.buildscape.client;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.block.PillarBlock;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.Camera;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.MultiBufferSource;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.RenderLevelStageEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import java.util.Map;

/**
 * Renders blinking borders around marked pillars in the world.
 */
@Mod.EventBusSubscriber(
        modid = BuildScape.MODID,
        bus = Mod.EventBusSubscriber.Bus.FORGE,
        value = Dist.CLIENT
)
public class PillarMarkerRenderer {
    private static final double MAX_RENDER_DISTANCE = 64.0; // Only render within 64 blocks
    
    @SubscribeEvent
    public static void onRenderLevelStage(RenderLevelStageEvent event) {
        try {
            // Only render after particles (which happens after entities)
            if (event.getStage() != RenderLevelStageEvent.Stage.AFTER_PARTICLES) {
                return;
            }
            
            Minecraft mc = Minecraft.getInstance();
            if (mc == null || mc.player == null || mc.level == null) {
                return;
            }
            
            Level level = mc.level;
            if (level == null) {
                return;
            }
            
            String dimension = level.dimension().location().toString();
            Map<String, PillarMarkerManager.MarkedPillar> markedPillars = 
                PillarMarkerManager.get().getMarkedPillars(dimension);
            
            if (markedPillars == null || markedPillars.isEmpty()) {
                return;
            }
            
            Camera camera = event.getCamera();
            if (camera == null) {
                return;
            }
            
            Vec3 cameraPos = camera.getPosition();
            PoseStack poseStack = event.getPoseStack();
            MultiBufferSource.BufferSource bufferSource = mc.renderBuffers().bufferSource();
            
            // Render bounding boxes for marked pillars
            for (PillarMarkerManager.MarkedPillar marked : markedPillars.values()) {
                if (marked == null || marked.pos == null) {
                    continue;
                }
                
                BlockPos pos = marked.pos;
                
                // Check distance
                double dx = pos.getX() + 0.5 - cameraPos.x;
                double dy = pos.getY() + 0.5 - cameraPos.y;
                double dz = pos.getZ() + 0.5 - cameraPos.z;
                double distance = Math.sqrt(dx * dx + dy * dy + dz * dz);
                
                if (distance > MAX_RENDER_DISTANCE) {
                    continue;
                }
                
                // Find the full pillar stack (connected pillars above and below)
                BlockPos bottomPos = findPillarStackBottom(level, pos);
                BlockPos topPos = findPillarStackTop(level, pos);
                
                // Render bounding box for the entire stack
                renderPillarStackBoundingBox(poseStack, bufferSource, cameraPos, bottomPos, topPos, marked);
            }
        } catch (Exception e) {
            // Silently catch any rendering errors to prevent crashes
            BuildScape.getLogger().debug("Error rendering pillar markers: " + e.getMessage());
        }
    }
    
    private static BlockPos findPillarStackBottom(Level level, BlockPos startPos) {
        BlockPos current = startPos;
        int maxDepth = 256;
        int checked = 0;
        
        while (checked < maxDepth) {
            BlockPos below = current.below();
            if (!level.isLoaded(below)) {
                break;
            }
            if (!(level.getBlockState(below).getBlock() instanceof PillarBlock)) {
                break;
            }
            current = below;
            checked++;
        }
        return current;
    }
    
    private static BlockPos findPillarStackTop(Level level, BlockPos startPos) {
        BlockPos current = startPos;
        int maxHeight = 256;
        int checked = 0;
        
        while (checked < maxHeight) {
            BlockPos above = current.above();
            if (!level.isLoaded(above)) {
                break;
            }
            if (!(level.getBlockState(above).getBlock() instanceof PillarBlock)) {
                break;
            }
            current = above;
            checked++;
        }
        return current;
    }
    
    private static void renderPillarStackBoundingBox(PoseStack poseStack, MultiBufferSource.BufferSource bufferSource, 
            Vec3 cameraPos, BlockPos bottomPos, BlockPos topPos, PillarMarkerManager.MarkedPillar marked) {
        float alpha = marked.getBlinkAlpha();
        if (alpha < 0.1f) {
            return; // Don't render if too transparent
        }
        
        poseStack.pushPose();
        
        // Calculate the bounding box for the entire stack
        double minX = bottomPos.getX();
        double minY = bottomPos.getY();
        double minZ = bottomPos.getZ();
        double maxX = topPos.getX() + 1.0;
        double maxY = topPos.getY() + 1.0;
        double maxZ = topPos.getZ() + 1.0;
        
        // Offset by camera position for rendering
        double offsetX = -cameraPos.x;
        double offsetY = -cameraPos.y;
        double offsetZ = -cameraPos.z;
        
        // Calculate color with yellow-red gradient and alpha (blinking effect)
        float gradientProgress = marked.getGradientProgress(); // 0.0 = yellow, 1.0 = red
        // Yellow: RGB(255, 255, 0), Red: RGB(255, 0, 0)
        int r = 255;
        int g = (int)(255 * (1.0f - gradientProgress));
        int b = 0;
        // Apply alpha
        r = (int)(r * alpha);
        g = (int)(g * alpha);
        b = (int)(b * alpha);
        int color = (r << 24) | (g << 16) | (b << 8) | 0xFF;
        
        VertexConsumer buffer = bufferSource.getBuffer(RenderType.lines());
        
        // Draw the 12 edges of the bounding box
        // Bottom face (4 edges)
        drawLine(buffer, poseStack, minX + offsetX, minY + offsetY, minZ + offsetZ, maxX + offsetX, minY + offsetY, minZ + offsetZ, color);
        drawLine(buffer, poseStack, maxX + offsetX, minY + offsetY, minZ + offsetZ, maxX + offsetX, minY + offsetY, maxZ + offsetZ, color);
        drawLine(buffer, poseStack, maxX + offsetX, minY + offsetY, maxZ + offsetZ, minX + offsetX, minY + offsetY, maxZ + offsetZ, color);
        drawLine(buffer, poseStack, minX + offsetX, minY + offsetY, maxZ + offsetZ, minX + offsetX, minY + offsetY, minZ + offsetZ, color);
        
        // Top face (4 edges)
        drawLine(buffer, poseStack, minX + offsetX, maxY + offsetY, minZ + offsetZ, maxX + offsetX, maxY + offsetY, minZ + offsetZ, color);
        drawLine(buffer, poseStack, maxX + offsetX, maxY + offsetY, minZ + offsetZ, maxX + offsetX, maxY + offsetY, maxZ + offsetZ, color);
        drawLine(buffer, poseStack, maxX + offsetX, maxY + offsetY, maxZ + offsetZ, minX + offsetX, maxY + offsetY, maxZ + offsetZ, color);
        drawLine(buffer, poseStack, minX + offsetX, maxY + offsetY, maxZ + offsetZ, minX + offsetX, maxY + offsetY, minZ + offsetZ, color);
        
        // Vertical edges (4 edges)
        drawLine(buffer, poseStack, minX + offsetX, minY + offsetY, minZ + offsetZ, minX + offsetX, maxY + offsetY, minZ + offsetZ, color);
        drawLine(buffer, poseStack, maxX + offsetX, minY + offsetY, minZ + offsetZ, maxX + offsetX, maxY + offsetY, minZ + offsetZ, color);
        drawLine(buffer, poseStack, maxX + offsetX, minY + offsetY, maxZ + offsetZ, maxX + offsetX, maxY + offsetY, maxZ + offsetZ, color);
        drawLine(buffer, poseStack, minX + offsetX, minY + offsetY, maxZ + offsetZ, minX + offsetX, maxY + offsetY, maxZ + offsetZ, color);
        
        bufferSource.endBatch();
        poseStack.popPose();
    }
    
    private static void drawLine(VertexConsumer buffer, PoseStack poseStack, 
            double x1, double y1, double z1, double x2, double y2, double z2, int color) {
        int r = (color >> 24) & 0xFF;
        int g = (color >> 16) & 0xFF;
        int b = (color >> 8) & 0xFF;
        int a = color & 0xFF;
        
        com.mojang.math.Matrix4f pose = poseStack.last().pose();
        com.mojang.math.Matrix3f normal = poseStack.last().normal();
        
        buffer.vertex(pose, (float)x1, (float)y1, (float)z1)
            .color(r, g, b, a)
            .normal(normal, 0, 1, 0)
            .endVertex();
        buffer.vertex(pose, (float)x2, (float)y2, (float)z2)
            .color(r, g, b, a)
            .normal(normal, 0, 1, 0)
            .endVertex();
    }
    
}

package com.kingodogo.buildscape.client;

