                nbt.putInt("Invul", 100); // Renders blue shield
            }
        } else if (entityTypeName.equals("iron_golem")) {
            if (state.parsedStates.contains("cracked") || state.parsedStates.contains("broken")) {
                // Lower health shows cracks (Max 100)
