                nbt.putFloat("Health", 25.0f);
            } else {
                nbt.putFloat("Health", 100.0f);
            }
        } else if (entityTypeName.equals("snow_golem")) {
            nbt.putBoolean("Pumpkin", !state.parsedStates.contains("no_pumpkin"));
