    private static void updateEntityFromState(Entity entity, MobState state) {
        try {
            CompoundTag nbt = new CompoundTag();
            if (entity.save(nbt)) {
                applyVariantToNBT(nbt, entity.getType(), state);
                entity.load(nbt);
            }
        } catch (Exception e) {
            // Ignore NBT errors to prevent crash
        }
    }

