    /**
     * Update entity position and rotation based on states
     */
    private static void updateEntityTransform(
            Entity entity,
            BlockPos pos,
            float facingYaw,
            float rotation,
            float gameTime,
            MobState state
    ) {
        // Calculate final yaw
        float finalYaw = facingYaw;
        if (state.upsideDown) {
            finalYaw = (finalYaw + 180.0f) % 360.0f;
        }
        if (state.spin) {
            finalYaw = (finalYaw + rotation) % 360.0f;
        }
        if (finalYaw < 0) {
            finalYaw += 360.0f;
        }

        // Update rotation
        float prevYRot = entity.getYRot();
        entity.setYRot(finalYaw);
        entity.yRotO = prevYRot;

        // Update living entity rotations
        if (entity instanceof LivingEntity) {
            LivingEntity livingEntity = (LivingEntity) entity;
            float prevBodyRot = livingEntity.yBodyRot;
            livingEntity.yBodyRot = finalYaw;
            livingEntity.yBodyRotO = prevBodyRot;

            float prevHeadRot = livingEntity.yHeadRot;
            livingEntity.yHeadRot = finalYaw;
            livingEntity.yHeadRotO = prevHeadRot;
        }

        // Add floating animation
        float bobAmount = (float) Math.sin(gameTime * 2.0f) * 0.05f;
        float baseY = pos.getY() + 1.125f;
        entity.setPos(pos.getX() + 0.5, baseY + bobAmount, pos.getZ() + 0.5);
    }

    /**
     * Render the entity with appropriate transformations
     */
    private static void renderEntity(
            Entity entity,
            PoseStack poseStack,
            MultiBufferSource bufferSource,
            int combinedLight,
            float partialTicks,
            MobState state
    ) {
        // Calculate scale
        float entityWidth = entity.getBbWidth();
        float entityHeight = entity.getBbHeight();
        float scale;

        if (state.parsedStates.contains("giant") || state.parsedStates.contains("huge")) {
            // Explicitly requested GIANT size.
            if (entityHeight > 6.0f) {
                scale = 0.4f; // Massive entities (Giants) become ~4.8m
            } else {
                scale = 1.2f; // Smaller entities (Slimes) become prominent
            }
        } else if (state.parsedStates.contains("large")) {
            scale = 0.9f;
        } else if (state.parsedStates.contains("medium")) {
            scale = 0.7f;
        } else if (state.parsedStates.contains("small") && (entity instanceof net.minecraft.world.entity.monster.Slime || entity instanceof net.minecraft.world.entity.monster.MagmaCube)) {
            // Explicit small slime/cube should carry some size
            scale = 0.8f;
        } else if (state.parsedStates.contains("tiny") && (entity instanceof net.minecraft.world.entity.monster.Slime || entity instanceof net.minecraft.world.entity.monster.MagmaCube)) {
            // Tiny slime (Size 0) is very small naturally
            scale = 1.0f;
        } else {
            // Standard Auto-Scaling Logic
            if (entityHeight <= 1.0f) {
                float maxDimension = Math.max(entityWidth, entityHeight);
                float targetSize = 0.8f;
                scale = targetSize / maxDimension;
                scale = Math.min(1.5f, scale);
            } else {
                if (entityHeight > 2.5f) {
                    scale = 1.8f / entityHeight;
                } else {
                    scale = 0.9f;
                }
                scale = Math.max(0.3f, scale);
            }
        }

        // Get entity renderer
        EntityRenderDispatcher dispatcher = Minecraft.getInstance().getEntityRenderDispatcher();
        @SuppressWarnings("unchecked")
        EntityRenderer<Entity> entityRenderer = (EntityRenderer<Entity>) dispatcher.getRenderer(entity);

        if (entityRenderer != null) {
            poseStack.pushPose();

            // Apply scale
            poseStack.scale(scale, scale, scale);

            // Apply upside-down rotation
            if (state.upsideDown) {
                float centerOffset = entityHeight * 0.5f;
                poseStack.translate(0.0, centerOffset, 0.0);
                poseStack.mulPose(Vector3f.XP.rotationDegrees(180.0f));
                poseStack.translate(0.0, -centerOffset, 0.0);
            }

            // Render
            entityRenderer.render(
                    entity,
                    entity.getYRot(),
                    0.0f,
                    poseStack,
                    bufferSource,
                    combinedLight
            );

            poseStack.popPose();
        }
    }

    /**
     * Clear cached entity for a specific position
     */
    public static void clearEntityCache(BlockPos pos) {
        entityCache.entrySet().removeIf(entry -> {
            if (entry.getKey().startsWith(pos.getX() + "," + pos.getY() + "," + pos.getZ() + ":")) {
                Entity entity = entry.getValue();
                if (entity != null && entity.isAlive()) {
                    lastAppliedStates.remove(entity.getId());
                    entity.remove(Entity.RemovalReason.DISCARDED);
                }
                return true;
            }
            return false;
        });
    }

    /**
     * Clear all cached entities
     */
    public static void clearAllEntityCaches() {
        entityCache.values().forEach(entity -> {
            if (entity != null && entity.isAlive()) {
                entity.remove(Entity.RemovalReason.DISCARDED);
            }
        });
        entityCache.clear();
        lastAppliedStates.clear();
    }

    /**
     * Clean up stale entities
     */
    public static void cleanupStaleEntities() {
        entityCache.entrySet().removeIf(entry -> {
            Entity entity = entry.getValue();
            boolean isStale = entity == null || !entity.isAlive();
            if (isStale && entity != null) {
                lastAppliedStates.remove(entity.getId());
            }
            return isStale;
        });

        // Also clean up lastAppliedStates for IDs that are no longer in known entities
        // This is a bit expensive so maybe just clear it periodically or rely on removal hooks above
        // For now, let's keep it simple and safe
    }
}

package com.kingodogo.buildscape.client.renderer;

import java.util.HashSet;
import java.util.Objects;
import java.util.Set;

/**
 * Data holder for mob variant states parsed from spawn egg names.
 */
public class MobState {

    public final Set<String> parsedStates = new HashSet<>();

    public boolean spin;
    public boolean upsideDown;
    public boolean baby;
    public boolean angry;
    public boolean sitting;
    public boolean charged;
    public boolean sheared;
    public boolean saddled;
    public boolean tamed;
    public boolean powered;
    public boolean invisible;
    public boolean glowing;
    public boolean fire;
    public boolean frozen;

    public MobState() {
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        MobState mobState = (MobState) o;
        return spin == mobState.spin &&
                upsideDown == mobState.upsideDown &&
                baby == mobState.baby &&
                angry == mobState.angry &&
                sitting == mobState.sitting &&
                charged == mobState.charged &&
                sheared == mobState.sheared &&
                saddled == mobState.saddled &&
                tamed == mobState.tamed &&
                powered == mobState.powered &&
                invisible == mobState.invisible &&
                glowing == mobState.glowing &&
                fire == mobState.fire &&
                frozen == mobState.frozen &&
                Objects.equals(parsedStates, mobState.parsedStates);
    }

    @Override
    public int hashCode() {
        return Objects.hash(parsedStates, spin, upsideDown, baby, angry, sitting, charged, sheared, saddled, tamed, powered, invisible, glowing, fire, frozen);
    }

    @Override
    public String toString() {
        return "MobState{" +
                "parsedStates=" + parsedStates +
                ", spin=" + spin +
                ", upsideDown=" + upsideDown +
                ", baby=" + baby +
                ", angry=" + angry +
                ", sitting=" + sitting +
                ", charged=" + charged +
                ", sheared=" + sheared +
                ", saddled=" + saddled +
                ", tamed=" + tamed +
                ", powered=" + powered +
                ", invisible=" + invisible +
                ", glowing=" + glowing +
                ", fire=" + fire +
                ", frozen=" + frozen +
                '}';
    }
}

package com.kingodogo.buildscape.client.renderer;

import net.minecraft.client.Minecraft;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.item.ItemStack;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;

public class MobStateParser {

    // Parsed state definitions from mob_states.txt or states.txt
    private static final Map<String, Set<String>> validMobStates = new HashMap<>();
    private static final Set<String> universalStates = new HashSet<>();
    private static boolean statesLoaded = false;

    /**
     * Load and parse the states configuration file.
     * Supports both formats:
     * 1. **MobName** header with bullet points
     * 2. mob_name|state_name|description pipe-delimited
     */
    public static void loadStates() {
        if (statesLoaded) {
            return;
        }

        try {
            // Add universal states first (always available)
            addUniversalStates();

            // Try to load from root directory first (user's custom file)
            java.io.File rootStatesFile = new java.io.File("states.txt");
            InputStream stream = null;

            if (rootStatesFile.exists()) {
                stream = new java.io.FileInputStream(rootStatesFile);
                System.out.println("[BuildScape] Loading states from root directory: states.txt");
            } else {
                // Fallback to resource file
                ResourceLocation statesFile = new ResourceLocation("buildscape:mob_states.txt");
                try {
                    stream = Minecraft.getInstance()
                            .getResourceManager()
                            .getResource(statesFile)
                            .getInputStream();
                    System.out.println("[BuildScape] Loading states from resources: mob_states.txt");
                } catch (Exception e) {
                    System.err.println("[BuildScape] Could not find mob_states.txt resource.");
                }
            }

            if (stream != null) {
                BufferedReader reader = new BufferedReader(new InputStreamReader(stream));
                String line;
                String currentMob = null;

                while ((line = reader.readLine()) != null) {
                    line = line.trim();

                    // Skip empty lines
                    if (line.isEmpty()) {
                        continue;
                    }

                    // Format 2: mob|state|desc (Pipe-delimited)
                    if (line.contains("|")) {
                        String[] parts = line.split("\\|");
                        if (parts.length >= 2) {
                            String mobName = parts[0].trim().toLowerCase().replace(" ", "_");
                            String stateName = parts[1].trim().toLowerCase();

                            // Handle combined states (e.g. "baby spin") by taking the first word or checking known states
                            // For simplicity, we add the full string and individual words if separated
                            if (stateName.contains(" ")) {
                                String[] stateWords = stateName.split("\\s+");
                                for (String s : stateWords) {
                                    addStateToMob(mobName, s);
                                }
                            } else {
                                addStateToMob(mobName, stateName);
                            }

                            // Also handle wildcard mob "*"
                            if (mobName.equals("*")) {
                                universalStates.add(stateName);
                            }
                        }
                        continue;
                    }

                    // Format 1: **MobName** header
                    if (line.startsWith("**") && line.endsWith("**")) {
                        currentMob = line.substring(2, line.length() - 2).trim().toLowerCase();
                        // Normalize mob names (remove spaces, handle special cases)
                        currentMob = currentMob.replace(" ", "_");
                        continue;
                    }

                    // Format 1: • stateName bullet point
                    if (line.startsWith("•") || line.startsWith("-") || line.startsWith("*")) {
                        if (currentMob != null) {
                            String stateName = line.substring(1).trim().toLowerCase();
                            // Skip section headers like "Biomes:" or "Professions:"
                            if (stateName.endsWith(":")) {
                                continue;
                            }
                            addStateToMob(currentMob, stateName);
                        }
                    }
                }

                reader.close();
            }

            statesLoaded = true;

            System.out.println("[BuildScape] Loaded " + validMobStates.size() + " mob state definitions");
            System.out.println("[BuildScape] Universal states: " + universalStates);

        } catch (Exception e) {
            System.err.println("[BuildScape] Failed to load states: " + e.getMessage());
            e.printStackTrace();
            // Ensure at least universal states are loaded
            addUniversalStates();
            statesLoaded = true;
        }
    }

