    private void saveConfig() {
        int contentX = 0;
        int contentY = 0;
        if (parentScreen instanceof BuildScapeConfigScreen configScreen) {
            contentX = configScreen.getContentX();
            contentY = configScreen.getContentY();
        }

        int screenWidth = this.width;
        int screenHeight = this.height;

        if (config.screen == null) {
            config.screen = new GuiConfigData.ScreenConfig();
        }
        config.screen.width = screenWidth;
        config.screen.height = screenHeight;
        config.screen.scale = (float)Minecraft.getInstance().getWindow().getGuiScale();

        Map<String, GuiConfigData.ElementConfig> sidebarElements = new HashMap<>();
        Map<String, GuiConfigData.ElementConfig> tabElements = new HashMap<>();

        for (VisualElement element : visualElements) {
            boolean isSidebarElement = element.config.properties != null && 
                Boolean.TRUE.equals(element.config.properties.get("isSidebarElement"));

            int absoluteScreenX = element.config.x;
            int absoluteScreenY = element.config.y;

            int contentRelativeX = isSidebarElement ? element.config.x : element.config.x - contentX;
            int contentRelativeY = isSidebarElement ? element.config.y : element.config.y - contentY;
            
            GuiConfigData.ElementConfig savedConfig = new GuiConfigData.ElementConfig(
                contentRelativeX,
                contentRelativeY,
                element.config.width,
                element.config.height,
                element.config.scale
            );
            savedConfig.visible = element.config.visible;
            savedConfig.properties = element.config.properties != null ? 
                new HashMap<>(element.config.properties) : new HashMap<>();

            if (screenWidth > 0 && screenHeight > 0) {
                savedConfig.percentX = (double)absoluteScreenX / screenWidth;
                savedConfig.percentY = (double)absoluteScreenY / screenHeight;
                savedConfig.percentWidth = (double)element.config.width / screenWidth;
                savedConfig.percentHeight = (double)element.config.height / screenHeight;
            }
            
            if (isSidebarElement) {
                String elementId = element.elementId.startsWith("sidebar.") ?
                    element.elementId.substring(8) : element.elementId;
                sidebarElements.put(elementId, savedConfig);
            } else {
                tabElements.put(element.elementId, savedConfig);
            }
        }

        for (Map.Entry<String, GuiConfigData.ElementConfig> entry : tabElements.entrySet()) {
            config.setElementConfig(entry.getKey(), entry.getValue());
        }
        configManager.saveConfig(tabName, config);
        configManager.clearCache(tabName);

        if (!sidebarElements.isEmpty()) {
            String sidebarConfigName = "Sidebar";
            GuiConfigData sidebarConfig = configManager.loadConfig(sidebarConfigName);
            for (Map.Entry<String, GuiConfigData.ElementConfig> entry : sidebarElements.entrySet()) {
                sidebarConfig.setElementConfig(entry.getKey(), entry.getValue());
            }
            configManager.saveConfig(sidebarConfigName, sidebarConfig);
            configManager.clearCache(sidebarConfigName);
        }

        if (minecraft.player != null) {
            minecraft.player.sendMessage(
                new TranslatableComponent("buildscape.gui.editor.saved", tabName),
                java.util.UUID.randomUUID()
            );
        }

        if (parentScreen instanceof BuildScapeConfigScreen configScreen) {
            if (configScreen.getActiveTab() != null &&
                configScreen.getActiveTab().getTabName().equals(tabName)) {
                configScreen.getActiveTab().init();
            }
            configScreen.init();
        }
        
        onClose();
    }
    
    private void resetConfig() {
        config.elements.clear();
        configManager.clearCache(tabName);
        GuiConfigData freshConfig = configManager.loadConfig(tabName);
        config.elements.putAll(freshConfig.elements);
        
        visualElements.clear();
        for (Map.Entry<String, GuiConfigData.ElementConfig> entry : config.elements.entrySet()) {
            visualElements.add(new VisualElement(entry.getKey(), entry.getValue()));
        }
        
        selectedElement = null;
        deleteButton.visible = false;
    }
    
    private void scanCurrentTab() {
        if (sourceTab == null) {
            return;
        }
        
        try {
            java.lang.reflect.Field[] fields = sourceTab.getClass().getDeclaredFields();
            Map<String, GuiConfigData.ElementConfig> discoveredWidgets = new HashMap<>();

            int contentX = 0;
            int contentY = 0;
            if (parentScreen instanceof BuildScapeConfigScreen configScreen) {
                contentX = configScreen.getContentX();
                contentY = configScreen.getContentY();
            }

            Class<?> currentClass = sourceTab.getClass();
            while (currentClass != null && currentClass != Object.class) {
                java.lang.reflect.Field[] classFields = currentClass.getDeclaredFields();
                for (java.lang.reflect.Field field : classFields) {
                field.setAccessible(true);
                Object value = field.get(sourceTab);
                
                if (value == null) continue;
                
                String elementId = field.getName();
                GuiConfigData.ElementConfig elementConfig = null;
                
                if (value instanceof net.minecraft.client.gui.components.AbstractWidget widget) {
                    if (!widget.visible || widget.x < 0 || widget.y < 0) continue;
                    elementConfig = new GuiConfigData.ElementConfig(
                            widget.x - contentX, widget.y - contentY, widget.getWidth(), 20
                    );
                    try {
                        java.lang.reflect.Field heightField = 
                            net.minecraft.client.gui.components.AbstractWidget.class.getDeclaredField("height");
                        heightField.setAccessible(true);
                        elementConfig.height = heightField.getInt(widget);
                    } catch (Exception e) {}
                } else if (value instanceof EditBox editBox) {
                    if (!editBox.visible || editBox.x < 0 || editBox.y < 0) continue;
                    elementConfig = new GuiConfigData.ElementConfig(
                            editBox.x - contentX, editBox.y - contentY, editBox.getWidth(), 20
                    );
                    try {
                        java.lang.reflect.Field heightField = EditBox.class.getDeclaredField("height");
                        heightField.setAccessible(true);
                        elementConfig.height = heightField.getInt(editBox);
                    } catch (Exception e) {}
                    } else if (value instanceof Button button) {
                    if (!button.visible || button.x < 0 || button.y < 0) continue;
                        elementConfig = new GuiConfigData.ElementConfig(
                            button.x - contentX, button.y - contentY, button.getWidth(), 20
                        );
                        try {
                            java.lang.reflect.Field heightField = 
                                net.minecraft.client.gui.components.AbstractWidget.class.getDeclaredField("height");
                            heightField.setAccessible(true);
                            elementConfig.height = heightField.getInt(button);
                        } catch (Exception e) {}
                    }
                    
                    if (elementConfig != null && !discoveredWidgets.containsKey(elementId)) {
                    discoveredWidgets.put(elementId, elementConfig);
                }
                }
                currentClass = currentClass.getSuperclass();
            }

            try {
                java.lang.reflect.Field childrenField = Screen.class.getDeclaredField("children");
                childrenField.setAccessible(true);
                @SuppressWarnings("unchecked")
                List<net.minecraft.client.gui.components.events.GuiEventListener> children = 
                    (List<net.minecraft.client.gui.components.events.GuiEventListener>) childrenField.get(sourceTab);
                if (children != null) {
                    int index = 0;
                    for (net.minecraft.client.gui.components.events.GuiEventListener child : children) {
                        if (child instanceof net.minecraft.client.gui.components.AbstractWidget widget) {
                            if (widget.visible && widget.x >= 0 && widget.y >= 0) {
                                String elementId = "widget_" + index++;
                                if (!discoveredWidgets.containsKey(elementId)) {
                                    GuiConfigData.ElementConfig elementConfig = new GuiConfigData.ElementConfig(
                                        widget.x - contentX, widget.y - contentY, widget.getWidth(), 20
                                    );
                                    try {
                                        java.lang.reflect.Field heightField = 
                                            net.minecraft.client.gui.components.AbstractWidget.class.getDeclaredField("height");
                                        heightField.setAccessible(true);
                                        elementConfig.height = heightField.getInt(widget);
                                    } catch (Exception e) {}
                                    discoveredWidgets.put(elementId, elementConfig);
                                }
                            }
                        }
                    }
                }
            } catch (Exception e) {
            }

            scanTextLabels(discoveredWidgets, contentX, contentY);
            
            if (!discoveredWidgets.isEmpty()) {
                com.kingodogo.buildscape.client.screen.GuiConfigHelper.registerWidgetDefaults(tabName, discoveredWidgets);
                configManager.clearCache(tabName);
                GuiConfigData newConfig = configManager.loadConfig(tabName);

                visualElements.clear();
                for (Map.Entry<String, GuiConfigData.ElementConfig> entry : newConfig.elements.entrySet()) {
                    GuiConfigData.ElementConfig elementConfig = entry.getValue();
                    boolean isSidebarElement = elementConfig.properties != null && 
                        Boolean.TRUE.equals(elementConfig.properties.get("isSidebarElement"));
                    
                    int screenX = isSidebarElement ? elementConfig.x : elementConfig.x + contentX;
                    int screenY = isSidebarElement ? elementConfig.y : elementConfig.y + contentY;
                    
                    GuiConfigData.ElementConfig screenConfig = new GuiConfigData.ElementConfig(
                        screenX, screenY, elementConfig.width, elementConfig.height, elementConfig.scale
                    );
                    screenConfig.visible = elementConfig.visible;
                    screenConfig.properties = elementConfig.properties != null ? 
                        new HashMap<>(elementConfig.properties) : new HashMap<>();
                    visualElements.add(new VisualElement(entry.getKey(), screenConfig));
                }
                
                if (minecraft.player != null) {
                    minecraft.player.sendMessage(
                        new TranslatableComponent("buildscape.gui.editor.scanned", discoveredWidgets.size()),
                        java.util.UUID.randomUUID()
                    );
                }
            }
        } catch (Exception e) {
            BuildScape.getLogger().error("Failed to scan tab: {}", e.getMessage());
            e.printStackTrace();
        }
    }
    
    private void scanTextLabels(Map<String, GuiConfigData.ElementConfig> discoveredWidgets, int contentX, int contentY) {
        if (sourceTab == null) return;
        
        try {
            if (sourceTab instanceof PillarItemsConfigTab) {
                addTextLabel(discoveredWidgets, "pillarItemsLabel", 
                    new TranslatableComponent("buildscape.config.pillar_items").getString(),
                    0, 10, "buildscape.config.pillar_items");

                addTextLabel(discoveredWidgets, "allItemsLabel",
                    "All items", 0, (parentScreen.height - contentY) / 2, null, true);

                addTextLabel(discoveredWidgets, "presetsLabel",
                    "Presets", (parentScreen.width - contentX) / 2 + 15, 10, null);
            } else if (sourceTab instanceof PillarParticlesConfigTab) {
                String titleText = new TranslatableComponent("buildscape.config.particles.title").getString();
                int textWidth = (int)(font.width(titleText) * 2.5f);
                GuiConfigData.ElementConfig titleConfig = new GuiConfigData.ElementConfig(
                    16, 6, textWidth + 10, 20
                );
                titleConfig.properties = new HashMap<>();
                titleConfig.properties.put("isTextElement", true);
                titleConfig.properties.put("text", titleText);
                titleConfig.properties.put("textKey", "buildscape.config.particles.title");
                titleConfig.properties.put("scale", 2.5f);
                discoveredWidgets.put("particlesTitle", titleConfig);

                addTextLabel(discoveredWidgets, "defaultPropertiesLabel",
                    new TranslatableComponent("buildscape.config.particles.default_properties").getString(),
                    20, 50, "buildscape.config.particles.default_properties");

                addTextLabel(discoveredWidgets, "customPropertiesLabel",
                    new TranslatableComponent("buildscape.config.particles.custom_properties").getString(),
                    (parentScreen.width - contentX) / 2 + 15, 50, "buildscape.config.particles.custom_properties");

                addTextLabel(discoveredWidgets, "particleSpeedLabel",
                    new TranslatableComponent("buildscape.config.particles.particle_speed").getString() + " ",
                    20, 90, "buildscape.config.particles.particle_speed");
                addTextLabel(discoveredWidgets, "particleSpreadLabel",
                    new TranslatableComponent("buildscape.config.particles.particle_spread").getString() + " ",
                    20, 116, "buildscape.config.particles.particle_spread");
                addTextLabel(discoveredWidgets, "particleLifetimeLabel",
                    new TranslatableComponent("buildscape.config.particles.particle_lifetime").getString() + " ",
                    20, 142, "buildscape.config.particles.particle_lifetime");
                addTextLabel(discoveredWidgets, "particleDensityLabel",
                    new TranslatableComponent("buildscape.config.particles.particle_density").getString() + " ",
                    20, 168, "buildscape.config.particles.particle_density");
                
                addTextLabel(discoveredWidgets, "patternSpeedLabel",
                    new TranslatableComponent("buildscape.config.particles.pattern_speed").getString() + " ",
                    (parentScreen.width - contentX) / 2 + 15, 90, "buildscape.config.particles.pattern_speed");
                addTextLabel(discoveredWidgets, "patternSpreadLabel",
                    new TranslatableComponent("buildscape.config.particles.pattern_spread").getString() + " ",
                    (parentScreen.width - contentX) / 2 + 15, 116, "buildscape.config.particles.pattern_spread");
                addTextLabel(discoveredWidgets, "patternIntensityLabel",
                    new TranslatableComponent("buildscape.config.particles.pattern_intensity").getString() + " ",
                    (parentScreen.width - contentX) / 2 + 15, 142, "buildscape.config.particles.pattern_intensity");
            } else if (sourceTab instanceof PillarIdsConfigTab) {
                int tableX = 12;
                int tableY = 32;
                int[] columns = new int[] { 
                    (int)((parentScreen.width - contentX - 24) * 0.22f),
                    (int)((parentScreen.width - contentX - 24) * 0.36f),
                    (int)((parentScreen.width - contentX - 24) * 0.16f)
                };
                int headerY = tableY + 28;

                int x = tableX;
                addTextLabel(discoveredWidgets, "pillarIdHeader",
                    new TranslatableComponent("buildscape.config.ids.id").getString(),
                    x + 6, headerY + 8, "buildscape.config.ids.id");
                x += columns[0] + 8;

                addTextLabel(discoveredWidgets, "colorsHeader",
                    new TranslatableComponent("buildscape.config.ids.colors").getString(),
                    x + 6, headerY + 8, "buildscape.config.ids.colors");
                x += columns[1] + 8;
                
                addTextLabel(discoveredWidgets, "dimensionHeader",
                    new TranslatableComponent("buildscape.config.ids.dimension").getString(),
                    x + 6, headerY + 8, "buildscape.config.ids.dimension");
                x += columns[2] + 8;
                
                addTextLabel(discoveredWidgets, "coordsHeader",
                    new TranslatableComponent("buildscape.config.ids.coords").getString(),
                    x + 6, headerY + 8, "buildscape.config.ids.coords");
            }
            if (parentScreen instanceof BuildScapeConfigScreen) {
                addTextLabel(discoveredWidgets, "configScreenTitle",
                    "BuildScape Config", parentScreen.width / 2 - font.width("BuildScape Config") / 2, 10, null);
            }
        } catch (Exception e) {
            BuildScape.getLogger().warn("Failed to scan text labels: {}", e.getMessage());
            e.printStackTrace();
        }
    }
    
    private void addTextLabel(Map<String, GuiConfigData.ElementConfig> discoveredWidgets,
                             String elementId, String text, int x, int y, String textKey) {
        addTextLabel(discoveredWidgets, elementId, text, x, y, textKey, false);
    }
    
    private void addTextLabel(Map<String, GuiConfigData.ElementConfig> discoveredWidgets,
                             String elementId, String text, int x, int y, String textKey, boolean isDynamic) {
        if (text == null || text.isEmpty()) return;
        
        int textWidth = font.width(text);
        int textHeight = 12;
        
        GuiConfigData.ElementConfig labelConfig = new GuiConfigData.ElementConfig(
            x, y, textWidth + 10, textHeight
        );
        labelConfig.properties = new HashMap<>();
        labelConfig.properties.put("isTextElement", true);
        labelConfig.properties.put("text", text);
        if (textKey != null) {
            labelConfig.properties.put("textKey", textKey);
        }
        if (isDynamic) {
            labelConfig.properties.put("isDynamic", true);
        }
        discoveredWidgets.put(elementId, labelConfig);
    }
    
    @Override
    public void onClose() {
        minecraft.setScreen(parentScreen);
    }
}

package com.kingodogo.buildscape.client.screen;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.screens.Screen;
import net.minecraft.client.renderer.entity.ItemRenderer;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.TranslatableComponent;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.registries.ForgeRegistries;
import com.mojang.blaze3d.vertex.PoseStack;

public class InventoryItemSelectorScreen extends Screen {
    private static final int SLOT_SIZE = 18;
    private static final int SLOTS_PER_ROW = 9;
    
    private final Screen parentScreen;
    private final PillarItemsConfigTab configTab;
    private Button backButton;
    
    public InventoryItemSelectorScreen(Screen parent, PillarItemsConfigTab configTab) {
        super(new TranslatableComponent("buildscape.config.select_inventory"));
        this.parentScreen = parent;
        this.configTab = configTab;
    }
    
    @Override
    protected void init() {
        super.init();
        
        backButton = new Button(
            width / 2 - 100, height - 30,
            200, 20,
            new TranslatableComponent("gui.back"),
            (button) -> onClose()
        );
        addRenderableWidget(backButton);
    }
    
    @Override
    public void render(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        this.renderBackground(poseStack);
        
        // Render title
        net.minecraft.client.gui.GuiComponent.drawCenteredString(poseStack, font, title, width / 2, 20, 0xFFFFFF);
        
        // Render instruction
        net.minecraft.client.gui.GuiComponent.drawCenteredString(poseStack, font,
            new TranslatableComponent("buildscape.config.select_inventory.instruction"),
            width / 2, 40, 0xCCCCCC);
        
        // Render inventory
        Minecraft mc = Minecraft.getInstance();
        if (mc.player != null) {
            Inventory inventory = mc.player.getInventory();
            ItemRenderer itemRenderer = mc.getItemRenderer();
            
            int startX = (width - SLOTS_PER_ROW * SLOT_SIZE) / 2;
            int startY = 60;
            
            // Render hotbar (slots 0-8)
            for (int i = 0; i < 9; i++) {
                int x = startX + i * SLOT_SIZE;
                int y = startY;
                renderInventorySlot(poseStack, itemRenderer, inventory.getItem(i), x, y, mouseX, mouseY);
            }
            
            // Render main inventory (slots 9-35)
            for (int row = 0; row < 3; row++) {
                for (int col = 0; col < 9; col++) {
                    int slot = 9 + row * 9 + col;
                    int x = startX + col * SLOT_SIZE;
                    int y = startY + (row + 1) * SLOT_SIZE + 5;
                    renderInventorySlot(poseStack, itemRenderer, inventory.getItem(slot), x, y, mouseX, mouseY);
                }
            }
        }
        
        super.render(poseStack, mouseX, mouseY, partialTick);
    }
    
    private void renderInventorySlot(PoseStack poseStack, ItemRenderer itemRenderer, 
                                     ItemStack stack, int x, int y, int mouseX, int mouseY) {
        // Render slot background
        boolean hovered = mouseX >= x && mouseX < x + SLOT_SIZE &&
                          mouseY >= y && mouseY < y + SLOT_SIZE;
        int bgColor = hovered ? 0xFF555555 : 0xFF333333;
        fill(poseStack, x, y, x + SLOT_SIZE, y + SLOT_SIZE, bgColor);
        
        // Render item
        if (!stack.isEmpty()) {
            itemRenderer.renderGuiItem(stack, x + 1, y + 1);
            itemRenderer.renderGuiItemDecorations(font, stack, x + 1, y + 1);
        }
    }
    
    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (super.mouseClicked(mouseX, mouseY, button)) {
            return true;
        }
        
        // Check if clicking on inventory slot
        Minecraft mc = Minecraft.getInstance();
        if (mc.player != null && button == 0) {
            Inventory inventory = mc.player.getInventory();
            
            int startX = (width - SLOTS_PER_ROW * SLOT_SIZE) / 2;
            int startY = 60;
            
            // Check hotbar
            for (int i = 0; i < 9; i++) {
                int x = startX + i * SLOT_SIZE;
                int y = startY;
                if (mouseX >= x && mouseX < x + SLOT_SIZE &&
                    mouseY >= y && mouseY < y + SLOT_SIZE) {
                    ItemStack stack = inventory.getItem(i);
                    if (!stack.isEmpty()) {
                        selectItem(stack);
                        return true;
                    }
                }
            }
            
            // Check main inventory
            for (int row = 0; row < 3; row++) {
                for (int col = 0; col < 9; col++) {
                    int slot = 9 + row * 9 + col;
                    int x = startX + col * SLOT_SIZE;
                    int y = startY + (row + 1) * SLOT_SIZE + 5;
                    if (mouseX >= x && mouseX < x + SLOT_SIZE &&
                        mouseY >= y && mouseY < y + SLOT_SIZE) {
                        ItemStack stack = inventory.getItem(slot);
                        if (!stack.isEmpty()) {
                            selectItem(stack);
                            return true;
                        }
                    }
                }
            }
        }
        
        return false;
    }
    
    private void selectItem(ItemStack stack) {
        String itemId = ForgeRegistries.ITEMS.getKey(stack.getItem()).toString();
        if (configTab != null) {
            // Add item through the config tab
            configTab.onItemSelected(itemId);
        } else {
            // Fallback: directly call the config
            com.kingodogo.buildscape.config.PillarParticleConfig.addItemToConfig(itemId);
            if (Minecraft.getInstance().player != null) {
                Minecraft.getInstance().player.sendMessage(
                    new TranslatableComponent("buildscape.config.item_added", itemId),
                    java.util.UUID.randomUUID()
                );
            }
        }
        onClose();
    }
    
    @Override
    public void onClose() {
        Minecraft.getInstance().setScreen(parentScreen);
    }
    
    @Override
    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
        if (keyCode == 256) { // ESC
            onClose();
            return true;
        }
        return super.keyPressed(keyCode, scanCode, modifiers);
    }
}

package com.kingodogo.buildscape.client.screen;

import com.kingodogo.buildscape.client.screen.widget.ColorPickerWidget;
import com.kingodogo.buildscape.client.screen.widget.ColorSwatchButton;
import com.kingodogo.buildscape.client.screen.widget.IntSliderWidget;
import com.kingodogo.buildscape.config.PillarIdManager;
import com.kingodogo.buildscape.config.PillarParticleConfig;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.GuiComponent;
import net.minecraft.network.chat.TranslatableComponent;
import net.minecraft.network.chat.TextComponent;
import com.mojang.blaze3d.vertex.PoseStack;
import java.util.ArrayList;
import java.util.List;

public class PillarIdDetailConfigTab extends AbstractConfigTab {
    private static final String[] PATTERNS = {"none", "default", "beam", "spiral", "fountain", "pulse", "ring", "burst", "snowflake"};
    private static final int MAX_COLORS = 5;

    private final String pillarId;
    private PillarIdManager.PillarData pillarData;

    private Button backButton;
    private Button saveButton;
    private Button patternSelector;
    private EditBox patternSpeedField;
    private EditBox patternSpreadField;
    private EditBox patternIntensityField;
    private IntSliderWidget maxParticleColorSlider;
    private List<ColorSwatchButton> colorSwatchButtons;
    private List<EditBox> colorHexFields;
    private ColorPickerWidget colorPicker;
    private int selectedColorIndex = -1;
    private int currentPatternIndex = 0;
    private int currentMaxColor = 5;

    // Panel coordinates
    private int leftBoxX, leftBoxY, leftBoxWidth, leftBoxHeight;
    private int rightBoxX, rightBoxY, rightBoxWidth, rightBoxHeight;

    public PillarIdDetailConfigTab(BuildScapeConfigScreen parent, String pillarId) {
        super(parent);
        this.pillarId = pillarId;
    }

    @Override
    public void init() {
        // Load pillar data
        PillarIdManager manager = PillarIdManager.get();
        try {
            manager.checkAndReload();
        } catch (Exception e) {
            // Ignore reload errors
        }

        pillarData = manager.getPillarData(pillarId);
        if (pillarData == null) {
            parent.setActiveTab(new PillarIdsConfigTab(parent));
            return;
        }

        // Try to sync pattern from block entity
        syncPatternFromBlockEntity(manager);
        pillarData = manager.getPillarData(pillarId);
        if (pillarData == null) {
            parent.setActiveTab(new PillarIdsConfigTab(parent));
            return;
        }

        PillarParticleConfig globalConfig = PillarParticleConfig.get();

        // Back button
        backButton = new Button(
            0, 0,
            80, 20,
            new TextComponent("← Back"),
            (btn) -> parent.setActiveTab(new PillarIdsConfigTab(parent))
        );
        addTabWidget(backButton);

        // Pattern selector
        String pattern = pillarData.pattern != null ? pillarData.pattern : globalConfig.pattern;
        currentPatternIndex = findPatternIndex(pattern);
        patternSelector = new com.kingodogo.buildscape.client.screen.widget.WideButton(
            0, 0,
            100, 20,
            new TranslatableComponent("buildscape.config.particles.pattern." + pattern),
            (btn) -> cyclePattern()
        );
        patternSelector.active = true;
        addTabWidget(patternSelector);

        // Pattern speed
        double patternSpeed = pillarData.pattern_speed != null ? pillarData.pattern_speed : globalConfig.pattern_speed;
        patternSpeedField = new EditBox(
            Minecraft.getInstance().font,
            0, 0,
            120, 20,
            TextComponent.EMPTY
        );
        patternSpeedField.setValue(String.valueOf(patternSpeed));
        patternSpeedField.setEditable(true);
        patternSpeedField.setBordered(true);
        patternSpeedField.setTextColor(0xFFFFFF);
        patternSpeedField.setTextColorUneditable(0xAAAAAA);
        patternSpeedField.setMaxLength(64);
        addTabWidget(patternSpeedField);

        // Pattern spread
        double patternSpread = pillarData.pattern_spread != null ? pillarData.pattern_spread : globalConfig.pattern_spread;
        patternSpreadField = new EditBox(
            Minecraft.getInstance().font,
            0, 0,
            120, 20,
            TextComponent.EMPTY
        );
        patternSpreadField.setValue(String.valueOf(patternSpread));
        patternSpreadField.setEditable(true);
        patternSpreadField.setBordered(true);
        patternSpreadField.setTextColor(0xFFFFFF);
        patternSpreadField.setTextColorUneditable(0xAAAAAA);
        patternSpreadField.setMaxLength(64);
        addTabWidget(patternSpreadField);

        // Pattern intensity
        double patternIntensity = pillarData.pattern_intensity != null ? pillarData.pattern_intensity : globalConfig.pattern_intensity;
        patternIntensityField = new EditBox(
            Minecraft.getInstance().font,
            0, 0,
            120, 20,
            TextComponent.EMPTY
        );
        patternIntensityField.setValue(String.valueOf(patternIntensity));
        patternIntensityField.setEditable(true);
        patternIntensityField.setBordered(true);
        patternIntensityField.setTextColor(0xFFFFFF);
        patternIntensityField.setTextColorUneditable(0xAAAAAA);
        patternIntensityField.setMaxLength(64);
        addTabWidget(patternIntensityField);

        // Max particle color slider
        int maxColor = pillarData.max_particle_color != null ? pillarData.max_particle_color : globalConfig.max_particle_color;
        currentMaxColor = Math.max(1, Math.min(MAX_COLORS, maxColor));
        maxParticleColorSlider = new IntSliderWidget(
            0, 0,
            120, 20,
            new TranslatableComponent("buildscape.config.particles.max_particle_color", currentMaxColor),
            1, MAX_COLORS, currentMaxColor,
            (value) -> onMaxParticleColorChanged(value)
        );
        maxParticleColorSlider.active = true;
        addTabWidget(maxParticleColorSlider);

        // Save button
        saveButton = new Button(
            0, 0,
            100, 20,
            new TextComponent("Save"),
            (btn) -> saveConfig()
        );
        addTabWidget(saveButton);

        // Color swatches and hex fields
        colorSwatchButtons = new ArrayList<>();
        colorHexFields = new ArrayList<>();

        List<String> colors = pillarData.dyeColors != null ? new ArrayList<>(pillarData.dyeColors) : new ArrayList<>();
        while (colors.size() < MAX_COLORS) {
            colors.add("#FFFFFF");
        }

        for (int i = 0; i < MAX_COLORS; i++) {
            final int colorIndex = i;
            String colorCode = i < colors.size() ? colors.get(i) : "#FFFFFF";
            int color = 0xFFFFFF;
            try {
                if (colorCode.startsWith("#") && colorCode.length() == 7) {
                    color = Integer.parseInt(colorCode.substring(1), 16);
                }
            } catch (NumberFormatException e) {
                // Use default white
            }

            ColorSwatchButton swatch = new ColorSwatchButton(
                0, 0,
                20, 20,
                color,
                (btn) -> onColorSwatchClicked(colorIndex)
            );
            colorSwatchButtons.add(swatch);
            addTabWidget(swatch);

            EditBox hexField = new EditBox(
                Minecraft.getInstance().font,
                0, 0,
                80, 20,
                TextComponent.EMPTY
            );
            hexField.setValue(colorCode);
            hexField.setBordered(true);
            hexField.setTextColor(0xFFFFFF);
            hexField.setMaxLength(7);
            hexField.setResponder((text) -> {
                try {
                    String hexText = text;
                    if (!hexText.startsWith("#")) {
                        hexText = "#" + hexText;
                    }
                    if (hexText.length() == 7 && hexText.matches("#[0-9A-Fa-f]{6}")) {
                        int newColor = Integer.parseInt(hexText.substring(1), 16);
                        onColorChanged(colorIndex, hexText);
                        updateSwatchButtonColor(colorIndex, newColor);
                        if (selectedColorIndex == colorIndex && colorPicker != null) {
                            colorPicker.setColor(newColor);
                        }
                        if (!text.equals(hexText)) {
                            hexField.setValue(hexText);
                        }
                    }
                } catch (NumberFormatException e) {
                    // Invalid hex, ignore
                }
            });
            colorHexFields.add(hexField);
            addTabWidget(hexField);
        }

        // Color picker - reduced size to fit in window
        colorPicker = new ColorPickerWidget(
            0, 0,
            190, 190,
            0xFFFFFF,
            (hexColor) -> {
                if (selectedColorIndex >= 0 && selectedColorIndex < MAX_COLORS) {
                    onColorChanged(selectedColorIndex, hexColor);
                    if (selectedColorIndex < colorHexFields.size()) {
                        colorHexFields.get(selectedColorIndex).setValue(hexColor);
                    }
                    try {
                        if (hexColor.startsWith("#") && hexColor.length() == 7) {
                            int newColor = Integer.parseInt(hexColor.substring(1), 16);
                            updateSwatchButtonColor(selectedColorIndex, newColor);
                        }
                    } catch (NumberFormatException e) {
                        // Ignore
                    }
                }
            }
        );
        colorPicker.visible = false;
        colorPicker.setEnabled(true);
        addTabWidget(colorPicker);

        updateSwatchesEnabledState();
    }

    private void onMaxParticleColorChanged(int value) {
        currentMaxColor = value;
        updateSwatchesEnabledState();
        if (maxParticleColorSlider != null) {
            maxParticleColorSlider.setMessage(new TranslatableComponent("buildscape.config.particles.max_particle_color", currentMaxColor));
        }

        if (selectedColorIndex >= currentMaxColor) {
            selectedColorIndex = -1;
            if (colorPicker != null) {
                colorPicker.visible = false;
            }
            for (ColorSwatchButton swatch : colorSwatchButtons) {
                swatch.setSelected(false);
            }
        }
    }

    private void updateSwatchesEnabledState() {
        for (int i = 0; i < colorSwatchButtons.size(); i++) {
            boolean enabled = i < currentMaxColor;
            colorSwatchButtons.get(i).active = enabled;
            if (i < colorHexFields.size()) {
                colorHexFields.get(i).setEditable(enabled);
            }
        }
    }

    private void onColorSwatchClicked(int colorIndex) {
        if (colorIndex >= currentMaxColor) {
            return;
        }

        selectedColorIndex = colorIndex;

        String hexValue = "#FFFFFF";
        if (colorIndex < pillarData.dyeColors.size()) {
            hexValue = pillarData.dyeColors.get(colorIndex);
        }

        int color = 0xFFFFFF;
        try {
            if (hexValue.startsWith("#") && hexValue.length() == 7) {
                color = Integer.parseInt(hexValue.substring(1), 16);
            }
        } catch (NumberFormatException e) {
            // Use default white
        }

        if (colorPicker != null) {
            colorPicker.setColor(color);
            colorPicker.visible = true;
            colorPicker.setEnabled(true);
        }

        for (int i = 0; i < colorSwatchButtons.size(); i++) {
            colorSwatchButtons.get(i).setSelected(i == colorIndex);
        }
    }

    private void onColorChanged(int colorIndex, String hexColor) {
        if (pillarData.dyeColors == null) {
            pillarData.dyeColors = new ArrayList<>();
        }

        while (pillarData.dyeColors.size() <= colorIndex) {
            pillarData.dyeColors.add("#FFFFFF");
        }

        pillarData.dyeColors.set(colorIndex, hexColor);
        pillarData.modifiedTime = System.currentTimeMillis();
    }

    private void updateSwatchButtonColor(int index, int color) {
        if (colorSwatchButtons != null && index >= 0 && index < colorSwatchButtons.size()) {
            colorSwatchButtons.get(index).setColor(color);
        }
    }

    private int findPatternIndex(String pattern) {
        for (int i = 0; i < PATTERNS.length; i++) {
            if (PATTERNS[i].equals(pattern)) {
                return i;
            }
        }
        return 0;
    }

    private void cyclePattern() {
        currentPatternIndex = (currentPatternIndex + 1) % PATTERNS.length;
        String pattern = PATTERNS[currentPatternIndex];
        patternSelector.setMessage(new TranslatableComponent("buildscape.config.particles.pattern." + pattern));
    }

    private void saveConfig() {
        if (pillarData == null) return;

        PillarParticleConfig globalConfig = PillarParticleConfig.get();

        pillarData.pattern = PATTERNS[currentPatternIndex];

        try {
            pillarData.pattern_speed = Double.parseDouble(patternSpeedField.getValue());
        } catch (NumberFormatException e) {
            pillarData.pattern_speed = globalConfig.pattern_speed;
        }

        try {
            pillarData.pattern_spread = Double.parseDouble(patternSpreadField.getValue());
        } catch (NumberFormatException e) {
            pillarData.pattern_spread = globalConfig.pattern_spread;
        }

        try {
            pillarData.pattern_intensity = Double.parseDouble(patternIntensityField.getValue());
        } catch (NumberFormatException e) {
            pillarData.pattern_intensity = globalConfig.pattern_intensity;
        }

        pillarData.max_particle_color = currentMaxColor;

        if (pillarData.dyeColors != null) {
            while (pillarData.dyeColors.size() > currentMaxColor) {
                pillarData.dyeColors.remove(pillarData.dyeColors.size() - 1);
            }
            while (!pillarData.dyeColors.isEmpty() && 
                   (pillarData.dyeColors.get(pillarData.dyeColors.size() - 1).equals("#FFFFFF") ||
                    pillarData.dyeColors.get(pillarData.dyeColors.size() - 1).equals("#ffffff"))) {
                pillarData.dyeColors.remove(pillarData.dyeColors.size() - 1);
            }
        }

        pillarData.modifiedTime = System.currentTimeMillis();

        PillarIdManager manager = PillarIdManager.get();
        manager.saveImmediate();

        updateBlockEntityNBT();
    }

    private void updateBlockEntityNBT() {
        if (pillarData == null) return;

        try {
            net.minecraft.server.MinecraftServer server = net.minecraftforge.server.ServerLifecycleHooks.getCurrentServer();
            if (server == null || !server.isRunning()) {
                return;
            }

            // Find the level for this pillar's dimension
            for (net.minecraft.server.level.ServerLevel level : server.getAllLevels()) {
                if (level == null) continue;

                String dimensionKey = PillarIdManager.getDimensionKey(level);
                if (!dimensionKey.equals(pillarData.dimension)) {
                    continue;
                }

                net.minecraft.core.BlockPos pos = new net.minecraft.core.BlockPos(pillarData.x, pillarData.y, pillarData.z);

                if (!level.isLoaded(pos)) {
                    continue;
                }

                net.minecraft.world.level.block.entity.BlockEntity be = level.getBlockEntity(pos);
                if (!(be instanceof com.kingodogo.buildscape.block.PillarBlockEntity pillarBE)) {
                    continue;
                }

                // Find the bottom of the stack
                net.minecraft.core.BlockPos bottomPos = pillarBE.findStackBottom();
                net.minecraft.world.level.block.entity.BlockEntity bottomBE = level.getBlockEntity(bottomPos);

                if (!(bottomBE instanceof com.kingodogo.buildscape.block.PillarBlockEntity bottomPillarBE)) {
                    continue;
                }

                // Update NBT with settings from manager
                boolean needsUpdate = false;

                // Update pattern
                if (pillarData.pattern != null && !pillarData.pattern.isEmpty()) {
                    if (bottomPillarBE.getParticlePattern() == null || 
                        !bottomPillarBE.getParticlePattern().equals(pillarData.pattern)) {
                        bottomPillarBE.setParticlePattern(pillarData.pattern);
                        needsUpdate = true;
                    }
                }

                // Update pattern speed
                if (pillarData.pattern_speed != null) {
                    if (bottomPillarBE.getPatternSpeed() == null || 
                        !bottomPillarBE.getPatternSpeed().equals(pillarData.pattern_speed)) {
                        bottomPillarBE.setPatternSpeed(pillarData.pattern_speed);
                        needsUpdate = true;
                    }
                }

                // Update pattern spread
                if (pillarData.pattern_spread != null) {
                    if (bottomPillarBE.getPatternSpread() == null || 
                        !bottomPillarBE.getPatternSpread().equals(pillarData.pattern_spread)) {
                        bottomPillarBE.setPatternSpread(pillarData.pattern_spread);
                        needsUpdate = true;
                    }
                }

                // Update pattern intensity
                if (pillarData.pattern_intensity != null) {
                    if (bottomPillarBE.getPatternIntensity() == null || 
                        !bottomPillarBE.getPatternIntensity().equals(pillarData.pattern_intensity)) {
                        bottomPillarBE.setPatternIntensity(pillarData.pattern_intensity);
                        needsUpdate = true;
                    }
                }

                // Update max particle color
                if (pillarData.max_particle_color != null) {
                    if (bottomPillarBE.getMaxParticleColor() == null || 
                        !bottomPillarBE.getMaxParticleColor().equals(pillarData.max_particle_color)) {
                        bottomPillarBE.setMaxParticleColor(pillarData.max_particle_color);
                        needsUpdate = true;
                    }
                }

                // Update colors
                if (pillarData.dyeColors != null && !pillarData.dyeColors.isEmpty()) {
                    java.util.List<String> nbtColors = bottomPillarBE.getParticleColors();
                    boolean colorsChanged = false;

                    if (nbtColors == null || nbtColors.size() != pillarData.dyeColors.size()) {
                        colorsChanged = true;
                    } else {
                        for (int i = 0; i < pillarData.dyeColors.size(); i++) {
                            String managerColor = pillarData.dyeColors.get(i);
                            String nbtColor = i < nbtColors.size() ? nbtColors.get(i) : null;
                            if (nbtColor == null || !nbtColor.equals(managerColor)) {
                                colorsChanged = true;
                                break;
                            }
                        }
                    }

                    if (colorsChanged) {
                        // Clear and set colors
                        if (bottomPillarBE.getParticleColors() != null) {
                            bottomPillarBE.getParticleColors().clear();
                        }
                        for (String color : pillarData.dyeColors) {
                            if (color != null && !color.isEmpty()) {
                                bottomPillarBE.addParticleColor(color);
                            }
                        }
                        needsUpdate = true;
                    }
                }

                if (needsUpdate) {
                    bottomPillarBE.setChanged();
                    level.sendBlockUpdated(
                        bottomPos,
                        level.getBlockState(bottomPos),
                        level.getBlockState(bottomPos),
                        3
                    );
                }

                break; // Found the pillar, done
            }
        } catch (Exception e) {
            System.err.println("BuildScape: Error updating block entity NBT: " + e.getMessage());
            e.printStackTrace();
        }
    }

