            RenderSystem.disableDepthTest();
            RenderSystem.disableBlend();
            itemRenderer.renderGuiItem(stack, centerX - 8, centerY - 8);
            itemRenderer.renderGuiItemDecorations(mc.font, stack, centerX - 8, centerY - 8);
            return;
        }

        poseStack.popPose();

        RenderSystem.disableDepthTest();
        RenderSystem.disableBlend();
    }

