                if (itemIndex >= maxItems)
                    break;

                boolean isParticleTrail = CosmeticManager.getInstance().isParticleTrail(cosmeticId);

                ItemStack stack = cosmeticRegistry.resolveToItemStack(cosmeticId);
                if (stack != null && !stack.isEmpty()) {
