package com.kingodogo.buildscape.client.screen.tabs.supporters;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.api.SupportersApiCache;
import com.kingodogo.buildscape.api.SupportersApiClient;
import com.kingodogo.buildscape.api.model.CosmeticData;
import com.kingodogo.buildscape.client.screen.AbstractConfigTab;
import com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.Minecraft;

import java.util.ArrayList;
import java.util.List;
import java.util.Set;
import java.util.UUID;

public class SupportersOnlyTab extends AbstractConfigTab {
    private static final Set<UUID> FULL_ACCESS_UUIDS = Set.of(
        UUID.fromString("3f97920a-de17-4e52-9770-a4183ddf2267"),
        UUID.fromString("7145ec43-712f-45ef-83aa-b259b8a8f184")
    );
    
    private CosmeticsDisplayPanel panel1;
    private PlayerAvatarPanel panel5;
    private final SupportersTabState state = SupportersTabState.getInstance();
    private final Minecraft mc = Minecraft.getInstance();
    
    public SupportersOnlyTab(BuildScapeConfigScreen parent) {
        super(parent);
    }
    
    @Override
    public void init() {

        int parentWidth = parent.width;
        int parentHeight = parent.height;

        int sidebarWidth = parent.getSidebarWidth();
        int contentY = parent.getContentY();
        int contentHeight = parentHeight - contentY - 10;

        double gapPercent = 0.01;
        double panel1Percent = 0.55;
        double panel5Percent = 0.32;

        int panel1Width = (int)(parentWidth * panel1Percent);
        int panel5Width = (int)(parentWidth * panel5Percent);
        int gapWidth = (int)(parentWidth * gapPercent);

        int panel1X = sidebarWidth + gapWidth;
        int panel1Y = contentY;
        int panel1Height = contentHeight;

        int panel5X = panel1X + panel1Width + gapWidth;
        int panel5Y = contentY;
        int panel5Height = contentHeight;

        panel1X = Math.max(0, Math.min(panel1X, parentWidth - 10));
        panel1Y = Math.max(0, Math.min(panel1Y, parentHeight - 10));
        panel1Width = Math.max(1, Math.min(panel1Width, parentWidth - panel1X));
        panel1Height = Math.max(1, Math.min(panel1Height, parentHeight - panel1Y));
        
        panel5X = Math.max(0, Math.min(panel5X, parentWidth - 10));
        panel5Y = Math.max(0, Math.min(panel5Y, parentHeight - 10));
        panel5Width = Math.max(1, Math.min(panel5Width, parentWidth - panel5X));
        panel5Height = Math.max(1, Math.min(panel5Height, parentHeight - panel5Y));

        panel1 = new CosmeticsDisplayPanel();
        panel1.setBounds(panel1X, panel1Y, panel1Width, panel1Height);
        panel1.init();
        
        panel5 = new PlayerAvatarPanel();
        panel5.setBounds(panel5X, panel5Y, panel5Width, panel5Height);
        panel5.init();

        loadApiData();
    }
    
    private void loadApiData() {
        Minecraft mc = Minecraft.getInstance();
        if (mc.player == null) {
            loadDefaultCosmetics();
            return;
        }
        
        UUID playerUuid = mc.player.getUUID();
        if (state.getPlayerUuid() == null || !state.getPlayerUuid().equals(playerUuid) || state.getEquippedCosmetics().isEmpty()) {
            state.setPlayerUuid(playerUuid);
        }
        
        SupportersApiClient apiClient = SupportersApiClient.getInstance();
        SupportersApiCache apiCache = SupportersApiCache.getInstance();

        CosmeticData cachedCosmetics = apiCache.getCachedCosmetics(playerUuid);
        if (cachedCosmetics != null) {
            updateCosmeticsData(cachedCosmetics);
        } else {
            loadDefaultCosmetics();
        }
        
        apiClient.getCosmetics(playerUuid)
            .thenAccept(cosmetics -> {
                if (cosmetics != null) {
                    apiCache.cacheCosmetics(playerUuid, cosmetics);
                    updateCosmeticsData(cosmetics);
                } else {
                    loadDefaultCosmetics();
                }
            })
            .exceptionally(throwable -> {
                BuildScape.getLogger().error("Failed to load cosmetics: " + throwable.getMessage());
                loadDefaultCosmetics();
                return null;
            });
    }
    
    private void loadDefaultCosmetics() {
        com.kingodogo.buildscape.cosmetics.CosmeticManager cosmeticManager =
            com.kingodogo.buildscape.cosmetics.CosmeticManager.getInstance();
        Set<String> allRegisteredCosmetics = cosmeticManager.getAllCosmetics();

        List<String> defaultCosmetics = new ArrayList<>(allRegisteredCosmetics);

        String playerUsername = null;
        UUID currentPlayerUuid = null;
        if (mc.player != null) {
            playerUsername = mc.player.getName().getString();
            currentPlayerUuid = mc.player.getUUID();
        }

        Set<String> defaultUnlocked;
        if (hasFullAccess(currentPlayerUuid)) {
            defaultUnlocked = new java.util.HashSet<>(allRegisteredCosmetics);
            BuildScape.getLogger().info("Full-access UUID detected - unlocking all " + allRegisteredCosmetics.size() + " cosmetics");
        } else if (playerUsername != null && playerUsername.equalsIgnoreCase("Dev")) {
            defaultUnlocked = new java.util.HashSet<>(allRegisteredCosmetics);
            BuildScape.getLogger().info("Dev access granted - unlocking all " + allRegisteredCosmetics.size() + " cosmetics");
        } else {
            defaultUnlocked = cosmeticManager.getUnlockedCosmetics(playerUsername);
        }
        
        state.setUnlockedCosmetics(defaultUnlocked);

        if (panel1 != null) {
            panel1.setAllCosmeticIds(defaultCosmetics);
        }
    }
    
    private void updateCosmeticsData(CosmeticData cosmetics) {
        com.kingodogo.buildscape.cosmetics.CosmeticManager cosmeticManager =
            com.kingodogo.buildscape.cosmetics.CosmeticManager.getInstance();
        Set<String> allRegisteredCosmetics = cosmeticManager.getAllCosmetics();

        String playerUsername = null;
        UUID currentPlayerUuid = null;
        if (mc.player != null) {
            playerUsername = mc.player.getName().getString();
            currentPlayerUuid = mc.player.getUUID();
        }

        Set<String> unlocked = new java.util.HashSet<>(cosmetics.getUnlocked() != null ? cosmetics.getUnlocked() : new ArrayList<>());

        if (hasFullAccess(currentPlayerUuid)) {
            unlocked.addAll(allRegisteredCosmetics);
            BuildScape.getLogger().debug("Full-access UUID detected - unlocking all cosmetics");
        } else if (playerUsername != null && playerUsername.equalsIgnoreCase("Dev")) {
            unlocked.addAll(allRegisteredCosmetics);
            BuildScape.getLogger().debug("Dev access - unlocking all cosmetics");
        }
        
        state.setUnlockedCosmetics(unlocked);

        List<String> allCosmetics = new ArrayList<>(allRegisteredCosmetics);

        if (cosmetics.getLocked() != null) {
            for (String lockedId : cosmetics.getLocked()) {
                if (!allCosmetics.contains(lockedId)) {
                    allCosmetics.add(lockedId);
                }
            }
        }

        if (panel1 != null) {
            panel1.setAllCosmeticIds(allCosmetics);
        }

        if (cosmetics.getEquipped() != null && !cosmetics.getEquipped().isEmpty()) {
            state.setEquippedCosmetics(new java.util.HashSet<>(cosmetics.getEquipped()));
        } else {
            UUID storedUuid = state.getPlayerUuid();
            if (storedUuid != null) {
                state.setPlayerUuid(storedUuid);
            }
        }
    }
    
    private boolean hasFullAccess(UUID uuid) {
        return uuid != null && FULL_ACCESS_UUIDS.contains(uuid);
    }
    
    @Override
    public void render(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        if (panel1 != null) panel1.render(poseStack, mouseX, mouseY, partialTick);
        if (panel5 != null) panel5.render(poseStack, mouseX, mouseY, partialTick);

        com.mojang.blaze3d.systems.RenderSystem.disableScissor();

        boolean mouseOverPanel1 = false;
        if (panel1 != null) {
            int panel1X = panel1.getStartX();
            int panel1Y = panel1.getStartY();
            int panel1Width = panel1.getWidth();
            int panel1Height = panel1.getHeight();

            if (mouseX >= panel1X && mouseX < panel1X + panel1Width &&
                mouseY >= panel1Y && mouseY < panel1Y + panel1Height) {
                mouseOverPanel1 = true;
                panel1.renderTooltips(poseStack, mouseX, mouseY);
            }
        }

        if (!mouseOverPanel1 && panel5 != null) {
            panel5.renderTooltips(poseStack, mouseX, mouseY);
        }

        if (panel1 != null) {
            panel1.renderColorPickerOverlay(poseStack, mouseX, mouseY, partialTick);
        }
    }
    
    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (panel1 != null && panel1.mouseClicked(mouseX, mouseY, button)) return true;
        return panel5 != null && panel5.mouseClicked(mouseX, mouseY, button);
    }
    
    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
        if (panel1 != null && panel1.mouseScrolled(mouseX, mouseY, delta)) return true;
        return panel5 != null && panel5.mouseScrolled(mouseX, mouseY, delta);
    }
    
    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        if (panel1 != null && panel1.mouseDragged(mouseX, mouseY, button, dragX, dragY)) return true;

        return panel5 != null && panel5.mouseDragged(mouseX, mouseY, button, dragX, dragY);
    }
    
    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        if (panel5 != null && panel5 instanceof PlayerAvatarPanel) {
            panel5.mouseReleased(mouseX, mouseY, button);
        }

        if (panel1 != null && panel1.mouseReleased(mouseX, mouseY, button)) {
            return true;
        }
        
        return super.mouseReleased(mouseX, mouseY, button);
    }
    
    @Override
    public void onClose() {
        SupportersTabState state = SupportersTabState.getInstance();
        UUID playerUuid = state.getPlayerUuid();
        if (playerUuid != null) {
            com.kingodogo.buildscape.config.CosmeticsConfig.get().setEquippedCosmetics(
                playerUuid, 
                state.getEquippedCosmeticsBySlot()
            );
        }

        state.setSelectedCosmeticId(null);
        super.onClose();
    }


    @Override
    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
        if (panel1 != null && panel1.keyPressed(keyCode, scanCode, modifiers)) {
            return true;
        }
        return super.keyPressed(keyCode, scanCode, modifiers);
    }
    
    @Override
    public boolean charTyped(char codePoint, int modifiers) {
        if (panel1 != null && panel1.charTyped(codePoint, modifiers)) {
            return true;
        }
        return super.charTyped(codePoint, modifiers);
    }
}

package com.kingodogo.buildscape.client.screen.tabs.supporters;

import com.kingodogo.buildscape.config.CosmeticsConfig;
import com.kingodogo.buildscape.cosmetics.CosmeticManager;
import com.kingodogo.buildscape.cosmetics.CosmeticRegistry;

import java.util.*;

public class SupportersTabState {
    private static SupportersTabState instance;
    
    public static final int SLOT_HEAD = 0;
    public static final int SLOT_CHEST = 1;
    public static final int SLOT_LEGS = 2;
    public static final int SLOT_FEET = 3;
    public static final int SLOT_TRAIL = -1;
    public static final int SLOT_WINGS = -2;
    public static final int SLOT_OTHER = -100;
    
    private String selectedCosmeticId;
    private Set<String> unlockedCosmetics = new HashSet<>();
    private Set<String> equippedCosmetics = new HashSet<>();
    private Map<Integer, String> equippedCosmeticsBySlot = new HashMap<>();
    private UUID playerUuid;
    private Runnable onSelectionChanged;
    private Runnable onEquippedChanged;
    
    private SupportersTabState() {
    }
    
    public static SupportersTabState getInstance() {
        if (instance == null) {
            instance = new SupportersTabState();
        }
        return instance;
    }
    
    public void reset() {
        selectedCosmeticId = null;
        unlockedCosmetics.clear();
        equippedCosmetics.clear();
        equippedCosmeticsBySlot.clear();
        playerUuid = null;
        onSelectionChanged = null;
        onEquippedChanged = null;
    }
    
    public String getSelectedCosmeticId() {
        return selectedCosmeticId;
    }
    
    public void setSelectedCosmeticId(String cosmeticId) {
        if (this.selectedCosmeticId != cosmeticId) {
            this.selectedCosmeticId = cosmeticId;
            if (onSelectionChanged != null) {
                onSelectionChanged.run();
            }
            // Clear preview state when selection changes
            this.previewCosmeticId = null;
        }
    }
    
    private String previewCosmeticId;
    
    public String getPreviewCosmeticId() {
        return previewCosmeticId;
    }
    
    public void setPreviewCosmeticId(String previewCosmeticId) {
        this.previewCosmeticId = previewCosmeticId;
    }
    
    public Set<String> getUnlockedCosmetics() {
        return new HashSet<>(unlockedCosmetics);
    }
    
    public void setUnlockedCosmetics(Set<String> unlockedCosmetics) {
        this.unlockedCosmetics = new HashSet<>(unlockedCosmetics != null ? unlockedCosmetics : new HashSet<>());
    }
    
    public boolean isUnlocked(String cosmeticId) {
        return unlockedCosmetics.contains(cosmeticId);
    }
    
    public Set<String> getEquippedCosmetics() {
        return new HashSet<>(equippedCosmetics);
    }
    
    public void setEquippedCosmetics(Set<String> equippedCosmetics) {
        if (equippedCosmetics == null) return;
        this.equippedCosmetics = new HashSet<>(equippedCosmetics);
        updateSlotMapFromSet();
        if (onEquippedChanged != null) {
            onEquippedChanged.run();
        }
    }
    
    public void equipCosmeticToSlot(int slotIndex, String cosmeticId) {
        equippedCosmeticsBySlot.values().remove(cosmeticId);

        String oldCosmetic = equippedCosmeticsBySlot.remove(slotIndex);
        if (oldCosmetic != null) equippedCosmetics.remove(oldCosmetic);

        if (cosmeticId != null && !cosmeticId.isEmpty()) {
            equippedCosmeticsBySlot.put(slotIndex, cosmeticId);
            equippedCosmetics.add(cosmeticId);
        }
        
        if (playerUuid != null) {
            CosmeticsConfig.get().equipCosmetic(playerUuid, slotIndex, cosmeticId);
        }
        
        if (onEquippedChanged != null) {
            onEquippedChanged.run();
        }
    }
    
    public void unequipCosmeticFromSlot(int slotIndex) {
        String cosmeticId = equippedCosmeticsBySlot.remove(slotIndex);
        if (cosmeticId != null) {
            equippedCosmetics.remove(cosmeticId);
            if (playerUuid != null) {
                CosmeticsConfig.get().unequipCosmetic(playerUuid, slotIndex);
            }
            if (onEquippedChanged != null) {
                onEquippedChanged.run();
            }
        }
    }
    
    public void equipCosmetic(String cosmeticId) {
        if (cosmeticId == null) return;
        
        boolean isUnlocked = unlockedCosmetics.contains(cosmeticId);
        if (!isUnlocked && playerUuid != null) {
            net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();
            if (mc.player != null && mc.player.getName().getString().equalsIgnoreCase("Dev")) {
                isUnlocked = true;
            }
        }
        
        if (isUnlocked) {
            int bestSlot = getBestSlotForCosmetic(cosmeticId);
            equipCosmeticToSlot(bestSlot, cosmeticId);
        }
    }
    
    private int getBestSlotForCosmetic(String cosmeticId) {
        CosmeticManager manager = CosmeticManager.getInstance();
        CosmeticRegistry registry = CosmeticRegistry.getInstance();
        
        if (manager.isParticleTrail(cosmeticId)) return SLOT_TRAIL;
        
        CosmeticManager.CosmeticMetadata metadata = manager.getMetadata(cosmeticId);
        if (metadata != null && metadata.type() == CosmeticManager.CosmeticType.WINGS) return SLOT_WINGS;
        
        net.minecraft.world.item.ItemStack stack = registry.resolveToItemStack(cosmeticId);
        if (stack != null && !stack.isEmpty()) {
            int slot = getSlotIndexForStack(stack);
            if (slot >= 0) return slot;
        }
        
        return SLOT_OTHER;
    }
    
    public void unequipCosmetic(String cosmeticId) {
        if (cosmeticId == null) return;

        Integer slotToUnequip = null;
        for (Map.Entry<Integer, String> entry : equippedCosmeticsBySlot.entrySet()) {
            if (cosmeticId.equals(entry.getValue())) {
                slotToUnequip = entry.getKey();
                break;
            }
        }
        
        if (slotToUnequip != null) {
            unequipCosmeticFromSlot(slotToUnequip);
        } else {
            equippedCosmetics.remove(cosmeticId);
            if (onEquippedChanged != null) onEquippedChanged.run();
        }
    }
    
    public boolean isEquipped(String cosmeticId) {
        return equippedCosmetics.contains(cosmeticId);
    }
    
    public UUID getPlayerUuid() {
        return playerUuid;
    }
    
    public void setPlayerUuid(UUID playerUuid) {
        this.playerUuid = playerUuid;

        equippedCosmeticsBySlot.clear();
        equippedCosmetics.clear();
        
        if (playerUuid != null) {
            Map<Integer, String> saved = CosmeticsConfig.get().getEquippedCosmetics(playerUuid);
            
            String lastEquippedId = null;
            for (Map.Entry<Integer, String> entry : saved.entrySet()) {
                String cosmeticId = entry.getValue();
                if (cosmeticId != null && !cosmeticId.isEmpty()) {
                    equippedCosmeticsBySlot.put(entry.getKey(), cosmeticId);
                    equippedCosmetics.add(cosmeticId);
                    lastEquippedId = cosmeticId;
                }
            }

            if (selectedCosmeticId == null && !equippedCosmetics.isEmpty()) {
                String trailId = equippedCosmeticsBySlot.get(SLOT_TRAIL);
                setSelectedCosmeticId(trailId != null ? trailId : lastEquippedId);
            }
        }
        
        if (onEquippedChanged != null) {
            onEquippedChanged.run();
        }
    }
    
    private void updateSlotMapFromSet() {
        equippedCosmeticsBySlot.clear();
        for (String id : equippedCosmetics) {
            if (id == null || id.isEmpty()) continue;
            int slot = getBestSlotForCosmetic(id);
            equippedCosmeticsBySlot.put(slot, id);
        }
    }
    
    private int getSlotIndexForStack(net.minecraft.world.item.ItemStack stack) {
        net.minecraft.world.item.Item item = stack.getItem();
        if (item instanceof net.minecraft.world.item.ArmorItem armor) {
            switch (armor.getSlot()) {
                case HEAD -> { return SLOT_HEAD; }
                case CHEST -> { return SLOT_CHEST; }
                case LEGS -> { return SLOT_LEGS; }
                case FEET -> { return SLOT_FEET; }
                default -> { return -100; }
            }
        }
        return -100;
    }
    
    public Map<Integer, String> getEquippedCosmeticsBySlot() {
        return new HashMap<>(equippedCosmeticsBySlot);
    }
    
    public String getEquippedCosmeticInSlot(int slotIndex) {
        return equippedCosmeticsBySlot.get(slotIndex);
    }
    
    public void setOnSelectionChanged(Runnable callback) {
        this.onSelectionChanged = callback;
    }
    
    public void setOnEquippedChanged(Runnable callback) {
        this.onEquippedChanged = callback;
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import java.util.function.Consumer;

import com.mojang.blaze3d.vertex.PoseStack;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.network.chat.TextComponent;

public class ColorPickerWidget extends AbstractWidget {
    private static final int GRADIENT_SIZE = 80;
    private static final int HUE_SLIDER_WIDTH = 20;
    private static final int HUE_SLIDER_HEIGHT = 80;
    private static final int SLIDER_HEIGHT = 12;
    private static final int SLIDER_WIDTH = 80;
    private static final int SLIDER_SPACING = 18;
    private static final int TEXT_FIELD_HEIGHT = 20;
    private static final int VALUE_TEXT_WIDTH = 40;

    private int currentColor;
    private final Consumer<String> onColorChanged;
    private boolean draggingHue = false;
    private boolean draggingGradient = false;
    private boolean draggingR = false, draggingG = false, draggingB = false;
    private boolean draggingH = false, draggingS = false, draggingBrightness = false;
    private float hue = 0.0f;
    private float saturation = 1.0f;
    private float brightness = 1.0f;
    private int r = 255, g = 255, b = 255;
    private boolean enabled = true;
    private float currentScale = 1.0f;

    public EditBox rField, gField, bField;
    public EditBox hField, sField, brightnessField;
    private boolean updatingFields = false;

    public ColorPickerWidget(int x, int y, int width, int height, int initialColor, Consumer<String> onColorChanged) {
        super(x, y, width, height, net.minecraft.network.chat.TextComponent.EMPTY);
        this.currentColor = initialColor;
        this.onColorChanged = onColorChanged;
        rgbToHsb(initialColor);
        updateRgbFromColor();
        createValueFields();
    }

    public void setColor(int rgb) {
        this.currentColor = rgb;
        rgbToHsb(rgb);
        updateRgbFromColor();
        updateFieldValues();
    }

    private void createValueFields() {
        Minecraft mc = Minecraft.getInstance();
        int fieldWidth = 40;
        int fieldHeight = 12;

        rField = new EditBox(mc.font, 0, 0, fieldWidth, fieldHeight, new TextComponent(""));
        rField.setMaxLength(3);
        rField.setFilter(s -> s.matches("[0-9]*"));
        rField.setResponder(value -> {
            if (!updatingFields && !value.isEmpty()) {
                try {
                    int newR = Integer.parseInt(value);
                    if (newR >= 0 && newR <= 255) {
                        r = newR;
                        updateColorFromRgb();
                    }
                } catch (NumberFormatException e) {
                }
            }
        });

        gField = new EditBox(mc.font, 0, 0, fieldWidth, fieldHeight, new TextComponent(""));
        gField.setMaxLength(3);
        gField.setFilter(s -> s.matches("[0-9]*"));
        gField.setResponder(value -> {
            if (!updatingFields && !value.isEmpty()) {
                try {
                    int newG = Integer.parseInt(value);
                    if (newG >= 0 && newG <= 255) {
                        g = newG;
                        updateColorFromRgb();
                    }
                } catch (NumberFormatException e) {
                }
            }
        });

        bField = new EditBox(mc.font, 0, 0, fieldWidth, fieldHeight, new TextComponent(""));
        bField.setMaxLength(3);
        bField.setFilter(s -> s.matches("[0-9]*"));
        bField.setResponder(value -> {
            if (!updatingFields && !value.isEmpty()) {
                try {
                    int newB = Integer.parseInt(value);
                    if (newB >= 0 && newB <= 255) {
                        b = newB;
                        updateColorFromRgb();
                    }
                } catch (NumberFormatException e) {
                }
            }
        });

        hField = new EditBox(mc.font, 0, 0, fieldWidth, fieldHeight, new TextComponent(""));
        hField.setMaxLength(6);
        hField.setFilter(s -> s.matches("[0-9.]*"));
        hField.setResponder(value -> {
            if (!updatingFields && !value.isEmpty()) {
                try {
                    float newH = Float.parseFloat(value);
                    if (newH >= 0 && newH <= 360) {
                        hue = newH;
                        updateColorFromHsb();
                    }
                } catch (NumberFormatException e) {
                }
            }
        });

        sField = new EditBox(mc.font, 0, 0, fieldWidth, fieldHeight, new TextComponent(""));
        sField.setMaxLength(5);
        sField.setFilter(s -> s.matches("[0-9.]*"));
        sField.setResponder(value -> {
            if (!updatingFields && !value.isEmpty()) {
                try {
                    float newS = Float.parseFloat(value);
                    if (newS >= 0 && newS <= 100) {
                        saturation = newS / 100.0f;
                        updateColorFromHsb();
                    }
                } catch (NumberFormatException e) {
                }
            }
        });

        brightnessField = new EditBox(mc.font, 0, 0, fieldWidth, fieldHeight, new TextComponent(""));
        brightnessField.setMaxLength(5);
        brightnessField.setFilter(s -> s.matches("[0-9.]*"));
        brightnessField.setResponder(value -> {
            if (!updatingFields && !value.isEmpty()) {
                try {
                    float newB = Float.parseFloat(value);
                    if (newB >= 0 && newB <= 100) {
                        brightness = newB / 100.0f;
                        updateColorFromHsb();
                    }
                } catch (NumberFormatException e) {
                }
            }
        });

        updateFieldValues();
    }

    private void updateFieldValues() {
        updatingFields = true;
        if (rField != null)
            rField.setValue(String.valueOf(r));
        if (gField != null)
            gField.setValue(String.valueOf(g));
        if (bField != null)
            bField.setValue(String.valueOf(b));
        if (hField != null)
            hField.setValue(String.format("%.1f", hue));
        if (sField != null)
            sField.setValue(String.format("%.1f", saturation * 100.0f));
        if (brightnessField != null)
            brightnessField.setValue(String.format("%.1f", brightness * 100.0f));
        updatingFields = false;
    }

