    private void updateRgbFromColor() {
        r = (currentColor >> 16) & 0xFF;
        g = (currentColor >> 8) & 0xFF;
        b = currentColor & 0xFF;
    }

    private void rgbToHsb(int rgb) {
        int r = (rgb >> 16) & 0xFF;
        int g = (rgb >> 8) & 0xFF;
        int b = rgb & 0xFF;

        float[] hsb = java.awt.Color.RGBtoHSB(r, g, b, null);
        this.hue = hsb[0] * 360.0f;
        this.saturation = hsb[1];
        this.brightness = hsb[2];
    }

    private int hsbToRgb(float h, float s, float b) {
        java.awt.Color color = java.awt.Color.getHSBColor(h / 360.0f, s, b);
        return (color.getRed() << 16) | (color.getGreen() << 8) | color.getBlue();
    }

    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        Minecraft mc = Minecraft.getInstance();

        float totalUnscaledWidth = GRADIENT_SIZE + 5 + HUE_SLIDER_WIDTH + 10 + 15 + SLIDER_WIDTH + VALUE_TEXT_WIDTH
                + 10;
        float totalUnscaledHeight = GRADIENT_SIZE + 5 + 20 + 10;

        float scaleX = (float) width / totalUnscaledWidth;
        float scaleY = (float) height / totalUnscaledHeight;
        currentScale = Math.min(scaleX, scaleY);
        currentScale = Math.min(1.0f, currentScale);
        float scale = currentScale;

        int scaledGradientSize = (int) (GRADIENT_SIZE * scale);
        int scaledHueSliderWidth = (int) (HUE_SLIDER_WIDTH * scale);
        int scaledHueSliderHeight = (int) (HUE_SLIDER_HEIGHT * scale);
        int scaledSliderWidth = (int) (SLIDER_WIDTH * scale);
        int scaledSliderHeight = (int) (SLIDER_HEIGHT * scale);
        int scaledSliderSpacing = (int) (SLIDER_SPACING * scale);
        int scaledValueTextWidth = (int) (VALUE_TEXT_WIDTH * scale);
        int scaledGap1 = (int) (5 * scale);
        int scaledGap2 = (int) (10 * scale);
        int scaledLabelWidth = (int) (15 * scale);
        int scaledPadding = (int) (5 * scale);

        int gradientX = x + scaledPadding;
        int gradientY = y + scaledPadding;
        int hueSliderX = gradientX + scaledGradientSize + scaledGap1;
        int hueSliderY = gradientY;

        for (int py = 0; py < scaledGradientSize; py++) {
            for (int px = 0; px < scaledGradientSize; px++) {
                float s = px / (float) scaledGradientSize;
                float b = 1.0f - (py / (float) scaledGradientSize);
                int color = hsbToRgb(hue, s, b);
                fill(poseStack, gradientX + px, gradientY + py, gradientX + px + 1, gradientY + py + 1,
                        0xFF000000 | color);
            }
        }

        fill(poseStack, gradientX - 1, gradientY - 1, gradientX + scaledGradientSize + 1, gradientY, 0xFF000000);
        fill(poseStack, gradientX - 1, gradientY + scaledGradientSize, gradientX + scaledGradientSize + 1,
                gradientY + scaledGradientSize + 1, 0xFF000000);
        fill(poseStack, gradientX - 1, gradientY - 1, gradientX, gradientY + scaledGradientSize + 1, 0xFF000000);
        fill(poseStack, gradientX + scaledGradientSize, gradientY - 1, gradientX + scaledGradientSize + 1,
                gradientY + scaledGradientSize + 1, 0xFF000000);

        for (int py = 0; py < scaledHueSliderHeight; py++) {
            float h = (py / (float) scaledHueSliderHeight) * 360.0f;
            int color = hsbToRgb(h, 1.0f, 1.0f);
            fill(poseStack, hueSliderX, hueSliderY + py, hueSliderX + scaledHueSliderWidth, hueSliderY + py + 1,
                    0xFF000000 | color);
        }

        fill(poseStack, hueSliderX - 1, hueSliderY - 1, hueSliderX + scaledHueSliderWidth + 1, hueSliderY, 0xFF000000);
        fill(poseStack, hueSliderX - 1, hueSliderY + scaledHueSliderHeight, hueSliderX + scaledHueSliderWidth + 1,
                hueSliderY + scaledHueSliderHeight + 1, 0xFF000000);
        fill(poseStack, hueSliderX - 1, hueSliderY - 1, hueSliderX, hueSliderY + scaledHueSliderHeight + 1, 0xFF000000);
        fill(poseStack, hueSliderX + scaledHueSliderWidth, hueSliderY - 1, hueSliderX + scaledHueSliderWidth + 1,
                hueSliderY + scaledHueSliderHeight + 1, 0xFF000000);

        int indicatorX = gradientX + (int) (saturation * scaledGradientSize);
        int indicatorY = gradientY + (int) ((1.0f - brightness) * scaledGradientSize);
        fill(poseStack, indicatorX - 2, indicatorY - 2, indicatorX + 2, indicatorY + 2, 0xFFFFFFFF);
        fill(poseStack, indicatorX - 1, indicatorY - 1, indicatorX + 1, indicatorY + 1, 0xFF000000);

        int hueIndicatorY = hueSliderY + (int) ((hue / 360.0f) * scaledHueSliderHeight);
        fill(poseStack, hueSliderX - 3, hueIndicatorY - 2, hueSliderX, hueIndicatorY + 2, 0xFFFFFFFF);
        fill(poseStack, hueSliderX + scaledHueSliderWidth, hueIndicatorY - 2, hueSliderX + scaledHueSliderWidth + 3,
                hueIndicatorY + 2, 0xFFFFFFFF);

        int previewY = gradientY + scaledGradientSize + scaledGap1;
        int previewX = gradientX;
        int previewHeight = (int) (20 * scale);
        int previewWidth = scaledGradientSize + scaledHueSliderWidth + scaledGap1;
        fill(poseStack, previewX, previewY, previewX + previewWidth, previewY + previewHeight,
                0xFF000000 | currentColor);
        fill(poseStack, previewX - 1, previewY - 1, previewX + previewWidth + 1, previewY, 0xFF000000);
        fill(poseStack, previewX - 1, previewY + previewHeight, previewX + previewWidth + 1,
                previewY + previewHeight + 1, 0xFF000000);
        fill(poseStack, previewX - 1, previewY - 1, previewX, previewY + previewHeight + 1, 0xFF000000);
        fill(poseStack, previewX + previewWidth, previewY - 1, previewX + previewWidth + 1,
                previewY + previewHeight + 1, 0xFF000000);

        int rgbStartX = hueSliderX + scaledHueSliderWidth + scaledGap2;
        int rgbStartY = gradientY;
        renderSliderScaled(poseStack, mc, rgbStartX, rgbStartY, "R", r, 0, 255, 0xFF0000, draggingR, scale, false,
                mouseX, mouseY, partialTick);
        renderSliderScaled(poseStack, mc, rgbStartX, rgbStartY + scaledSliderSpacing, "G", g, 0, 255, 0x00FF00,
                draggingG, scale, false, mouseX, mouseY, partialTick);
        renderSliderScaled(poseStack, mc, rgbStartX, rgbStartY + scaledSliderSpacing * 2, "B", b, 0, 255, 0x0000FF,
                draggingB, scale, false, mouseX, mouseY, partialTick);

        int hsbStartY = rgbStartY + scaledSliderSpacing * 3 + 5;
        renderSliderScaled(poseStack, mc, rgbStartX, hsbStartY, "H", (int) hue, 0, 360, -1, draggingH, scale, true,
                mouseX, mouseY, partialTick);
        renderSliderScaled(poseStack, mc, rgbStartX, hsbStartY + scaledSliderSpacing, "S", (int) (saturation * 100), 0,
                100, -1, draggingS, scale, true, mouseX, mouseY, partialTick);
        renderSliderScaled(poseStack, mc, rgbStartX, hsbStartY + scaledSliderSpacing * 2, "B", (int) (brightness * 100),
                0, 100, -1, draggingBrightness, scale, true, mouseX, mouseY, partialTick);

        if (!enabled) {
            fill(poseStack, x, y, x + width, y + height, 0x80000000);
        }
    }

    private void renderSliderScaled(PoseStack poseStack, Minecraft mc, int x, int y, String label, int value, int min,
            int max, int gradientColor, boolean isDragging, float scale, boolean isHsb, int mouseX, int mouseY,
            float partialTick) {
        int scaledSliderWidth = (int) (SLIDER_WIDTH * scale);
        int scaledSliderHeight = (int) (SLIDER_HEIGHT * scale);

        poseStack.pushPose();
        if (scale < 1.0f) {
            poseStack.translate(x, y + 2, 0);
            poseStack.scale(scale, scale, 1.0f);
            mc.font.draw(poseStack, label, 0, 0, 0xFFFFFF);
        } else {
            mc.font.draw(poseStack, label, x, y + 2, 0xFFFFFF);
        }
        poseStack.popPose();

        int sliderX = x + 15;
        int sliderY = y;

        if (gradientColor == -1) {
            if (label.equals("H")) {
                for (int px = 0; px < scaledSliderWidth; px++) {
                    float h = (px / (float) scaledSliderWidth) * 360.0f;
                    int color = hsbToRgb(h, 1.0f, 1.0f);
                    fill(poseStack, sliderX + px, sliderY, sliderX + px + 1, sliderY + scaledSliderHeight,
                            0xFF000000 | color);
                }
            } else {
                int baseColor = label.equals("S") ? hsbToRgb(hue, 1.0f, brightness) : hsbToRgb(hue, saturation, 1.0f);
                for (int px = 0; px < scaledSliderWidth; px++) {
                    float ratio = px / (float) scaledSliderWidth;
                    int r = (baseColor >> 16) & 0xFF;
                    int g = (baseColor >> 8) & 0xFF;
                    int bl = baseColor & 0xFF;
                    if (label.equals("S")) {
                        r = (int) (128 + (r - 128) * ratio);
                        g = (int) (128 + (g - 128) * ratio);
                        bl = (int) (128 + (bl - 128) * ratio);
                    } else {
                        r = (int) (r * ratio);
                        g = (int) (g * ratio);
                        bl = (int) (bl * ratio);
                    }
                    int color = (r << 16) | (g << 8) | bl;
                    fill(poseStack, sliderX + px, sliderY, sliderX + px + 1, sliderY + scaledSliderHeight,
                            0xFF000000 | color);
                }
            }
        } else {
            for (int px = 0; px < scaledSliderWidth; px++) {
                float ratio = px / (float) scaledSliderWidth;
                int color = 0;
                if (label.equals("R")) {
                    color = ((int) (ratio * 255) << 16) | ((g << 8) | b);
                } else if (label.equals("G")) {
                    color = (r << 16) | ((int) (ratio * 255) << 8) | b;
                } else {
                    color = (r << 16) | (g << 8) | (int) (ratio * 255);
                }
                fill(poseStack, sliderX + px, sliderY, sliderX + px + 1, sliderY + scaledSliderHeight,
                        0xFF000000 | color);
            }
        }

        fill(poseStack, sliderX - 1, sliderY - 1, sliderX + scaledSliderWidth + 1, sliderY, 0xFF000000);
        fill(poseStack, sliderX - 1, sliderY + scaledSliderHeight, sliderX + scaledSliderWidth + 1,
                sliderY + scaledSliderHeight + 1, 0xFF000000);
        fill(poseStack, sliderX - 1, sliderY - 1, sliderX, sliderY + scaledSliderHeight + 1, 0xFF000000);
        fill(poseStack, sliderX + scaledSliderWidth, sliderY - 1, sliderX + scaledSliderWidth + 1,
                sliderY + scaledSliderHeight + 1, 0xFF000000);

        float ratio = (value - min) / (float) (max - min);
        int indicatorX = sliderX + (int) (ratio * scaledSliderWidth);
        fill(poseStack, indicatorX - 1, sliderY - 2, indicatorX + 1, sliderY + scaledSliderHeight + 2, 0xFFFFFFFF);
        fill(poseStack, indicatorX, sliderY - 1, indicatorX, sliderY + scaledSliderHeight + 1, 0xFF000000);

        int fieldX = sliderX + scaledSliderWidth + 3;
        int fieldY = sliderY;

        String valueStr = isHsb && !label.equals("H") ? String.format("%.1f", (float) value) : String.valueOf(value);
        int textWidth = mc.font.width(valueStr);

        int scaledFieldWidth = (int) ((textWidth + 6) * scale);
        int scaledFieldHeight = (int) (SLIDER_HEIGHT * scale) + 1;

        fill(poseStack, fieldX, fieldY, fieldX + scaledFieldWidth, fieldY + scaledFieldHeight, 0xFF000000);
        fill(poseStack, fieldX + 1, fieldY + 1, fieldX + scaledFieldWidth - 1, fieldY + scaledFieldHeight - 1,
                0x80FFFFFF);

        poseStack.pushPose();
        poseStack.translate(fieldX + 2, fieldY + 2, 0);
        poseStack.scale(scale, scale, 1.0f);
        mc.font.draw(poseStack, valueStr, 0, 0, 0xFF000000);
        poseStack.popPose();
    }

    private void renderSlider(PoseStack poseStack, Minecraft mc, int x, int y, String label, int value, int min,
            int max, int gradientColor, boolean isDragging) {
        mc.font.draw(poseStack, label, x, y + 2, 0xFFFFFF);

        int sliderX = x + 15;
        int sliderY = y;

        if (gradientColor == -1) {
            if (label.equals("H")) {
                for (int px = 0; px < SLIDER_WIDTH; px++) {
                    float h = (px / (float) SLIDER_WIDTH) * 360.0f;
                    int color = hsbToRgb(h, 1.0f, 1.0f);
                    fill(poseStack, sliderX + px, sliderY, sliderX + px + 1, sliderY + SLIDER_HEIGHT,
                            0xFF000000 | color);
                }
            } else {
                int baseColor = label.equals("S") ? hsbToRgb(hue, 1.0f, brightness) : hsbToRgb(hue, saturation, 1.0f);
                for (int px = 0; px < SLIDER_WIDTH; px++) {
                    float ratio = px / (float) SLIDER_WIDTH;
                    int r = (baseColor >> 16) & 0xFF;
                    int g = (baseColor >> 8) & 0xFF;
                    int bl = baseColor & 0xFF;
                    if (label.equals("S")) {
                        r = (int) (128 + (r - 128) * ratio);
                        g = (int) (128 + (g - 128) * ratio);
                        bl = (int) (128 + (bl - 128) * ratio);
                    } else {
                        r = (int) (r * ratio);
                        g = (int) (g * ratio);
                        bl = (int) (bl * ratio);
                    }
                    int color = (r << 16) | (g << 8) | bl;
                    fill(poseStack, sliderX + px, sliderY, sliderX + px + 1, sliderY + SLIDER_HEIGHT,
                            0xFF000000 | color);
                }
            }
        } else {
            for (int px = 0; px < SLIDER_WIDTH; px++) {
                float ratio = px / (float) SLIDER_WIDTH;
                int color = 0;
                if (label.equals("R")) {
                    color = ((int) (ratio * 255) << 16) | ((g << 8) | b);
                } else if (label.equals("G")) {
                    color = (r << 16) | ((int) (ratio * 255) << 8) | b;
                } else {
                    color = (r << 16) | (g << 8) | (int) (ratio * 255);
                }
                fill(poseStack, sliderX + px, sliderY, sliderX + px + 1, sliderY + SLIDER_HEIGHT, 0xFF000000 | color);
            }
        }

        fill(poseStack, sliderX - 1, sliderY - 1, sliderX + SLIDER_WIDTH + 1, sliderY, 0xFF000000);
        fill(poseStack, sliderX - 1, sliderY + SLIDER_HEIGHT, sliderX + SLIDER_WIDTH + 1, sliderY + SLIDER_HEIGHT + 1,
                0xFF000000);
        fill(poseStack, sliderX - 1, sliderY - 1, sliderX, sliderY + SLIDER_HEIGHT + 1, 0xFF000000);
        fill(poseStack, sliderX + SLIDER_WIDTH, sliderY - 1, sliderX + SLIDER_WIDTH + 1, sliderY + SLIDER_HEIGHT + 1,
                0xFF000000);

        float ratio = (value - min) / (float) (max - min);
        int indicatorX = sliderX + (int) (ratio * SLIDER_WIDTH);
        fill(poseStack, indicatorX - 1, sliderY - 2, indicatorX + 1, sliderY + SLIDER_HEIGHT + 2, 0xFFFFFFFF);
        fill(poseStack, indicatorX, sliderY - 1, indicatorX, sliderY + SLIDER_HEIGHT + 1, 0xFF000000);

        String valueText;
        if (label.equals("R") || label.equals("G") || label.equals("B")) {
            valueText = String.valueOf(value);
        } else {
            valueText = String.format("%.1f", (float) value);
        }
        int textX = sliderX + SLIDER_WIDTH + 3;
        int maxTextWidth = VALUE_TEXT_WIDTH - 3;
        int textWidth = mc.font.width(valueText);
        if (textWidth > maxTextWidth) {
            valueText = String.valueOf(value);
        }
        mc.font.draw(poseStack, valueText, textX, sliderY + 2, 0xFFFFFF);
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (rField != null && rField.mouseClicked(mouseX, mouseY, button))
            return true;
        if (gField != null && gField.mouseClicked(mouseX, mouseY, button))
            return true;
        if (bField != null && bField.mouseClicked(mouseX, mouseY, button))
            return true;
        if (hField != null && hField.mouseClicked(mouseX, mouseY, button))
            return true;
        if (sField != null && sField.mouseClicked(mouseX, mouseY, button))
            return true;
        if (brightnessField != null && brightnessField.mouseClicked(mouseX, mouseY, button))
            return true;

        if (!enabled || button != 0) {
            clearAllDragging();
            return false;
        }

        if (mouseX < x || mouseX >= x + width || mouseY < y || mouseY >= y + height) {
            return false;
        }

        float totalUnscaledWidth = GRADIENT_SIZE + 5 + HUE_SLIDER_WIDTH + 10 + 15 + SLIDER_WIDTH + VALUE_TEXT_WIDTH
                + 10;
        float totalUnscaledHeight = GRADIENT_SIZE + 5 + 20 + 10;

        float scaleX = (float) width / totalUnscaledWidth;
        float scaleY = (float) height / totalUnscaledHeight;
        float scale = Math.min(scaleX, scaleY);
        scale = Math.min(1.0f, scale);

        int scaledGradientSize = (int) (GRADIENT_SIZE * scale);
        int scaledHueSliderWidth = (int) (HUE_SLIDER_WIDTH * scale);
        int scaledHueSliderHeight = (int) (HUE_SLIDER_HEIGHT * scale);
        int scaledSliderWidth = (int) (SLIDER_WIDTH * scale);
        int scaledSliderSpacing = (int) (SLIDER_SPACING * scale);
        int scaledGap1 = (int) (5 * scale);
        int scaledGap2 = (int) (10 * scale);
        int scaledPadding = (int) (5 * scale);

        int gradientX = x + scaledPadding;
        int gradientY = y + scaledPadding;
        int hueSliderX = gradientX + scaledGradientSize + scaledGap1;
        int hueSliderY = gradientY;
        int rgbStartX = hueSliderX + scaledHueSliderWidth + scaledGap2;
        int rgbStartY = gradientY;
        int hsbStartY = rgbStartY + scaledSliderSpacing * 3 + scaledGap1;

        if (mouseX >= gradientX - 2 && mouseX < gradientX + scaledGradientSize + 2 &&
                mouseY >= gradientY - 2 && mouseY < gradientY + scaledGradientSize + 2) {
            draggingGradient = true;
            clearOtherDragging();
            double clampedX = Math.max(gradientX, Math.min(gradientX + scaledGradientSize - 1, mouseX));
            double clampedY = Math.max(gradientY, Math.min(gradientY + scaledGradientSize - 1, mouseY));
            saturation = (float) Math.max(0, Math.min(1, (clampedX - gradientX) / (double) scaledGradientSize));
            brightness = (float) Math.max(0, Math.min(1, 1.0 - (clampedY - gradientY) / (double) scaledGradientSize));
            updateColorFromHsb();
            return true;
        }

        if (mouseX >= hueSliderX - 2 && mouseX < hueSliderX + scaledHueSliderWidth + 2 &&
                mouseY >= hueSliderY - 2 && mouseY < hueSliderY + scaledHueSliderHeight + 2) {
            draggingGradient = false;
            draggingR = draggingG = draggingB = false;
            draggingH = draggingS = draggingBrightness = false;
            draggingHue = true;
            double clampedY = Math.max(hueSliderY, Math.min(hueSliderY + scaledHueSliderHeight - 1, mouseY));
            hue = (float) Math.max(0,
                    Math.min(360, ((clampedY - hueSliderY) / (double) scaledHueSliderHeight) * 360.0));
            updateColorFromHsb();
            return true;
        }

        int sliderX = rgbStartX + 15;
        if (mouseX >= sliderX - 2 && mouseX < sliderX + scaledSliderWidth + 2) {
            double clampedX = Math.max(sliderX, Math.min(sliderX + scaledSliderWidth - 1, mouseX));
            float ratio = (float) Math.max(0, Math.min(1, (clampedX - sliderX) / (double) scaledSliderWidth));

            if (mouseY >= rgbStartY - 2 && mouseY < rgbStartY + scaledSliderSpacing + 2) {
                draggingGradient = false;
                draggingHue = false;
                draggingG = draggingB = false;
                draggingH = draggingS = draggingBrightness = false;
                draggingR = true;
                r = (int) (ratio * 255);
                updateColorFromRgb();
                return true;
            } else if (mouseY >= rgbStartY + scaledSliderSpacing - 2
                    && mouseY < rgbStartY + scaledSliderSpacing * 2 + 2) {
                draggingGradient = false;
                draggingHue = false;
                draggingR = draggingB = false;
                draggingH = draggingS = draggingBrightness = false;
                draggingG = true;
                g = (int) (ratio * 255);
                updateColorFromRgb();
                return true;
            } else if (mouseY >= rgbStartY + scaledSliderSpacing * 2 - 2
                    && mouseY < rgbStartY + scaledSliderSpacing * 3 + 2) {
                draggingGradient = false;
                draggingHue = false;
                draggingR = draggingG = false;
                draggingH = draggingS = draggingBrightness = false;
                draggingB = true;
                b = (int) (ratio * 255);
                updateColorFromRgb();
                return true;
            }
        }

        if (mouseX >= sliderX - 2 && mouseX < sliderX + scaledSliderWidth + 2) {
            double clampedX = Math.max(sliderX, Math.min(sliderX + scaledSliderWidth - 1, mouseX));
            float ratio = (float) Math.max(0, Math.min(1, (clampedX - sliderX) / (double) scaledSliderWidth));

            if (mouseY >= hsbStartY - 2 && mouseY < hsbStartY + scaledSliderSpacing + 2) {
                draggingGradient = false;
                draggingHue = false;
                draggingR = draggingG = draggingB = false;
                draggingS = draggingBrightness = false;
                draggingH = true;
                hue = ratio * 360.0f;
                updateColorFromHsb();
                return true;
            } else if (mouseY >= hsbStartY + scaledSliderSpacing - 2
                    && mouseY < hsbStartY + scaledSliderSpacing * 2 + 2) {
                draggingGradient = false;
                draggingHue = false;
                draggingR = draggingG = draggingB = false;
                draggingH = draggingBrightness = false;
                draggingS = true;
                saturation = ratio;
                updateColorFromHsb();
                return true;
            } else if (mouseY >= hsbStartY + scaledSliderSpacing * 2 - 2
                    && mouseY < hsbStartY + scaledSliderSpacing * 3 + 2) {
                draggingGradient = false;
                draggingHue = false;
                draggingR = draggingG = draggingB = false;
                draggingH = draggingS = false;
                draggingBrightness = true;
                brightness = ratio;
                updateColorFromHsb();
                return true;
            }
        }

        clearAllDragging();
        return false;
    }

    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        boolean isDragging = draggingGradient || draggingHue || draggingR || draggingG || draggingB ||
                draggingH || draggingS || draggingBrightness;

        if (!enabled && !isDragging) {
            clearAllDragging();
            return false;
        }

        if (!isDragging) {
            return false;
        }

        float totalUnscaledWidth = GRADIENT_SIZE + 5 + HUE_SLIDER_WIDTH + 10 + 15 + SLIDER_WIDTH + VALUE_TEXT_WIDTH
                + 10;
        float totalUnscaledHeight = GRADIENT_SIZE + 5 + 20 + 10;

        float scaleX = (float) width / totalUnscaledWidth;
        float scaleY = (float) height / totalUnscaledHeight;
        float scale = Math.min(scaleX, scaleY);
        scale = Math.min(1.0f, scale);

        int scaledGradientSize = (int) (GRADIENT_SIZE * scale);
        int scaledHueSliderWidth = (int) (HUE_SLIDER_WIDTH * scale);
        int scaledHueSliderHeight = (int) (HUE_SLIDER_HEIGHT * scale);
        int scaledSliderWidth = (int) (SLIDER_WIDTH * scale);
        int scaledSliderSpacing = (int) (SLIDER_SPACING * scale);
        int scaledGap1 = (int) (5 * scale);
        int scaledGap2 = (int) (10 * scale);
        int scaledPadding = (int) (5 * scale);

        int gradientX = x + scaledPadding;
        int gradientY = y + scaledPadding;
        int hueSliderX = gradientX + scaledGradientSize + scaledGap1;
        int hueSliderY = gradientY;
        int rgbStartX = hueSliderX + scaledHueSliderWidth + scaledGap2;
        int sliderX = rgbStartX + (int) (15 * scale);

        if (draggingGradient) {
            double clampedX = Math.max(gradientX, Math.min(gradientX + scaledGradientSize - 1, mouseX));
            double clampedY = Math.max(gradientY, Math.min(gradientY + scaledGradientSize - 1, mouseY));
            saturation = (float) Math.max(0, Math.min(1, (clampedX - gradientX) / (double) scaledGradientSize));
            brightness = (float) Math.max(0, Math.min(1, 1.0 - (clampedY - gradientY) / (double) scaledGradientSize));
            updateColorFromHsb();
            return true;
        }

        if (draggingHue) {
            double clampedY = Math.max(hueSliderY, Math.min(hueSliderY + scaledHueSliderHeight - 1, mouseY));
            hue = (float) Math.max(0,
                    Math.min(360, ((clampedY - hueSliderY) / (double) scaledHueSliderHeight) * 360.0));
            updateColorFromHsb();
            return true;
        }

        if (draggingR || draggingG || draggingB || draggingH || draggingS || draggingBrightness) {
            double clampedX = Math.max(sliderX, Math.min(sliderX + scaledSliderWidth - 1, mouseX));
            float ratio = (float) Math.max(0, Math.min(1, (clampedX - sliderX) / (double) scaledSliderWidth));

            if (draggingR) {
                r = (int) (ratio * 255);
                updateColorFromRgb();
                return true;
            }

            if (draggingG) {
                g = (int) (ratio * 255);
                updateColorFromRgb();
                return true;
            }

            if (draggingB) {
                b = (int) (ratio * 255);
                updateColorFromRgb();
                return true;
            }

            if (draggingH) {
                hue = ratio * 360.0f;
                updateColorFromHsb();
                return true;
            }

            if (draggingS) {
                saturation = ratio;
                updateColorFromHsb();
                return true;
            }

            if (draggingBrightness) {
                brightness = ratio;
                updateColorFromHsb();
                return true;
            }
        }

        return false;
    }

    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        boolean wasDragging = draggingGradient || draggingHue || draggingR || draggingG || draggingB ||
                draggingH || draggingS || draggingBrightness;
        clearAllDragging();
        return wasDragging;
    }

    private void clearAllDragging() {
        draggingGradient = false;
        draggingHue = false;
        draggingR = draggingG = draggingB = false;
        draggingH = draggingS = draggingBrightness = false;
    }

    private void clearOtherDragging() {
        if (!draggingGradient)
            draggingGradient = false;
        if (!draggingHue)
            draggingHue = false;
        if (!draggingR)
            draggingR = false;
        if (!draggingG)
            draggingG = false;
        if (!draggingB)
            draggingB = false;
        if (!draggingH)
            draggingH = false;
        if (!draggingS)
            draggingS = false;
        if (!draggingBrightness)
            draggingBrightness = false;
    }

    private void updateColorFromHsb() {
        currentColor = hsbToRgb(hue, saturation, brightness);
        updateRgbFromColor();
        updateFieldValues();
        if (onColorChanged != null) {
            String hexColor = String.format("#%06X", currentColor);
            onColorChanged.accept(hexColor);
        }
    }

    private void updateColorFromRgb() {
        currentColor = (r << 16) | (g << 8) | b;
        rgbToHsb(currentColor);
        updateFieldValues();
        if (onColorChanged != null) {
            String hexColor = String.format("#%06X", currentColor);
            onColorChanged.accept(hexColor);
        }
    }

    @Override
    public void updateNarration(NarrationElementOutput narrationElementOutput) {
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.gui.components.Button;
import net.minecraft.network.chat.TextComponent;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.gui.GuiComponent;

public class ColorSwatchButton extends Button {
    private int color = 0xFFFFFF;
    private boolean isSelected = false;
    
    public ColorSwatchButton(int x, int y, int width, int height, int color, OnPress onPress) {
        super(x, y, width, height, TextComponent.EMPTY, onPress);
        this.color = color;
    }
    
    public void setColor(int color) {
        this.color = color;
    }
    
    public int getColor() {
        return color;
    }
    
    public void setSelected(boolean selected) {
        this.isSelected = selected;
    }
    
    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        int swatchX = this.x;
        int swatchY = this.y;
        int swatchSize = this.width;

        int displayColor = color;
        if (!this.active) {
            int r = (color >> 16) & 0xFF;
            int g = (color >> 8) & 0xFF;
            int b = color & 0xFF;
            r = (int)(r * 0.4f);
            g = (int)(g * 0.4f);
            b = (int)(b * 0.4f);
            displayColor = (r << 16) | (g << 8) | b;
        }
        GuiComponent.fill(poseStack, swatchX, swatchY, swatchX + swatchSize, swatchY + swatchSize, 0xFF000000 | displayColor);

        int borderColor = this.active ? 0xFFFFFFFF : 0xFF666666;
        GuiComponent.fill(poseStack, swatchX, swatchY, swatchX + swatchSize, swatchY + 1, borderColor);
        GuiComponent.fill(poseStack, swatchX, swatchY + swatchSize - 1, swatchX + swatchSize, swatchY + swatchSize, borderColor);
        GuiComponent.fill(poseStack, swatchX, swatchY, swatchX + 1, swatchY + swatchSize, borderColor);
        GuiComponent.fill(poseStack, swatchX + swatchSize - 1, swatchY, swatchX + swatchSize, swatchY + swatchSize, borderColor);

        if (isSelected && this.active) {
            GuiComponent.fill(poseStack, swatchX - 2, swatchY - 2, swatchX + swatchSize + 2, swatchY, 0xFFFF00FF);
            GuiComponent.fill(poseStack, swatchX - 2, swatchY + swatchSize, swatchX + swatchSize + 2, swatchY + swatchSize + 2, 0xFFFF00FF);
            GuiComponent.fill(poseStack, swatchX - 2, swatchY - 2, swatchX, swatchY + swatchSize + 2, 0xFFFF00FF);
            GuiComponent.fill(poseStack, swatchX + swatchSize, swatchY - 2, swatchX + swatchSize + 2, swatchY + swatchSize + 2, 0xFFFF00FF);
        }
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.gui.components.Button;
import net.minecraft.network.chat.Component;

public class ConfigCategoryButton extends Button {
    private boolean active = false;
    
    public ConfigCategoryButton(int x, int y, int width, int height, Component message, OnPress onPress) {
        super(x, y, width, height, message, onPress);
    }
    
    public void setActive(boolean active) {
        this.active = active;
    }
    
    @Override
    public void renderButton(com.mojang.blaze3d.vertex.PoseStack poseStack, int mouseX, int mouseY, float partialTick) {

        net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();
        double guiScale = mc.getWindow().getGuiScale();
        float textScale = 1.0f;
        if (guiScale >= 3.0) {
            textScale = 0.75f;
        } else if (guiScale >= 2.5) {
            textScale = 0.85f;
        }

        String buttonText = getMessage().getString();
        int textColor = active ? 0xFFFFFF : 0xCCCCCC;

        int availableWidth = (int)(width / textScale);
        int textWidth = mc.font.width(buttonText);

        if (textWidth > availableWidth) {
            String truncated = mc.font.plainSubstrByWidth(buttonText, availableWidth - mc.font.width("..."));
            buttonText = truncated + "...";
        }

        poseStack.pushPose();
        poseStack.translate(x + width / 2.0, y + (height - 8) / 2.0, 0);
        poseStack.scale(textScale, textScale, 1.0f);
        drawCenteredString(poseStack, 
            mc.font, 
            new net.minecraft.network.chat.TextComponent(buttonText), 
            0, 
            0, 
            textColor
        );
        poseStack.popPose();
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import com.mojang.blaze3d.systems.RenderSystem;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.gui.GuiComponent;
import net.minecraft.client.renderer.GameRenderer;
import net.minecraft.resources.ResourceLocation;

/**
 * Utility class for rendering custom scrollbars with drag-to-scroll
 * functionality.
 * Supports both mouse wheel scrolling and click-drag scrolling on content
 * areas.
 */
public class CustomScrollbarRenderer {
    // For Minecraft 1.18.2, use the two-argument constructor
    private static final ResourceLocation CUSTOM_SCROLLER_TEXTURE = new ResourceLocation("buildscape",
            "textures/gui/custom_scroller.png");

    private static final int SCROLLBAR_WIDTH = 8;
    private static final int MIN_THUMB_HEIGHT = 21; // Match new texture height + padding if needed

    // Drag state tracking
    private boolean isDraggingScrollbar = false;
    private boolean isDraggingContent = false;
    private double scrollbarDragStartY = 0;
    private double scrollbarDragStartOffset = 0;
    private double contentDragStartY = 0;
    private double contentDragStartOffset = 0;

    /**
     * Gets the scrollbar width.
     */
    public static int getScrollbarWidth() {
        return SCROLLBAR_WIDTH;
    }

    /**
     * Checks if currently dragging (scrollbar or content).
     */
    public boolean isDragging() {
        return isDraggingScrollbar || isDraggingContent;
    }

    /**
     * Renders the custom scrollbar with texture.
     * 
     * @param poseStack    The pose stack for rendering
     * @param x            X position of the scrollbar
     * @param y            Y position of the scrollbar
     * @param height       Height of the scrollbar track
     * @param scrollOffset Current scroll offset
     * @param maxScroll    Maximum scroll value
     * @param visibleRatio Ratio of visible content to total content (0.0-1.0)
     */
    public void renderScrollbar(PoseStack poseStack, int x, int y, int height,
            double scrollOffset, double maxScroll, double visibleRatio) {
        if (maxScroll <= 0) {
            return;
        }

        // Push pose and disable depth test to render on top (prevent clipping)
        poseStack.pushPose();
        poseStack.translate(0, 0, 400); // Render way in front
        RenderSystem.disableDepthTest(); // Disable depth test to prevent clipping

        // Calculate scroll position ratio
        double scrollRatio = maxScroll > 0 ? scrollOffset / maxScroll : 0;

        // Render scrollbar track (thin vertical line in the center)
        int trackX = x + (SCROLLBAR_WIDTH / 2);
        GuiComponent.fill(poseStack, trackX, y, trackX + 1, y + height, 0x80000000);

        // Render custom scrollbar thumb as a SINGLE fixed-size element
        RenderSystem.setShader(GameRenderer::getPositionTexShader);
        RenderSystem.setShaderTexture(0, CUSTOM_SCROLLER_TEXTURE);
        RenderSystem.setShaderColor(1.0f, 1.0f, 1.0f, 1.0f);
        RenderSystem.enableBlend();
        RenderSystem.defaultBlendFunc();

        // The scroller texture is 8x17, render it at fixed size
        int scrollerWidth = 8; // Use correct texture width
        int scrollerHeight = 17; // Fixed height from texture

        // Calculate thumb position - it moves along the track
        // Leave space at top and bottom for the thumb
        int usableTrackHeight = height - scrollerHeight;
        int thumbY = y + (int) (scrollRatio * usableTrackHeight);

        // Render the scroller texture as a single fixed-size element
        // blit(poseStack, x, y, u, v, width, height, textureWidth, textureHeight)
        GuiComponent.blit(poseStack, x, thumbY, 0, 0, scrollerWidth, scrollerHeight, 8, 17);

        RenderSystem.disableBlend();
        RenderSystem.enableDepthTest(); // Re-enable depth test

        poseStack.popPose(); // Restore pose
    }

    /**
     * Handles mouse click on scrollbar or content area.
     * 
     * @param mouseX          Mouse X position
     * @param mouseY          Mouse Y position
     * @param button          Mouse button (0 = left click)
     * @param scrollbarX      X position of scrollbar
     * @param scrollbarY      Y position of scrollbar
     * @param scrollbarHeight Height of scrollbar
     * @param contentX        X position of content area
     * @param contentY        Y position of content area
     * @param contentWidth    Width of content area
     * @param contentHeight   Height of content area
     * @param scrollOffset    Current scroll offset
     * @param maxScroll       Maximum scroll value
     * @param visibleRatio    Ratio of visible content to total content
     * @return New scroll offset, or -1 if click was not handled
     */
    public double handleMouseClick(double mouseX, double mouseY, int button,
            int scrollbarX, int scrollbarY, int scrollbarHeight,
            int contentX, int contentY, int contentWidth, int contentHeight,
            double scrollOffset, double maxScroll, double visibleRatio) {
        if (button != 0) {
            return -1;
        }

        // Check if clicking on scrollbar
        if (mouseX >= scrollbarX && mouseX <= scrollbarX + SCROLLBAR_WIDTH &&
                mouseY >= scrollbarY && mouseY <= scrollbarY + scrollbarHeight) {

            isDraggingScrollbar = true;
            scrollbarDragStartY = mouseY;
            scrollbarDragStartOffset = scrollOffset;

            // Calculate thumb position with fixed scroller height
            int scrollerHeight = 17; // Fixed size
            int usableTrackHeight = scrollbarHeight - scrollerHeight;
            double scrollRatio = maxScroll > 0 ? scrollOffset / maxScroll : 0;
            int thumbY = scrollbarY + (int) (scrollRatio * usableTrackHeight);

            // If clicking on track (not thumb), jump to that position
            if (mouseY < thumbY || mouseY > thumbY + scrollerHeight) {
                // Calculate new scroll position based on click
                double clickRatio = Math.max(0,
                        Math.min(1, (mouseY - scrollbarY - scrollerHeight / 2.0) / usableTrackHeight));
                return Math.max(0, Math.min(maxScroll, clickRatio * maxScroll));
            }

            return scrollOffset;
        }

        // Check if clicking on content area for drag-to-scroll
        /*
         * // DISABLED: Drag-to-scroll on content area blocks interaction with widgets
         * (buttons, fields)
         * if (mouseX >= contentX && mouseX <= contentX + contentWidth &&
         * mouseY >= contentY && mouseY <= contentY + contentHeight) {
         * 
         * isDraggingContent = true;
         * contentDragStartY = mouseY;
         * contentDragStartOffset = scrollOffset;
         * return scrollOffset;
         * }
         */

        return -1;
    }

    /**
     * Handles mouse drag for scrollbar or content dragging.
     * 
     * @param mouseY          Current mouse Y position
     * @param scrollbarY      Y position of scrollbar
     * @param scrollbarHeight Height of scrollbar
     * @param maxScroll       Maximum scroll value
     * @param visibleRatio    Ratio of visible content to total content
     * @param dragSensitivity Sensitivity multiplier for content dragging (1.0 =
     *                        normal)
     * @return New scroll offset, or -1 if drag was not handled
     */
    public double handleMouseDrag(double mouseY, int scrollbarY, int scrollbarHeight,
            double maxScroll, double visibleRatio, double dragSensitivity) {
        if (isDraggingScrollbar) {
            int scrollerHeight = 17; // Fixed size
            int usableTrackHeight = scrollbarHeight - scrollerHeight;

            double clampedMouseY = Math.max(scrollbarY, Math.min(scrollbarY + scrollbarHeight, mouseY));
            double mouseYRelative = clampedMouseY - scrollbarY;

            double thumbCenterRatio = usableTrackHeight > 0
                    ? Math.max(0, Math.min(1, (mouseYRelative - scrollerHeight / 2.0) / usableTrackHeight))
                    : 0;

            double newOffset = thumbCenterRatio * maxScroll;
            return Math.max(0, Math.min(maxScroll, newOffset));
        }

        if (isDraggingContent) {
            double dragDelta = (mouseY - contentDragStartY) * dragSensitivity;
            double newOffset = contentDragStartOffset - dragDelta;
            return Math.max(0, Math.min(maxScroll, newOffset));
        }

        return -1;
    }

    /**
     * Handles mouse release to stop dragging.
     * 
     * @param button Mouse button that was released
     * @return true if a drag was stopped, false otherwise
     */
    public boolean handleMouseRelease(int button) {
        if (button == 0) {
            boolean wasDragging = isDraggingScrollbar || isDraggingContent;
            isDraggingScrollbar = false;
            isDraggingContent = false;
            return wasDragging;
        }
        return false;
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.client.renderer.entity.ItemRenderer;
import net.minecraft.core.Registry;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.tags.TagKey;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.registries.ForgeRegistries;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.systems.RenderSystem;
import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.function.Predicate;

public class ExistingItemsWidget extends AbstractWidget {
    private static final int ITEM_SIZE = 20;
    private static final int ITEM_SPACING = 2;
    private static final int SCROLLBAR_WIDTH = 10;
    private static final int HORIZONTAL_MARGIN = 10;
    private static final int MAX_ITEMS_PER_ROW = 16;
    private static final int MAX_VISIBLE_ROWS = 16;

    private final Consumer<String> onItemRemoved;
    private final Predicate<String> isItemInConfig;
    private List<String> itemIds;
    private List<DisplayEntry> displayEntries;
    private double scrollOffset = 0;
    private int maxVisibleRows;
    private int itemsPerRow;
    private long lastUpdateTime = 0;
    private static final long CYCLE_INTERVAL = 1000;
    private final CustomScrollbarRenderer scrollbarRenderer = new CustomScrollbarRenderer();

    public ExistingItemsWidget(int x, int y, int width, int height,
            List<String> itemIds,
            Consumer<String> onItemRemoved,
            Predicate<String> isItemInConfig) {
        super(x, y, width, height, net.minecraft.network.chat.TextComponent.EMPTY);
        this.onItemRemoved = onItemRemoved;
        this.isItemInConfig = isItemInConfig;
        this.itemIds = new ArrayList<>(itemIds);

        calculateItemsPerRow();
        this.maxVisibleRows = Math.min(MAX_VISIBLE_ROWS, (height - 5) / (ITEM_SIZE + ITEM_SPACING));
        updateDisplayEntries();
    }

    private void calculateItemsPerRow() {
        int availableWidth = width - 21; // width - 16 - 5
        itemsPerRow = Math.max(1,
                Math.min(MAX_ITEMS_PER_ROW, (availableWidth + ITEM_SPACING) / (ITEM_SIZE + ITEM_SPACING)));
    }

    @Override
    public void setWidth(int width) {
        super.setWidth(width);
        calculateItemsPerRow();
        updateDisplayEntries();
    }

    public void setHeight(int height) {
        try {
            java.lang.reflect.Field heightField = AbstractWidget.class.getDeclaredField("height");
            heightField.setAccessible(true);
            heightField.setInt(this, height);
            this.maxVisibleRows = Math.min(MAX_VISIBLE_ROWS, (height - 5) / (ITEM_SIZE + ITEM_SPACING));
            updateDisplayEntries();
        } catch (Exception e) {
        }
    }

    public void setItems(List<String> itemIds) {
        this.itemIds = new ArrayList<>(itemIds);
        updateDisplayEntries();
    }

    private void updateDisplayEntries() {
        displayEntries = new ArrayList<>();
        for (String itemId : itemIds) {
            if (itemId.startsWith("#")) {
                String tagString = itemId.substring(1);
                try {
                    String[] parts = tagString.split(":", 2);
                    ResourceLocation tagLocation;
                    if (parts.length == 2) {
                        tagLocation = new ResourceLocation(parts[0], parts[1]);
                    } else {
                        tagLocation = new ResourceLocation("minecraft", tagString);
                    }
                    TagKey<Item> tagKey = TagKey.create(Registry.ITEM_REGISTRY, tagLocation);
                    displayEntries.add(new TagDisplayEntry(itemId, tagKey));
                } catch (Exception e) {
                }
            } else {
                try {
                    String[] parts = itemId.split(":", 2);
                    ResourceLocation itemLocation;
                    if (parts.length == 2) {
                        itemLocation = new ResourceLocation(parts[0], parts[1]);
                    } else {
                        itemLocation = new ResourceLocation("minecraft", itemId);
                    }
                    Item item = ForgeRegistries.ITEMS.getValue(itemLocation);
                    if (item != null) {
                        displayEntries.add(new ItemDisplayEntry(itemId, item));
                    }
                } catch (Exception e) {
                }
            }
        }
    }

    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        calculateItemsPerRow();
        int labelHeight = 20;
        int availableHeight = height - labelHeight;
        maxVisibleRows = Math.min(MAX_VISIBLE_ROWS, availableHeight / (ITEM_SIZE + ITEM_SPACING));

        poseStack.pushPose();
        Minecraft mc = Minecraft.getInstance();
        double guiScale = mc.getWindow().getGuiScale();
        int windowHeight = mc.getWindow().getHeight();

        // Draw border around panel (debug mode)
        if (com.kingodogo.buildscape.client.screen.DebugRenderConfig.RENDER_PANEL_BORDERS) {
            int borderColor = com.kingodogo.buildscape.client.screen.DebugRenderConfig.PANEL_BORDER_COLOR;
            fill(poseStack, x, y, x + width, y + 1, borderColor); // Top
            fill(poseStack, x, y + height - 1, x + width, y + height, borderColor); // Bottom
            fill(poseStack, x, y, x + 1, y + height, borderColor); // Left
            fill(poseStack, x + width - 1, y, x + width, y + height, borderColor); // Right
        }

        int scissorX = (int) (x * guiScale);
        int bottomMargin = 10;
        int scissorY = (int) (windowHeight - (y + height) * guiScale + bottomMargin * guiScale);
        int scissorWidth = (int) ((width - 21) * guiScale); // Exclude scrollbar area
        int scissorHeight = (int) ((height - labelHeight - bottomMargin) * guiScale);

        if (scissorHeight > 0 && scissorWidth > 0) {
            RenderSystem.enableScissor(scissorX, scissorY, scissorWidth, scissorHeight);
        }
        long currentTime = System.currentTimeMillis();
        if (currentTime - lastUpdateTime >= CYCLE_INTERVAL) {
            lastUpdateTime = currentTime;
        }

        if (displayEntries == null || displayEntries.isEmpty()) {
            updateDisplayEntries();
        }

        int startRow = (int) scrollOffset;
        int endRow = Math.min(startRow + maxVisibleRows,
                (int) Math.ceil((double) displayEntries.size() / itemsPerRow));

        int itemY = y + labelHeight;
        ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();
        DisplayEntry hoveredEntry = null;
        boolean hoveringRemoveButton = false;
        int hoveredRemoveX = 0, hoveredRemoveY = 0;

        for (int row = startRow; row < endRow; row++) {
            int rowY = itemY + (row - startRow) * (ITEM_SIZE + ITEM_SPACING);

            if (rowY + ITEM_SIZE < y || rowY > y + height) {
                continue;
            }

            for (int col = 0; col < itemsPerRow; col++) {
                int index = row * itemsPerRow + col;
                if (index >= displayEntries.size())
                    break;

                DisplayEntry entry = displayEntries.get(index);
                int itemX = x + 5 + col * (ITEM_SIZE + ITEM_SPACING);

                if (itemX + ITEM_SIZE < x || itemX > x + width) {
                    continue;
                }

                Item itemToDisplay = entry.getCurrentItem();

                int removeSize = 8;
                int removeX = itemX + ITEM_SIZE - removeSize;
                int removeY = rowY;
                boolean removeHovered = mouseX >= removeX && mouseX <= itemX + ITEM_SIZE &&
                        mouseY >= removeY && mouseY <= removeY + removeSize &&
                        mouseX >= x && mouseX < x + width &&
                        mouseY >= y && mouseY < y + height;

                boolean itemHovered = mouseX >= itemX && mouseX < itemX + ITEM_SIZE &&
                        mouseY >= rowY && mouseY < rowY + ITEM_SIZE &&
                        !removeHovered &&
                        mouseX >= x && mouseX < x + width &&
                        mouseY >= y && mouseY < y + height;

                if (itemHovered) {
                    hoveredEntry = entry;
                }
                if (removeHovered) {
                    hoveringRemoveButton = true;
                    hoveredRemoveX = removeX;
                    hoveredRemoveY = removeY;
                }

                int bgColor = itemHovered ? 0x40CCCCCC : 0x33CCCCCC;
                fill(poseStack, itemX, rowY, itemX + ITEM_SIZE, rowY + ITEM_SIZE, bgColor);

                if (itemToDisplay != null) {
                    poseStack.pushPose();
                    poseStack.translate(0, 0, 100);
                    ItemStack stack = new ItemStack(itemToDisplay);
                    itemRenderer.renderGuiItem(stack, itemX + 2, rowY + 2);
                    itemRenderer.renderGuiItemDecorations(
                            mc.font, stack, itemX + 2, rowY + 2);
                    poseStack.popPose();
                }

                fill(poseStack, removeX, removeY, itemX + ITEM_SIZE, removeY + removeSize,
                        removeHovered ? 0x40CCCCCC : 0x33CCCCCC);
                Minecraft.getInstance().font.draw(
                        poseStack, "×", removeX + 2, removeY - 1, 0xFFFFFF);
            }
        }

        RenderSystem.disableScissor();
        poseStack.popPose();

        // Render scrollbar after disabling scissor so it is not clipped
        // Use local variable maxScroll which needs to be re-calculated or scoped
        // correctly
        // We will re-calculate maxScroll here to be safe and clear
        double maxScrollForBar = Math.max(0, Math.ceil((double) displayEntries.size() / itemsPerRow) - maxVisibleRows);
        if (maxScrollForBar > 0) {
            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4; // 4px from edge
            int scrollbarY = itemY;
            // bottomMargin is a local variable in the removed block, need to redefine or
            // use constant
            int scrollbarHeight = height - labelHeight - 10; // Replaced bottomMargin with its constant value 10

            double visibleRatio = maxVisibleRows * itemsPerRow / (double) displayEntries.size();
            scrollbarRenderer.renderScrollbar(poseStack, scrollbarX, scrollbarY, scrollbarHeight,
                    scrollOffset, maxScrollForBar, visibleRatio);
        }

    }

    public void renderTooltip(PoseStack poseStack, int mouseX, int mouseY) {
        if (mouseX < x || mouseX >= x + width || mouseY < y || mouseY >= y + height) {
            return;
        }

        int labelHeight = 20;
        int startRow = (int) scrollOffset;
        int endRow = Math.min(startRow + maxVisibleRows,
                (int) Math.ceil((double) displayEntries.size() / itemsPerRow));

        int itemY = y + labelHeight;
        DisplayEntry hoveredEntry = null;
        boolean hoveringRemoveButton = false;
        int hoveredRemoveX = 0, hoveredRemoveY = 0;

        for (int row = startRow; row < endRow; row++) {
            int rowY = itemY + (row - startRow) * (ITEM_SIZE + ITEM_SPACING);

            if (rowY + ITEM_SIZE < y || rowY > y + height) {
                continue;
            }

            for (int col = 0; col < itemsPerRow; col++) {
                int index = row * itemsPerRow + col;
                if (index >= displayEntries.size())
                    break;

                DisplayEntry entry = displayEntries.get(index);
                int itemX = x + 5 + col * (ITEM_SIZE + ITEM_SPACING);

                if (itemX + ITEM_SIZE < x || itemX > x + width) {
                    continue;
                }

                int removeSize = 8;
                int removeX = itemX + ITEM_SIZE - removeSize;
                int removeY = rowY;
                boolean removeHovered = mouseX >= removeX && mouseX <= itemX + ITEM_SIZE &&
                        mouseY >= removeY && mouseY <= removeY + removeSize &&
                        mouseX >= x && mouseX < x + width &&
                        mouseY >= y && mouseY < y + height;

                boolean itemHovered = mouseX >= itemX && mouseX < itemX + ITEM_SIZE &&
                        mouseY >= rowY && mouseY < rowY + ITEM_SIZE &&
                        !removeHovered &&
                        mouseX >= x && mouseX < x + width &&
                        mouseY >= y && mouseY < y + height;

                if (itemHovered) {
                    hoveredEntry = entry;
                }
                if (removeHovered) {
                    hoveringRemoveButton = true;
                    hoveredRemoveX = removeX;
                    hoveredRemoveY = removeY;
                }
            }
        }

        if (hoveredEntry != null && hoveredEntry.getCurrentItem() != null) {
            Minecraft mc = Minecraft.getInstance();

            if (mc.screen != null) {
                if (hoveredEntry.getItemId().startsWith("#")) {
                    net.minecraft.network.chat.Component tooltip = new net.minecraft.network.chat.TextComponent(
                            hoveredEntry.getItemId());
                    mc.screen.renderTooltip(poseStack, tooltip, mouseX, mouseY);
                } else {
                    ItemStack stack = new ItemStack(hoveredEntry.getCurrentItem());
                    java.util.List<net.minecraft.network.chat.Component> tooltipLines = stack.getTooltipLines(null,
                            net.minecraft.world.item.TooltipFlag.Default.NORMAL);

                    java.util.List<net.minecraft.util.FormattedCharSequence> formattedLines = new java.util.ArrayList<>();
                    int maxWidth = Math.max(200, mc.screen.width / 2);
                    for (net.minecraft.network.chat.Component line : tooltipLines) {
                        formattedLines.addAll(mc.font.split(line, maxWidth));
                    }

                    mc.screen.renderTooltip(poseStack, formattedLines, mouseX, mouseY);
                }
            }
        }

        if (hoveringRemoveButton) {
            Minecraft mc = Minecraft.getInstance();
            if (mc.screen != null) {
                net.minecraft.network.chat.Component tooltip = new net.minecraft.network.chat.TranslatableComponent(
                        "buildscape.config.remove");
                mc.screen.renderTooltip(poseStack, tooltip, hoveredRemoveX, hoveredRemoveY);
            }
        }

    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (!isMouseOver(mouseX, mouseY)) {
            return false;
        }

        int startRow = (int) scrollOffset;
        int endRow = Math.min(startRow + maxVisibleRows,
                (int) Math.ceil((double) displayEntries.size() / itemsPerRow));

        int labelHeight = 20;
        int itemY = y + labelHeight;

        double maxScroll = Math.max(0, Math.ceil((double) displayEntries.size() / itemsPerRow) - maxVisibleRows);
        if (maxScroll > 0) {
            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4; // 4px form edge
            int scrollbarY = itemY;
            int bottomMargin = 10;
            int scrollbarHeight = height - labelHeight - bottomMargin;
            int contentX = x + 5;
            int contentY = itemY;
            int contentWidth = width - 21; // width - 16 - 5
            int contentHeight = scrollbarHeight;

            double visibleRatio = maxVisibleRows / Math.ceil((double) displayEntries.size() / itemsPerRow);
            double newOffset = scrollbarRenderer.handleMouseClick(mouseX, mouseY, button,
                    scrollbarX, scrollbarY, scrollbarHeight,
                    contentX, contentY, contentWidth, contentHeight,
                    scrollOffset, maxScroll, visibleRatio);

            if (newOffset >= 0) {
                scrollOffset = newOffset;
                return true;
            }
        }

        for (int row = startRow; row < endRow; row++) {
            int rowY = itemY + (row - startRow) * (ITEM_SIZE + ITEM_SPACING);

            for (int col = 0; col < itemsPerRow; col++) {
                int index = row * itemsPerRow + col;
                if (index >= displayEntries.size())
                    break;

                int itemX = x + 5 + col * (ITEM_SIZE + ITEM_SPACING);
                int removeSize = 8;
                int removeX = itemX + ITEM_SIZE - removeSize;
                int removeY = rowY;

                if (mouseX >= removeX && mouseX <= itemX + ITEM_SIZE &&
                        mouseY >= removeY && mouseY <= removeY + removeSize) {
                    DisplayEntry entry = displayEntries.get(index);
                    onItemRemoved.accept(entry.getItemId());
                    return true;
                }
            }
        }

        return false;
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
        if (!isMouseOver(mouseX, mouseY)) {
            return false;
        }

        double maxScroll = Math.max(0, Math.ceil((double) displayEntries.size() / itemsPerRow) - maxVisibleRows);
        scrollOffset = Math.max(0, Math.min(maxScroll, scrollOffset - delta));
        return true;
    }

    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        if (scrollbarRenderer.isDragging() && button == 0) {
            double maxScroll = Math.max(0, Math.ceil((double) displayEntries.size() / itemsPerRow) - maxVisibleRows);
            if (maxScroll > 0) {
                int labelHeight = 20;
                int itemY = y + labelHeight;
                int scrollbarY = itemY;
                int scrollbarHeight = maxVisibleRows * (ITEM_SIZE + ITEM_SPACING);
                double visibleRatio = maxVisibleRows / Math.ceil((double) displayEntries.size() / itemsPerRow);

                double newOffset = scrollbarRenderer.handleMouseDrag(mouseY, scrollbarY, scrollbarHeight,
                        maxScroll, visibleRatio, 1.0);

                if (newOffset >= 0) {
                    scrollOffset = newOffset;
                    return true;
                }
            }
        }
        return false;
    }

    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        return scrollbarRenderer.handleMouseRelease(button);
    }

    @Override
    public void updateNarration(NarrationElementOutput narrationElementOutput) {
    }

    private abstract static class DisplayEntry {
        protected final String itemId;

        public DisplayEntry(String itemId) {
            this.itemId = itemId;
        }

        public String getItemId() {
            return itemId;
        }

        public abstract Item getCurrentItem();
    }

    private static class ItemDisplayEntry extends DisplayEntry {
        private final Item item;

        public ItemDisplayEntry(String itemId, Item item) {
            super(itemId);
            this.item = item;
        }

        @Override
        public Item getCurrentItem() {
            return item;
        }
    }

    private static class TagDisplayEntry extends DisplayEntry {
        private final TagKey<Item> tagKey;
        private List<Item> tagItems;
        private int currentIndex = 0;
        private long lastCycleTime = 0;

        public TagDisplayEntry(String itemId, TagKey<Item> tagKey) {
            super(itemId);
            this.tagKey = tagKey;
            loadTagItems();
        }

        private void loadTagItems() {
            tagItems = new ArrayList<>();
            ForgeRegistries.ITEMS.getValues().forEach(item -> {
                if (item.builtInRegistryHolder().is(tagKey)) {
                    tagItems.add(item);
                }
            });
        }

        @Override
        public Item getCurrentItem() {
            if (tagItems.isEmpty()) {
                return null;
            }

            long currentTime = System.currentTimeMillis();
            if (currentTime - lastCycleTime >= 1000) {
                lastCycleTime = currentTime;
                currentIndex = (currentIndex + 1) % tagItems.size();
            }

            return tagItems.get(currentIndex);
        }
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractSliderButton;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.TextComponent;
import com.mojang.blaze3d.vertex.PoseStack;
import java.util.function.Consumer;

public class IntSliderWidget extends AbstractSliderButton {
    private final int minValue;
    private final int maxValue;
    private int currentValue;
    private final Consumer<Integer> onValueChanged;
    
    public IntSliderWidget(int x, int y, int width, int height, Component message, int minValue, int maxValue, int initialValue, Consumer<Integer> onValueChanged) {
        super(x, y, width, height, message, (initialValue - minValue) / (double) (maxValue - minValue));
        this.minValue = minValue;
        this.maxValue = maxValue;
        this.currentValue = initialValue;
        this.onValueChanged = onValueChanged;
        updateMessage();
    }
    
    @Override
    protected void updateMessage() {
        this.setMessage(new TextComponent(String.valueOf(currentValue)));
    }
    
    @Override
    protected void applyValue() {
        this.currentValue = (int) Math.round(minValue + value * (maxValue - minValue));
        if (onValueChanged != null) {
            onValueChanged.accept(currentValue);
        }
        updateMessage();
    }
    
    public int getValue() {
        return currentValue;
    }
    
    public void setValue(int value) {
        this.currentValue = Math.max(minValue, Math.min(maxValue, value));
        this.value = (currentValue - minValue) / (double) (maxValue - minValue);
        updateMessage();
    }
    
    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (!this.active || !this.isMouseOver(mouseX, mouseY)) {
            return false;
        }
        return super.mouseClicked(mouseX, mouseY, button);
    }
    
    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        if (!this.active) {
            return false;
        }
        return super.mouseDragged(mouseX, mouseY, button, dragX, dragY);
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.Button;
import net.minecraft.network.chat.Component;
import net.minecraft.network.chat.TranslatableComponent;
import com.mojang.blaze3d.vertex.PoseStack;
import java.util.function.Consumer;

public class InventorySortDropdown extends Button {
    public enum SortMode {
        INVENTORY(new TranslatableComponent("buildscape.config.sort.inventory")),
        ALL(new TranslatableComponent("buildscape.config.sort.all")),
        MOD_ONLY(new TranslatableComponent("buildscape.config.sort.mod_only"));
        
        private final Component displayName;
        
        SortMode(Component displayName) {
            this.displayName = displayName;
        }
        
        public Component getDisplayName() {
            return displayName;
        }
    }
    
    private SortMode currentMode = SortMode.INVENTORY;
    private boolean dropdownOpen = false;
    private final Consumer<SortMode> onModeChanged;
    private final int dropdownHeight = 60;

    public InventorySortDropdown(int x, int y, int width, int height, Consumer<SortMode> onModeChanged) {
        super(x, y, width, height, new TranslatableComponent("buildscape.config.select_inventory"), (button) -> {
            InventorySortDropdown dropdown = (InventorySortDropdown) button;
            dropdown.dropdownOpen = !dropdown.dropdownOpen;
        });
        this.onModeChanged = onModeChanged;
    }
    
    public SortMode getCurrentMode() {
        return currentMode;
    }
    
    public void setMode(SortMode mode) {
        if (this.currentMode != mode) {
            this.currentMode = mode;
            if (onModeChanged != null) {
                onModeChanged.accept(mode);
            }
        }
        dropdownOpen = false;
    }
    
    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {

        Minecraft.getInstance().font.draw(
            poseStack,
            getMessage(),
            x + width / 2 - Minecraft.getInstance().font.width(getMessage()) / 2,
            y + (height - 8) / 2,
            0xFFFFFF
        );

        int arrowX = x + width - 15;
        int arrowY = y + height / 2;
        if (dropdownOpen) {
            fill(poseStack, arrowX, arrowY - 2, arrowX + 5, arrowY, 0xFFFFFF);
            fill(poseStack, arrowX + 2, arrowY - 4, arrowX + 3, arrowY - 2, 0xFFFFFF);
        } else {
            fill(poseStack, arrowX, arrowY, arrowX + 5, arrowY + 2, 0xFFFFFF);
            fill(poseStack, arrowX + 2, arrowY + 2, arrowX + 3, arrowY + 4, 0xFFFFFF);
        }

        if (dropdownOpen) {
            int dropdownY = y + height;
            int optionHeight = 20;

            for (int i = 0; i < SortMode.values().length; i++) {
                SortMode mode = SortMode.values()[i];
                int optionY = dropdownY + i * optionHeight;
                boolean hovered = mouseX >= x && mouseX < x + width &&
                                mouseY >= optionY && mouseY < optionY + optionHeight;
                boolean selected = mode == currentMode;

                String icon = "";
                switch (mode) {
                    case INVENTORY:
                        icon = "📦";
                        break;
                    case ALL:
                        icon = "A";
                        break;
                    case MOD_ONLY:
                        icon = "M";
                        break;
                }
                
                Minecraft.getInstance().font.draw(
                    poseStack,
                    icon + " " + mode.getDisplayName().getString(),
                    x + 5,
                    optionY + (optionHeight - 8) / 2,
                    selected ? 0xFFFFFF : 0xCCCCCC
                );
            }
        }
    }
    
    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (!this.active || !this.visible) {
            return false;
        }
        
        if (isValidClickButton(button)) {
            boolean clicked = mouseX >= (double)this.x && mouseY >= (double)this.y && 
                            mouseX < (double)(this.x + this.width) && 
                            mouseY < (double)(this.y + this.height);
            
            if (clicked) {
                this.playDownSound(Minecraft.getInstance().getSoundManager());
                this.onClick(mouseX, mouseY);
                return true;
            }

            if (dropdownOpen) {
                int dropdownY = y + height;
                int optionHeight = 20;
                
                for (int i = 0; i < SortMode.values().length; i++) {
                    SortMode mode = SortMode.values()[i];
                    int optionY = dropdownY + i * optionHeight;
                    
                    if (mouseX >= x && mouseX < x + width &&
                        mouseY >= optionY && mouseY < optionY + optionHeight) {
                        setMode(mode);
                        return true;
                    }
                }

                dropdownOpen = false;
            }
        }
        
        return false;
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import com.mojang.blaze3d.systems.RenderSystem;
import com.mojang.blaze3d.vertex.PoseStack;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.client.renderer.entity.ItemRenderer;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.entity.player.Inventory;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraftforge.registries.ForgeRegistries;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import java.util.function.Predicate;
import java.util.stream.Collectors;

public class ItemSelectionWidget extends AbstractWidget {
    private static final int ITEM_SIZE = 20;
    private static final int ITEM_SPACING = 2;
    private static final int SCROLLBAR_WIDTH = 10;
    private static final int HORIZONTAL_MARGIN = 10;
    private static final int MAX_ITEMS_PER_ROW = 16;
    private static final int MAX_VISIBLE_ROWS = 16;
    // Header area: top padding (5px) + search box height (~20px) + gap (5px) = 30px
    // Items start below this area
    private static final int HEADER_AREA_HEIGHT = 26; // Reduced to start 1px below search bar (5px padding + 20px
                                                      // height + 1px)

    private final Consumer<String> onItemSelected;
    private final Predicate<String> isItemInConfig;
    private List<Item> allItems;
    private List<Item> filteredItems;
    private String filter = "";
    private double scrollOffset = 0;
    private int maxVisibleRows;
    private int itemsPerRow;
    private SortToggleButton.SortType sortMode = SortToggleButton.SortType.ALL_ITEMS;
    private String currentModNamespace = "buildscape";
    private final CustomScrollbarRenderer scrollbarRenderer = new CustomScrollbarRenderer();

    public ItemSelectionWidget(int x, int y, int width, int height,
            Consumer<String> onItemSelected,
            Predicate<String> isItemInConfig) {
        super(x, y, width, height, net.minecraft.network.chat.TextComponent.EMPTY);
        this.onItemSelected = onItemSelected;
        this.isItemInConfig = isItemInConfig;

        allItems = new ArrayList<>(ForgeRegistries.ITEMS.getValues());
        filteredItems = new ArrayList<>(allItems);

        calculateItemsPerRow();
        calculateItemsPerRow();
        int bottomMargin = 10;
        int visibleHeight = height - HEADER_AREA_HEIGHT - bottomMargin;
        maxVisibleRows = Math.max(1, visibleHeight / (ITEM_SIZE + ITEM_SPACING));
    }

    private void calculateItemsPerRow() {
        int availableWidth = width - 21; // width - 16 - 5
        itemsPerRow = Math.max(1,
                Math.min(MAX_ITEMS_PER_ROW, (availableWidth + ITEM_SPACING) / (ITEM_SIZE + ITEM_SPACING)));
    }

    @Override
    public void setWidth(int width) {
        super.setWidth(width);
        calculateItemsPerRow();
        refresh();
    }

    public void setHeight(int height) {
        try {
            java.lang.reflect.Field heightField = AbstractWidget.class.getDeclaredField("height");
            heightField.setAccessible(true);
            heightField.setInt(this, height);
            heightField.setInt(this, height);
            int bottomMargin = 10;
            int visibleHeight = height - HEADER_AREA_HEIGHT - bottomMargin;
            this.maxVisibleRows = Math.max(1, visibleHeight / (ITEM_SIZE + ITEM_SPACING));
            refresh();
        } catch (Exception e) {
        }
    }

    public void setFilter(String filter) {
        this.filter = filter.toLowerCase();
        refresh();
    }

    public void setSortMode(SortToggleButton.SortType sortMode) {
        this.sortMode = sortMode;
        refresh();
    }

    public void setModNamespace(String namespace) {
        this.currentModNamespace = namespace;
        if (sortMode == SortToggleButton.SortType.MOD_ONLY) {
            refresh();
        }
    }

    public String getCurrentModNamespace() {
        return currentModNamespace;
    }

    public SortToggleButton.SortType getSortMode() {
        return sortMode;
    }

    public void refresh() {
        List<Item> itemsToFilter = allItems;

        switch (sortMode) {
            case INVENTORY:
                itemsToFilter = getInventoryItems();
                break;
            case MOD_ONLY:
                itemsToFilter = allItems.stream()
                        .filter(item -> {
                            ResourceLocation itemId = ForgeRegistries.ITEMS.getKey(item);
                            return itemId != null && itemId.getNamespace().equals(currentModNamespace);
                        })
                        .collect(Collectors.toList());
                break;
            case ALL_ITEMS:
            default:
                itemsToFilter = allItems;
                break;
        }

        if (filter.isEmpty()) {
            filteredItems = new ArrayList<>(itemsToFilter);
        } else {
            filteredItems = itemsToFilter.stream()
                    .filter(item -> {
                        String itemId = ForgeRegistries.ITEMS.getKey(item).toString().toLowerCase();
                        String itemName = item.getDescription().getString().toLowerCase();
                        return itemId.contains(filter) || itemName.contains(filter);
                    })
                    .collect(Collectors.toList());
        }
        scrollOffset = Math.max(0, Math.min(scrollOffset, getMaxScroll()));
    }

    private List<Item> getInventoryItems() {
        Set<Item> inventoryItems = new HashSet<>();
        Minecraft mc = Minecraft.getInstance();
        if (mc.player != null) {
            Inventory inventory = mc.player.getInventory();
            for (int i = 0; i < inventory.getContainerSize(); i++) {
                ItemStack stack = inventory.getItem(i);
                if (!stack.isEmpty()) {
                    inventoryItems.add(stack.getItem());
                }
            }
        }
        return new ArrayList<>(inventoryItems);
    }

    private double getMaxScroll() {
        int totalRows = (int) Math.ceil((double) filteredItems.size() / itemsPerRow);
        int visibleHeight = maxVisibleRows * (ITEM_SIZE + ITEM_SPACING);
        int contentHeight = totalRows * (ITEM_SIZE + ITEM_SPACING);
        return Math.max(0, contentHeight - visibleHeight);
    }

    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        calculateItemsPerRow();
        maxVisibleRows = Math.min(MAX_VISIBLE_ROWS, (height - HEADER_AREA_HEIGHT - 5) / (ITEM_SIZE + ITEM_SPACING)); // Account
                                                                                                                     // for
                                                                                                                     // header
                                                                                                                     // area

        poseStack.pushPose();
        Minecraft mc = Minecraft.getInstance();
        double guiScale = mc.getWindow().getGuiScale();
        int windowHeight = mc.getWindow().getHeight();

        // Draw border around panel (debug mode)
        if (com.kingodogo.buildscape.client.screen.DebugRenderConfig.RENDER_PANEL_BORDERS) {
            int borderColor = com.kingodogo.buildscape.client.screen.DebugRenderConfig.PANEL_BORDER_COLOR;
            fill(poseStack, x, y, x + width, y + 1, borderColor); // Top
            fill(poseStack, x, y + height - 1, x + width, y + height, borderColor); // Bottom
            fill(poseStack, x, y, x + 1, y + height, borderColor); // Left
            fill(poseStack, x + width - 1, y, x + width, y + height, borderColor); // Right
        }

        int scissorX = (int) (x * guiScale);
        // Exclude header area from scissor height
        // Scissor Y is from bottom, so it remains the same (scissoring from bottom
        // usually implies bottom origin)
        // Correct logic: scissorY is bottom of rect. scissorHeight is height.
        // We want to reduce height by HEADER_AREA_HEIGHT.
        // And we want the bottom to stay fixed.
        int bottomMargin = 10;
        int scissorY = (int) (windowHeight - (y + height) * guiScale + bottomMargin * guiScale);
        int scissorWidth = (int) ((width - 21) * guiScale); // Exclude scrollbar area
        int scissorHeight = (int) ((height - HEADER_AREA_HEIGHT - bottomMargin) * guiScale);

        if (scissorHeight > 0 && scissorWidth > 0) {
            RenderSystem.enableScissor(scissorX, scissorY, scissorWidth, scissorHeight);
        }

        int totalRows = (int) Math.ceil((double) filteredItems.size() / itemsPerRow);
        int startRow = (int) Math.floor(scrollOffset / (ITEM_SIZE + ITEM_SPACING));
        int endRow = Math.min(startRow + maxVisibleRows + 2, totalRows);

        double pixelOffsetInRow = scrollOffset % (ITEM_SIZE + ITEM_SPACING);
        int itemY = y + HEADER_AREA_HEIGHT - (int) pixelOffsetInRow; // Start below header area
        ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();

        for (int row = startRow; row < endRow; row++) {
            int rowY = itemY + (row - startRow) * (ITEM_SIZE + ITEM_SPACING);

            // Updated visibility check to respect HEADER_AREA_HEIGHT
            if (rowY + ITEM_SIZE < y + HEADER_AREA_HEIGHT || rowY > y + height) {
                continue;
            }

            for (int col = 0; col < itemsPerRow; col++) {
                int index = row * itemsPerRow + col;
                if (index >= filteredItems.size())
                    break;

                Item item = filteredItems.get(index);
                int itemX = x + 5 + col * (ITEM_SIZE + ITEM_SPACING);

                if (itemX + ITEM_SIZE < x || itemX > x + width) {
                    continue;
                }

                boolean isHovered = mouseX >= itemX && mouseX < itemX + ITEM_SIZE &&
                        mouseY >= rowY && mouseY < rowY + ITEM_SIZE &&
                        mouseX >= x && mouseX < x + width &&
                        mouseY >= y + HEADER_AREA_HEIGHT && mouseY < y + height; // Updated hover check

                String itemId = ForgeRegistries.ITEMS.getKey(item).toString();
                boolean inConfig = isItemInConfig.test(itemId);

                int bgColor;
                if (inConfig) {
                    bgColor = isHovered ? 0x6000FF00 : 0x4000FF00;
                } else {
                    bgColor = isHovered ? 0x40CCCCCC : 0x33CCCCCC;
                }
                fill(poseStack, itemX, rowY, itemX + ITEM_SIZE, rowY + ITEM_SIZE, bgColor);

                if (inConfig) {
                    int borderColor = 0xFF00FF00;
                    fill(poseStack, itemX - 1, rowY - 1, itemX + ITEM_SIZE + 1, rowY, borderColor);
                    fill(poseStack, itemX - 1, rowY + ITEM_SIZE, itemX + ITEM_SIZE + 1, rowY + ITEM_SIZE + 1,
                            borderColor);
                    fill(poseStack, itemX - 1, rowY - 1, itemX, rowY + ITEM_SIZE + 1, borderColor);
                    fill(poseStack, itemX + ITEM_SIZE, rowY - 1, itemX + ITEM_SIZE + 1, rowY + ITEM_SIZE + 1,
                            borderColor);
                }

                poseStack.pushPose();
                poseStack.translate(0, 0, 100);
                ItemStack stack = new ItemStack(item);
                itemRenderer.renderGuiItem(stack, itemX + 2, rowY + 2);
                itemRenderer.renderGuiItemDecorations(
                        mc.font, stack, itemX + 2, rowY + 2);
                poseStack.popPose();
            }
        }

        if (scissorHeight > 0 && scissorWidth > 0) {
            RenderSystem.disableScissor();
        }
        poseStack.popPose();

        // Render scrollbar after disabling scissor so it is not clipped
        if (getMaxScroll() > 0) {
            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4; // 4px form edge
            int scrollbarY = y + HEADER_AREA_HEIGHT;
            bottomMargin = 10;
            int scrollbarHeight = height - HEADER_AREA_HEIGHT - bottomMargin;

            double visibleRatio = maxVisibleRows * itemsPerRow / (double) filteredItems.size();
            scrollbarRenderer.renderScrollbar(poseStack, scrollbarX, scrollbarY, scrollbarHeight,
                    scrollOffset, getMaxScroll(), visibleRatio);
        }

    }

    public void renderTooltip(PoseStack poseStack, int mouseX, int mouseY) {
        if (mouseX < x || mouseX >= x + width || mouseY < y || mouseY >= y + height) {
            return;
        }

        int totalRows = (int) Math.ceil((double) filteredItems.size() / itemsPerRow);
        int startRow = (int) Math.floor(scrollOffset / (ITEM_SIZE + ITEM_SPACING));
        int endRow = Math.min(startRow + maxVisibleRows + 2, totalRows);

        double pixelOffsetInRow = scrollOffset % (ITEM_SIZE + ITEM_SPACING);
        int itemY = y + HEADER_AREA_HEIGHT - (int) pixelOffsetInRow; // Updated to HEADER_AREA_HEIGHT
        Item hoveredItem = null;

        for (int row = startRow; row < endRow; row++) {
            int rowY = itemY + (row - startRow) * (ITEM_SIZE + ITEM_SPACING);

            // Updated visibility check
            if (rowY + ITEM_SIZE < y + HEADER_AREA_HEIGHT || rowY > y + height) {
                continue;
            }

            for (int col = 0; col < itemsPerRow; col++) {
                int index = row * itemsPerRow + col;
                if (index >= filteredItems.size())
                    break;

                Item item = filteredItems.get(index);
                int itemX = x + 5 + col * (ITEM_SIZE + ITEM_SPACING);

                if (itemX + ITEM_SIZE < x || itemX > x + width) {
                    continue;
                }

                boolean isHovered = mouseX >= itemX && mouseX < itemX + ITEM_SIZE &&
                        mouseY >= rowY && mouseY < rowY + ITEM_SIZE &&
                        mouseX >= x && mouseX < x + width &&
                        mouseY >= y + HEADER_AREA_HEIGHT && mouseY < y + height; // Updated hover check
                if (isHovered) {
                    hoveredItem = item;
                }
            }
        }

        if (hoveredItem != null) {
            ItemStack stack = new ItemStack(hoveredItem);
            Minecraft mc = Minecraft.getInstance();

            if (mc.screen != null) {
                java.util.List<net.minecraft.network.chat.Component> tooltipLines = stack.getTooltipLines(null,
                        net.minecraft.world.item.TooltipFlag.Default.NORMAL);

                java.util.List<net.minecraft.util.FormattedCharSequence> formattedLines = new java.util.ArrayList<>();
                int maxWidth = Math.max(200, mc.screen.width / 2);
                for (net.minecraft.network.chat.Component line : tooltipLines) {
                    formattedLines.addAll(mc.font.split(line, maxWidth));
                }

                mc.screen.renderTooltip(poseStack, formattedLines, mouseX, mouseY);
            }
        }

        // Scrollbar is now rendered in renderButton method using
        // CustomScrollbarRenderer
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        // Updated check to ignore clicks in header area
        if (!isMouseOver(mouseX, mouseY) || mouseY < y + HEADER_AREA_HEIGHT) {
            return false;
        }

        double maxScroll = getMaxScroll();
        if (maxScroll > 0) {
            double pixelOffsetInRow = scrollOffset % (ITEM_SIZE + ITEM_SPACING);
            // int itemY = y + HEADER_AREA_HEIGHT - (int) pixelOffsetInRow; // Not used for
            // scrollbar click

            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4; // 4px form edge
            int scrollbarY = y + HEADER_AREA_HEIGHT;
            int bottomMargin = 10;
            int scrollbarHeight = height - HEADER_AREA_HEIGHT - bottomMargin;
            int contentX = x + 5;
            int contentY = y + HEADER_AREA_HEIGHT;
            int contentWidth = width - 21; // width - 16 - 5
            int contentHeight = scrollbarHeight;

            double visibleRatio = maxVisibleRows * itemsPerRow / (double) filteredItems.size();
            double newOffset = scrollbarRenderer.handleMouseClick(mouseX, mouseY, button,
                    scrollbarX, scrollbarY, scrollbarHeight,
                    contentX, contentY, contentWidth, contentHeight,
                    scrollOffset, maxScroll, visibleRatio);

            if (newOffset >= 0) {
                scrollOffset = newOffset;
                return true;
            }
        }

        int totalRows = (int) Math.ceil((double) filteredItems.size() / itemsPerRow);
        int startRow = (int) Math.floor(scrollOffset / (ITEM_SIZE + ITEM_SPACING));
        int endRow = Math.min(startRow + maxVisibleRows + 2, totalRows);

        double pixelOffsetInRow = scrollOffset % (ITEM_SIZE + ITEM_SPACING);
        int itemY = y + HEADER_AREA_HEIGHT - (int) pixelOffsetInRow;

        for (int row = startRow; row < endRow; row++) {
            int rowY = itemY + (row - startRow) * (ITEM_SIZE + ITEM_SPACING);

            // Updated visibility check
            if (rowY + ITEM_SIZE < y + HEADER_AREA_HEIGHT || rowY > y + height) {
                continue;
            }

            for (int col = 0; col < itemsPerRow; col++) {
                int index = row * itemsPerRow + col;
                if (index >= filteredItems.size())
                    break;

                int itemX = x + 5 + col * (ITEM_SIZE + ITEM_SPACING);

                if (itemX + ITEM_SIZE < x || itemX > x + width) {
                    continue;
                }

                if (mouseX >= itemX && mouseX < itemX + ITEM_SIZE &&
                        mouseY >= rowY && mouseY < rowY + ITEM_SIZE &&
                        mouseX >= x && mouseX < x + width &&
                        mouseY >= y + HEADER_AREA_HEIGHT && mouseY < y + height) { // Updated click check
                    Item item = filteredItems.get(index);
                    String itemId = ForgeRegistries.ITEMS.getKey(item).toString();
                    onItemSelected.accept(itemId);
                    return true;
                }
            }
        }

        return false;
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
        if (!isMouseOver(mouseX, mouseY)) {
            return false;
        }

        double step = (ITEM_SIZE + ITEM_SPACING);
        scrollOffset = Math.max(0, Math.min(getMaxScroll(), scrollOffset - delta * step));
        return true;
    }

    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        if (scrollbarRenderer.isDragging() && button == 0) {
            double maxScroll = getMaxScroll();
            if (maxScroll > 0) {
                int scrollbarY = y + HEADER_AREA_HEIGHT;
                int bottomMargin = 10;
                int scrollbarHeight = height - HEADER_AREA_HEIGHT - bottomMargin;
                double visibleRatio = maxVisibleRows * itemsPerRow / (double) filteredItems.size();

                double newOffset = scrollbarRenderer.handleMouseDrag(mouseY, scrollbarY, scrollbarHeight,
                        maxScroll, visibleRatio, 1.0);

                if (newOffset >= 0) {
                    scrollOffset = newOffset;
                    return true;
                }
            }
        }
        return false;
    }

    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        return scrollbarRenderer.handleMouseRelease(button);
    }

    @Override
    public void updateNarration(NarrationElementOutput narrationElementOutput) {
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import com.kingodogo.buildscape.config.PresetsConfig;
import com.kingodogo.buildscape.config.PillarParticleConfig;
import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.EditBox;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.network.chat.TranslatableComponent;
import com.mojang.blaze3d.vertex.PoseStack;
import java.util.List;
import java.util.function.Consumer;

public class PresetsWidget extends AbstractWidget {
    private static final int PRESET_BUTTON_HEIGHT = 20;
    private static final int PRESET_BUTTON_SPACING = 2;
    private static final int MAX_VISIBLE_PRESETS = 6;

    private List<PresetsConfig.Preset> presets;
    private List<String> presetKeys;
    private String selectedPresetKey = null;
    private final EditBox nameEditBox;
    private final Button createButton;
    private final Button saveButton;
    private final Button deleteButton;
    private final Button applyButton;
    private final Consumer<String> onPresetApplied;
    private int scrollOffset = 0;
    private final CustomScrollbarRenderer scrollbarRenderer = new CustomScrollbarRenderer();

    public PresetsWidget(int x, int y, int width, int height, Consumer<String> onPresetApplied) {
        super(x, y, width, height, net.minecraft.network.chat.TextComponent.EMPTY);
        this.onPresetApplied = onPresetApplied;

        loadPresets();

        PresetsConfig config = PresetsConfig.get();
        if (selectedPresetKey == null) {
            if (config.hasUnnamedPreset()) {
                selectedPresetKey = "_unnamed";
            } else {
                selectedPresetKey = "default";
            }
        }

        int scaledSpacing = com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(10);
        int buttonY = y + height - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(40); // moved
                                                                                                                // up
        int scaledButtonHeight = com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.getScaledButtonHeight();
        int buttonWidth = (width - scaledSpacing * 5) / 4;

        int editBoxHeight = com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.getScaledEditBoxHeight();
        int editBoxY = buttonY - editBoxHeight - 2;
        int editBoxWidth = width - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(10);
        nameEditBox = new EditBox(
                Minecraft.getInstance().font,
                x + com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(5), editBoxY,
                editBoxWidth, com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.getScaledEditBoxHeight(),
                new TranslatableComponent("buildscape.config.preset.name"));
        nameEditBox.setMaxLength(32);

        if (selectedPresetKey != null) {
            if (selectedPresetKey.equals("_unnamed")) {
                nameEditBox.setValue("");
            } else {
                PresetsConfig.Preset preset = config.getPreset(selectedPresetKey);
                if (preset != null) {
                    nameEditBox.setValue(preset.name);
                }
            }
        }

        if (selectedPresetKey != null && selectedPresetKey.equals("default")) {
            nameEditBox.setEditable(false);
        }

        createButton = new Button(
                x + scaledSpacing, buttonY,
                buttonWidth, scaledButtonHeight,
                new TranslatableComponent("buildscape.config.preset.create"),
                (btn) -> createNewPreset());

        saveButton = new Button(
                x + scaledSpacing * 2 + buttonWidth, buttonY,
                buttonWidth, scaledButtonHeight,
                new TranslatableComponent("buildscape.config.preset.save"),
                (btn) -> saveCurrentPreset());

        deleteButton = new Button(
                x + scaledSpacing * 3 + buttonWidth * 2, buttonY,
                buttonWidth, scaledButtonHeight,
                new TranslatableComponent("buildscape.config.preset.delete"),
                (btn) -> deleteSelectedPreset());

        applyButton = new Button(
                x + scaledSpacing * 4 + buttonWidth * 3, buttonY,
                buttonWidth, scaledButtonHeight,
                new TranslatableComponent("buildscape.config.preset.apply"),
                (btn) -> applySelectedPreset());
    }

    private void loadPresets() {
        PresetsConfig config = PresetsConfig.get();
        presets = config.getPresets();
        presetKeys = config.getPresetKeys();
    }

    private void createNewPreset() {
        nameEditBox.setValue("");
        nameEditBox.setEditable(true);
        selectedPresetKey = "_unnamed";

        PresetsConfig config = PresetsConfig.get();
        PillarParticleConfig itemConfig = PillarParticleConfig.get();
        java.util.Set<String> emptyItems = new java.util.HashSet<>();
        config.saveUnnamedPreset(emptyItems);

        itemConfig.items.clear();
        itemConfig.saveItems();

        loadPresets();

        if (onPresetApplied != null) {
            onPresetApplied.accept("_unnamed");
        }
    }

    private void saveCurrentPreset() {
        if (selectedPresetKey != null && selectedPresetKey.equals("default")) {
            return;
        }

        String name = nameEditBox.getValue().trim();
        if (name.isEmpty()) {
            return;
        }

        PresetsConfig config = PresetsConfig.get();
        PillarParticleConfig itemConfig = PillarParticleConfig.get();

        String key;
        if (selectedPresetKey != null && !selectedPresetKey.equals("default")
                && !selectedPresetKey.equals("_unnamed")) {
            key = selectedPresetKey;
        } else {
            List<String> existingKeys = config.getPresetKeys();
            if (existingKeys.size() >= 5) {
                return;
            }
            key = config.generatePresetKey();
        }

        if (config.savePreset(key, name, itemConfig.items)) {
            selectedPresetKey = key;
            config.clearUnnamedPreset();
            loadPresets();
            nameEditBox.setValue(name);
            nameEditBox.setEditable(true);
        }
    }

    private void deleteSelectedPreset() {
        if (selectedPresetKey != null && !selectedPresetKey.equals("default")
                && !selectedPresetKey.equals("_unnamed")) {
            PresetsConfig config = PresetsConfig.get();
            if (config.deletePreset(selectedPresetKey)) {
                selectedPresetKey = "default";
                PresetsConfig.Preset defaultPreset = config.getPreset("default");
                if (defaultPreset != null) {
                    nameEditBox.setValue(defaultPreset.name);
                } else {
                    nameEditBox.setValue("");
                }
                nameEditBox.setEditable(false);
                loadPresets();
            }
        }
    }

    private void applySelectedPreset() {
        if (selectedPresetKey != null) {
            PresetsConfig config = PresetsConfig.get();
            config.applyPreset(selectedPresetKey);
            if (onPresetApplied != null) {
                onPresetApplied.accept(selectedPresetKey);
            }
        }
    }

    public void setSelectedPreset(String key) {
        selectedPresetKey = key;
        PresetsConfig config = PresetsConfig.get();
        PresetsConfig.Preset preset = config.getPreset(key);
        if (preset != null) {
            nameEditBox.setValue(preset.name);
        } else {
            nameEditBox.setValue("");
        }

        nameEditBox.setEditable(key == null || !key.equals("default"));
    }

    public String getSelectedPresetKey() {
        return selectedPresetKey;
    }

    public Button getCreateButton() {
        return createButton;
    }

    public void updateChildPositions() {
        int scaledSpacing = com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(10);
        int buttonY = y + height - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(40);
        int scaledButtonHeight = 20; // Fixed 20px for vanilla button assets
        int buttonWidth = (width - scaledSpacing * 5) / 4;

        if (nameEditBox != null) {
            int editBoxHeight = com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.getScaledEditBoxHeight();
            int editBoxY = buttonY - editBoxHeight - 2;
            int editBoxWidth = width - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(10);
            nameEditBox.x = x + com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(5);
            nameEditBox.y = editBoxY;
            nameEditBox.setWidth(editBoxWidth);
        }

        if (createButton != null) {
            createButton.x = x + scaledSpacing;
            createButton.y = buttonY;
            createButton.setWidth(buttonWidth);
        }

        if (saveButton != null) {
            saveButton.x = x + scaledSpacing * 2 + buttonWidth;
            saveButton.y = buttonY;
            saveButton.setWidth(buttonWidth);
        }

        if (deleteButton != null) {
            deleteButton.x = x + scaledSpacing * 3 + buttonWidth * 2;
            deleteButton.y = buttonY;
            deleteButton.setWidth(buttonWidth);
        }

        if (applyButton != null) {
            applyButton.x = x + scaledSpacing * 4 + buttonWidth * 3;
            applyButton.y = buttonY;
            applyButton.setWidth(buttonWidth);
        }
    }

    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {

        // Draw border around panel (debug mode)
        if (com.kingodogo.buildscape.client.screen.DebugRenderConfig.RENDER_PANEL_BORDERS) {
            int borderColor = com.kingodogo.buildscape.client.screen.DebugRenderConfig.PANEL_BORDER_COLOR;
            fill(poseStack, x, y, x + width, y + 1, borderColor); // Top
            fill(poseStack, x, y + height - 1, x + width, y + height, borderColor); // Bottom
            fill(poseStack, x, y, x + 1, y + height, borderColor); // Left
            fill(poseStack, x + width - 1, y, x + width, y + height, borderColor); // Right
        }

        Minecraft.getInstance().font.draw(
                poseStack,
                new TranslatableComponent("buildscape.config.presets"),
                x + 5, y + 5,
                0xFFFFFF);

        int presetY = y + 20;
        int scaledSpacing = com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(10);
        int buttonYPos = y + height - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(40); // Lift
                                                                                                                   // buttons
                                                                                                                   // up
        int editBoxTop = nameEditBox != null ? nameEditBox.y : buttonYPos;
        int availableHeight = editBoxTop - presetY - 5;
        int maxVisiblePresets = Math.max(1, availableHeight / (PRESET_BUTTON_HEIGHT + PRESET_BUTTON_SPACING));
        int visibleCount = Math.min(presets.size() - scrollOffset, maxVisiblePresets);

        for (int i = 0; i < visibleCount; i++) {
            int index = scrollOffset + i;
            if (index >= presets.size())
                break;

            PresetsConfig.Preset preset = presets.get(index);
            String presetKey = presetKeys.get(index);
            boolean isSelected = presetKey.equals(selectedPresetKey);

            int buttonY = presetY + i * (PRESET_BUTTON_HEIGHT + PRESET_BUTTON_SPACING);

            if (buttonY + PRESET_BUTTON_HEIGHT >= editBoxTop) {
                break;
            }
            // Hover check: x + 5 to width - 16 (scrollbar area)
            boolean isHovered = mouseX >= x + 5 && mouseX < x + width - 16
                    &&
                    mouseY >= buttonY && mouseY < buttonY + PRESET_BUTTON_HEIGHT;
            int bgColor = isHovered ? 0x40CCCCCC : 0x33CCCCCC;

            fill(poseStack, x + 5, buttonY, x + width - 16,
                    buttonY + PRESET_BUTTON_HEIGHT, bgColor);

            String displayName = preset.name;
            if (presetKey.equals("_unnamed")) {
                displayName = "(Unsaved Changes)";
            } else if (displayName.isEmpty()) {
                displayName = "(Unnamed)";
            }

            int availableWidth = width - 20;
            int textWidth = Minecraft.getInstance().font.width(displayName);
            if (textWidth > availableWidth) {
                String truncated = Minecraft.getInstance().font.plainSubstrByWidth(displayName,
                        availableWidth - Minecraft.getInstance().font.width("..."));
                displayName = truncated + "...";
            }

            Minecraft.getInstance().font.draw(
                    poseStack,
                    displayName,
                    x + 10, buttonY + 6,
                    0xFFFFFF);
        }

        if (presets.size() > maxVisiblePresets) {
            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4; // 4px form edge
            int scrollbarHeight = editBoxTop - presetY - 5;
            int scrollbarY = presetY;

            double maxScroll = Math.max(0, presets.size() - maxVisiblePresets);
            double visibleRatio = maxVisiblePresets / (double) presets.size();
            scrollbarRenderer.renderScrollbar(poseStack, scrollbarX, scrollbarY, scrollbarHeight,
                    scrollOffset, maxScroll, visibleRatio);
        }

        nameEditBox.render(poseStack, mouseX, mouseY, partialTick);
        createButton.render(poseStack, mouseX, mouseY, partialTick);
        saveButton.render(poseStack, mouseX, mouseY, partialTick);
        deleteButton.render(poseStack, mouseX, mouseY, partialTick);
        applyButton.render(poseStack, mouseX, mouseY, partialTick);

        deleteButton.active = selectedPresetKey != null && !selectedPresetKey.equals("default");
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (!isMouseOver(mouseX, mouseY)) {
            return false;
        }

        int presetY = y + 20;
        int buttonYPos = y + height - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(40); // Lift
                                                                                                                   // buttons
                                                                                                                   // up
        int editBoxTop = nameEditBox != null ? nameEditBox.y : buttonYPos;
        int availableHeight = editBoxTop - presetY - 5;
        int maxVisiblePresets = Math.max(1, availableHeight / (PRESET_BUTTON_HEIGHT + PRESET_BUTTON_SPACING));

        double maxScroll = Math.max(0, presets.size() - maxVisiblePresets);
        if (maxScroll > 0) {
            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4; // 4px form edge
            int scrollbarY = presetY;
            int scrollbarHeight = editBoxTop - presetY - 5;
            int contentX = x + 5;
            int contentY = presetY;
            int contentWidth = width - 21; // width - 16 - 5
            int contentHeight = scrollbarHeight;

            double visibleRatio = maxVisiblePresets / (double) presets.size();
            double newOffset = scrollbarRenderer.handleMouseClick(mouseX, mouseY, button,
                    scrollbarX, scrollbarY, scrollbarHeight,
                    contentX, contentY, contentWidth, contentHeight,
                    scrollOffset, maxScroll, visibleRatio);

            if (newOffset >= 0) {
                scrollOffset = (int) newOffset;
                return true;
            }
        }

        int visibleCount = Math.min(presets.size() - scrollOffset, maxVisiblePresets);
        for (int i = 0; i < visibleCount; i++) {
            int index = scrollOffset + i;
            if (index >= presets.size())
                break;

            int buttonY = presetY + i * (PRESET_BUTTON_HEIGHT + PRESET_BUTTON_SPACING);
            if (buttonY + PRESET_BUTTON_HEIGHT >= editBoxTop) {
                break;
            }
            if (mouseX >= x + 5 && mouseX < x + width - 5 &&
                    mouseY >= buttonY && mouseY < buttonY + PRESET_BUTTON_HEIGHT) {
                String presetKey = presetKeys.get(index);
                setSelectedPreset(presetKey);
                return true;
            }
        }

        if (nameEditBox.mouseClicked(mouseX, mouseY, button)) {
            return true;
        }
        if (createButton.mouseClicked(mouseX, mouseY, button)) {
            return true;
        }
        if (saveButton.mouseClicked(mouseX, mouseY, button)) {
            return true;
        }
        if (deleteButton.mouseClicked(mouseX, mouseY, button)) {
            return true;
        }
        return applyButton.mouseClicked(mouseX, mouseY, button);
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
        if (!isMouseOver(mouseX, mouseY)) {
            return false;
        }

        int presetY = y + 20;
        int buttonYPos = y + height - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(40); // Lift
                                                                                                                   // buttons
                                                                                                                   // up
        int editBoxTop = nameEditBox != null ? nameEditBox.y : buttonYPos;
        int availableHeight = editBoxTop - presetY - 5;
        int maxVisiblePresets = Math.max(1, availableHeight / (PRESET_BUTTON_HEIGHT + PRESET_BUTTON_SPACING));
        double maxScroll = Math.max(0, presets.size() - maxVisiblePresets);
        scrollOffset = (int) Math.max(0, Math.min(maxScroll, scrollOffset - delta));
        return true;
    }

    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        if (scrollbarRenderer.isDragging() && button == 0) {
            int presetY = y + 20;
            int buttonYPos = y + height - com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen.scaleSize(40); // Lift
                                                                                                                       // buttons
                                                                                                                       // up
            int editBoxTop = nameEditBox != null ? nameEditBox.y : buttonYPos;
            int availableHeight = editBoxTop - presetY - 5;
            int maxVisiblePresets = Math.max(1, availableHeight / (PRESET_BUTTON_HEIGHT + PRESET_BUTTON_SPACING));
            double maxScroll = Math.max(0, presets.size() - maxVisiblePresets);

            if (maxScroll > 0) {
                int scrollbarY = presetY;
                int scrollbarHeight = editBoxTop - presetY - 5;
                double visibleRatio = maxVisiblePresets / (double) presets.size();

                double newOffset = scrollbarRenderer.handleMouseDrag(mouseY, scrollbarY, scrollbarHeight,
                        maxScroll, visibleRatio, 1.0);

                if (newOffset >= 0) {
                    scrollOffset = (int) newOffset;
                    return true;
                }
            }
        }
        return false;
    }

    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        return scrollbarRenderer.handleMouseRelease(button);
    }

    @Override
    public boolean keyPressed(int keyCode, int scanCode, int modifiers) {
        return nameEditBox.keyPressed(keyCode, scanCode, modifiers);
    }

    @Override
    public boolean charTyped(char codePoint, int modifiers) {
        return nameEditBox.charTyped(codePoint, modifiers);
    }

    @Override
    public void updateNarration(NarrationElementOutput narrationElementOutput) {
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.gui.components.Button;
import net.minecraft.network.chat.Component;

public class ScaledTextButton extends Button {
    
    public ScaledTextButton(int x, int y, int width, int height, Component message, OnPress onPress) {
        super(x, y, width, height, message, onPress);
    }
    
    @Override
    public void renderButton(com.mojang.blaze3d.vertex.PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();
        double guiScale = mc.getWindow().getGuiScale();
        float textScale = 1.0f;
        if (guiScale >= 3.0) {
            textScale = 0.75f;
        } else if (guiScale >= 2.5) {
            textScale = 0.85f;
        }

        String buttonText = getMessage().getString();

        int availableWidth = (int)(width / textScale);
        int textWidth = mc.font.width(buttonText);

        String displayText = buttonText;
        if (textWidth > availableWidth) {
            if (buttonText.contains("Ko-fi") || buttonText.contains("ko-fi")) {
                displayText = "Ko-fi";
            } else if (buttonText.contains("Edit GUI")) {
                displayText = "Edit GUI";
            } else {
                String truncated = mc.font.plainSubstrByWidth(buttonText, availableWidth - mc.font.width("..."));
                displayText = truncated + "...";
            }
        }

        int bgColor = this.isHovered ? 0xFFE0E0E0 : 0xFFC0C0C0;
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y, this.x + this.width, this.y + this.height, bgColor);

        int borderColor = 0xFF000000;
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y, this.x + this.width, this.y + 1, borderColor);
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y + this.height - 1, this.x + this.width, this.y + this.height, borderColor);
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y, this.x + 1, this.y + this.height, borderColor);
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x + this.width - 1, this.y, this.x + this.width, this.y + this.height, borderColor);

        int textColor = this.active ? 0xFFFFFF : 0xA0A0A0;
        poseStack.pushPose();
        poseStack.translate(this.x + this.width / 2.0, this.y + (this.height - 8) / 2.0, 0);
        poseStack.scale(textScale, textScale, 1.0f);
        drawCenteredString(poseStack, 
            mc.font, 
            new net.minecraft.network.chat.TextComponent(displayText), 
            0, 
            0, 
            textColor
        );
        poseStack.popPose();
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.client.renderer.entity.ItemRenderer;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraftforge.registries.ForgeRegistries;
import com.mojang.blaze3d.vertex.PoseStack;
import java.util.function.Consumer;

public class SortToggleButton extends AbstractWidget {
    public enum SortType {
        INVENTORY,
        ALL_ITEMS,
        MOD_ONLY
    }
    
    private final SortType sortType;
    private boolean selected = false;
    private final Consumer<SortType> onToggle;
    private Item iconItem;
    
    public SortToggleButton(int x, int y, int width, int height, SortType sortType, Consumer<SortType> onToggle) {
        super(x, y, width, height, net.minecraft.network.chat.TextComponent.EMPTY);
        this.sortType = sortType;
        this.onToggle = onToggle;

        switch (sortType) {
            case INVENTORY:
                iconItem = Items.CHEST;
                break;
            case ALL_ITEMS:
                iconItem = Items.BOOK;
                break;
            case MOD_ONLY:
                iconItem = Items.BOOK;
                break;
        }
    }
    
    public void setSelected(boolean selected) {
        this.selected = selected;
    }
    
    public boolean isSelected() {
        return selected;
    }
    
    public SortType getSortType() {
        return sortType;
    }
    
    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {

        ItemRenderer itemRenderer = Minecraft.getInstance().getItemRenderer();
        int centerX = x + width / 2;
        int centerY = y + height / 2;
        
        if (sortType == SortType.INVENTORY) {
            ItemStack stack = new ItemStack(iconItem);
            Minecraft mc = Minecraft.getInstance();
            itemRenderer.renderGuiItem(stack, centerX - 8, centerY - 8);
        } else if (sortType == SortType.ALL_ITEMS) {
            Minecraft.getInstance().font.draw(
                poseStack,
                "A",
                centerX - Minecraft.getInstance().font.width("A") / 2,
                centerY - 4,
                0xFFFFFF
            );
        } else if (sortType == SortType.MOD_ONLY) {
            Minecraft.getInstance().font.draw(
                poseStack,
                "M",
                centerX - Minecraft.getInstance().font.width("M") / 2,
                centerY - 4,
                0xFFFFFF
            );
        }
    }
    
    @Override
    public void onClick(double mouseX, double mouseY) {
        if (onToggle != null) {
            onToggle.accept(sortType);
        }
    }
    
    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        if (this.active && this.visible) {
            if (isValidClickButton(button)) {
                boolean clicked = mouseX >= (double)this.x && mouseY >= (double)this.y && 
                                mouseX < (double)(this.x + this.width) && 
                                mouseY < (double)(this.y + this.height);
                
                if (clicked) {
                    this.playDownSound(net.minecraft.client.Minecraft.getInstance().getSoundManager());
                    this.onClick(mouseX, mouseY);
                    return true;
                }
            }
        }
        return false;
    }
    
    @Override
    public void updateNarration(NarrationElementOutput narrationElementOutput) {
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.Minecraft;
import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.narration.NarrationElementOutput;
import net.minecraft.core.Registry;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.tags.TagKey;
import net.minecraft.tags.TagManager;
import net.minecraft.world.item.Item;
import net.minecraftforge.registries.ForgeRegistries;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.systems.RenderSystem;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import java.util.stream.Collectors;

public class TagsSelectorWidget extends AbstractWidget {
    private static final int TAG_BUTTON_HEIGHT = 20;
    private static final int TAG_BUTTON_SPACING = 2;
    private static final int TAGS_PER_ROW = 1;
    // Header area: top padding (5px) + search box height (~20px) + gap (5px) = 30px
    // Tags start below this area
    private static final int HEADER_AREA_HEIGHT = 26; // Reduced to start 1px below search bar (5px padding + 20px
                                                      // height + 1px)

    private List<TagKey<Item>> allTags;
    private List<TagKey<Item>> filteredTags;
    private String filter = "";
    private double scrollOffset = 0;
    private int maxVisibleRows;
    private final Consumer<String> onTagSelected;
    private Set<String> selectedTags;
    private SortType sortType = SortType.ALL_ITEMS;
    private final CustomScrollbarRenderer scrollbarRenderer = new CustomScrollbarRenderer();

    // Scrolling text state
    private String currentHoveredTagId = null;
    private long hoverStartTime = 0;

    public enum SortType {
        INVENTORY,
        ALL_ITEMS,
        MOD_ONLY
    }

    public TagsSelectorWidget(int x, int y, int width, int height, Consumer<String> onTagSelected) {
        super(x, y, width, height, net.minecraft.network.chat.TextComponent.EMPTY);
        this.onTagSelected = onTagSelected;
        this.selectedTags = new HashSet<>();
        loadAllTags();
        filteredTags = new ArrayList<>(allTags);
        maxVisibleRows = (height - HEADER_AREA_HEIGHT) / (TAG_BUTTON_HEIGHT + TAG_BUTTON_SPACING);
    }

    private void loadAllTags() {
        allTags = new ArrayList<>();
        Set<String> seenTags = new HashSet<>();

        ForgeRegistries.ITEMS.getValues().forEach(item -> {
            item.builtInRegistryHolder().tags().forEach(tagKey -> {
                String tagId = tagKey.location().toString();
                if (!seenTags.contains(tagId)) {
                    seenTags.add(tagId);
                    allTags.add(tagKey);
                }
            });
        });

        allTags.sort((a, b) -> a.location().toString().compareToIgnoreCase(b.location().toString()));
    }

    public void setFilter(String filter) {
        this.filter = filter.toLowerCase();
        refresh();
    }

    public void setSortType(SortType sortType) {
        this.sortType = sortType;
        refresh();
    }

    public SortType getSortType() {
        return sortType;
    }

    public void refresh() {
        List<TagKey<Item>> baseList = allTags;

        if (!filter.isEmpty()) {
            baseList = allTags.stream()
                    .filter(tag -> {
                        String tagId = tag.location().toString().toLowerCase();
                        return tagId.contains(filter);
                    })
                    .collect(Collectors.toList());
        }

        switch (sortType) {
            case INVENTORY:
                filteredTags = baseList.stream()
                        .filter(tag -> {
                            return ForgeRegistries.ITEMS.getValues().stream()
                                    .anyMatch(item -> {
                                        if (!item.builtInRegistryHolder().tags().anyMatch(t -> t.equals(tag))) {
                                            return false;
                                        }
                                        net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft
                                                .getInstance();
                                        if (mc.player != null) {
                                            return mc.player.getInventory().items.stream()
                                                    .anyMatch(stack -> stack.getItem() == item);
                                        }
                                        return false;
                                    });
                        })
                        .collect(Collectors.toList());
                break;
            case MOD_ONLY:
                filteredTags = baseList.stream()
                        .filter(tag -> tag.location().getNamespace().equals("buildscape"))
                        .collect(Collectors.toList());
                break;
            case ALL_ITEMS:
            default:
                filteredTags = new ArrayList<>(baseList);
                break;
        }

        scrollOffset = Math.max(0, Math.min(scrollOffset, getMaxScroll()));
    }

    public void setSelectedTags(Set<String> tags) {
        this.selectedTags = new HashSet<>(tags);
    }

    private double getMaxScroll() {
        int totalRows = filteredTags.size();
        return Math.max(0, totalRows - maxVisibleRows);
    }

    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        // Tags should start below the header area (label, search box, buttons)
        // Tags should start below the header area (label, search box, buttons)
        int topPadding = HEADER_AREA_HEIGHT;
        int bottomMargin = 10;
        int availableHeight = height - topPadding - bottomMargin; // Account for bottom margin
        maxVisibleRows = availableHeight / (TAG_BUTTON_HEIGHT + TAG_BUTTON_SPACING);
        maxVisibleRows = Math.max(1, maxVisibleRows);

        poseStack.pushPose();
        Minecraft mc = Minecraft.getInstance();
        double guiScale = mc.getWindow().getGuiScale();
        int windowHeight = mc.getWindow().getHeight();

        // Draw border around panel (debug mode)
        if (com.kingodogo.buildscape.client.screen.DebugRenderConfig.RENDER_PANEL_BORDERS) {
            int borderColor = com.kingodogo.buildscape.client.screen.DebugRenderConfig.PANEL_BORDER_COLOR;
            fill(poseStack, x, y, x + width, y + 1, borderColor); // Top
            fill(poseStack, x, y + height - 1, x + width, y + height, borderColor); // Bottom
            fill(poseStack, x, y, x + 1, y + height, borderColor); // Left
            fill(poseStack, x + width - 1, y, x + width, y + height, borderColor); // Right
        }

        int scissorX = (int) (x * guiScale);
        // Exclude header area from scissor height and add bottom margin
        // bottomMargin is already defined above
        // Raise bottom edge by bottomMargin
        int scissorY = (int) (windowHeight - (y + height) * guiScale + bottomMargin * guiScale);
        // Clip content to exclude scrollbar area:
        // 4px right gap + 8px scrollbar + 4px left gap = 16px reserved
        int scissorWidth = (int) ((width - 16) * guiScale);
        int scissorHeight = (int) ((height - HEADER_AREA_HEIGHT - bottomMargin) * guiScale); // Reduce height

        if (scissorHeight > 0 && scissorWidth > 0) {
            RenderSystem.enableScissor(scissorX, scissorY, scissorWidth, scissorHeight);
        }

        int startRow = (int) scrollOffset;
        int endRow = Math.min(startRow + maxVisibleRows + 1, filteredTags.size()); // +1 to ensure smooth scrolling

        int tagY = y + topPadding;
        // Total width - 5px left padding - 16px right reserved space = width - 21
        int tagWidth = width - 21;

        for (int row = startRow; row < endRow; row++) {
            if (row >= filteredTags.size())
                break;

            TagKey<Item> tag = filteredTags.get(row);
            String tagId = "#" + tag.location();
            int rowY = tagY + (row - startRow) * (TAG_BUTTON_HEIGHT + TAG_BUTTON_SPACING);

            // Updated visibility check to respect HEADER_AREA_HEIGHT
            if (rowY + TAG_BUTTON_HEIGHT < y + HEADER_AREA_HEIGHT || rowY > y + height) {
                continue;
            }

            int tagX = x + 5;

            boolean isSelected = selectedTags.contains(tagId);
            boolean isHovered = mouseX >= tagX && mouseX < tagX + tagWidth &&
                    mouseY >= rowY && mouseY < rowY + TAG_BUTTON_HEIGHT &&
                    mouseX >= x && mouseX < x + width &&
                    mouseY >= y + HEADER_AREA_HEIGHT && mouseY < y + height; // Updated hover check

            int bgColor;
            if (isSelected) {
                bgColor = isHovered ? 0x6000FF00 : 0x4000FF00;
            } else {
                bgColor = isHovered ? 0x40CCCCCC : 0x33CCCCCC;
            }
            fill(poseStack, tagX, rowY, tagX + tagWidth, rowY + TAG_BUTTON_HEIGHT, bgColor);

            if (isSelected) {
                int borderColor = 0xFF00FF00;
                fill(poseStack, tagX - 1, rowY - 1, tagX + tagWidth + 1, rowY, borderColor);
                fill(poseStack, tagX - 1, rowY + TAG_BUTTON_HEIGHT, tagX + tagWidth + 1, rowY + TAG_BUTTON_HEIGHT + 1,
                        borderColor);
                fill(poseStack, tagX - 1, rowY - 1, tagX, rowY + TAG_BUTTON_HEIGHT + 1, borderColor);
                fill(poseStack, tagX + tagWidth, rowY - 1, tagX + tagWidth + 1, rowY + TAG_BUTTON_HEIGHT + 1,
                        borderColor);
            }

            String displayName = tag.location().toString();
            int availableWidth = tagWidth - 10;
            int textWidth = Minecraft.getInstance().font.width(displayName);

            if (isHovered && textWidth > availableWidth) {
                // Scrolling text logic
                if (!tagId.equals(currentHoveredTagId)) {
                    currentHoveredTagId = tagId;
                    hoverStartTime = System.currentTimeMillis();
                }

                long elapsed = System.currentTimeMillis() - hoverStartTime;
                double speed = 0.001; // Speed factor
                int maxScroll = textWidth - availableWidth;

                // Sine wave scrolling: 0 -> max -> 0
                // (1 - cos(t)) / 2 ranges from 0 to 1 to 0
                double scrollProgress = (1.0 - Math.cos(elapsed * speed)) / 2.0;
                int textOffset = (int) (maxScroll * scrollProgress);

                // Clip text to button bounds to prevent leaking
                int buttonScissorX = (int) ((tagX + 5) * guiScale);
                int buttonScissorY = (int) (windowHeight - (rowY + TAG_BUTTON_HEIGHT - 6) * guiScale); // Approx bounds
                int buttonScissorWidth = (int) ((availableWidth) * guiScale);
                int buttonScissorHeight = (int) (TAG_BUTTON_HEIGHT * guiScale);

                // Use intersection with existing scissor (list area) to remain safe
                // But simplified: just enabling scissor for the text line is usually enough if
                // strictly contained
                // Better: Use viewport intersection logic or just a tighter scissor

                // Strict clipping for the text
                int textScissorY = (int) (windowHeight - (rowY + TAG_BUTTON_HEIGHT) * guiScale);
                int textScissorH = (int) (TAG_BUTTON_HEIGHT * guiScale);

                // Apply scissor for text
                RenderSystem.enableScissor(buttonScissorX, textScissorY, buttonScissorWidth, textScissorH);

                Minecraft.getInstance().font.draw(
                        poseStack,
                        displayName,
                        tagX + 5 - textOffset, rowY + 6,
                        0xFFFFFF);

                // Restore list scissor
                if (scissorHeight > 0 && scissorWidth > 0) {
                    RenderSystem.enableScissor(scissorX, scissorY, scissorWidth, scissorHeight);
                } else {
                    RenderSystem.disableScissor();
                }
            } else {
                if (textWidth > availableWidth) {
                    String truncated = Minecraft.getInstance().font.plainSubstrByWidth(displayName,
                            availableWidth - Minecraft.getInstance().font.width("..."));
                    displayName = truncated + "...";
                }
                Minecraft.getInstance().font.draw(
                        poseStack,
                        displayName,
                        tagX + 5, rowY + 6,
                        0xFFFFFF);
            }
        }

        if (scissorHeight > 0 && scissorWidth > 0) {
            RenderSystem.disableScissor();
        }
        poseStack.popPose();

        if (getMaxScroll() > 0) {
            // Scrollbar X = width - 4px gap - 8px width = width - 12
            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4;
            bottomMargin = 10; // Increased margin at bottom
            int scrollbarHeight = height - HEADER_AREA_HEIGHT - bottomMargin;
            int scrollbarY = y + HEADER_AREA_HEIGHT;

            double visibleRatio = maxVisibleRows / (double) filteredTags.size();
            scrollbarRenderer.renderScrollbar(poseStack, scrollbarX, scrollbarY, scrollbarHeight,
                    scrollOffset, getMaxScroll(), visibleRatio);
        }
    }

    @Override
    public boolean mouseClicked(double mouseX, double mouseY, int button) {
        // Updated check to ignore clicks in header area
        if (!isMouseOver(mouseX, mouseY) || mouseY < y + HEADER_AREA_HEIGHT) {
            return false;
        }

        double maxScroll = getMaxScroll();
        if (maxScroll > 0) {
            int scrollbarX = x + width - CustomScrollbarRenderer.getScrollbarWidth() - 4; // 4px form edge
            int scrollbarY = y + HEADER_AREA_HEIGHT;
            int bottomMargin = 10;
            int scrollbarHeight = height - HEADER_AREA_HEIGHT - bottomMargin;
            int contentX = x + 5;
            int contentY = y + HEADER_AREA_HEIGHT;
            // Content width = width - 16px reserved - 5px left padding = width - 21
            int contentWidth = width - 21;
            int contentHeight = height - HEADER_AREA_HEIGHT;

            double visibleRatio = maxVisibleRows / (double) filteredTags.size();
            double newOffset = scrollbarRenderer.handleMouseClick(mouseX, mouseY, button,
                    scrollbarX, scrollbarY, scrollbarHeight,
                    contentX, contentY, contentWidth, contentHeight,
                    scrollOffset, maxScroll, visibleRatio);

            if (newOffset >= 0) {
                scrollOffset = newOffset;
                return true;
            }
        }

        int topPadding = HEADER_AREA_HEIGHT; // Use constant
        int bottomMargin = 10;
        int availableHeight = height - topPadding - bottomMargin;
        maxVisibleRows = availableHeight / (TAG_BUTTON_HEIGHT + TAG_BUTTON_SPACING);
        maxVisibleRows = Math.max(1, maxVisibleRows);

        int startRow = (int) scrollOffset;
        int endRow = Math.min(startRow + maxVisibleRows + 1, filteredTags.size());

        int tagY = y + topPadding;
        int tagWidth = width - 21;

        for (int row = startRow; row < endRow; row++) {
            if (row >= filteredTags.size())
                break;

            TagKey<Item> tag = filteredTags.get(row);
            String tagId = "#" + tag.location();
            int rowY = tagY + (row - startRow) * (TAG_BUTTON_HEIGHT + TAG_BUTTON_SPACING);

            // Updated visibility check
            if (rowY + TAG_BUTTON_HEIGHT < y + HEADER_AREA_HEIGHT || rowY > y + height) {
                continue;
            }

            int tagX = x + 5;

            if (mouseX >= tagX && mouseX < tagX + tagWidth &&
                    mouseY >= rowY && mouseY < rowY + TAG_BUTTON_HEIGHT &&
                    mouseX >= x && mouseX < x + width &&
                    mouseY >= y + HEADER_AREA_HEIGHT && mouseY < y + height) { // Updated click check
                if (selectedTags.contains(tagId)) {
                    selectedTags.remove(tagId);
                } else {
                    selectedTags.add(tagId);
                }
                if (onTagSelected != null) {
                    onTagSelected.accept(tagId);
                }
                return true;
            }
        }

        return false;
    }

    @Override
    public boolean mouseScrolled(double mouseX, double mouseY, double delta) {
        if (!isMouseOver(mouseX, mouseY)) {
            return false;
        }

        scrollOffset = Math.max(0, Math.min(getMaxScroll(), scrollOffset - delta));
        return true;
    }

    @Override
    public boolean mouseDragged(double mouseX, double mouseY, int button, double dragX, double dragY) {
        if (scrollbarRenderer.isDragging() && button == 0) {
            double maxScroll = getMaxScroll();
            if (maxScroll > 0) {
                int scrollbarY = y + HEADER_AREA_HEIGHT;
                int bottomMargin = 10;
                int scrollbarHeight = height - HEADER_AREA_HEIGHT - bottomMargin;
                double visibleRatio = maxVisibleRows / (double) filteredTags.size();

                double newOffset = scrollbarRenderer.handleMouseDrag(mouseY, scrollbarY, scrollbarHeight,
                        maxScroll, visibleRatio, 1.0);

                if (newOffset >= 0) {
                    scrollOffset = newOffset;
                    return true;
                }
            }
        }
        return false;
    }

    @Override
    public boolean mouseReleased(double mouseX, double mouseY, int button) {
        return scrollbarRenderer.handleMouseRelease(button);
    }

    @Override
    public void updateNarration(NarrationElementOutput narrationElementOutput) {
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.gui.components.Button;
import net.minecraft.network.chat.Component;
import com.mojang.blaze3d.vertex.PoseStack;

public class WideButton extends Button {
    
    public WideButton(int x, int y, int width, int height, Component message, OnPress onPress) {
        super(x, y, width, height, message, onPress);
    }
    
    @Override
    public void renderButton(PoseStack poseStack, int mouseX, int mouseY, float partialTick) {
        int bgColor = this.isHovered ? 0xFFE0E0E0 : 0xFFC0C0C0;
        if (!this.active) {
            bgColor = 0xFF808080;
        }

        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y, this.x + this.width, this.y + this.height, bgColor);

        int borderColor = 0xFF000000;
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y, this.x + this.width, this.y + 1, borderColor);
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y + this.height - 1, this.x + this.width, this.y + this.height, borderColor);
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x, this.y, this.x + 1, this.y + this.height, borderColor);
        net.minecraft.client.gui.GuiComponent.fill(poseStack, this.x + this.width - 1, this.y, this.x + this.width, this.y + this.height, borderColor);

        int textColor = this.active ? 0xFFFFFF : 0xA0A0A0;
        net.minecraft.client.Minecraft mc = net.minecraft.client.Minecraft.getInstance();
        drawCenteredString(poseStack, 
            mc.font, 
            this.getMessage(), 
            this.x + this.width / 2, 
            this.y + (this.height - 8) / 2, 
            textColor
        );
    }
}

package com.kingodogo.buildscape.client.screen.widget;

import net.minecraft.client.gui.components.AbstractWidget;
import net.minecraft.client.gui.components.EditBox;
import com.kingodogo.buildscape.client.screen.BuildScapeConfigScreen;

public class WidgetLayoutHelper {
    
    public static void positionSearchBoxWithButtons(AbstractWidget parent, EditBox searchBox,
                                                    int buttonAreaWidth, int topOffset, int leftPadding) {
        if (parent == null || searchBox == null) return;
        
        int searchBoxY = parent.y + topOffset;
        int searchBoxWidth = parent.getWidth() - buttonAreaWidth - leftPadding * 2;
        int searchBoxX = parent.x + leftPadding;
        
        searchBox.x = searchBoxX;
        searchBox.y = searchBoxY;
        searchBox.setWidth(searchBoxWidth);
    }
    
    public static void positionButtonsInRow(AbstractWidget parent, AbstractWidget[] buttons,
                                           int buttonSize, int buttonSpacing,
                                           int searchBoxWidth, int topOffset, int leftPadding) {
        if (parent == null || buttons == null) return;
        
        int buttonY = parent.y + topOffset;
        int buttonsStartX = parent.x + leftPadding + searchBoxWidth + BuildScapeConfigScreen.scaleSize(10);
        
        for (int i = 0; i < buttons.length; i++) {
            if (buttons[i] != null) {
                buttons[i].x = buttonsStartX + i * (buttonSize + buttonSpacing);
                buttons[i].y = buttonY;
                if (buttons[i] instanceof AbstractWidget) {
                    buttons[i].setWidth(buttonSize);
                    try {
                        java.lang.reflect.Field heightField = AbstractWidget.class.getDeclaredField("height");
                        heightField.setAccessible(true);
                        heightField.setInt(buttons[i], buttonSize);
                    } catch (Exception e) {
                    }
                }
            }
        }
    }
    
    public static void positionWidgetBelowSearchBox(AbstractWidget parent, AbstractWidget child,
                                                   int searchBoxHeight, int searchBoxOffset, int bottomPadding) {
        if (parent == null || child == null) return;
        
        int childY = parent.y + searchBoxOffset + searchBoxHeight + BuildScapeConfigScreen.scaleSize(5);
        int childHeight = parent.y + parent.getHeight() - childY - bottomPadding;
        
        child.x = parent.x;
        child.y = childY;
        child.setWidth(parent.getWidth());
        
        try {
            java.lang.reflect.Method setHeightMethod = child.getClass().getMethod("setHeight", int.class);
            setHeightMethod.invoke(child, childHeight);
        } catch (NoSuchMethodException e) {
            try {
                java.lang.reflect.Field heightField = AbstractWidget.class.getDeclaredField("height");
                heightField.setAccessible(true);
                heightField.setInt(child, childHeight);
            } catch (Exception ex) {
            }
        } catch (Exception e) {
        }
    }
    
    public static void updateChildPositions(AbstractWidget parent, EditBox searchBox,
                                           AbstractWidget[] buttons, AbstractWidget childWidget,
                                           int buttonAreaWidth, int topOffset, int leftPadding,
                                           int searchBoxHeight, int bottomPadding) {
        if (parent == null) return;

        if (searchBox != null) {
            positionSearchBoxWithButtons(parent, searchBox, buttonAreaWidth, topOffset, leftPadding);
        }

        if (buttons != null && searchBox != null) {
            int searchBoxWidth = parent.getWidth() - buttonAreaWidth - leftPadding * 2;
            int buttonSize = BuildScapeConfigScreen.scaleSize(20);
            int buttonSpacing = BuildScapeConfigScreen.scaleSize(5);
            positionButtonsInRow(parent, buttons, buttonSize, buttonSpacing, searchBoxWidth, topOffset, leftPadding);
        }

        if (childWidget != null && searchBox != null) {
            positionWidgetBelowSearchBox(parent, childWidget, searchBoxHeight, topOffset, bottomPadding);
        }
    }
}

package com.kingodogo.buildscape.client;

import com.kingodogo.buildscape.network.ModMessages;
import com.kingodogo.buildscape.network.TreeChopPacket;
import com.mojang.blaze3d.vertex.PoseStack;
import com.mojang.blaze3d.vertex.VertexConsumer;
import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.LevelRenderer;
import net.minecraft.client.renderer.RenderType;
import net.minecraft.core.BlockPos;
import net.minecraft.tags.BlockTags;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
import net.minecraft.world.phys.BlockHitResult;
import net.minecraft.world.phys.HitResult;
import net.minecraft.world.phys.shapes.VoxelShape;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.DrawSelectionEvent;
import net.minecraftforge.client.event.InputEvent;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import java.util.HashSet;
import java.util.LinkedList;
import java.util.Queue;
import java.util.Set;

@Mod.EventBusSubscriber(
        modid = com.kingodogo.buildscape.BuildScape.MODID,
        bus = Mod.EventBusSubscriber.Bus.FORGE,
        value = Dist.CLIENT
)
public class TreeChopHandler {

    private static final long BREAK_DELAY_MS = 1000;
    private static final int MAX_LOGS = 200;
    private static BlockPos targetBlockPos = null;
    private static long breakingStartTime = 0;
    // Cache
    private static BlockPos lastLookedAtPos = null;
    private static Set<BlockPos> connectedLogsCache = new HashSet<>();
    private static long lastCacheUpdate = 0;

    @SubscribeEvent
    public static void onClientTick(TickEvent.ClientTickEvent event) {
        if (event.phase != TickEvent.Phase.END) return;

        Minecraft mc = Minecraft.getInstance();
        Player player = mc.player;
        if (player == null || mc.level == null) return;

        // Reset
        if (!player.isCreative() || !player.isShiftKeyDown() || mc.options.keyAttack == null || !mc.options.keyAttack.isDown()) {
            if (mc.level != null && targetBlockPos != null) {
                mc.level.destroyBlockProgress(player.getId(), targetBlockPos, -1);
            }
            targetBlockPos = null;
            breakingStartTime = 0;
            return;
        }

        HitResult hit = mc.hitResult;
        if (hit == null || hit.getType() != HitResult.Type.BLOCK) {
            if (mc.level != null && targetBlockPos != null) {
                mc.level.destroyBlockProgress(player.getId(), targetBlockPos, -1);
            }
            targetBlockPos = null;
            breakingStartTime = 0;
            return;
        }

        BlockPos pos = ((BlockHitResult) hit).getBlockPos();
        if (mc.level == null) return;
        BlockState state = mc.level.getBlockState(pos);

        if (!isLog(state)) {
            if (mc.level != null && targetBlockPos != null) {
                mc.level.destroyBlockProgress(player.getId(), targetBlockPos, -1);
            }
            targetBlockPos = null;
            breakingStartTime = 0;
            return;
        }

        if (!pos.equals(targetBlockPos)) {
            if (mc.level != null && targetBlockPos != null) {
                mc.level.destroyBlockProgress(player.getId(), targetBlockPos, -1);
            }
            targetBlockPos = pos;
            breakingStartTime = System.currentTimeMillis();
        } else {
            if (breakingStartTime > 0) {
                long elapsed = System.currentTimeMillis() - breakingStartTime;
                if (elapsed >= BREAK_DELAY_MS) {
                    // Succeeded
                    ModMessages.INSTANCE.sendToServer(new TreeChopPacket(targetBlockPos));
                    // Reset
                    if (mc.level != null) {
                        mc.level.destroyBlockProgress(player.getId(), targetBlockPos, -1);
                    }
                    targetBlockPos = null;
                    breakingStartTime = 0;
                } else {
                    // Update break progress (0-9)
                    int progress = (int) (elapsed * 10 / BREAK_DELAY_MS);
                    if (mc.level != null) {
                        mc.level.destroyBlockProgress(player.getId(), targetBlockPos, progress);
                    }
                }
            }
        }
    }

    @SubscribeEvent
    public static void onRenderGameOverlay(net.minecraftforge.client.event.RenderGameOverlayEvent.Post event) {
        if (event.getType() != net.minecraftforge.client.event.RenderGameOverlayEvent.ElementType.TEXT) return;

        Minecraft mc = Minecraft.getInstance();
        Player player = mc.player;
        if (player == null || mc.level == null) return;
        if (!player.isCreative() || !player.isShiftKeyDown()) return;

        // Check what we are looking at NOW
        HitResult hit = mc.hitResult;
        if (hit == null || hit.getType() != HitResult.Type.BLOCK) return;

        BlockPos pos = ((BlockHitResult) hit).getBlockPos();
        BlockState state = mc.level.getBlockState(pos);
        if (!isLog(state)) return;

        if (connectedLogsCache.isEmpty()) return;

        // Render count with block name
        String blockName = state.getBlock().getName().getString();
        String text = blockName + ": " + connectedLogsCache.size();

        int width = mc.font.width(text);
        int halfWidth = width / 2;
        int screenWidth = event.getWindow().getGuiScaledWidth();
        int screenHeight = event.getWindow().getGuiScaledHeight();

        // Position above crosshair
        int x = screenWidth / 2 - halfWidth;
        int y = screenHeight / 2 - 20;

        mc.font.draw(event.getMatrixStack(), text, x, y, 0xFF00FF00); // Green text
    }

    @SubscribeEvent
    public static void onHighlightBlock(DrawSelectionEvent.HighlightBlock event) {
        Minecraft mc = Minecraft.getInstance();
        Player player = mc.player;
        if (player == null || mc.level == null) return;

        if (!player.isCreative() || !player.isShiftKeyDown()) return;

        HitResult target = event.getTarget();
        if (target.getType() != HitResult.Type.BLOCK) return;

        BlockPos pos = ((BlockHitResult) target).getBlockPos();
        BlockState state = mc.level.getBlockState(pos);

        if (!isLog(state)) return;

        // Update cache
        if (!pos.equals(lastLookedAtPos) || System.currentTimeMillis() - lastCacheUpdate > 500) {
            if (mc.level != null) {
                connectedLogsCache = findConnectedLogs(mc.level, pos, state.getBlock());
                lastLookedAtPos = pos;
                lastCacheUpdate = System.currentTimeMillis();
            }
        }

        PoseStack poseStack = event.getPoseStack();
        VertexConsumer consumer = event.getMultiBufferSource().getBuffer(RenderType.lines());
        double camX = event.getCamera().getPosition().x;
        double camY = event.getCamera().getPosition().y;
        double camZ = event.getCamera().getPosition().z;

        // Render
        for (BlockPos logPos : connectedLogsCache) {
            if (mc.level != null && !mc.level.isLoaded(logPos)) continue;
            if (mc.level != null) {
                VoxelShape shape = mc.level.getBlockState(logPos).getShape(mc.level, logPos);
                if (shape.isEmpty()) continue;

                AABB aabb = shape.bounds().move(logPos);
                LevelRenderer.renderLineBox(
                        poseStack,
                        consumer,
                        aabb.minX - camX, aabb.minY - camY, aabb.minZ - camZ,
                        aabb.maxX - camX, aabb.maxY - camY, aabb.maxZ - camZ,
                        0.0f, 1.0f, 1.0f, 0.8f // Cyan/Aqua color
                );
            }
        }

        event.setCanceled(true);
    }

    @SubscribeEvent
    public static void onLeftClick(InputEvent.ClickInputEvent event) {
        if (!event.isAttack()) return;
        Minecraft mc = Minecraft.getInstance();
        if (mc.player == null || mc.level == null) return;

        if (mc.player.isCreative() && mc.player.isShiftKeyDown()) {
            HitResult hit = mc.hitResult;
            if (hit != null && hit.getType() == HitResult.Type.BLOCK) {
                BlockHitResult blockHit = (BlockHitResult) hit;
                BlockState state = mc.level.getBlockState(blockHit.getBlockPos());
                if (isLog(state)) {
                    event.setCanceled(true);
                    event.setSwingHand(true);
                }
            }
        }
    }

    private static boolean isLog(BlockState state) {
        return state.is(BlockTags.LOGS) || state.is(BlockTags.WARPED_STEMS) || state.is(BlockTags.CRIMSON_STEMS);
    }

    private static Set<BlockPos> findConnectedLogs(Level level, BlockPos startPos, Block targetBlock) {
        Set<BlockPos> visited = new HashSet<>();
        Queue<BlockPos> queue = new LinkedList<>();

        visited.add(startPos);
        queue.add(startPos);

        int count = 0;
        while (!queue.isEmpty() && count < MAX_LOGS) {
            BlockPos current = queue.poll();
            count++;

            // Check neighbors
            for (int dx = -1; dx <= 1; dx++) {
                for (int dy = -1; dy <= 1; dy++) {
                    for (int dz = -1; dz <= 1; dz++) {
                        if (dx == 0 && dy == 0 && dz == 0) continue;

                        BlockPos neighbor = current.offset(dx, dy, dz);
                        if (!visited.contains(neighbor) && level.isLoaded(neighbor)) {
                            BlockState neighborState = level.getBlockState(neighbor);
                            if (neighborState.getBlock() == targetBlock) {
                                visited.add(neighbor);
                                queue.add(neighbor);
                            }
                        }
                    }
                }
            }
        }
        return visited;
    }
}

package com.kingodogo.buildscape.client;

import net.minecraft.client.Camera;
import net.minecraft.client.Minecraft;
import net.minecraft.util.Mth;

public class ZoomHandler {

    private static boolean isZooming = false;
    private static float currentZoomLevel = 1.0f;
    private static float targetZoomLevel = 1.0f;

    private static final float BASE_ZOOM = 0.25f;
    private static final float MIN_ZOOM = 0.1f;
    private static final float MAX_ZOOM = 1.0f;
    private static final float SCROLL_SENSITIVITY = 0.05f;
    private static final float ZOOM_SPEED = 0.15f;

    private static final float CINEMATIC_SMOOTHING = 0.15f;

    private static float smoothedYaw = 0.0f;
    private static float smoothedPitch = 0.0f;
    private static boolean hasInitialRotation = false;

    public static void toggleZoom() {
        isZooming = !isZooming;
        if (!isZooming) {
            targetZoomLevel = MAX_ZOOM;
            hasInitialRotation = false;
        } else {
            targetZoomLevel = BASE_ZOOM;
        }
    }

    public static boolean isZooming() {
        return isZooming;
    }

    public static void handleScroll(double scrollDelta) {
        if (!isZooming) return;

        float zoomChange = (float) (-scrollDelta * SCROLL_SENSITIVITY);
        targetZoomLevel = Mth.clamp(
                targetZoomLevel + zoomChange,
                MIN_ZOOM,
                MAX_ZOOM
        );
    }

    public static void tick() {
        Minecraft mc = Minecraft.getInstance();
        if (mc.player == null) return;

        float zoomDiff = targetZoomLevel - currentZoomLevel;
        currentZoomLevel += zoomDiff * ZOOM_SPEED;

        if (Math.abs(zoomDiff) < 0.001f) {
            currentZoomLevel = targetZoomLevel;
        }
    }

    public static float getZoomLevel() {
        return currentZoomLevel;
    }

    public static float[] getSmoothedRotation(
            float currentYaw,
            float currentPitch
    ) {
        if (!isZooming || !hasInitialRotation) {
            smoothedYaw = currentYaw;
            smoothedPitch = currentPitch;
            hasInitialRotation = true;
            return new float[]{currentYaw, currentPitch};
        }

        float yawDiff = currentYaw - smoothedYaw;
        float pitchDiff = currentPitch - smoothedPitch;

        while (yawDiff > 180.0f) yawDiff -= 360.0f;
        while (yawDiff < -180.0f) yawDiff += 360.0f;

        smoothedYaw += yawDiff * CINEMATIC_SMOOTHING;
        smoothedPitch += pitchDiff * CINEMATIC_SMOOTHING;

        while (smoothedYaw > 180.0f) smoothedYaw -= 360.0f;
        while (smoothedYaw < -180.0f) smoothedYaw += 360.0f;

        smoothedPitch = Mth.clamp(smoothedPitch, -90.0f, 90.0f);

        return new float[]{smoothedYaw, smoothedPitch};
    }

    public static void reset() {
        isZooming = false;
        currentZoomLevel = MAX_ZOOM;
        targetZoomLevel = MAX_ZOOM;
        hasInitialRotation = false;
    }
}

package com.kingodogo.buildscape.config;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.kingodogo.buildscape.BuildScape;

import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/**
 * Configuration manager for equipped cosmetics.
 * Persists equipped cosmetics per player UUID.
 */
public class CosmeticsConfig {
    private static final Gson GSON = new GsonBuilder()
            .setPrettyPrinting()
            .create();

    // Color picker window position
    private Integer colorPickerX = null;
    private Integer colorPickerY = null;

    private static CosmeticsConfig INSTANCE;

    // Map of player UUID to their equipped cosmetics by slot
    // Slot: 0=head, 1=chest, 2=legs, 3=feet
    private Map<String, Map<Integer, String>> playerCosmetics = new HashMap<>();

    // Map of player UUID to cosmetic colors (cosmeticId -> hex color string)
    // Stores custom colors for particle trails and other colorable cosmetics
    private Map<String, Map<String, String>> playerCosmeticColors = new HashMap<>();

    private CosmeticsConfig() {
        load();
    }

    public static CosmeticsConfig get() {
        if (INSTANCE == null) {
            INSTANCE = new CosmeticsConfig();
        }
        return INSTANCE;
    }

    private File getConfigFile() {
        String configPath = Paths.get("config", BuildScape.MODID).toString();
        File dir = new File(configPath);
        if (!dir.exists()) {
            dir.mkdirs();
        }
        return new File(dir, "equipped-cosmetics.json");
    }

    /**
     * Load equipped cosmetics from config file.
     */
    public void load() {
        File file = getConfigFile();
        if (!file.exists()) {
            playerCosmetics = new HashMap<>();
            return;
        }

        try (FileReader reader = new FileReader(file)) {
            @SuppressWarnings("unchecked")
            Map<String, Object> loaded = GSON.fromJson(reader, Map.class);
            if (loaded != null) {
                playerCosmetics = new HashMap<>();
                playerCosmeticColors = new HashMap<>();
                for (Map.Entry<String, Object> entry : loaded.entrySet()) {
                    String playerUuid = entry.getKey();
                    Object value = entry.getValue();
                    if (value instanceof Map) {
                        @SuppressWarnings("unchecked")
                        Map<String, Object> playerData = (Map<String, Object>) value;

                        // Load equipped cosmetics by slot
                        Object cosmeticsObj = playerData.get("cosmetics");
                        if (cosmeticsObj instanceof Map) {
                            @SuppressWarnings("unchecked")
                            Map<String, Object> slotMap = (Map<String, Object>) cosmeticsObj;
                            Map<Integer, String> cosmeticsBySlot = new HashMap<>();
                            for (Map.Entry<String, Object> slotEntry : slotMap.entrySet()) {
                                try {
                                    int slot = Integer.parseInt(slotEntry.getKey());
                                    if (slotEntry.getValue() instanceof String) {
                                        cosmeticsBySlot.put(slot, (String) slotEntry.getValue());
                                    }
                                } catch (NumberFormatException e) {
                                    // Skip invalid slot
                                }
                            }
                            playerCosmetics.put(playerUuid, cosmeticsBySlot);
                        }

                        // Load cosmetic colors
                        Object colorsObj = playerData.get("colors");
                        if (colorsObj instanceof Map) {
                            @SuppressWarnings("unchecked")
                            Map<String, Object> colorMap = (Map<String, Object>) colorsObj;
                            Map<String, String> cosmeticColors = new HashMap<>();
                            for (Map.Entry<String, Object> colorEntry : colorMap.entrySet()) {
                                if (colorEntry.getValue() instanceof String) {
                                    cosmeticColors.put(colorEntry.getKey(), (String) colorEntry.getValue());
                                }
                            }
                            playerCosmeticColors.put(playerUuid, cosmeticColors);
                            playerCosmeticColors.put(playerUuid, cosmeticColors);
                        }

                        // Load color picker position
                        if (playerData.containsKey("colorPickerX")
                                && playerData.get("colorPickerX") instanceof Number) {
                            colorPickerX = ((Number) playerData.get("colorPickerX")).intValue();
                        }
                        if (playerData.containsKey("colorPickerY")
                                && playerData.get("colorPickerY") instanceof Number) {
                            colorPickerY = ((Number) playerData.get("colorPickerY")).intValue();
                        }
                    } else {
                        // Legacy format: just slot map
                        @SuppressWarnings("unchecked")
                        Map<String, Object> slotMap = (Map<String, Object>) value;
                        Map<Integer, String> cosmeticsBySlot = new HashMap<>();
                        for (Map.Entry<String, Object> slotEntry : slotMap.entrySet()) {
                            try {
                                int slot = Integer.parseInt(slotEntry.getKey());
                                if (slotEntry.getValue() instanceof String) {
                                    cosmeticsBySlot.put(slot, (String) slotEntry.getValue());
                                }
                            } catch (NumberFormatException e) {
                                // Skip invalid slot
                            }
                        }
                        playerCosmetics.put(playerUuid, cosmeticsBySlot);
                    }
                }
            }
        } catch (Exception e) {
            BuildScape.getLogger().error("Failed to load cosmetics config: " + e.getMessage());
            playerCosmetics = new HashMap<>();
            playerCosmeticColors = new HashMap<>();
        }
    }

    /**
     * Save equipped cosmetics to config file.
     */
    public void save() {
        File file = getConfigFile();
        try {
            File parentDir = file.getParentFile();
            if (parentDir != null && !parentDir.exists()) {
                parentDir.mkdirs();
            }

            // Combine cosmetics and colors into a single structure
            Map<String, Object> combined = new HashMap<>();
            for (String uuid : playerCosmetics.keySet()) {
                Map<String, Object> playerData = new HashMap<>();
                playerData.put("cosmetics", playerCosmetics.get(uuid));
                if (playerCosmeticColors.containsKey(uuid)) {
                    playerData.put("colors", playerCosmeticColors.get(uuid));
                }
                combined.put(uuid, playerData);
            }

            try (FileWriter writer = new FileWriter(file)) {
                GSON.toJson(combined, writer);
                writer.flush();
            }

            BuildScape.getLogger().debug("Saved cosmetics config to " + file.getAbsolutePath());
            // Add global settings
            Map<String, Object> globalSettings = (Map<String, Object>) combined.computeIfAbsent("global_settings",
                    k -> new HashMap<>());
            if (colorPickerX != null)
                globalSettings.put("colorPickerX", colorPickerX);
            if (colorPickerY != null)
                globalSettings.put("colorPickerY", colorPickerY);

        } catch (Exception e) {
            BuildScape.getLogger().error("Failed to save cosmetics config: " + e.getMessage());
        }
    }

    /**
     * Get equipped cosmetics for a player.
     * Fallback to "global" if UUID not found.
     */
    public Map<Integer, String> getEquippedCosmetics(UUID playerUuid) {
        if (playerUuid == null) {
            return playerCosmetics.getOrDefault("global", new HashMap<>());
        }
        String uuidStr = playerUuid.toString();
        Map<Integer, String> cosmetics = playerCosmetics.get(uuidStr);
        if (cosmetics == null || cosmetics.isEmpty()) {
            // Fallback to global profile
            cosmetics = playerCosmetics.get("global");
        }
        return cosmetics != null ? new HashMap<>(cosmetics) : new HashMap<>();
    }

    /**
     * Set equipped cosmetics for a player.
     * Also updates "global" profile.
     */
    public void setEquippedCosmetics(UUID playerUuid, Map<Integer, String> cosmeticsBySlot) {
        if (playerUuid != null) {
            String uuidStr = playerUuid.toString();
            playerCosmetics.put(uuidStr, new HashMap<>(cosmeticsBySlot));
        }
        // Always update global profile for persistence across different UUIDs/SP
        playerCosmetics.put("global", new HashMap<>(cosmeticsBySlot));
        save();
    }

    /**
     * Equip a cosmetic to a specific slot for a player.
     * Also updates "global" profile.
     */
    public void equipCosmetic(UUID playerUuid, int slotIndex, String cosmeticId) {
        if (playerUuid != null) {
            String uuidStr = playerUuid.toString();
            Map<Integer, String> cosmetics = playerCosmetics.computeIfAbsent(uuidStr, k -> new HashMap<>());
            cosmetics.values().remove(cosmeticId);
            cosmetics.remove(slotIndex);
            if (cosmeticId != null && !cosmeticId.isEmpty()) {
                cosmetics.put(slotIndex, cosmeticId);
            }
        }

        // Update global profile
        Map<Integer, String> globalCosmetics = playerCosmetics.computeIfAbsent("global", k -> new HashMap<>());
        globalCosmetics.values().remove(cosmeticId);
        globalCosmetics.remove(slotIndex);
        if (cosmeticId != null && !cosmeticId.isEmpty()) {
            globalCosmetics.put(slotIndex, cosmeticId);
        }

        save();
    }

    /**
     * Unequip cosmetic from a specific slot for a player.
     * Also updates "global" profile.
     */
    public void unequipCosmetic(UUID playerUuid, int slotIndex) {
        if (playerUuid != null) {
            String uuidStr = playerUuid.toString();
            Map<Integer, String> cosmetics = playerCosmetics.get(uuidStr);
            if (cosmetics != null) {
                cosmetics.remove(slotIndex);
                if (cosmetics.isEmpty()) {
                    playerCosmetics.remove(uuidStr);
                }
            }
        }

        // Update global profile
        Map<Integer, String> globalCosmetics = playerCosmetics.get("global");
        if (globalCosmetics != null) {
            globalCosmetics.remove(slotIndex);
            if (globalCosmetics.isEmpty()) {
                playerCosmetics.remove("global");
            }
        }

        save();
    }

    /**
     * Get color for a cosmetic (hex string like "#FF0000").
     * Fallback to "global" if UUID not found.
     */
    public String getCosmeticColor(UUID playerUuid, String cosmeticId) {
        if (cosmeticId == null)
            return null;

        if (playerUuid != null) {
            String uuidStr = playerUuid.toString();
            Map<String, String> colors = playerCosmeticColors.get(uuidStr);
            if (colors != null && colors.containsKey(cosmeticId)) {
                return colors.get(cosmeticId);
            }
        }

        // Fallback to global profile
        Map<String, String> globalColors = playerCosmeticColors.get("global");
        if (globalColors != null) {
            return globalColors.get(cosmeticId);
        }

        return null;
    }

    /**
     * Set color for a cosmetic (hex string like "#FF0000").
     * Also updates "global" profile.
     */
    public void setCosmeticColor(UUID playerUuid, String cosmeticId, String hexColor) {
        if (cosmeticId == null)
            return;

        if (playerUuid != null) {
            String uuidStr = playerUuid.toString();
            Map<String, String> colors = playerCosmeticColors.computeIfAbsent(uuidStr, k -> new HashMap<>());
            if (hexColor != null && !hexColor.isEmpty()) {
                colors.put(cosmeticId, hexColor);
            } else {
                colors.remove(cosmeticId);
            }
        }

        // Update global profile
        Map<String, String> globalColors = playerCosmeticColors.computeIfAbsent("global", k -> new HashMap<>());
        if (hexColor != null && !hexColor.isEmpty()) {
            globalColors.put(cosmeticId, hexColor);
        } else {
            globalColors.remove(cosmeticId);
        }

        save();
    }

    /**
     * Check if a cosmetic supports color customization.
     */
    public boolean supportsColor(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return false;
        }
        String idLower = cosmeticId.toLowerCase();
        // Particle trails support colors
        return idLower.contains("particle") && idLower.contains("trail");
    }

    /**
     * Get saved X position of color picker window.
     */
    public Integer getColorPickerX() {
        return colorPickerX;
    }

    /**
     * Get saved Y position of color picker window.
     */
    public Integer getColorPickerY() {
        return colorPickerY;
    }

    /**
     * Set and save color picker window position.
     */
    public void setColorPickerPosition(int x, int y) {
        this.colorPickerX = x;
        this.colorPickerY = y;
        save();
    }

    /**
     * Clear saved color picker window position.
     */
    public void clearColorPickerPosition() {
        this.colorPickerX = null;
        this.colorPickerY = null;
        save();
    }
}

package com.kingodogo.buildscape.config;

import com.google.gson.annotations.SerializedName;
import java.util.HashMap;
import java.util.Map;

/**
 * Data class for storing GUI element configuration.
 * Stores position, size, and scale information for GUI elements.
 */
public class GuiConfigData {
    
    /**
     * Configuration for a single GUI element/widget.
     */
    public static class ElementConfig {
        @SerializedName("x")
        public int x = 0;
        
        @SerializedName("y")
        public int y = 0;
        
        @SerializedName("width")
        public int width = 100;
        
        @SerializedName("height")
        public int height = 20;
        
        @SerializedName("scale")
        public float scale = 1.0f;
        
        @SerializedName("visible")
        public boolean visible = true;
        
        /**
         * Percentage-based positioning (0.0 to 1.0, e.g., 0.2 = 20%)
         * If set, these override x/y/width/height when calculating positions
         */
        @SerializedName("percentX")
        public Double percentX = null;
        
        @SerializedName("percentY")
        public Double percentY = null;
        
        @SerializedName("percentWidth")
        public Double percentWidth = null;
        
        @SerializedName("percentHeight")
        public Double percentHeight = null;
        
        /**
         * Additional custom properties that can be stored for extensibility
         */
        @SerializedName("properties")
        public Map<String, Object> properties = new HashMap<>();
        
        public ElementConfig() {}
        
        public ElementConfig(int x, int y, int width, int height) {
            this.x = x;
            this.y = y;
            this.width = width;
            this.height = height;
        }
        
        public ElementConfig(int x, int y, int width, int height, float scale) {
            this(x, y, width, height);
            this.scale = scale;
        }
        
        /**
         * Copy constructor
         */
        public ElementConfig(ElementConfig other) {
            this.x = other.x;
            this.y = other.y;
            this.width = other.width;
            this.height = other.height;
            this.scale = other.scale;
            this.visible = other.visible;
            this.properties = new HashMap<>(other.properties);
        }
    }
    
    /**
     * Screen-level configuration
     */
    @SerializedName("screen")
    public ScreenConfig screen = new ScreenConfig();
    
    /**
     * Map of element IDs to their configurations
     * Element IDs are widget names or identifiers like "itemSelectionWidget", "searchBox", etc.
     */
    @SerializedName("elements")
    public Map<String, ElementConfig> elements = new HashMap<>();
    
    /**
     * Screen-level configuration
     */
    public static class ScreenConfig {
        @SerializedName("width")
        public int width = 0; // 0 means use default/screen width
        
        @SerializedName("height")
        public int height = 0; // 0 means use default/screen height
        
        @SerializedName("scale")
        public float scale = 1.0f;
        
        @SerializedName("contentX")
        public int contentX = 0;
        
        @SerializedName("contentY")
        public int contentY = 0;
        
        @SerializedName("contentWidth")
        public int contentWidth = 0; // 0 means use default
        
        @SerializedName("contentHeight")
        public int contentHeight = 0; // 0 means use default
    }
    
    public GuiConfigData() {}
    
    /**
     * Get configuration for an element, creating a default if it doesn't exist
     */
    public ElementConfig getElementConfig(String elementId, int defaultX, int defaultY, int defaultWidth, int defaultHeight) {
        return elements.computeIfAbsent(elementId, k -> new ElementConfig(defaultX, defaultY, defaultWidth, defaultHeight));
    }
    
    /**
     * Get configuration for an element, returning null if it doesn't exist
     */
    public ElementConfig getElementConfig(String elementId) {
        return elements.get(elementId);
    }
    
    /**
     * Set configuration for an element
     */
    public void setElementConfig(String elementId, ElementConfig config) {
        elements.put(elementId, config);
    }
    
    /**
     * Remove configuration for an element
     */
    public void removeElementConfig(String elementId) {
        elements.remove(elementId);
    }
    
    /**
     * Check if an element configuration exists
     */
    public boolean hasElementConfig(String elementId) {
        return elements.containsKey(elementId);
    }
}

package com.kingodogo.buildscape.config;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.kingodogo.buildscape.BuildScape;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.nio.file.Paths;
import java.util.HashMap;
import java.util.Map;

/**
 * Manager for loading and saving GUI configuration files.
 * Handles JSON serialization/deserialization for GUI layouts.
 */
public class GuiConfigManager {
    private static final Gson GSON = new GsonBuilder()
        .setPrettyPrinting()
        .serializeNulls()
        .create();
    
    private static final Map<String, GuiConfigData> CACHE = new HashMap<>();
    
    /**
     * Get the config directory for GUI configs
     */
    private File getConfigDir() {
        String configPath = Paths.get("config", BuildScape.MODID).toString();
        File dir = new File(configPath);
        if (!dir.exists()) {
            dir.mkdirs();
        }
        return dir;
    }
    
    /**
     * Get the file path for a tab's GUI config
     * @param tabName The name of the tab (e.g., "PillarItems", "PillarParticles")
     * @return The file for the GUI config
     */
    private File getGuiConfigFile(String tabName) {
        String fileName = sanitizeFileName(tabName) + "-GUI.json";
        return new File(getConfigDir(), fileName);
    }
    
    /**
     * Sanitize a tab name to be a valid file name
     */
    private String sanitizeFileName(String tabName) {
        // Replace invalid characters with underscores
        return tabName.replaceAll("[^a-zA-Z0-9-_]", "_");
    }
    
    /**
     * Load GUI configuration for a tab
     * @param tabName The name of the tab
     * @return The GUI configuration data, or a new empty config if file doesn't exist
     */
    public GuiConfigData loadConfig(String tabName) {
        String cacheKey = tabName.toLowerCase();
        
        // Return cached config if available
        if (CACHE.containsKey(cacheKey)) {
            return CACHE.get(cacheKey);
        }
        
        File file = getGuiConfigFile(tabName);
        GuiConfigData config = new GuiConfigData();
        
        if (file.exists()) {
            try (FileReader reader = new FileReader(file)) {
                config = GSON.fromJson(reader, GuiConfigData.class);
                if (config == null) {
                    config = new GuiConfigData();
                }
                // Ensure maps are initialized
                if (config.elements == null) {
                    config.elements = new java.util.HashMap<>();
                }
                if (config.screen == null) {
                    config.screen = new GuiConfigData.ScreenConfig();
                }
            } catch (Exception e) {
                BuildScape.getLogger().error("Failed to load GUI config for tab '{}': {}", tabName, e.getMessage());
                e.printStackTrace();
                config = new GuiConfigData();
            }
        }
        
        // Cache the config
        CACHE.put(cacheKey, config);
        return config;
    }
    
    /**
     * Save GUI configuration for a tab
     * @param tabName The name of the tab
     * @param config The GUI configuration data to save
     */
    public void saveConfig(String tabName, GuiConfigData config) {
        if (config == null) {
            BuildScape.getLogger().warn("Attempted to save null GUI config for tab '{}'", tabName);
            return;
        }
        
        File file = getGuiConfigFile(tabName);
        try {
            File parentDir = file.getParentFile();
            if (parentDir != null && !parentDir.exists()) {
                parentDir.mkdirs();
            }
            
            try (FileWriter writer = new FileWriter(file)) {
                GSON.toJson(config, writer);
                writer.flush();
            }
            
            // Update cache
            String cacheKey = tabName.toLowerCase();
            CACHE.put(cacheKey, config);
            
            BuildScape.getLogger().debug("Saved GUI config for tab '{}' to {}", tabName, file.getAbsolutePath());
        } catch (Exception e) {
            BuildScape.getLogger().error("Failed to save GUI config for tab '{}': {}", tabName, e.getMessage());
            e.printStackTrace();
        }
    }
    
    /**
     * Clear the cache for a specific tab (useful when reloading)
     * @param tabName The name of the tab
     */
    public void clearCache(String tabName) {
        CACHE.remove(tabName.toLowerCase());
    }
    
    /**
     * Clear all cached configs
     */
    public void clearAllCache() {
        CACHE.clear();
    }
    
    /**
     * Get the singleton instance
     */
    private static GuiConfigManager INSTANCE;
    
    public static GuiConfigManager get() {
        if (INSTANCE == null) {
            INSTANCE = new GuiConfigManager();
        }
        return INSTANCE;
    }
}

package com.kingodogo.buildscape.config;

import com.google.gson.Gson;
import com.google.gson.GsonBuilder;
import com.google.gson.reflect.TypeToken;
import net.minecraft.core.BlockPos;
import net.minecraft.server.MinecraftServer;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.storage.LevelResource;
import net.minecraftforge.server.ServerLifecycleHooks;

import java.io.*;
import java.lang.reflect.Type;
import java.nio.channels.FileChannel;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

public class PillarIdManager {

    private static final Gson GSON = new GsonBuilder()
            .setPrettyPrinting()
            .create();
    private static final String FILE_NAME = "pillar-ids.dat";
    private static final String BACKUP_FILE_NAME = "pillar-ids.bak.dat";
    private static final String FOLDER_NAME = "buildscape";
    private static PillarIdManager INSTANCE;

    private final Map<String, PillarData> pillarData = new ConcurrentHashMap<>();

    private long lastLoadedTime = 0L;
    private long lastFileSize = 0L;

    private boolean hasLoaded = false;
    private boolean hadColorsOnLoad = false; // Track if we had colors when we loaded
    
    private static boolean recoveryScheduled = false;
    private static long recoveryScheduledTime = 0L;
    private static final long RECOVERY_DELAY_MS = 5000; // 5 seconds after world load
    private static boolean recoveryInProgress = false; // Flag to prevent saving during recovery

    private static long worldLoadStartTime = 0L;
    private static final long MIN_WORLD_LOAD_TIME_MS = 15000;

    private static File cachedWorldSaveDir = null;

    public static final String PREFIX_MOSSY = "M";
    public static final String PREFIX_STONE = "S";
    public static final String PREFIX_DEEPSLATE = "D";
    public static final String PREFIX_QUARTZ = "Q";

    public static class PillarData {

        public String id;
        public List<String> dyeColors = new ArrayList<>();
        public String dimension;
        public int x, y, z;
        public long createdTime;
        public long modifiedTime;
        
        // Per-pillar config options (optional, defaults to global config if not set)
        public Boolean use_pattern = null; // null means use global config
        public String pattern = null; // null means use global config
        public Double pattern_speed = null;
        public Double pattern_spread = null;
        public Double pattern_intensity = null;
        public Integer max_particle_color = null; // Max number of colors for this pillar (1-5)

        public PillarData() {
        }

        public PillarData(String id, String dimension, BlockPos pos) {
            this.id = id;
            this.dimension = dimension;
            this.x = pos.getX();
            this.y = pos.getY();
            this.z = pos.getZ();
            this.createdTime = System.currentTimeMillis();
            this.modifiedTime = this.createdTime;
        }

        public BlockPos getBlockPos() {
            return new BlockPos(x, y, z);
        }

        public boolean addColor(String colorCode) {
            if (dyeColors.size() >= 5) {
                return false;
            }
            dyeColors.add(colorCode.toUpperCase());
            modifiedTime = System.currentTimeMillis();
            return true;
        }

        public void clearColors() {
            dyeColors.clear();
            modifiedTime = System.currentTimeMillis();
        }

        public List<String> getColors() {
            return Collections.unmodifiableList(dyeColors);
        }

        public boolean hasColors() {
            return !dyeColors.isEmpty();
        }

        public int getColorCount() {
            return dyeColors.size();
        }
    }

    public static PillarIdManager get() {
        if (INSTANCE == null) {
            INSTANCE = new PillarIdManager();
        }
        return INSTANCE;
    }

    public boolean hasLoaded() {
        return hasLoaded;
    }

    private File getDataDir() {
        try {
            if (cachedWorldSaveDir != null && cachedWorldSaveDir.exists()) {
                return cachedWorldSaveDir;
            }

            if (com.kingodogo.buildscape.BuildScape.isServerFullyInitialized()) {
                try {
                    MinecraftServer server = ServerLifecycleHooks.getCurrentServer();
                    if (
                            server != null &&
                                    server.isRunning() &&
                                    server.getPlayerList().getPlayerCount() > 0
                    ) {
                        Path worldPath = server.getWorldPath(LevelResource.ROOT);
                        if (worldPath != null) {
                            File buildscapeDir = worldPath.resolve(FOLDER_NAME).toFile();
                            if (!buildscapeDir.exists()) {
                                buildscapeDir.mkdirs();
                            }
                            cachedWorldSaveDir = buildscapeDir;
                            return buildscapeDir;
                        }
                    }
                } catch (Exception e) {
                }
            }

            String configPath = Paths.get(
                    "config",
                    "buildscape",
                    "pillar"
            ).toString();
            File dir = new File(configPath);
            if (!dir.exists()) {
                dir.mkdirs();
            }
            return dir;
        } catch (Throwable t) {
            return new File(".");
        }
    }

    private void updateCachedWorldDir() {
        try {
            if (!com.kingodogo.buildscape.BuildScape.isServerFullyInitialized()) {
                return;
            }

            MinecraftServer server = ServerLifecycleHooks.getCurrentServer();
            if (
                    server != null &&
                            server.isRunning() &&
                            server.getPlayerList().getPlayerCount() > 0
            ) {
                try {
                    Path worldPath = server.getWorldPath(LevelResource.ROOT);
                    if (worldPath != null) {
                        File buildscapeDir = worldPath.resolve(FOLDER_NAME).toFile();
                        if (!buildscapeDir.exists()) {
                            buildscapeDir.mkdirs();
                        }
                        cachedWorldSaveDir = buildscapeDir;
                    }
                } catch (Exception e) {
                }
            }
        } catch (Throwable t) {
        }
    }

    private File getDataFile() {
        return new File(getDataDir(), FILE_NAME);
    }
    
    private File getBackupDataFile() {
        return new File(getDataDir(), BACKUP_FILE_NAME);
    }

    /**
     * Reset world cache directory only - does NOT clear pillar data.
     * Called on world unload/player logout to reset cache, but preserves data.
     */
    public static void resetWorldCache() {
        System.out.println("BuildScape: resetWorldCache() called - preserving pillar data (not clearing)");
        cachedWorldSaveDir = null;
        worldLoadStartTime = System.currentTimeMillis();
        recoveryScheduled = false;
        recoveryScheduledTime = 0L;
        
        // IMPORTANT: Don't clear pillarData or reset hasLoaded here!
        // Data should persist through world switches
        // Only reset the cache directory, not the actual data
    }
    
    /**
     * Full reset - clears all data. Only called on server stop.
     */
    public static void fullReset() {
        System.out.println("BuildScape: fullReset() called - clearing all pillar data from memory");
        cachedWorldSaveDir = null;
        worldLoadStartTime = System.currentTimeMillis();
        recoveryScheduled = false;
        recoveryScheduledTime = 0L;
        
        if (INSTANCE != null) {
            int dataCount = INSTANCE.pillarData.size();
            INSTANCE.pillarData.clear();
            INSTANCE.lastLoadedTime = 0L;
            INSTANCE.lastFileSize = 0L;
            INSTANCE.hasLoaded = false;
            INSTANCE.hadColorsOnLoad = false;
            INSTANCE.fileWasDeleted = false;
            System.out.println("BuildScape: Cleared " + dataCount + " pillar entries from memory");
        }
    }
    
    /**
     * Schedule recovery to run after world load.
     * Recovery will run automatically after RECOVERY_DELAY_MS.
     */
    public static void scheduleRecoveryAfterLoad() {
        recoveryScheduled = true;
        recoveryScheduledTime = System.currentTimeMillis();
        System.out.println("BuildScape: Scheduled pillar recovery to run after " + (RECOVERY_DELAY_MS / 1000) + " seconds");
    }
    
    /**
     * Check if scheduled recovery should run and execute it.
     * Called from server tick event.
     */
    public static void checkAndRunScheduledRecovery() {
        if (!recoveryScheduled) {
            return;
        }
        
        long elapsed = System.currentTimeMillis() - recoveryScheduledTime;
        if (elapsed < RECOVERY_DELAY_MS) {
            return;
        }
        
        recoveryScheduled = false;
        
        MinecraftServer server = ServerLifecycleHooks.getCurrentServer();
        if (server == null || !server.isRunning()) {
            System.out.println("BuildScape: Scheduled recovery skipped - server not running");
            return;
        }
        
        PillarIdManager manager = get();
        if (manager == null) {
            System.out.println("BuildScape: Scheduled recovery skipped - manager is null");
            return;
        }
        
        if (!manager.hasLoaded()) {
            System.out.println("BuildScape: Scheduled recovery skipped - manager not loaded yet");
            return;
        }
        
        System.out.println("BuildScape: Running scheduled pillar recovery (preserving colors)...");
        manager.recoverPillarsFromWorld(server, false); // false = don't clear colors
    }

    private static boolean isWorldReadyForRecovery() {
        if (worldLoadStartTime == 0L) {
            return true;
        }
        long elapsed = System.currentTimeMillis() - worldLoadStartTime;
        return elapsed >= MIN_WORLD_LOAD_TIME_MS;
    }

    public static String getVariantPrefix(Level level, BlockPos pos) {
        if (level == null || pos == null) return PREFIX_STONE;

        if (
                !level.isClientSide &&
                        !com.kingodogo.buildscape.BuildScape.isServerFullyInitialized()
        ) {
            return PREFIX_STONE;
        }

        if (!level.hasChunkAt(pos)) {
            return PREFIX_STONE;
        }

        try {
            if (!level.isClientSide) {
                net.minecraft.world.level.chunk.ChunkAccess chunk = level.getChunk(pos);
                if (!(chunk instanceof net.minecraft.world.level.chunk.LevelChunk)) {
                    return PREFIX_STONE;
                }
                if (
                        !chunk
                                .getStatus()
                                .isOrAfter(net.minecraft.world.level.chunk.ChunkStatus.FULL)
                ) {
                    return PREFIX_STONE;
                }
            }
        } catch (Exception e) {
            return PREFIX_STONE;
        }

        try {
            BlockState state = level.getBlockState(pos);
            Block block = state.getBlock();
            String blockName =
                    net.minecraftforge.registries.ForgeRegistries.BLOCKS.getKey(
                            block
                    ).getPath();

            if (blockName.contains("mossy")) {
                return PREFIX_MOSSY;
            } else if (blockName.contains("deepslate")) {
                return PREFIX_DEEPSLATE;
            } else if (blockName.contains("quartz")) {
                return PREFIX_QUARTZ;
            } else {
                return PREFIX_STONE;
            }
        } catch (Exception e) {
            return PREFIX_STONE;
        }
    }

    private static final String ALPHANUMERIC =
            "0123456789abcdefghijklmnopqrstuvwxyz";

    public String generatePillarId(String variantPrefix) {
        if (variantPrefix == null || variantPrefix.isEmpty()) {
            variantPrefix = PREFIX_STONE;
        }

        String prefix = variantPrefix + "-P";
        Random random = new Random();

        for (int attempt = 0; attempt < 50; attempt++) {
            int num = random.nextInt(9999) + 1;
            String id = prefix + String.format("%04d", num);
            if (!pillarData.containsKey(id)) {
                return id;
            }
        }

        for (int num = 1; num <= 9999; num++) {
            String id = prefix + String.format("%04d", num);
            if (!pillarData.containsKey(id)) {
                return id;
            }
        }

        for (int attempt = 0; attempt < 100; attempt++) {
            char c1 = (char) ('a' + random.nextInt(26));
            char c2 = ALPHANUMERIC.charAt(random.nextInt(36));
            char c3 = ALPHANUMERIC.charAt(random.nextInt(36));
            char c4 = ALPHANUMERIC.charAt(random.nextInt(36));
            String id = prefix + "" + c1 + c2 + c3 + c4;
            if (!pillarData.containsKey(id)) {
                return id;
            }
        }

        for (int i = 10; i < 36; i++) {
            char c1 = ALPHANUMERIC.charAt(i);
            for (int j = 0; j < 36; j++) {
                for (int k = 0; k < 36; k++) {
                    for (int l = 0; l < 36; l++) {
                        String id =
                                prefix +
                                        "" +
                                        c1 +
                                        ALPHANUMERIC.charAt(j) +
                                        ALPHANUMERIC.charAt(k) +
                                        ALPHANUMERIC.charAt(l);
                        if (!pillarData.containsKey(id)) {
                            return id;
                        }
                    }
                }
            }
        }

        return prefix + Long.toString(System.currentTimeMillis(), 36);
    }

