    public List<Preset> getPresets() {
        List<Preset> presetList = new ArrayList<>();
        // Always include default first
        if (presets.containsKey("default")) {
            presetList.add(presets.get("default"));
        }
        // Include unnamed preset if it exists (for display)
        if (presets.containsKey(UNNAMED_PRESET_KEY)) {
            presetList.add(presets.get(UNNAMED_PRESET_KEY));
        }
        // Then add custom presets (up to 5 total including default)
        // Sort by key to maintain consistent order
        List<String> sortedKeys = new ArrayList<>(presets.keySet());
        sortedKeys.remove("default");
        sortedKeys.remove(UNNAMED_PRESET_KEY);
        sortedKeys.sort(String::compareTo);

        int customCount = 0;
        for (String key : sortedKeys) {
            if (customCount < MAX_PRESETS - 1) {
                presetList.add(presets.get(key));
                customCount++;
            }
        }
        return presetList;
    }

    public List<String> getPresetKeys() {
        List<String> keys = new ArrayList<>();
        if (presets.containsKey("default")) {
            keys.add("default");
        }
        // Include unnamed preset if it exists
        if (presets.containsKey(UNNAMED_PRESET_KEY)) {
            keys.add(UNNAMED_PRESET_KEY);
        }
        // Add custom preset keys in sorted order
        List<String> sortedKeys = new ArrayList<>(presets.keySet());
        sortedKeys.remove("default");
        sortedKeys.remove(UNNAMED_PRESET_KEY);
        sortedKeys.sort(String::compareTo);

        int customCount = 0;
        for (String key : sortedKeys) {
            if (customCount < MAX_PRESETS - 1) {
                keys.add(key);
                customCount++;
            }
        }
        return keys;
    }

    public boolean savePreset(String key, String name, Set<String> items) {
        if (key.equals("default") || key.equals(UNNAMED_PRESET_KEY)) {
            return false; // Can't modify default or unnamed
        }

        // Check if we're at max presets (exclude default and unnamed from count)
        int customPresetCount = 0;
        for (String k : presets.keySet()) {
            if (!k.equals("default") && !k.equals(UNNAMED_PRESET_KEY)) {
                customPresetCount++;
            }
        }

        // If this is a new preset and we're at max, don't allow
        if (!presets.containsKey(key) && customPresetCount >= MAX_PRESETS - 1) {
            return false;
        }

        presets.put(key, new Preset(name, items));
        save();
        return true;
    }

    public Preset getPreset(String key) {
        return presets.get(key);
    }

    public static class Preset {
        public String name;
        public Set<String> items;

        public Preset() {
            this.name = "";
            this.items = new HashSet<>();
        }

        public Preset(String name, Set<String> items) {
            this.name = name;
            this.items = new HashSet<>(items);
        }
    }

    public boolean deletePreset(String key) {
        if (key.equals("default") || key.equals(UNNAMED_PRESET_KEY)) {
            return false; // Can't delete default or unnamed
        }
        if (presets.remove(key) != null) {
            save();
            return true;
        }
        return false;
    }

    public void applyPreset(String key) {
        Preset preset = presets.get(key);
        if (preset != null) {
            PillarParticleConfig config = PillarParticleConfig.get();
            config.items.clear();
            config.items.addAll(preset.items);
            config.saveItems();
            if (!key.equals(UNNAMED_PRESET_KEY)) {
                lastAppliedPreset = key; // Track last applied preset (but not unnamed)
                save(); // Save the last applied preset info
            }
        }
    }

    public String getLastAppliedPreset() {
        return lastAppliedPreset;
    }

    public void saveUnnamedPreset(Set<String> items) {
        // Save current items as unnamed preset (unsaved changes)
        presets.put(UNNAMED_PRESET_KEY, new Preset("", items));
        // Don't save to file - this is temporary
    }

    public Preset getUnnamedPreset() {
        return presets.get(UNNAMED_PRESET_KEY);
    }

    public boolean hasUnnamedPreset() {
        return presets.containsKey(UNNAMED_PRESET_KEY);
    }

    public void clearUnnamedPreset() {
        presets.remove(UNNAMED_PRESET_KEY);
    }

    public void autoApplyOnLoad() {
        // Auto-apply unnamed preset if it exists, otherwise apply last applied preset
        if (hasUnnamedPreset()) {
            applyPreset(UNNAMED_PRESET_KEY);
        } else if (lastAppliedPreset != null && presets.containsKey(lastAppliedPreset)) {
            applyPreset(lastAppliedPreset);
        } else {
            // First time - apply default
            applyPreset("default");
            lastAppliedPreset = "default";
            save();
        }
    }

    public String generatePresetKey() {
        // Generate a unique key for a new preset
        int index = 1;
        while (presets.containsKey("preset_" + index)) {
            index++;
        }
        return "preset_" + index;
    }
}

package com.kingodogo.buildscape.cosmetics;

import com.kingodogo.buildscape.BuildScape;

import java.util.*;

/**
 * Manages cosmetic registration and provides access to all available cosmetics.
 * Automatically registers built-in cosmetics and provides dev access.
 */
public class CosmeticManager {
    private static final CosmeticManager INSTANCE = new CosmeticManager();

    // All registered cosmetics
    private final Set<String> allCosmetics = new HashSet<>();

    // Cosmetic metadata (name, description, tier, etc.)
    private final Map<String, CosmeticMetadata> cosmeticMetadata = new HashMap<>();

    // Particle shape mapping (cosmeticId -> shape type)
    private final Map<String, String> particleShapes = new HashMap<>();

    // Dev username for development access
    private static final String DEV_USERNAME = "Dev";

    private CosmeticManager() {
        registerBuiltInCosmetics();
    }

    public static CosmeticManager getInstance() {
        return INSTANCE;
    }

    /**
     * Register all built-in cosmetics.
     */
    private void registerBuiltInCosmetics() {
        // Register particle trail cosmetics with different shapes
        // Default / Dyeable Particles
        registerParticleTrail("buildscape:cosmatics/particle/heart_trail", "Heart Trail", "Hearts float behind you", 2,
                "heart");
        registerParticleTrail("buildscape:cosmatics/particle/sparkle_trail", "Sparkle Trail",
                "Magical sparkles trail behind you", 1, "sparkle");

        // Other Default Particles
        registerParticleTrail("buildscape:cosmatics/particle/bubble_trail", "Bubble Trail", "Bubbles float behind you",
                1, "bubble");
        registerParticleTrail("buildscape:cosmatics/particle/cherry_leaves_trail", "Cherry Leaves Trail",
                "Falling pink leaves trail behind you", 1, "cherry"); // Changed from "cherry_leaves" to "cherry" to use ModParticles.CHERRY
        registerParticleTrail("buildscape:cosmatics/particle/note_trail", "Note Trail", "Musical notes follow you", 1,
                "note");

        // Custom Particles
        registerParticleTrail("buildscape:cosmatics/particle/snowflake_trail", "Snowflake Trail",
                "Snowflakes drift behind you", 2, "snowflake");
        registerParticleTrail("buildscape:cosmatics/particle/firework_trail", "Firework Trail",
                "Miniature fireworks trail behind you", 3, "firework");
        registerParticleTrail("buildscape:cosmatics/particle/cake_trail", "Cake Trail",
                "Sweet cake particles follow you", 3, "cake");

        // Register some item cosmetics for variety

        registerItemCosmetic("buildscape:cosmatics/wings/elytra", "Elytra Wings", "Wings for gliding", 2,
                "item:minecraft:elytra");
        registerHeadCosmetic("buildscape:cosmatics/gear/builders_hat", "Builder's Hat", "A stylish builder's hat", 1);
        registerItemCosmetic("buildscape:cosmatics/gear/netherite_helmet", "Netherite Helmet",
                "Powerful netherite helmet", 3, "item:minecraft:netherite_helmet");
        registerItemCosmetic("buildscape:cosmatics/gear/netherite_chestplate", "Netherite Chestplate",
                "Powerful netherite chestplate", 3, "item:minecraft:netherite_chestplate");
        registerItemCosmetic("buildscape:cosmatics/gear/netherite_leggings", "Netherite Leggings",
                "Powerful netherite leggings", 3, "item:minecraft:netherite_leggings");
        registerItemCosmetic("buildscape:cosmatics/gear/netherite_boots", "Netherite Boots", "Powerful netherite boots",
                3, "item:minecraft:netherite_boots");

        // Register block cosmetics

        BuildScape.getLogger().info("Registered " + allCosmetics.size() + " built-in cosmetics");
    }

    /**
     * Register a particle trail cosmetic.
     */
    private void registerParticleTrail(String cosmeticId, String name, String description, int tier, String shape) {
        allCosmetics.add(cosmeticId);
        cosmeticMetadata.put(cosmeticId,
                new CosmeticMetadata(name, description, tier, CosmeticType.PARTICLE_TRAIL, null));
        particleShapes.put(cosmeticId, shape);
    }

    /**
     * Get particle shape for a cosmetic.
     */
    public String getParticleShape(String cosmeticId) {
        return particleShapes.getOrDefault(cosmeticId, "sparkle");
    }

    /**
     * Check if a particle trail supports color customization.
     */
    public boolean supportsColor(String cosmeticId) {
        if (!isParticleTrail(cosmeticId)) {
            return false;
        }

        String shape = getParticleShape(cosmeticId);
        // Only Sparkle and Heart shapes support colors
        // Cherry, Cake, Snowflake, Firework, Note, Bubble, Cherry Leaves are NOT colorable
        return shape.equals("sparkle") || shape.equals("heart");
    }

    /**
     * Register an item cosmetic.
     */
    private void registerItemCosmetic(String cosmeticId, String name, String description, int tier, String legacyId) {
        allCosmetics.add(cosmeticId);
        CosmeticType type = cosmeticId.contains("/wings/") ? CosmeticType.WINGS : CosmeticType.ITEM;
        cosmeticMetadata.put(cosmeticId, new CosmeticMetadata(name, description, tier, type, legacyId));
    }

    /**
     * Register a custom head/armor cosmetic with a custom model.
     */
    private void registerHeadCosmetic(String cosmeticId, String name, String description, int tier) {
        allCosmetics.add(cosmeticId);
        cosmeticMetadata.put(cosmeticId, new CosmeticMetadata(name, description, tier, CosmeticType.HEAD, null));
        BuildScape.getLogger().info("Registered HEAD cosmetic: " + cosmeticId + " (" + name + ")");
    }

    /**
     * Get all registered cosmetics.
     */
    public Set<String> getAllCosmetics() {
        return new HashSet<>(allCosmetics);
    }

    /**
     * Get metadata for a cosmetic.
     */
    public CosmeticMetadata getMetadata(String cosmeticId) {
        return cosmeticMetadata.get(cosmeticId);
    }

    /**
     * Check if a cosmetic is registered.
     */
    public boolean isRegistered(String cosmeticId) {
        return allCosmetics.contains(cosmeticId);
    }

    /**
     * Check if a player has access to a cosmetic (dev always has access).
     */
    public boolean hasAccess(String playerUsername, String cosmeticId) {
        // Dev always has access to everything
        if (playerUsername != null && playerUsername.equalsIgnoreCase(DEV_USERNAME)) {
            return true;
        }

        // For now, all cosmetics are accessible (will be replaced with API check)
        return isRegistered(cosmeticId);
    }

    /**
     * Get unlocked cosmetics for a player (dev gets everything).
     */
    public Set<String> getUnlockedCosmetics(String playerUsername) {
        Set<String> unlocked = new HashSet<>();

        // Dev gets everything
        if (playerUsername != null && playerUsername.equalsIgnoreCase(DEV_USERNAME)) {
            unlocked.addAll(allCosmetics);
            return unlocked;
        }

        // For now, return empty (will be replaced with API check)
        // API will determine which cosmetics are unlocked
        return unlocked;
    }

    /**
     * Check if a cosmetic ID is a particle trail.
     */
    public boolean isParticleTrail(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty())
            return false;

        // Check metadata type if available
        CosmeticMetadata metadata = cosmeticMetadata.get(cosmeticId);
        if (metadata != null && metadata.type == CosmeticType.PARTICLE_TRAIL) {
            return true;
        }

        // Fallback to string check
        String idLower = cosmeticId.toLowerCase();
        return idLower.contains("particle") &&
                (idLower.contains("trail") ||
                        idLower.contains("star") ||
                        idLower.contains("sparkle") ||
                        idLower.contains("effect"));
    }

    /**
     * Cosmetic metadata.
     *
     * @param tier     1 = Bronze, 2 = Silver, 3 = Gold
     * @param legacyId For resolving to Item/Block
     */
        public record CosmeticMetadata(String name, String description, int tier, CosmeticType type, String legacyId) {
    }

    /**
     * Cosmetic type enum.
     */
    public enum CosmeticType {
        ITEM,
        BLOCK,
        PARTICLE_TRAIL,
        WINGS,
        EFFECT,
        HEAD // Custom head/armor model cosmetics
    }
}

package com.kingodogo.buildscape.cosmetics;

import com.kingodogo.buildscape.BuildScape;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import net.minecraftforge.registries.ForgeRegistries;
import org.jetbrains.annotations.Nullable;

import java.util.HashMap;
import java.util.Map;

/**
 * Registry for parsing and resolving cosmetic IDs to Minecraft registry
 * entries.
 * 
 * Cosmetic IDs are strings in format:
 * - "item:namespace:item_id" - Item cosmetic (e.g.,
 * "item:minecraft:diamond_sword")
 * - "block:namespace:block_id" - Block cosmetic (e.g.,
 * "block:minecraft:gold_block")
 * - "nbt:custom_data" - NBT-based cosmetic (custom data stored in game)
 * - "type:armor_set_1" - Type-based cosmetic (armor sets, etc.)
 * 
 * All cosmetic assets (models, textures) are built into the game.
 * This registry only resolves IDs to registry entries.
 */
public class CosmeticRegistry {
    private static final CosmeticRegistry INSTANCE = new CosmeticRegistry();

    // Cache for resolved items/blocks to avoid repeated lookups
    private final Map<String, Item> itemCache = new HashMap<>();
    private final Map<String, Block> blockCache = new HashMap<>();
    private final Map<String, ItemStack> itemStackCache = new HashMap<>();

    // Custom cosmetic type definitions (can be extended)
    private final Map<String, CosmeticType> typeDefinitions = new HashMap<>();

    private CosmeticRegistry() {
        // Initialize custom types if needed
        // Example: typeDefinitions.put("armor_set_1", new CosmeticType(...));
    }

    public static CosmeticRegistry getInstance() {
        return INSTANCE;
    }

    /**
     * Parse a cosmetic ID string and return the type and identifier.
     *
     * @param cosmeticId Cosmetic ID string (e.g.,
     *                   "buildscape:cosmatics/gear/diamond_sword")
     * @return Parsed cosmetic info, or null if invalid format
     */
    @Nullable
    public CosmeticInfo parseCosmeticId(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return null;
        }

        // Handle new format: buildscape:cosmatics/category/id
        if (cosmeticId.startsWith("buildscape:cosmatics/")) {
            String path = cosmeticId.substring("buildscape:cosmatics/".length());
            String[] parts = path.split("/", 2);
            if (parts.length == 2) {
                String category = parts[0]; // e.g. "gear", "particle", "wings"
                String id = parts[1];

                // Map new categories to internal types
                String type = category;
                if (category.equals("gear"))
                    type = "item"; // Default to item for gear

                // Get legacy ID from CosmeticManager if possible for resolving
                CosmeticManager.CosmeticMetadata metadata = CosmeticManager.getInstance().getMetadata(cosmeticId);
                String legacyId = (metadata != null) ? metadata.legacyId() : null;

                if (legacyId != null) {
                    // Parse legacy ID to get namespace and id
                    String[] legacyParts = legacyId.split(":", 3);
                    if (legacyParts.length >= 2) {
                        String lType = legacyParts[0];
                        String namespace = legacyParts.length >= 3 ? legacyParts[1] : "minecraft";
                        String lId = legacyParts.length >= 3 ? legacyParts[2] : legacyParts[1];
                        return new CosmeticInfo(lType, namespace, lId, cosmeticId);
                    }
                }

                return new CosmeticInfo(type, "buildscape", id, cosmeticId);
            }
        }

        // Fallback to legacy format: type:namespace:id
        String[] parts = cosmeticId.split(":", 3);
        if (parts.length < 2) {
            BuildScape.getLogger().warn("Invalid cosmetic ID format: " + cosmeticId);
            return null;
        }

        String type = parts[0];
        String namespace = parts.length >= 3 ? parts[1] : "minecraft";
        String id = parts.length >= 3 ? parts[2] : parts[1];

        return new CosmeticInfo(type, namespace, id, cosmeticId);
    }

    /**
     * Resolve a cosmetic ID to an Item.
     * 
     * @param cosmeticId Cosmetic ID string
     * @return Item if found, null otherwise
     */
    @Nullable
    public Item resolveToItem(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return null;
        }

        // Check cache first
        if (itemCache.containsKey(cosmeticId)) {
            return itemCache.get(cosmeticId);
        }

        CosmeticInfo info = parseCosmeticId(cosmeticId);
        if (info == null || !info.type.equals("item")) {
            return null;
        }

        ResourceLocation resourceLocation = new ResourceLocation(info.namespace + ":" + info.id);
        Item item = ForgeRegistries.ITEMS.getValue(resourceLocation);

        if (item != null) {
            itemCache.put(cosmeticId, item);
        } else {
            BuildScape.getLogger().warn("Could not resolve cosmetic item: " + cosmeticId);
        }

        return item;
    }

    /**
     * Resolve a cosmetic ID to a Block.
     * 
     * @param cosmeticId Cosmetic ID string
     * @return Block if found, null otherwise
     */
    @Nullable
    public Block resolveToBlock(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return null;
        }

        // Check cache first
        if (blockCache.containsKey(cosmeticId)) {
            return blockCache.get(cosmeticId);
        }

        CosmeticInfo info = parseCosmeticId(cosmeticId);
        if (info == null || !info.type.equals("block")) {
            return null;
        }

        ResourceLocation resourceLocation = new ResourceLocation(info.namespace + ":" + info.id);
        Block block = ForgeRegistries.BLOCKS.getValue(resourceLocation);

        if (block != null) {
            blockCache.put(cosmeticId, block);
        } else {
            BuildScape.getLogger().warn("Could not resolve cosmetic block: " + cosmeticId);
        }

        return block;
    }

    /**
     * Resolve a cosmetic ID to an ItemStack.
     * Handles both item and block cosmetics (blocks are converted to ItemStacks).
     * For particle trails, returns a placeholder item (nether star) for display.
     * 
     * @param cosmeticId Cosmetic ID string
     * @return ItemStack if found, null otherwise
     */
    public ItemStack resolveToItemStack(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return null;
        }

        // Check if this is a custom HEAD cosmetic - these should NOT resolve to
        // ItemStacks
        // Custom head cosmetics like builder's hat use custom models, not ItemStack
        // models
        CosmeticManager.CosmeticMetadata meta = CosmeticManager.getInstance().getMetadata(cosmeticId);
        if (meta != null && meta.type() == CosmeticManager.CosmeticType.HEAD) {
            // Return null for custom head cosmetics - they use custom rendering
            return null;
        }

        // Check cache first
        if (itemStackCache.containsKey(cosmeticId)) {
            ItemStack cached = itemStackCache.get(cosmeticId);
            return cached != null ? cached.copy() : null;
        }

        ItemStack result = null;

        CosmeticInfo info = parseCosmeticId(cosmeticId);
        if (info != null) {
            // Check if it's a particle trail (use nether star as placeholder)
            if (info.type.equals("particle")) {
                result = new ItemStack(net.minecraft.world.item.Items.NETHER_STAR);
            } else if (info.type.equals("wings")) {
                // For wings, try to resolve as item (usually elytra)
                Item item = resolveToItem(cosmeticId);
                if (item != null) {
                    result = new ItemStack(item);
                } else {
                    // Placeholder for wings if item not found
                    result = new ItemStack(net.minecraft.world.item.Items.FEATHER);
                }
            } else {
                // Try as item first
                Item item = resolveToItem(cosmeticId);
                if (item != null) {
                    result = new ItemStack(item);
                } else {
                    // Try as block
                    Block block = resolveToBlock(cosmeticId);
                    if (block != null) {
                        result = new ItemStack(block.asItem());
                    } else {
                        // Try as custom type
                        if (info.type.equals("type")) {
                            CosmeticType typeDef = typeDefinitions.get(info.id);
                            if (typeDef != null) {
                                result = typeDef.createItemStack();
                            }
                        } else {
                            // Fallback: if cosmetic metadata has a legacyId, try resolving that
                            // Reuse the meta variable we already have from the HEAD check above
                            if (meta != null && meta.legacyId() != null && !meta.legacyId().isEmpty()) {
                                Item legacyItem = resolveToItem(meta.legacyId());
                                if (legacyItem == null) {
                                    // legacyId might be block:... or item:...
                                    Block legacyBlock = resolveToBlock(meta.legacyId());
                                    if (legacyBlock != null) {
                                        result = new ItemStack(legacyBlock.asItem());
                                    }
                                } else {
                                    result = new ItemStack(legacyItem);
                                }
                            }
                        }
                    }
                }
            }
        }

        // Cache result (even if null to avoid repeated lookups)
        itemStackCache.put(cosmeticId, result != null ? result.copy() : null);

        return result != null ? result.copy() : null;
    }

    /**
     * Check if a cosmetic ID is valid and can be resolved.
     * 
     * @param cosmeticId Cosmetic ID string
     * @return true if valid and resolvable
     */
    public boolean isValid(String cosmeticId) {
        if (cosmeticId == null || cosmeticId.isEmpty()) {
            return false;
        }

        CosmeticInfo info = parseCosmeticId(cosmeticId);
        if (info == null) {
            return false;
        }

        switch (info.type) {
            case "item":
                return resolveToItem(cosmeticId) != null;
            case "block":
                return resolveToBlock(cosmeticId) != null;
            case "type":
                return typeDefinitions.containsKey(info.id);
            case "nbt":
                // NBT cosmetics are handled separately
                return true;
            default:
                return false;
        }
    }

    /**
     * Clear all caches.
     * Useful for reloading or debugging.
     */
    public void clearCache() {
        itemCache.clear();
        blockCache.clear();
        itemStackCache.clear();
    }

    /**
     * Internal class to hold parsed cosmetic information.
     */
    public static class CosmeticInfo {
        public final String type;
        public final String namespace;
        public final String id;
        public final String fullId;

        public CosmeticInfo(String type, String namespace, String id, String fullId) {
            this.type = type;
            this.namespace = namespace;
            this.id = id;
            this.fullId = fullId;
        }
    }

    /**
     * Interface for custom cosmetic types.
     * Extend this to create custom cosmetic type definitions.
     */
    public interface CosmeticType {
        ItemStack createItemStack();
    }
}

package com.kingodogo.buildscape.entity;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.Packet;
import net.minecraft.network.protocol.game.ClientboundAddEntityPacket;
import net.minecraft.network.syncher.EntityDataAccessor;
import net.minecraft.network.syncher.EntityDataSerializers;
import net.minecraft.network.syncher.SynchedEntityData;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.world.InteractionHand;
import net.minecraft.world.InteractionResult;
import net.minecraft.world.damagesource.DamageSource;
import net.minecraft.world.entity.Entity;
import net.minecraft.world.entity.EntityType;
import net.minecraft.world.entity.decoration.HangingEntity;
import net.minecraft.world.entity.player.Player;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.item.Items;
import net.minecraft.world.item.MapItem;
import net.minecraft.world.level.GameRules;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.DiodeBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.saveddata.maps.MapItemSavedData;
import net.minecraft.world.phys.AABB;
import org.apache.commons.lang3.Validate;

import javax.annotation.Nullable;

public class ColoredItemFrameEntity extends HangingEntity {

    private static final EntityDataAccessor<ItemStack> DATA_ITEM = SynchedEntityData
            .defineId(ColoredItemFrameEntity.class, EntityDataSerializers.ITEM_STACK);
    private static final EntityDataAccessor<Integer> DATA_ROTATION = SynchedEntityData
            .defineId(ColoredItemFrameEntity.class, EntityDataSerializers.INT);
    private static final EntityDataAccessor<String> DATA_COLOR = SynchedEntityData
            .defineId(ColoredItemFrameEntity.class, EntityDataSerializers.STRING);

    private float dropChance = 1.0F;
    private boolean fixed = false;

    public ColoredItemFrameEntity(EntityType<? extends ColoredItemFrameEntity> entityType, Level level) {
        super(entityType, level);
    }

    public ColoredItemFrameEntity(EntityType<? extends ColoredItemFrameEntity> entityType, Level level, BlockPos pos,
                                  Direction direction) {
        super(entityType, level, pos);
        this.setDirection(direction);
    }

    public ColoredItemFrameEntity(Level level, BlockPos pos, Direction direction) {
        this(ModEntities.COLORED_ITEM_FRAME.get(), level, pos, direction);
    }

    public ColoredItemFrameEntity(Level level, BlockPos pos, Direction direction, String color) {
        this(ModEntities.COLORED_ITEM_FRAME.get(), level, pos, direction);
        this.setColorVariant(color);
        if ("invisible".equals(color)) {
            this.setInvisible(true);
        }
    }

    @Override
    protected void defineSynchedData() {
        this.getEntityData().define(DATA_ITEM, ItemStack.EMPTY);
        this.getEntityData().define(DATA_ROTATION, 0);
        this.getEntityData().define(DATA_COLOR, "white");
    }

    @Override
    protected void setDirection(Direction direction) {
        Validate.notNull(direction);
        this.direction = direction;
        if (direction.getAxis().isHorizontal()) {
            this.setXRot(0.0F);
            this.setYRot((float) (this.direction.get2DDataValue() * 90));
        } else {
            this.setXRot((float) (-90 * direction.getAxisDirection().getStep()));
            this.setYRot(0.0F);
        }
        this.xRotO = this.getXRot();
        this.yRotO = this.getYRot();
        this.recalculateBoundingBox();
    }

    @Override
    protected void recalculateBoundingBox() {
        if (this.direction == null) {
            return;
        }

        double x = (double) this.pos.getX() + 0.5D - (double) this.direction.getStepX() * 0.46875D;
        double y = (double) this.pos.getY() + 0.5D - (double) this.direction.getStepY() * 0.46875D;
        double z = (double) this.pos.getZ() + 0.5D - (double) this.direction.getStepZ() * 0.46875D;
        this.setPosRaw(x, y, z);

        double w = this.getWidth();
        double h = this.getHeight();
        double d = this.getWidth();

        Direction.Axis axis = this.direction.getAxis();
        switch (axis) {
            case X:
                w = 1.0D;
                break;
            case Y:
                h = 1.0D;
                break;
            case Z:
                d = 1.0D;
                break;
        }

        w /= 32.0D;
        h /= 32.0D;
        d /= 32.0D;

        this.setBoundingBox(new AABB(x - w, y - h, z - d, x + w, y + h, z + d));
    }

    @Override
    public int getWidth() {
        return 12;
    }

    @Override
    public int getHeight() {
        return 12;
    }

    public String getColorVariant() {
        return this.getEntityData().get(DATA_COLOR);
    }

    public void setColorVariant(String color) {
        this.getEntityData().set(DATA_COLOR, color);
    }

    public ItemStack getItem() {
        return this.getEntityData().get(DATA_ITEM);
    }

    public void setItem(ItemStack stack) {
        this.setItem(stack, true);
    }

    public void setItem(ItemStack stack, boolean playSound) {
        if (!stack.isEmpty()) {
            stack = stack.copy();
            stack.setCount(1);
            stack.setEntityRepresentation(this);
        }
        this.getEntityData().set(DATA_ITEM, stack);
        if (!stack.isEmpty() && playSound) {
            this.playSound(SoundEvents.ITEM_FRAME_ADD_ITEM, 1.0F, 1.0F);
        }
        if (this.pos != null) {
            this.level.updateNeighbourForOutputSignal(this.pos, Blocks.AIR);
        }
    }

    public int getRotation() {
        return this.getEntityData().get(DATA_ROTATION);
    }

    public void setRotation(int rotation) {
        this.setRotation(rotation, true);
    }

    private void setRotation(int rotation, boolean playSound) {
        this.getEntityData().set(DATA_ROTATION, rotation % 8);
        if (playSound && !this.getItem().isEmpty()) {
            this.playSound(SoundEvents.ITEM_FRAME_ROTATE_ITEM, 1.0F, 1.0F);
        }
        if (this.pos != null) {
            this.level.updateNeighbourForOutputSignal(this.pos, Blocks.AIR);
        }
    }

    @Override
    public InteractionResult interact(Player player, InteractionHand hand) {
        ItemStack heldItem = player.getItemInHand(hand);
        ItemStack frameItem = this.getItem();
        boolean hasItemInFrame = !frameItem.isEmpty();
        boolean hasItemInHand = !heldItem.isEmpty();

        if (this.fixed) {
            return InteractionResult.PASS;
        } else if (!this.level.isClientSide) {
            if (!hasItemInFrame) {
                if (hasItemInHand && !this.isRemoved()) {
                    if (heldItem.is(Items.FILLED_MAP)) {
                        MapItemSavedData mapData = MapItem.getSavedData(heldItem, this.level);
                        if (mapData != null && mapData.isTrackedCountOverLimit(256)) {
                            return InteractionResult.FAIL;
                        }
                    }
                    this.setItem(heldItem);
                    if (!player.getAbilities().instabuild) {
                        heldItem.shrink(1);
                    }
                }
            } else {
                this.playSound(SoundEvents.ITEM_FRAME_ROTATE_ITEM, 1.0F, 1.0F);
                this.setRotation(this.getRotation() + 1);
            }
            return InteractionResult.CONSUME;
        } else {
            return !hasItemInFrame && !hasItemInHand ? InteractionResult.PASS : InteractionResult.SUCCESS;
        }
    }

    @Override
    public boolean hurt(DamageSource source, float amount) {
        if (this.fixed) {
            return (source == DamageSource.OUT_OF_WORLD || source.isCreativePlayer()) && super.hurt(source, amount);
        } else if (this.isInvulnerableTo(source)) {
            return false;
        } else if (!source.isExplosion() && !this.getItem().isEmpty()) {
            if (!this.level.isClientSide) {
                this.dropItem(source.getEntity(), false);
                this.playSound(SoundEvents.ITEM_FRAME_REMOVE_ITEM, 1.0F, 1.0F);
                this.gameEvent(net.minecraft.world.level.gameevent.GameEvent.BLOCK_CHANGE, source.getEntity());
            }
            return true;
        } else {
            return super.hurt(source, amount);
        }
    }

    @Override
    public boolean isPickable() {
        return true;
    }

    @Override
    public boolean skipAttackInteraction(Entity entity) {
        if (entity instanceof Player player) {
            return !this.level.mayInteract(player, this.pos);
        }
        return false;
    }

    @Override
    public void dropItem(@Nullable Entity entity) {
        this.playSound(SoundEvents.ITEM_FRAME_BREAK, 1.0F, 1.0F);
        this.dropItem(entity, true);
    }

    private void dropItem(@Nullable Entity entity, boolean dropSelf) {
        if (!this.fixed) {
            ItemStack itemstack = this.getItem();
            this.setItem(ItemStack.EMPTY);

            if (!this.level.getGameRules().getBoolean(GameRules.RULE_DOENTITYDROPS)) {
                if (entity == null) {
                    this.removeFramedMap(itemstack);
                }
            } else {
                if (entity instanceof Player player) {
                    if (player.getAbilities().instabuild) {
                        this.removeFramedMap(itemstack);
                        return;
                    }
                }

                if (dropSelf) {
                    this.spawnAtLocation(this.getFrameItemForColor(this.getColorVariant()));
                }

                if (!itemstack.isEmpty()) {
                    itemstack = itemstack.copy();
                    this.removeFramedMap(itemstack);
                    if (this.random.nextFloat() < this.dropChance) {
                        this.spawnAtLocation(itemstack);
                    }
                }
            }
        }
    }

    private void removeFramedMap(ItemStack stack) {
        if (stack.is(Items.FILLED_MAP)) {
            MapItemSavedData mapData = MapItem.getSavedData(stack, this.level);
            if (mapData != null) {
                mapData.removedFromFrame(this.pos, this.getId());
                mapData.setDirty(true);
            }
        }
        stack.setEntityRepresentation(null);
    }

    @Override
    public void playPlacementSound() {
        this.playSound(SoundEvents.ITEM_FRAME_PLACE, 1.0F, 1.0F);
    }

    @Override
    public boolean survives() {
        if (this.fixed) {
            return true;
        } else if (!this.level.noCollision(this)) {
            return false;
        } else {
            BlockState blockstate = this.level.getBlockState(this.pos.relative(this.direction.getOpposite()));
            return (blockstate.getMaterial().isSolid()
                    || (this.direction.getAxis().isHorizontal() && DiodeBlock.isDiode(blockstate)))
                    && this.level.getEntities(this, this.getBoundingBox(), HANGING_ENTITY).isEmpty();
        }
    }

    @Override
    public void addAdditionalSaveData(CompoundTag tag) {
        super.addAdditionalSaveData(tag);
        if (!this.getItem().isEmpty()) {
            tag.put("Item", this.getItem().save(new CompoundTag()));
            tag.putByte("ItemRotation", (byte) this.getRotation());
            tag.putFloat("ItemDropChance", this.dropChance);
        }
        tag.putString("ColorVariant", this.getColorVariant());
        tag.putByte("Facing", (byte) this.direction.get3DDataValue());
        tag.putBoolean("Invisible", this.isInvisible());
        tag.putBoolean("Fixed", this.fixed);
    }

    @Override
    public void readAdditionalSaveData(CompoundTag tag) {
        super.readAdditionalSaveData(tag);

        CompoundTag itemTag = tag.getCompound("Item");
        if (itemTag != null && !itemTag.isEmpty()) {
            ItemStack itemstack = ItemStack.of(itemTag);
            if (itemstack.isEmpty()) {
                this.setItem(ItemStack.EMPTY, false);
            } else {
                this.setItem(itemstack, false);
            }
            this.setRotation(tag.getByte("ItemRotation"), false);
            if (tag.contains("ItemDropChance", 99)) {
                this.dropChance = tag.getFloat("ItemDropChance");
            }
        }

        if (tag.contains("ColorVariant")) {
            this.setColorVariant(tag.getString("ColorVariant"));
        }

        this.setDirection(Direction.from3DDataValue(tag.getByte("Facing")));
        this.setInvisible(tag.getBoolean("Invisible"));
        this.fixed = tag.getBoolean("Fixed");
    }

    @Override
    public Packet<?> getAddEntityPacket() {
        return new ClientboundAddEntityPacket(this, this.getType(), this.direction.get3DDataValue(), this.getPos());
    }

    @Override
    public void recreateFromPacket(ClientboundAddEntityPacket packet) {
        super.recreateFromPacket(packet);
        this.setDirection(Direction.from3DDataValue(packet.getData()));
    }

    @Override
    public ItemStack getPickResult() {
        ItemStack itemstack = this.getItem();
        return itemstack.isEmpty() ? this.getFrameItemForColor(this.getColorVariant()) : itemstack.copy();
    }

    public int getAnalogOutput() {
        return this.getItem().isEmpty() ? 0 : this.getRotation() % 8 + 1;
    }

    private ItemStack getFrameItemForColor(String color) {
        switch (color) {
            case "black":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.BLACK_ITEM_FRAME.get());
            case "blue":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.BLUE_ITEM_FRAME.get());
            case "brown":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.BROWN_ITEM_FRAME.get());
            case "cyan":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.CYAN_ITEM_FRAME.get());
            case "gray":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.GRAY_ITEM_FRAME.get());
            case "green":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.GREEN_ITEM_FRAME.get());
            case "light_blue":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.LIGHT_BLUE_ITEM_FRAME.get());
            case "light_gray":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.LIGHT_GRAY_ITEM_FRAME.get());
            case "lime":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.LIME_ITEM_FRAME.get());
            case "magenta":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.MAGENTA_ITEM_FRAME.get());
            case "orange":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.ORANGE_ITEM_FRAME.get());
            case "pink":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.PINK_ITEM_FRAME.get());
            case "purple":
                return new ItemStack(com.kingodogo.buildscape.item.ModItems.PURPLE_ITEM_FRAME.get());
