                );
            case "magenta":
                return new ItemStack(
                        com.kingodogo.buildscape.item.ModItems.MAGENTA_FESTIVE_STOCKING.get()
                );
            case "orange":
                return new ItemStack(
                        com.kingodogo.buildscape.item.ModItems.ORANGE_FESTIVE_STOCKING.get()
