    public static java.util.List<String> getParticleColors(ItemFrame itemFrame) {
        if (itemFrame.level.isClientSide) {
            java.util.List<String> cached = CLIENT_COLOR_CACHE.get(itemFrame.getId());
            return cached != null ? cached : new java.util.ArrayList<>();
        }

        CompoundTag data = itemFrame.getPersistentData();
        java.util.List<String> colors = new java.util.ArrayList<>();

        if (data.contains(PARTICLE_COLORS_KEY)) {
            net.minecraft.nbt.ListTag colorList = data.getList(
                    PARTICLE_COLORS_KEY,
                    8
            );
            for (int i = 0; i < colorList.size() && i < MAX_DYE_COLORS; i++) {
                String color = colorList.getString(i);
                if (color != null && !color.isEmpty()) {
                    colors.add(color);
                }
            }
        }

        return colors;
    }

    public static void addParticleColor(ItemFrame itemFrame, String color) {
        java.util.List<String> colors = getParticleColors(itemFrame);
        if (colors.size() >= MAX_DYE_COLORS) return;

        colors.add(color.toUpperCase());

        CLIENT_COLOR_CACHE.put(itemFrame.getId(), colors);

        if (!itemFrame.level.isClientSide) {
            CompoundTag data = itemFrame.getPersistentData();
            net.minecraft.nbt.ListTag colorList = new net.minecraft.nbt.ListTag();
            for (String c : colors) {
                colorList.add(net.minecraft.nbt.StringTag.valueOf(c));
            }
            data.put(PARTICLE_COLORS_KEY, colorList);

            if (!data.contains(FRAME_ID_KEY)) {
                String frameId = generateFrameId();
                data.putString(FRAME_ID_KEY, frameId);
                CLIENT_FRAME_ID_CACHE.put(itemFrame.getId(), frameId);
            }
        }
    }

    public static boolean hasCustomColors(ItemFrame itemFrame) {
        return !getParticleColors(itemFrame).isEmpty();
    }

    public static String getFrameId(ItemFrame itemFrame) {
        if (itemFrame.level.isClientSide) {
            String cached = CLIENT_FRAME_ID_CACHE.get(itemFrame.getId());
            return cached != null ? cached : "F-????";
        }

        CompoundTag data = itemFrame.getPersistentData();
        if (data.contains(FRAME_ID_KEY)) {
            return data.getString(FRAME_ID_KEY);
        }

        String frameId = generateFrameId();
        data.putString(FRAME_ID_KEY, frameId);
        CLIENT_FRAME_ID_CACHE.put(itemFrame.getId(), frameId);
        return frameId;
    }

    private static String generateFrameId() {
        frameIdCounter++;
        return (
                FRAME_PREFIX +
                        "-P" +
                        String.format("%04d", (frameIdCounter + new Random().nextInt(9000)))
        );
    }

    public static void clearCaches(int entityId) {
        CLIENT_PATTERN_CACHE.remove(entityId);
        CLIENT_COLOR_CACHE.remove(entityId);
        CLIENT_FRAME_ID_CACHE.remove(entityId);
    }

    public static void clearCaches() {
        CLIENT_PATTERN_CACHE.clear();
        CLIENT_COLOR_CACHE.clear();
        CLIENT_FRAME_ID_CACHE.clear();
        COLOR_COUNTERS.clear();
    }
}

package com.kingodogo.buildscape.event;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.block.ModBlocks;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.PointedDripstoneBlock;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.world.BlockEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;

@Mod.EventBusSubscriber(modid = BuildScape.MODID)
public class MudToClayHandler {

    private static final List<TrackedMud> trackedMud = new ArrayList<>();

    @SubscribeEvent
    public static void onBlockPlace(BlockEvent.EntityPlaceEvent event) {
        if (!(event.getWorld() instanceof ServerLevel level)) return;
        if (level.dimension() == Level.NETHER) return;

        BlockPos pos = event.getPos();
        BlockState placedState = event.getPlacedBlock();

        // Case 1: Mud was placed - check for dripstone below
        if (placedState.is(ModBlocks.MUD.get())) {
            tryTrackMud(level, pos);
        }

        // Case 2: Pointed dripstone placed - check for mud two blocks above
        if (placedState.is(Blocks.POINTED_DRIPSTONE) &&
                placedState.getValue(PointedDripstoneBlock.TIP_DIRECTION) == Direction.DOWN) {
            BlockPos mudPos = pos.above(2);
            if (level.getBlockState(mudPos).is(ModBlocks.MUD.get())) {
                tryTrackMud(level, mudPos);
            }
        }

        // Case 3: Block placed between existing mud and dripstone
        BlockPos abovePos = pos.above();
        BlockPos belowPos = pos.below();
        if (level.getBlockState(abovePos).is(ModBlocks.MUD.get())) {
            BlockState belowState = level.getBlockState(belowPos);
            if (belowState.is(Blocks.POINTED_DRIPSTONE) &&
                    belowState.getValue(PointedDripstoneBlock.TIP_DIRECTION) == Direction.DOWN) {
                tryTrackMud(level, abovePos);
            }
        }
    }

    private static void tryTrackMud(ServerLevel level, BlockPos mudPos) {
        // Avoid duplicate tracking
        for (TrackedMud tracked : trackedMud) {
            if (tracked.pos.equals(mudPos) && tracked.level == level) return;
        }

        BlockPos belowMud = mudPos.below();
        BlockPos dripstonePos = mudPos.below(2);

        BlockState belowState = level.getBlockState(belowMud);
        BlockState dripstoneState = level.getBlockState(dripstonePos);

        // Requires: non-air block below mud, pointed dripstone facing down below that
        if (!belowState.isAir() &&
                dripstoneState.is(Blocks.POINTED_DRIPSTONE) &&
                dripstoneState.getValue(PointedDripstoneBlock.TIP_DIRECTION) == Direction.DOWN) {
            // 1-2 seconds (20-40 ticks)
            int ticks = 20 + level.random.nextInt(21);
            trackedMud.add(new TrackedMud(level, mudPos, ticks));
        }
    }

    @SubscribeEvent
    public static void onServerTick(TickEvent.ServerTickEvent event) {
        if (event.phase != TickEvent.Phase.END) return;
        if (trackedMud.isEmpty()) return;

        Iterator<TrackedMud> it = trackedMud.iterator();
        while (it.hasNext()) {
            TrackedMud tracked = it.next();
            tracked.ticksRemaining--;

            if (tracked.ticksRemaining <= 0) {
                // Verify mud is still there before converting
                if (tracked.level.getBlockState(tracked.pos).is(ModBlocks.MUD.get())) {
                    tracked.level.setBlock(tracked.pos, Blocks.CLAY.defaultBlockState(), 3);
                }
                it.remove();
            }
        }
    }

    private static class TrackedMud {
        final ServerLevel level;
        final BlockPos pos;
        int ticksRemaining;

        TrackedMud(ServerLevel level, BlockPos pos, int ticks) {
            this.level = level;
            this.pos = pos;
            this.ticksRemaining = ticks;
        }
    }
}

