        this.zd *= 0.98;
        
        // Add slight horizontal drift for more realistic confetti movement
        if (this.age % 5 == 0) {
            this.xd += (this.level.random.nextDouble() - 0.5) * 0.01;
            this.zd += (this.level.random.nextDouble() - 0.5) * 0.01;
        }
        
