package com.kingodogo.buildscape.verticalslab;

import com.google.gson.*;
import com.kingodogo.buildscape.BuildScape;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.packs.PackType;
import net.minecraft.server.packs.resources.IoSupplier;
import net.minecraft.server.packs.resources.Resource;
import net.minecraft.server.packs.resources.ResourceManager;
import net.minecraftforge.common.data.ExistingFileHelper;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.*;

/**
 * Generates dynamic JSON resources for vertical slabs at runtime.
 * Handles blockstates, block models, item models, loot tables, and recipes.
 */
public class DynamicVerticalSlabResources {
    
    private static final Gson GSON = new GsonBuilder().setPrettyPrinting().create();
    
    /**
     * Generate blockstate JSON for a vertical slab
     */
    public static String generateBlockstateJson(ResourceLocation verticalSlabId, ResourceLocation parentSlabId) {
        JsonObject root = new JsonObject();
        JsonObject variants = new JsonObject();
        
        String namespace = verticalSlabId.getNamespace();
        String path = verticalSlabId.getPath();
        
        // Generate all variants (facing * type combinations)
        String[] facings = {"north", "south", "east", "west"};
        String[] types = {"bottom", "double"};
        
        for (String facing : facings) {
            for (String type : types) {
                String variantKey = "facing=" + facing + ",type=" + type;
                JsonObject variantValue = new JsonObject();
                
                if (type.equals("double")) {
                    // Double type uses the full block model from parent
                    variantValue.addProperty("model", namespace + ":block/" + parentSlabId.getPath().replace("_slab", ""));
                } else {
                    // Single slab uses vertical slab model
                    String modelPath = namespace + ":block/" + path;
                    variantValue.addProperty("model", modelPath);
                    
                    // Add rotation based on facing
                    int yRotation = getYRotation(facing);
                    if (yRotation != 0) {
                        variantValue.addProperty("y", yRotation);
                    }
                }
                
                variants.add(variantKey, variantValue);
            }
            
            // Add waterlogged variants
            for (String type : types) {
                String variantKey = "facing=" + facing + ",type=" + type + ",waterlogged=true";
                JsonObject variantValue = new JsonObject();
                
                if (type.equals("double")) {
                    variantValue.addProperty("model", namespace + ":block/" + parentSlabId.getPath().replace("_slab", ""));
                } else {
                    String modelPath = namespace + ":block/" + path;
                    variantValue.addProperty("model", modelPath);
                    
                    int yRotation = getYRotation(facing);
                    if (yRotation != 0) {
                        variantValue.addProperty("y", yRotation);
                    }
                }
                
                variants.add(variantKey, variantValue);
            }
        }
        
        root.add("variants", variants);
        return GSON.toJson(root);
    }
    
    /**
     * Generate block model JSON for a vertical slab
     */
    public static String generateBlockModelJson(ResourceLocation verticalSlabId, ResourceLocation parentSlabId, 
                                               Map<String, String> parentTextures) {
        JsonObject root = new JsonObject();
        
        // Use a vertical slab parent model (we'll create this as a base model)
        root.addProperty("parent", "buildscape:block/vertical_slab");
        
        // Extract textures from parent slab
        JsonObject textures = new JsonObject();
        
        if (parentTextures != null && !parentTextures.isEmpty()) {
            for (Map.Entry<String, String> entry : parentTextures.entrySet()) {
                textures.addProperty(entry.getKey(), entry.getValue());
            }
        } else {
            // Fallback: try to infer texture from slab name
            String baseName = parentSlabId.getPath().replace("_slab", "");
            String textureLocation = parentSlabId.getNamespace() + ":block/" + baseName;
            textures.addProperty("bottom", textureLocation);
            textures.addProperty("top", textureLocation);
            textures.addProperty("side", textureLocation);
        }
        
        root.add("textures", textures);
        return GSON.toJson(root);
    }
    
    /**
     * Generate item model JSON for a vertical slab
     */
    public static String generateItemModelJson(ResourceLocation verticalSlabId) {
        JsonObject root = new JsonObject();
        root.addProperty("parent", verticalSlabId.getNamespace() + ":block/" + verticalSlabId.getPath());
        return GSON.toJson(root);
    }
    
    /**
     * Generate loot table JSON for a vertical slab (drops itself)
     */
    public static String generateLootTableJson(ResourceLocation verticalSlabId) {
        JsonObject root = new JsonObject();
        root.addProperty("type", "minecraft:block");
        
        JsonArray pools = new JsonArray();
        JsonObject pool = new JsonObject();
        pool.addProperty("rolls", 1);
        pool.addProperty("bonus_rolls", 0);
        
        JsonArray entries = new JsonArray();
        JsonObject entry = new JsonObject();
        entry.addProperty("type", "minecraft:item");
        entry.addProperty("name", verticalSlabId.toString());
        
        JsonArray functions = new JsonArray();
        JsonObject function = new JsonObject();
        function.addProperty("function", "minecraft:set_count");
        
        JsonArray conditions = new JsonArray();
        JsonObject condition = new JsonObject();
        condition.addProperty("condition", "minecraft:block_state_property");
        condition.addProperty("block", verticalSlabId.toString());
        
        JsonObject properties = new JsonObject();
        properties.addProperty("type", "double");
        condition.add("properties", properties);
        conditions.add(condition);
        
        function.add("conditions", conditions);
        function.addProperty("count", 2);
        function.addProperty("add", false);
        functions.add(function);
        
        entry.add("functions", functions);
        entries.add(entry);
        pool.add("entries", entries);
        pools.add(pool);
        root.add("pools", pools);
        
        return GSON.toJson(root);
    }
    
    /**
     * Generate crafting recipe JSON for a vertical slab (2 vertical slabs from 1 slab)
     */
    public static String generateRecipeJson(ResourceLocation verticalSlabId, ResourceLocation parentSlabId) {
        JsonObject root = new JsonObject();
        root.addProperty("type", "minecraft:crafting_shapeless");
        
        JsonArray ingredients = new JsonArray();
        JsonObject ingredient = new JsonObject();
        ingredient.addProperty("item", parentSlabId.toString());
        ingredients.add(ingredient);
        root.add("ingredients", ingredients);
        
        JsonObject result = new JsonObject();
        result.addProperty("item", verticalSlabId.toString());
        result.addProperty("count", 1);
        root.add("result", result);
        
        return GSON.toJson(root);
    }
    
    /**
     * Generate reverse crafting recipe JSON (1 slab from 1 vertical slab)
     */
    public static String generateReverseRecipeJson(ResourceLocation verticalSlabId, ResourceLocation parentSlabId) {
        JsonObject root = new JsonObject();
        root.addProperty("type", "minecraft:crafting_shapeless");
        
        JsonArray ingredients = new JsonArray();
        JsonObject ingredient = new JsonObject();
        ingredient.addProperty("item", verticalSlabId.toString());
        ingredients.add(ingredient);
        root.add("ingredients", ingredients);
        
        JsonObject result = new JsonObject();
        result.addProperty("item", parentSlabId.toString());
        result.addProperty("count", 1);
        root.add("result", result);
        
        return GSON.toJson(root);
    }
    
    /**
     * Get Y rotation for a facing direction
     */
    private static int getYRotation(String facing) {
        switch (facing) {
            case "north": return 0;
            case "east": return 90;
            case "south": return 180;
            case "west": return 270;
            default: return 0;
        }
    }
    
    /**
     * Extract textures from a parent slab's model JSON
     */
    public static Map<String, String> extractTexturesFromModel(ResourceManager resourceManager, 
                                                               ResourceLocation parentSlabId) {
        Map<String, String> textures = new HashMap<>();
        
        try {
            // Try to load the parent slab's block model
            ResourceLocation modelLocation = new ResourceLocation(
                parentSlabId.getNamespace(),
                "models/block/" + parentSlabId.getPath() + ".json"
            );
            
            Optional<Resource> resourceOpt = resourceManager.getResource(modelLocation);
            if (resourceOpt.isPresent()) {
                try (InputStream is = resourceOpt.get().open()) {
                    JsonObject modelJson = GSON.fromJson(
                        new String(is.readAllBytes(), StandardCharsets.UTF_8),
                        JsonObject.class
                    );
                    
                    if (modelJson.has("textures")) {
                        JsonObject texturesObj = modelJson.getAsJsonObject("textures");
                        for (Map.Entry<String, JsonElement> entry : texturesObj.entrySet()) {
                            textures.put(entry.getKey(), entry.getValue().getAsString());
                        }
                    }
                    
                    // If model has a parent, try to load parent textures too
                    if (modelJson.has("parent") && textures.isEmpty()) {
                        String parentPath = modelJson.get("parent").getAsString();
                        ResourceLocation parentLoc = new ResourceLocation(parentPath);
                        textures.putAll(extractTexturesFromModel(resourceManager, parentLoc));
                    }
                }
            }
        } catch (Exception e) {
            BuildScape.LOGGER.warn("Failed to extract textures from parent slab model {}: {}", 
                parentSlabId, e.getMessage());
        }
        
        return textures;
    }
    
    /**
     * Generate the base vertical slab model template
     */
    public static String generateBaseVerticalSlabModel() {
        JsonObject root = new JsonObject();
        root.addProperty("parent", "minecraft:block/block");
        
        JsonObject textures = new JsonObject();
        textures.addProperty("particle", "#side");
        root.add("textures", textures);
        
        JsonArray elements = new JsonArray();
        JsonObject element = new JsonObject();
        
        JsonArray from = new JsonArray();
        from.add(0);
        from.add(0);
        from.add(0);
        element.add("from", from);
        
        JsonArray to = new JsonArray();
        to.add(8);
        to.add(16);
        to.add(16);
        element.add("to", to);
        
        JsonObject faces = new JsonObject();
        
        // Define all faces
        String[] faceNames = {"down", "up", "north", "south", "west", "east"};
        for (String faceName : faceNames) {
            JsonObject face = new JsonObject();
            face.addProperty("texture", getTextureForFace(faceName));
            face.addProperty("cullface", faceName);
            faces.add(faceName, face);
        }
        
        element.add("faces", faces);
        elements.add(element);
        root.add("elements", elements);
        
        return GSON.toJson(root);
    }
    
    private static String getTextureForFace(String faceName) {
        switch (faceName) {
            case "down":
            case "up":
                return "#top";
            case "north":
            case "south":
            case "east":
            case "west":
                return "#side";
            default:
                return "#side";
        }
    }
}

package com.kingodogo.buildscape.verticalslab;

import com.kingodogo.buildscape.BuildScape;
import net.minecraft.world.item.Item;
import net.minecraft.world.item.ItemStack;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.SlabBlock;

import java.util.ArrayList;
import java.util.List;

/**
 * Helper class to integrate vertical slabs into the creative tab.
 * Ensures vertical slabs appear immediately after their parent slabs.
 */
public class VerticalSlabCreativeTabHelper {
    
    /**
     * Process a list of items and insert vertical slabs after their parent slabs
     * 
     * @param items The current list of items in the creative tab
     * @return A new list with vertical slabs properly ordered
     */
    public static List<ItemStack> insertVerticalSlabsInOrder(List<ItemStack> items) {
        List<ItemStack> result = new ArrayList<>();
        
        for (ItemStack stack : items) {
            // Add the original item
            result.add(stack);
            
            // Check if this item is a slab block item
            Item item = stack.getItem();
            if (item instanceof net.minecraft.world.item.BlockItem) {
                net.minecraft.world.item.BlockItem blockItem = (net.minecraft.world.item.BlockItem) item;
                Block block = blockItem.getBlock();
                
                // If this is a slab, check if it has a vertical variant
                if (block instanceof SlabBlock && VerticalSlabRegistry.hasVerticalSlab(block)) {
                    Block verticalSlab = VerticalSlabRegistry.getVerticalSlab(block);
                    if (verticalSlab != null) {
                        // Insert the vertical slab right after the parent slab
                        result.add(new ItemStack(verticalSlab));
                        BuildScape.LOGGER.debug("Inserted vertical slab after {}", block.getDescriptionId());
                    }
                }
            }
        }
        
        return result;
    }
    
    /**
     * Check if an item is a vertical slab
     */
    public static boolean isVerticalSlab(ItemStack stack) {
        Item item = stack.getItem();
        if (item instanceof net.minecraft.world.item.BlockItem) {
            net.minecraft.world.item.BlockItem blockItem = (net.minecraft.world.item.BlockItem) item;
            Block block = blockItem.getBlock();
            return VerticalSlabRegistry.isVerticalSlab(block);
        }
        return false;
    }
    
    /**
     * Get the parent slab for a vertical slab item
     */
    public static Block getParentSlab(ItemStack stack) {
        Item item = stack.getItem();
        if (item instanceof net.minecraft.world.item.BlockItem) {
            net.minecraft.world.item.BlockItem blockItem = (net.minecraft.world.item.BlockItem) item;
            Block block = blockItem.getBlock();
            if (VerticalSlabRegistry.isVerticalSlab(block)) {
                return VerticalSlabRegistry.getParentSlab(block);
            }
        }
        return null;
    }
}

package com.kingodogo.buildscape.verticalslab;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.block.VerticalSlabBlock;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.SlabBlock;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.RegisterEvent;

import java.util.*;

/**
 * Main generator system for vertical slabs.
 * Scans the block registry and dynamically generates vertical slab variants.
 */
@Mod.EventBusSubscriber(modid = BuildScape.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)
public class VerticalSlabGenerator {
    
    private static final Set<ResourceLocation> BLACKLIST = new HashSet<>();
    private static boolean blocksGenerated = false;
    private static boolean itemsGenerated = false;
    private static final List<VerticalSlabPendingRegistration> pendingBlocks = new ArrayList<>();
    
    static {
        // Add any slabs that should not have vertical variants here
        // Example: BLACKLIST.add(new ResourceLocation("minecraft", "petrified_oak_slab"));
    }
    
    /**
     * Listen for block registration completion and generate vertical slabs
     */
    @SubscribeEvent
    public static void onRegisterBlocks(RegisterEvent event) {
        event.register(ForgeRegistries.Keys.BLOCKS, helper -> {
            if (!blocksGenerated) {
                BuildScape.LOGGER.info("Scanning for slabs to generate vertical variants...");
                
                int detectedCount = 0;
                
                // Scan all registered blocks
                for (Map.Entry<ResourceLocation, Block> entry : ForgeRegistries.BLOCKS.getEntries()) {
                    ResourceLocation slabId = entry.getKey();
                    Block block = entry.getValue();
                    
                    // Check if this block is a slab and should have a vertical variant
                    if (shouldGenerateVerticalSlab(slabId, block)) {
                        generateVerticalSlabBlock(helper, slabId, block);
                        detectedCount++;
                    }
                }
                
                BuildScape.LOGGER.info("Generated {} vertical slab blocks", detectedCount);
                blocksGenerated = true;
            }
        });
        
        event.register(ForgeRegistries.Keys.ITEMS, helper -> {
            if (!itemsGenerated && blocksGenerated) {
                BuildScape.LOGGER.info("Registering vertical slab items...");
                
                int itemCount = 0;
                
                // Register items for all pending vertical slabs
                for (VerticalSlabPendingRegistration pending : pendingBlocks) {
                    helper.register(pending.verticalSlabId, 
                        new BlockItem(pending.verticalSlabBlock, 
                            new Item.Properties().tab(BuildScape.BUILDSCAPE_TAB)));
                    itemCount++;
                }
                
                BuildScape.LOGGER.info("Registered {} vertical slab items", itemCount);
                itemsGenerated = true;
                
                // Clear pending list
                pendingBlocks.clear();
            }
        });
    }
    
    /**
     * Check if a block should have a vertical slab variant generated
     */
    private static boolean shouldGenerateVerticalSlab(ResourceLocation id, Block block) {
        // Must be a slab block
        if (!(block instanceof SlabBlock)) {
            return false;
        }
        
        // Check blacklist
        if (BLACKLIST.contains(id)) {
            return false;
        }
        
        // Don't generate for already existing vertical slabs
        if (block instanceof VerticalSlabBlock) {
            return false;
        }
        
        // Check if the slab name contains "slab"
        String path = id.getPath();
        if (!path.contains("slab")) {
            return false;
        }
        
        return true;
    }
    
    /**
     * Generate a vertical slab block variant for a given slab block
     */
    private static void generateVerticalSlabBlock(RegisterEvent.RegisterHelper<Block> helper,
                                                  ResourceLocation slabId, Block slab) {
        try {
            // Create vertical slab ID by replacing "slab" with "vertical_slab"
            String verticalSlabName = slabId.getPath().replace("_slab", "_vertical_slab");
            if (verticalSlabName.equals(slabId.getPath())) {
                // If no "_slab" suffix, just append "_vertical"
                verticalSlabName = slabId.getPath() + "_vertical";
            }
            
            ResourceLocation verticalSlabId = new ResourceLocation(slabId.getNamespace(), verticalSlabName);
            
            // Copy properties from the parent slab
            BlockBehaviour.Properties properties = BlockBehaviour.Properties.copy(slab);
            
            // Create the vertical slab block
            VerticalSlabBlock verticalSlabBlock = new VerticalSlabBlock(properties, slab);
            
            // Register the block
            helper.register(verticalSlabId, verticalSlabBlock);
            
            // Add to pending list for item registration
            pendingBlocks.add(new VerticalSlabPendingRegistration(
                verticalSlabId, slabId, verticalSlabBlock, slab));
            
            // Register in the vertical slab registry
            VerticalSlabRegistry.register(
                verticalSlabBlock,
                slab,
                verticalSlabId,
                slabId,
                null, // Block registry object not available in this context
                null  // Item registry object not available in this context
            );
            
            BuildScape.LOGGER.debug("Generated vertical slab: {} for parent: {}", verticalSlabId, slabId);
        } catch (Exception e) {
            BuildScape.LOGGER.error("Failed to generate vertical slab for {}: {}", 
                slabId, e.getMessage(), e);
        }
    }
    
    /**
     * Add a slab to the blacklist (won't generate vertical variant)
     */
    public static void addToBlacklist(ResourceLocation slabId) {
        BLACKLIST.add(slabId);
    }
    
    /**
     * Check if generation has been initialized
     */
    public static boolean isInitialized() {
        return blocksGenerated && itemsGenerated;
    }
    
    /**
     * Internal class to hold pending vertical slab registrations
     */
    private static class VerticalSlabPendingRegistration {
        final ResourceLocation verticalSlabId;
        final ResourceLocation parentSlabId;
        final VerticalSlabBlock verticalSlabBlock;
        final Block parentSlab;
        
        VerticalSlabPendingRegistration(ResourceLocation verticalSlabId, ResourceLocation parentSlabId,
                                       VerticalSlabBlock verticalSlabBlock, Block parentSlab) {
            this.verticalSlabId = verticalSlabId;
            this.parentSlabId = parentSlabId;
            this.verticalSlabBlock = verticalSlabBlock;
            this.parentSlab = parentSlab;
        }
    }
}

