package com.kingodogo.buildscape.verticalslab;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.block.VerticalSlabBlock;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.world.item.BlockItem;
import net.minecraft.world.item.Item;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.SlabBlock;
import net.minecraftforge.registries.DeferredRegister;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.RegistryObject;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * Registry for dynamically generated vertical slabs.
 * Tracks all vertical slabs and their parent slabs for resource generation.
 */
public class VerticalSlabRegistry {
    
    private static final Map<ResourceLocation, VerticalSlabData> VERTICAL_SLABS = new ConcurrentHashMap<>();
    private static final Map<Block, Block> SLAB_TO_VERTICAL = new ConcurrentHashMap<>();
    private static final Map<Block, Block> VERTICAL_TO_SLAB = new ConcurrentHashMap<>();
    
    /**
     * Data class to hold information about a generated vertical slab
     */
    public static class VerticalSlabData {
        private final Block verticalSlab;
        private final Block parentSlab;
        private final ResourceLocation verticalSlabId;
        private final ResourceLocation parentSlabId;
        private final RegistryObject<Block> blockRegistryObject;
        private final RegistryObject<Item> itemRegistryObject;
        
        public VerticalSlabData(Block verticalSlab, Block parentSlab, 
                               ResourceLocation verticalSlabId, ResourceLocation parentSlabId,
                               RegistryObject<Block> blockRegistryObject,
                               RegistryObject<Item> itemRegistryObject) {
            this.verticalSlab = verticalSlab;
            this.parentSlab = parentSlab;
            this.verticalSlabId = verticalSlabId;
            this.parentSlabId = parentSlabId;
            this.blockRegistryObject = blockRegistryObject;
            this.itemRegistryObject = itemRegistryObject;
        }
        
        public Block getVerticalSlab() { return verticalSlab; }
        public Block getParentSlab() { return parentSlab; }
        public ResourceLocation getVerticalSlabId() { return verticalSlabId; }
        public ResourceLocation getParentSlabId() { return parentSlabId; }
        public RegistryObject<Block> getBlockRegistryObject() { return blockRegistryObject; }
        public RegistryObject<Item> getItemRegistryObject() { return itemRegistryObject; }
    }
    
    /**
     * Register a vertical slab and its parent slab
     */
    public static void register(Block verticalSlab, Block parentSlab, 
                                ResourceLocation verticalSlabId, ResourceLocation parentSlabId,
                                RegistryObject<Block> blockRegistryObject,
                                RegistryObject<Item> itemRegistryObject) {
        VerticalSlabData data = new VerticalSlabData(
            verticalSlab, parentSlab, verticalSlabId, parentSlabId,
            blockRegistryObject, itemRegistryObject
        );
        
        VERTICAL_SLABS.put(verticalSlabId, data);
        SLAB_TO_VERTICAL.put(parentSlab, verticalSlab);
        VERTICAL_TO_SLAB.put(verticalSlab, parentSlab);
        
        BuildScape.LOGGER.info("Registered vertical slab: {} for parent slab: {}", 
            verticalSlabId, parentSlabId);
    }
    
    /**
     * Get all registered vertical slabs
     */
    public static Collection<VerticalSlabData> getAllVerticalSlabs() {
        return Collections.unmodifiableCollection(VERTICAL_SLABS.values());
    }
    
    /**
     * Get vertical slab data by its resource location
     */
    public static VerticalSlabData getVerticalSlabData(ResourceLocation id) {
        return VERTICAL_SLABS.get(id);
    }
    
    /**
     * Get the vertical slab variant for a given parent slab
     */
    public static Block getVerticalSlab(Block parentSlab) {
        return SLAB_TO_VERTICAL.get(parentSlab);
    }
    
    /**
     * Get the parent slab for a given vertical slab
     */
    public static Block getParentSlab(Block verticalSlab) {
        return VERTICAL_TO_SLAB.get(verticalSlab);
    }
    
    /**
     * Check if a block has a vertical slab variant
     */
    public static boolean hasVerticalSlab(Block parentSlab) {
        return SLAB_TO_VERTICAL.containsKey(parentSlab);
    }
    
    /**
     * Check if a block is a vertical slab
     */
    public static boolean isVerticalSlab(Block block) {
        return VERTICAL_TO_SLAB.containsKey(block);
    }
    
    /**
     * Get the count of registered vertical slabs
     */
    public static int getVerticalSlabCount() {
        return VERTICAL_SLABS.size();
    }
    
    /**
     * Clear all registrations (for testing purposes)
     */
    public static void clear() {
        VERTICAL_SLABS.clear();
        SLAB_TO_VERTICAL.clear();
        VERTICAL_TO_SLAB.clear();
    }
}

package com.kingodogo.buildscape.verticalslab;

import com.google.gson.JsonObject;
import com.kingodogo.buildscape.BuildScape;
import net.minecraft.resources.ResourceLocation;
