import net.minecraft.server.packs.metadata.MetadataSectionSerializer;
import net.minecraft.server.packs.resources.IoSupplier;
import net.minecraftforge.event.AddPackFindersEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import net.minecraftforge.resource.PathPackResources;

import javax.annotation.Nullable;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.nio.file.Path;
import java.util.*;
import java.util.function.Predicate;

/**
 * Custom pack resources that provides dynamically generated vertical slab resources
 */
@Mod.EventBusSubscriber(modid = BuildScape.MODID, bus = Mod.EventBusSubscriber.Bus.MOD)
public class VerticalSlabResourcePack implements PackResources {
    
    private static final String PACK_NAME = "Vertical Slabs Dynamic Resources";
    private final Map<ResourceLocation, String> generatedResources = new HashMap<>();
    
    public VerticalSlabResourcePack() {
        BuildScape.LOGGER.info("Initializing Vertical Slab Resource Pack");
    }
    
    /**
     * Generate all resources for registered vertical slabs
     */
    public void generateResources() {
        BuildScape.LOGGER.info("Generating dynamic resources for {} vertical slabs", 
            VerticalSlabRegistry.getVerticalSlabCount());
        
        // Generate base vertical slab model
        ResourceLocation baseModelLoc = new ResourceLocation(BuildScape.MODID, "models/block/vertical_slab.json");
        generatedResources.put(baseModelLoc, DynamicVerticalSlabResources.generateBaseVerticalSlabModel());
        
        // Generate resources for each vertical slab
        for (VerticalSlabRegistry.VerticalSlabData data : VerticalSlabRegistry.getAllVerticalSlabs()) {
            generateResourcesForVerticalSlab(data);
        }
        
        BuildScape.LOGGER.info("Generated {} dynamic resources", generatedResources.size());
    }
    
    private void generateResourcesForVerticalSlab(VerticalSlabRegistry.VerticalSlabData data) {
        ResourceLocation verticalSlabId = data.getVerticalSlabId();
        ResourceLocation parentSlabId = data.getParentSlabId();
        String namespace = verticalSlabId.getNamespace();
        String path = verticalSlabId.getPath();
        
        try {
            // Generate blockstate JSON
            ResourceLocation blockstateLoc = new ResourceLocation(namespace, "blockstates/" + path + ".json");
            String blockstateJson = DynamicVerticalSlabResources.generateBlockstateJson(verticalSlabId, parentSlabId);
            generatedResources.put(blockstateLoc, blockstateJson);
            
            // Generate block model JSON
            ResourceLocation blockModelLoc = new ResourceLocation(namespace, "models/block/" + path + ".json");
            Map<String, String> textures = new HashMap<>();
            // Try to infer textures from parent slab
            String baseName = parentSlabId.getPath().replace("_slab", "");
            textures.put("bottom", parentSlabId.getNamespace() + ":block/" + baseName);
            textures.put("top", parentSlabId.getNamespace() + ":block/" + baseName);
            textures.put("side", parentSlabId.getNamespace() + ":block/" + baseName);
            
            String blockModelJson = DynamicVerticalSlabResources.generateBlockModelJson(
                verticalSlabId, parentSlabId, textures);
            generatedResources.put(blockModelLoc, blockModelJson);
            
            // Generate item model JSON
            ResourceLocation itemModelLoc = new ResourceLocation(namespace, "models/item/" + path + ".json");
            String itemModelJson = DynamicVerticalSlabResources.generateItemModelJson(verticalSlabId);
            generatedResources.put(itemModelLoc, itemModelJson);
            
            // Generate loot table JSON
            ResourceLocation lootTableLoc = new ResourceLocation(namespace, "loot_tables/blocks/" + path + ".json");
            String lootTableJson = DynamicVerticalSlabResources.generateLootTableJson(verticalSlabId);
            generatedResources.put(lootTableLoc, lootTableJson);
            
            // Generate crafting recipe JSON (slab -> vertical slab)
            ResourceLocation recipeLoc = new ResourceLocation(namespace, "recipes/" + path + ".json");
            String recipeJson = DynamicVerticalSlabResources.generateRecipeJson(verticalSlabId, parentSlabId);
            generatedResources.put(recipeLoc, recipeJson);
            
            // Generate reverse crafting recipe JSON (vertical slab -> slab)
            ResourceLocation reverseRecipeLoc = new ResourceLocation(namespace, "recipes/" + path + "_to_slab.json");
            String reverseRecipeJson = DynamicVerticalSlabResources.generateReverseRecipeJson(verticalSlabId, parentSlabId);
            generatedResources.put(reverseRecipeLoc, reverseRecipeJson);
            
            BuildScape.LOGGER.debug("Generated resources for vertical slab: {}", verticalSlabId);
        } catch (Exception e) {
            BuildScape.LOGGER.error("Failed to generate resources for vertical slab {}: {}", 
                verticalSlabId, e.getMessage(), e);
        }
    }
    
    @Nullable
    @Override
    public IoSupplier<InputStream> getRootResource(String... paths) {
        return null;
    }
    
    @Nullable
    @Override
    public IoSupplier<InputStream> getResource(PackType packType, ResourceLocation location) {
        if (packType == PackType.CLIENT_RESOURCES) {
            // Check if we have this resource
            String resourcePath = location.getNamespace() + "/" + location.getPath();
            
            for (Map.Entry<ResourceLocation, String> entry : generatedResources.entrySet()) {
                ResourceLocation resLoc = entry.getKey();
                if (resLoc.getNamespace().equals(location.getNamespace()) && 
                    resLoc.getPath().equals(location.getPath())) {
                    String content = entry.getValue();
                    return () -> new ByteArrayInputStream(content.getBytes(StandardCharsets.UTF_8));
                }
            }
        }
        
        if (packType == PackType.SERVER_DATA) {
            // Check for data resources (loot tables, recipes)
            for (Map.Entry<ResourceLocation, String> entry : generatedResources.entrySet()) {
                ResourceLocation resLoc = entry.getKey();
                if (resLoc.getNamespace().equals(location.getNamespace()) && 
                    resLoc.getPath().equals(location.getPath())) {
                    String content = entry.getValue();
                    return () -> new ByteArrayInputStream(content.getBytes(StandardCharsets.UTF_8));
                }
            }
        }
        
        return null;
    }
    
    @Override
    public void listResources(PackType packType, String namespace, String path, ResourceOutput resourceOutput) {
        for (ResourceLocation resLoc : generatedResources.keySet()) {
            if (resLoc.getNamespace().equals(namespace) && resLoc.getPath().startsWith(path)) {
                IoSupplier<InputStream> supplier = getResource(packType, resLoc);
                if (supplier != null) {
                    resourceOutput.accept(resLoc, supplier);
                }
            }
        }
    }
    
    @Override
    public Set<String> getNamespaces(PackType type) {
        Set<String> namespaces = new HashSet<>();
        for (ResourceLocation loc : generatedResources.keySet()) {
            namespaces.add(loc.getNamespace());
        }
        return namespaces;
    }
    
    @Nullable
    @Override
    public <T> T getMetadataSection(MetadataSectionSerializer<T> deserializer) {
        return null;
    }
    
    @Override
    public String packId() {
        return "buildscape:vertical_slabs";
    }
    
    @Override
    public void close() {
        // Nothing to close
    }
    
    /**
     * Event handler to register this pack
     */
    @SubscribeEvent
    public static void onAddPackFinders(AddPackFindersEvent event) {
        if (event.getPackType() == PackType.CLIENT_RESOURCES || event.getPackType() == PackType.SERVER_DATA) {
            VerticalSlabResourcePack pack = new VerticalSlabResourcePack();
            pack.generateResources();
            
            event.addRepositorySource((consumer, constructor) -> {
                consumer.accept(constructor.create(
                    "buildscape_vertical_slabs",
                    net.minecraft.network.chat.Component.literal("BuildScape Vertical Slabs"),
                    true,
                    () -> pack,
                    new net.minecraft.server.packs.PackType[] { PackType.CLIENT_RESOURCES, PackType.SERVER_DATA },
                    net.minecraft.server.packs.repository.Pack.Position.TOP,
                    net.minecraft.server.packs.repository.PackSource.BUILT_IN
                ));
            });
            
            BuildScape.LOGGER.info("Registered Vertical Slab Resource Pack");
        }
    }
}

package com.kingodogo.buildscape.world;

import net.minecraft.world.level.GameRules;

import java.lang.reflect.Method;

public class ModGameRules {
    public static GameRules.Key<GameRules.BooleanValue> FAST_LEAF_DECAY;

    public static void register() {
        try {
            // Access the private create method using reflection
            Method createMethod = GameRules.BooleanValue.class.getDeclaredMethod("create", boolean.class);
            createMethod.setAccessible(true);

            // Create the boolean value type with default value false
            GameRules.Type<GameRules.BooleanValue> booleanType =
                    (GameRules.Type<GameRules.BooleanValue>) createMethod.invoke(null, false);

            // Register the gamerule
            FAST_LEAF_DECAY = GameRules.register(
                    "fastLeafDecay",
                    GameRules.Category.UPDATES,
                    booleanType
            );
        } catch (Exception e) {
            throw new RuntimeException("Failed to register fastLeafDecay gamerule", e);
        }
    }
}

