import java.util.function.BiConsumer;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.world.level.LevelSimulatedReader;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecorator;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecoratorType;

public class MangroveLeaveVineDecorator extends TreeDecorator {

    public static final Codec<MangroveLeaveVineDecorator> CODEC =
            RecordCodecBuilder.create(instance ->
                    instance
                            .group(
                                    Codec.floatRange(0.0F, 1.0F)
                                            .fieldOf("probability")
                                            .forGetter(decorator -> decorator.probability)
                            )
                            .apply(instance, MangroveLeaveVineDecorator::new)
            );

    private final float probability;

    public MangroveLeaveVineDecorator(float probability) {
        this.probability = probability;
    }

    @Override
    protected TreeDecoratorType<?> type() {
        return ModTreeDecoratorTypes.MANGROVE_LEAVE_VINE.get();
    }

    @Override
    public void place(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            List<BlockPos> logPositions,
            List<BlockPos> leavesPositions
    ) {
        leavesPositions.forEach(pos -> {
            if (random.nextFloat() < probability) {
                BlockPos belowPos = pos.below();
                if (level.isStateAtPosition(belowPos, BlockState::isAir)) {
                    blockSetter.accept(belowPos, Blocks.VINE.defaultBlockState());
                }
            }
        });
    }
}

package com.kingodogo.buildscape.worldgen;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.function.BiConsumer;

import net.minecraft.core.BlockPos;
import net.minecraft.world.level.LevelSimulatedReader;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecorator;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecoratorType;

public class MangroveMossCarpetDecorator extends TreeDecorator {

    public static final Codec<MangroveMossCarpetDecorator> CODEC =
            RecordCodecBuilder.create(instance ->
                    instance
                            .group(
                                    Codec.floatRange(0.0F, 1.0F)
                                            .fieldOf("probability")
                                            .forGetter(decorator -> decorator.probability)
                            )
                            .apply(instance, MangroveMossCarpetDecorator::new)
            );

    private final float probability;

    public MangroveMossCarpetDecorator(float probability) {
        this.probability = probability;
    }

    @Override
    protected TreeDecoratorType<?> type() {
        return ModTreeDecoratorTypes.MANGROVE_MOSS_CARPET.get();
    }

    @Override
    public void place(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            List<BlockPos> logPositions,
            List<BlockPos> leavesPositions
    ) {
        if (logPositions.isEmpty()) {
            return;
        }

        BlockPos basePos = logPositions
                .stream()
                .min((a, b) -> Integer.compare(a.getY(), b.getY()))
                .orElse(logPositions.get(0));

        Set<BlockPos> checkedPositions = new HashSet<>();
        for (int x = -10; x <= 10; x++) {
            for (int z = -10; z <= 10; z++) {
                for (int y = -5; y <= 5; y++) {
                    BlockPos checkPos = basePos.offset(x, y, z);

                    if (checkedPositions.contains(checkPos)) {
                        continue;
                    }
                    checkedPositions.add(checkPos);

                    boolean isRoot = level.isStateAtPosition(
                            checkPos,
                            state ->
                                    state.is(
                                            com.kingodogo.buildscape.block.ModBlocks.MANGROVE_ROOTS.get()
                                    ) ||
                                            state.is(
                                                    com.kingodogo.buildscape.block.ModBlocks.MUDDY_MANGROVE_ROOTS.get()
                                            )
                    );

                    if (isRoot) {
                        BlockPos abovePos = checkPos.above();

                        if (random.nextFloat() < probability) {
                            if (level.isStateAtPosition(abovePos, state -> state.isAir())) {
                                blockSetter.accept(
                                        abovePos,
                                        com.kingodogo.buildscape.block.ModBlocks.MOSS_OVERLAY.get()
                                                .defaultBlockState()
                                );
                            }
                        }
                    }
                }
            }
        }
    }
}

package com.kingodogo.buildscape.worldgen;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import java.util.List;
import java.util.Random;
import java.util.function.BiConsumer;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.util.valueproviders.IntProvider;
import net.minecraft.world.level.LevelSimulatedReader;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecorator;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecoratorType;

public class MangrovePropaguleDecorator extends TreeDecorator {

    public static final Codec<MangrovePropaguleDecorator> CODEC =
            RecordCodecBuilder.create(instance ->
                    instance
                            .group(
                                    Codec.floatRange(0.0F, 1.0F)
                                            .fieldOf("probability")
                                            .forGetter(decorator -> decorator.probability),
                                    IntProvider.codec(0, 16)
                                            .fieldOf("exclusion_radius_xz")
                                            .forGetter(decorator -> decorator.exclusionRadiusXZ),
                                    IntProvider.codec(0, 16)
                                            .fieldOf("exclusion_radius_y")
                                            .forGetter(decorator -> decorator.exclusionRadiusY),
                                    Codec.intRange(0, 16)
                                            .fieldOf("required_empty_blocks")
                                            .forGetter(decorator -> decorator.requiredEmptyBlocks)
                            )
                            .apply(instance, MangrovePropaguleDecorator::new)
            );

    private final float probability;
    private final IntProvider exclusionRadiusXZ;
    private final IntProvider exclusionRadiusY;
    private final int requiredEmptyBlocks;

    public MangrovePropaguleDecorator(
            float probability,
            IntProvider exclusionRadiusXZ,
            IntProvider exclusionRadiusY,
            int requiredEmptyBlocks
    ) {
        this.probability = probability;
        this.exclusionRadiusXZ = exclusionRadiusXZ;
        this.exclusionRadiusY = exclusionRadiusY;
        this.requiredEmptyBlocks = requiredEmptyBlocks;
    }

    @Override
    protected TreeDecoratorType<?> type() {
        return ModTreeDecoratorTypes.MANGROVE_PROPAGULE.get();
    }

    @Override
    public void place(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            List<BlockPos> logPositions,
            List<BlockPos> leavesPositions
    ) {
        if (leavesPositions.isEmpty()) {
            return;
        }

        int propagulesToPlace = 2 + random.nextInt(3);

        java.util.Collections.shuffle(leavesPositions, random);

        int placed = 0;
        for (BlockPos leafPos : leavesPositions) {
            if (placed >= propagulesToPlace) {
                break;
            }

            BlockPos belowPos = leafPos.below();

            if (
                    level.isStateAtPosition(
                            belowPos,
                            state -> state.isAir() || state.is(Blocks.WATER)
                    )
            ) {
                boolean canPlace = true;
                for (int i = 1; i <= requiredEmptyBlocks; i++) {
                    BlockPos checkPos = belowPos.below(i);
                    if (
                            !level.isStateAtPosition(
                                    checkPos,
                                    state -> state.isAir() || state.is(Blocks.WATER)
                            )
                    ) {
                        canPlace = false;
                        break;
                    }
                }

                if (canPlace) {
                    int age = random.nextInt(5);
                    BlockState propaguleState =
                            com.kingodogo.buildscape.block.ModBlocks.MANGROVE_PROPAGULE.get()
                                    .defaultBlockState()
                                    .setValue(
                                            com.kingodogo.buildscape.block.MangrovePropaguleBlock.AGE,
                                            age
                                    )
                                    .setValue(
                                            com.kingodogo.buildscape.block.MangrovePropaguleBlock.HANGING,
                                            true
                                    );

                    blockSetter.accept(belowPos, propaguleState);
                    placed++;
                }
            }
        }
    }
}

package com.kingodogo.buildscape.worldgen;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import java.util.Random;
import java.util.function.BiConsumer;

import net.minecraft.core.BlockPos;
import net.minecraft.util.valueproviders.IntProvider;
import net.minecraft.world.level.LevelSimulatedReader;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.feature.configurations.TreeConfiguration;
import net.minecraft.world.level.levelgen.feature.foliageplacers.FoliagePlacer;
import net.minecraft.world.level.levelgen.feature.foliageplacers.FoliagePlacerType;

public class MangroveRandomSpreadFoliagePlacer extends FoliagePlacer {

    public static final Codec<MangroveRandomSpreadFoliagePlacer> CODEC =
            RecordCodecBuilder.create(instance ->
                    foliagePlacerParts(instance)
                            .and(
                                    IntProvider.codec(0, 16)
                                            .fieldOf("foliage_height")
                                            .forGetter(placer -> placer.foliageHeight)
                            )
                            .and(
                                    Codec.intRange(0, 512)
                                            .fieldOf("leaf_placement_attempts")
                                            .forGetter(placer -> placer.leafPlacementAttempts)
                            )
                            .apply(instance, MangroveRandomSpreadFoliagePlacer::new)
            );

    private final IntProvider foliageHeight;
    private final int leafPlacementAttempts;

    public MangroveRandomSpreadFoliagePlacer(
            IntProvider radius,
            IntProvider offset,
            IntProvider foliageHeight,
            int leafPlacementAttempts
    ) {
        super(radius, offset);
        this.foliageHeight = foliageHeight;
        this.leafPlacementAttempts = leafPlacementAttempts;
    }

    @Override
    protected FoliagePlacerType<?> type() {
        return ModFoliagePlacerTypes.MANGROVE_RANDOM_SPREAD.get();
    }

    @Override
    protected void createFoliage(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            TreeConfiguration config,
            int maxFreeTreeHeight,
            FoliageAttachment attachment,
            int foliageHeight,
            int foliageRadius,
            int offset
    ) {
        BlockPos centerPos = attachment.pos();
        int actualFoliageHeight = this.foliageHeight.sample(random);

        java.util.Set<BlockPos> placedLeaves = new java.util.HashSet<>();

        for (int attempt = 0; attempt < leafPlacementAttempts; attempt++) {
            double angle1 = random.nextDouble() * 2 * Math.PI;
            double angle2 = random.nextDouble() * Math.PI;
            double radius = foliageRadius * Math.sqrt(random.nextDouble());

            radius += (random.nextDouble() - 0.5) * 0.5;
            radius = Math.max(0, Math.min(radius, foliageRadius + 1));

            int x = (int) (centerPos.getX() +
                    radius * Math.sin(angle2) * Math.cos(angle1));
            int y = (int) (centerPos.getY() +
                    radius *
                            Math.cos(angle2) *
                            (actualFoliageHeight / (double) foliageRadius));
            int z = (int) (centerPos.getZ() +
                    radius * Math.sin(angle2) * Math.sin(angle1));

            y = Math.max(
                    centerPos.getY(),
                    Math.min(centerPos.getY() + actualFoliageHeight - 1, y)
            );

            BlockPos leafPos = new BlockPos(x, y, z);

            if (leafPos.equals(centerPos)) {
                continue;
            }

            if (isConnectedToLogOrLeaf(level, leafPos, placedLeaves, config)) {
                if (level.isStateAtPosition(leafPos, BlockState::isAir)) {
                    blockSetter.accept(
                            leafPos,
                            config.foliageProvider.getState(random, leafPos)
                    );
                    placedLeaves.add(leafPos);
                }
            }
        }

        java.util.List<BlockPos> candidates = new java.util.ArrayList<>();
        for (int yOffset = -1; yOffset < actualFoliageHeight + 1; yOffset++) {
            int currentY = centerPos.getY() + yOffset;
            int searchRadius = foliageRadius + 2;

            for (int xOffset = -searchRadius; xOffset <= searchRadius; xOffset++) {
                for (int zOffset = -searchRadius; zOffset <= searchRadius; zOffset++) {
                    BlockPos leafPos = new BlockPos(
                            centerPos.getX() + xOffset,
                            currentY,
                            centerPos.getZ() + zOffset
                    );

                    if (
                            level.isStateAtPosition(leafPos, BlockState::isAir) &&
                                    !placedLeaves.contains(leafPos)
                    ) {
                        int adjacentLeaves = countAdjacentLeaves(
                                level,
                                leafPos,
                                config,
                                placedLeaves
                        );
                        if (adjacentLeaves >= 4 && random.nextFloat() < 0.6F) {
                            candidates.add(leafPos);
                        }
                    }
                }
            }
        }

        java.util.Collections.shuffle(candidates, random);
        for (BlockPos candidate : candidates) {
            if (isConnectedToLogOrLeaf(level, candidate, placedLeaves, config)) {
                blockSetter.accept(
                        candidate,
                        config.foliageProvider.getState(random, candidate)
                );
                placedLeaves.add(candidate);
            }
        }

        java.util.List<BlockPos> extensionCandidates = new java.util.ArrayList<>(
                placedLeaves
        );
        java.util.Collections.shuffle(extensionCandidates, random);

        for (int i = 0; i < Math.min(extensionCandidates.size() / 4, 20); i++) {
            BlockPos baseLeaf = extensionCandidates.get(i);

            for (int dir = 0; dir < 6; dir++) {
                if (random.nextFloat() < 0.3F) continue;

                BlockPos extensionPos = baseLeaf.relative(
                        net.minecraft.core.Direction.from3DDataValue(dir)
                );

                int distFromCenter = (int) Math.sqrt(
                        (extensionPos.getX() - centerPos.getX()) *
                                (extensionPos.getX() - centerPos.getX()) +
                                (extensionPos.getZ() - centerPos.getZ()) *
                                        (extensionPos.getZ() - centerPos.getZ()) +
                                (extensionPos.getY() - centerPos.getY()) *
                                        (extensionPos.getY() - centerPos.getY())
                );

                if (
                        distFromCenter <= foliageRadius + 2 &&
                                !placedLeaves.contains(extensionPos) &&
                                level.isStateAtPosition(extensionPos, BlockState::isAir) &&
                                isConnectedToLogOrLeaf(level, extensionPos, placedLeaves, config)
                ) {
                    blockSetter.accept(
                            extensionPos,
                            config.foliageProvider.getState(random, extensionPos)
                    );
                    placedLeaves.add(extensionPos);
                    break;
                }
            }
        }
    }

    private boolean isConnectedToLogOrLeaf(
            LevelSimulatedReader level,
            BlockPos pos,
            java.util.Set<BlockPos> placedLeaves,
            TreeConfiguration config
    ) {
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                for (int dz = -1; dz <= 1; dz++) {
                    if (dx == 0 && dy == 0 && dz == 0) continue;

                    BlockPos checkPos = pos.offset(dx, dy, dz);

                    if (
                            level.isStateAtPosition(
                                    checkPos,
                                    state ->
                                            state.is(net.minecraft.tags.BlockTags.LOGS) ||
                                                    state.getBlock() ==
                                                            config.trunkProvider.getState(null, null).getBlock()
                            )
                    ) {
                        return true;
                    }

                    if (placedLeaves.contains(checkPos)) {
                        return true;
                    }

                    if (
                            level.isStateAtPosition(
                                    checkPos,
                                    state ->
                                            state.getBlock() ==
                                                    config.foliageProvider.getState(null, null).getBlock()
                            )
                    ) {
                        return true;
                    }
                }
            }
        }

        for (int dx = -6; dx <= 6; dx++) {
            for (int dy = -6; dy <= 6; dy++) {
                for (int dz = -6; dz <= 6; dz++) {
                    if (dx == 0 && dy == 0 && dz == 0) continue;
                    int distanceSq = dx * dx + dy * dy + dz * dz;
                    if (distanceSq > 36) continue;

                    BlockPos checkPos = pos.offset(dx, dy, dz);
                    if (
                            level.isStateAtPosition(
                                    checkPos,
                                    state ->
                                            state.is(net.minecraft.tags.BlockTags.LOGS) ||
                                                    state.getBlock() ==
                                                            config.trunkProvider.getState(null, null).getBlock()
                            )
                    ) {
                        return true;
                    }
                }
            }
        }

        return false;
    }

    private int countAdjacentLeaves(
            LevelSimulatedReader level,
            BlockPos pos,
            TreeConfiguration config,
            java.util.Set<BlockPos> placedLeaves
    ) {
        int count = 0;
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                for (int dz = -1; dz <= 1; dz++) {
                    if (dx == 0 && dy == 0 && dz == 0) continue;

                    BlockPos checkPos = pos.offset(dx, dy, dz);
                    if (placedLeaves.contains(checkPos)) {
                        count++;
                    } else if (
                            level.isStateAtPosition(
                                    checkPos,
                                    state ->
                                            state.getBlock() ==
                                                    config.foliageProvider.getState(null, null).getBlock()
                            )
                    ) {
                        count++;
                    }
                }
            }
        }
        return count;
    }

    @Override
    protected boolean shouldSkipLocation(
            Random random,
            int baseHeight,
            int x,
            int y,
            int z,
            boolean large
    ) {
        if (x == 0 && z == 0) {
            return y == 0;
        }
        return false;
    }

    @Override
    public int foliageHeight(
            Random random,
            int height,
            TreeConfiguration config
    ) {
        return this.foliageHeight.sample(random);
    }
}

package com.kingodogo.buildscape.worldgen;

import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;

import java.util.*;
import java.util.function.BiConsumer;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.util.valueproviders.ConstantInt;
import net.minecraft.util.valueproviders.IntProvider;
import net.minecraft.world.level.LevelSimulatedReader;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecorator;
import net.minecraft.world.level.levelgen.feature.treedecorators.TreeDecoratorType;

public class MangroveRootDecorator extends TreeDecorator {

    public static final Codec<MangroveRootDecorator> CODEC =
            RecordCodecBuilder.create(instance ->
                    instance
                            .group(
                                    IntProvider.codec(1, 16)
                                            .fieldOf("max_root_width")
                                            .forGetter(decorator -> decorator.maxRootWidth),
                                    IntProvider.codec(1, 16)
                                            .fieldOf("max_root_length")
                                            .forGetter(decorator -> decorator.maxRootLength),
                                    Codec.floatRange(0.0F, 1.0F)
                                            .fieldOf("random_skew_chance")
                                            .forGetter(decorator -> decorator.randomSkewChance),
                                    IntProvider.codec(0, 16)
                                            .optionalFieldOf("trunk_offset_y", ConstantInt.of(0))
                                            .forGetter(decorator -> decorator.trunkOffsetY)
                            )
                            .apply(instance, MangroveRootDecorator::new)
            );

    private final IntProvider maxRootWidth;
    private final IntProvider maxRootLength;
    private final float randomSkewChance;
    private final IntProvider trunkOffsetY;

    public MangroveRootDecorator(
            IntProvider maxRootWidth,
            IntProvider maxRootLength,
            float randomSkewChance
    ) {
        this(maxRootWidth, maxRootLength, randomSkewChance, ConstantInt.of(0));
    }

    public MangroveRootDecorator(
            IntProvider maxRootWidth,
            IntProvider maxRootLength,
            float randomSkewChance,
            IntProvider trunkOffsetY
    ) {
        this.maxRootWidth = maxRootWidth;
        this.maxRootLength = maxRootLength;
        this.randomSkewChance = randomSkewChance;
        this.trunkOffsetY = trunkOffsetY;
    }

    @Override
    protected TreeDecoratorType<?> type() {
        return ModTreeDecoratorTypes.MANGROVE_ROOT.get();
    }

    @Override
    public void place(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            List<BlockPos> logPositions,
            List<BlockPos> leavesPositions
    ) {
        if (logPositions.isEmpty()) {
            return;
        }

        BlockPos basePos = logPositions
                .stream()
                .min((a, b) -> Integer.compare(a.getY(), b.getY()))
                .orElse(logPositions.get(0));

        int logBaseLevel = basePos.getY();

        int groundLevel = findGroundLevel(level, basePos);

        int rootStartLevel = logBaseLevel;

        Direction[] cardinalDirections = {
                Direction.NORTH,
                Direction.SOUTH,
                Direction.EAST,
                Direction.WEST,
        };

        for (Direction direction : cardinalDirections) {
            int horizontalDistance = 2 + random.nextInt(4);

            List<BlockPos> horizontalRoots = new ArrayList<>();
            for (int i = 1; i <= horizontalDistance; i++) {
                BlockPos rootPos = new BlockPos(
                        basePos.getX() + direction.getStepX() * i,
                        rootStartLevel,
                        basePos.getZ() + direction.getStepZ() * i
                );
                horizontalRoots.add(rootPos);
            }

            if (horizontalRoots.isEmpty()) {
                continue;
            }

            for (BlockPos horizontalPos : horizontalRoots) {
                placeRootBlock(level, blockSetter, random, horizontalPos);
            }

            BlockPos lastPos = horizontalRoots.get(horizontalRoots.size() - 1);
            int downDepth = lastPos.getY() - groundLevel;

            if (downDepth > 0) {
                for (int y = 1; y <= downDepth; y++) {
                    BlockPos rootPos = lastPos.below(y);
                    placeRootBlock(level, blockSetter, random, rootPos);
                }
            }

            if (
                    horizontalRoots.size() >= 2 && random.nextFloat() < randomSkewChance
            ) {
                BlockPos secondLastPos = horizontalRoots.get(
                        horizontalRoots.size() - 2
                );
                int secondDownDepth = Math.min(
                        2 + random.nextInt(2),
                        secondLastPos.getY() - groundLevel
                );

                if (secondDownDepth > 0) {
                    for (int y = 1; y <= secondDownDepth; y++) {
                        BlockPos rootPos = secondLastPos.below(y);
                        placeRootBlock(level, blockSetter, random, rootPos);
                    }
                }
            }
        }
    }

    private int findGroundLevel(LevelSimulatedReader level, BlockPos startPos) {
        BlockPos.MutableBlockPos checkPos = startPos.mutable();
        int minY = -64;

        while (checkPos.getY() > minY) {
            final BlockPos.MutableBlockPos finalCheckPos = checkPos.mutable();
            boolean isTerrain = level.isStateAtPosition(finalCheckPos, state -> {
                if (state.isAir() || state.is(Blocks.WATER)) {
                    return false;
                }
                boolean isTerrainBlock =
                        state.is(Blocks.DIRT) ||
                                state.is(Blocks.GRASS_BLOCK) ||
                                state.is(Blocks.STONE) ||
                                state.is(Blocks.SAND) ||
                                state.is(Blocks.GRAVEL) ||
                                state.is(Blocks.CLAY);
                boolean isTreeBlock =
                        state.is(net.minecraft.tags.BlockTags.LOGS) ||
                                state.is(
                                        com.kingodogo.buildscape.block.ModBlocks.MANGROVE_ROOTS.get()
                                ) ||
                                state.is(
                                        com.kingodogo.buildscape.block.ModBlocks.MUDDY_MANGROVE_ROOTS.get()
                                );
                return (
                        isTerrainBlock &&
                                !isTreeBlock &&
                                state.getMaterial().isSolid() &&
                                !state.getMaterial().isReplaceable()
                );
            });

            if (isTerrain) {
                return finalCheckPos.getY();
            }
            checkPos.move(Direction.DOWN);
        }

        return Math.max(startPos.getY() - 3, minY);
    }

    private void placeRootBlock(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            BlockPos rootPos
    ) {
        boolean canPlace = level.isStateAtPosition(rootPos, state -> {
            if (state.is(net.minecraft.tags.BlockTags.LOGS)) {
                return false;
            }
            if (
                    state.is(
                            com.kingodogo.buildscape.block.ModBlocks.MANGROVE_ROOTS.get()
                    ) ||
                            state.is(
                                    com.kingodogo.buildscape.block.ModBlocks.MUDDY_MANGROVE_ROOTS.get()
                            )
            ) {
                return true;
            }
            return state.isAir() || state.is(Blocks.WATER);
        });

        if (!canPlace) {
            return;
        }

        BlockState rootState =
                com.kingodogo.buildscape.block.ModBlocks.MANGROVE_ROOTS.get()
                        .defaultBlockState()
                        .setValue(
                                net.minecraft.world.level.block.RotatedPillarBlock.AXIS,
                                net.minecraft.core.Direction.Axis.Y
                        );

        blockSetter.accept(rootPos, rootState);
    }
}

package com.kingodogo.buildscape.worldgen;

import com.google.common.collect.Lists;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.util.valueproviders.IntProvider;
import net.minecraft.world.level.LevelSimulatedReader;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.feature.configurations.TreeConfiguration;
import net.minecraft.world.level.levelgen.feature.foliageplacers.FoliagePlacer;
import net.minecraft.world.level.levelgen.feature.trunkplacers.TrunkPlacer;
import net.minecraft.world.level.levelgen.feature.trunkplacers.TrunkPlacerType;

import java.util.List;
import java.util.Random;
import java.util.function.BiConsumer;

public class MangroveUpwardsBranchingTrunkPlacer extends TrunkPlacer {

    public static final Codec<MangroveUpwardsBranchingTrunkPlacer> CODEC =
            RecordCodecBuilder.create(instance ->
                    trunkPlacerParts(instance)
                            .and(
                                    IntProvider.codec(0, 24)
                                            .fieldOf("extra_branch_steps")
                                            .forGetter(placer -> placer.extraBranchSteps)
                            )
                            .and(
                                    Codec.floatRange(0.0F, 1.0F)
                                            .fieldOf("place_branch_per_log_probability")
                                            .forGetter(placer -> placer.placeBranchPerLogProbability)
                            )
                            .and(
                                    IntProvider.codec(0, 24)
                                            .fieldOf("extra_branch_length")
                                            .forGetter(placer -> placer.extraBranchLength)
                            )
                            .apply(instance, MangroveUpwardsBranchingTrunkPlacer::new)
            );

    private final IntProvider extraBranchSteps;
    private final IntProvider extraBranchLength;
    private final float placeBranchPerLogProbability;

    public MangroveUpwardsBranchingTrunkPlacer(
            int baseHeight,
            int heightRandA,
            int heightRandB,
            IntProvider extraBranchSteps,
            float placeBranchPerLogProbability,
            IntProvider extraBranchLength
    ) {
        super(baseHeight, heightRandA, heightRandB);
        this.extraBranchSteps = extraBranchSteps;
        this.placeBranchPerLogProbability = placeBranchPerLogProbability;
        this.extraBranchLength = extraBranchLength;
    }

    @Override
    protected TrunkPlacerType<?> type() {
        return ModTrunkPlacerTypes.MANGROVE_UPWARDS_BRANCHING.get();
    }

    @Override
    public List<FoliagePlacer.FoliageAttachment> placeTrunk(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            int freeTreeHeight,
            BlockPos pos,
            TreeConfiguration config
    ) {
        List<FoliagePlacer.FoliageAttachment> foliageAttachments =
                Lists.newArrayList();
        BlockPos.MutableBlockPos mutablePos = new BlockPos.MutableBlockPos();

        int elevationShift = 2 + random.nextInt(3);
        int elevatedStartY = pos.getY() + elevationShift;

        int trunkHeight = freeTreeHeight;
        int extraHeight = random.nextInt(4);
        trunkHeight += extraHeight;

        for (int i = 0; i < trunkHeight; i++) {
            int y = elevatedStartY + i;
            mutablePos.set(pos.getX(), y, pos.getZ());

            if (this.placeLog(level, blockSetter, random, mutablePos, config)) {
                if (i > 0 && random.nextFloat() < placeBranchPerLogProbability) {
                    this.placeBranch(
                            level,
                            blockSetter,
                            random,
                            mutablePos,
                            config,
                            foliageAttachments
                    );
                }
            }
        }

        foliageAttachments.add(
                new FoliagePlacer.FoliageAttachment(
                        mutablePos.set(pos.getX(), elevatedStartY + trunkHeight, pos.getZ()),
                        0,
                        false
                )
        );

        return foliageAttachments;
    }

    private void placeBranch(
            LevelSimulatedReader level,
            BiConsumer<BlockPos, BlockState> blockSetter,
            Random random,
            BlockPos.MutableBlockPos branchStart,
            TreeConfiguration config,
            List<FoliagePlacer.FoliageAttachment> foliageAttachments
    ) {
        int branchSteps = this.extraBranchSteps.sample(random);
        int branchLength = this.extraBranchLength.sample(random);

        if (branchSteps <= 0 || branchLength <= 0) {
            return;
        }

        Direction[] horizontalDirections = {
                Direction.NORTH,
                Direction.SOUTH,
                Direction.EAST,
                Direction.WEST,
        };
        Direction branchDirection =
                horizontalDirections[random.nextInt(horizontalDirections.length)];

        BlockPos.MutableBlockPos currentPos = branchStart.mutable();
        BlockPos.MutableBlockPos branchEnd = branchStart.mutable();

        for (int i = 0; i < branchLength; i++) {
            branchEnd.move(branchDirection);
            if (this.placeLog(level, blockSetter, random, branchEnd, config)) {
                currentPos.set(branchEnd);
            } else {
                break;
            }
        }

        for (int i = 0; i < branchSteps; i++) {
            branchEnd.move(Direction.UP);
            if (this.placeLog(level, blockSetter, random, branchEnd, config)) {
                currentPos.set(branchEnd);
                foliageAttachments.add(
                        new FoliagePlacer.FoliageAttachment(currentPos.immutable(), 0, false)
                );
            } else {
                break;
            }
        }
    }
}

package com.kingodogo.buildscape.worldgen;

import com.kingodogo.buildscape.BuildScape;
import com.kingodogo.buildscape.block.ModBlocks;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;

import net.minecraft.core.BlockPos;
import net.minecraft.core.Direction;
import net.minecraft.core.Holder;
import net.minecraft.util.valueproviders.ConstantInt;
import net.minecraft.util.valueproviders.UniformInt;
import net.minecraft.world.level.WorldGenLevel;
import net.minecraft.world.level.biome.Biomes;
import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.level.levelgen.GenerationStep;
import net.minecraft.world.level.levelgen.Heightmap;
import net.minecraft.world.level.levelgen.blockpredicates.BlockPredicate;
import net.minecraft.world.level.levelgen.blockpredicates.BlockPredicate;
import net.minecraft.world.level.levelgen.feature.ConfiguredFeature;
import net.minecraft.world.level.levelgen.placement.*;
import net.minecraft.world.level.levelgen.placement.PlacedFeature;
import net.minecraftforge.event.world.BiomeLoadingEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;

@Mod.EventBusSubscriber(
        modid = BuildScape.MODID,
        bus = Mod.EventBusSubscriber.Bus.FORGE
)
public class ModBiomeModifications {

    private static BlockPredicate matchesBlocksBelow(List<Block> blocks) {
        return new BlockPredicate() {
            @Override
            public boolean test(WorldGenLevel level, BlockPos pos) {
                BlockPos belowPos = pos.below();
                BlockState belowState = level.getBlockState(belowPos);
                return blocks.contains(belowState.getBlock());
            }

            @Override
            public net.minecraft.world.level.levelgen.blockpredicates.BlockPredicateType<
                    ?
                    > type() {
                return null;
            }
        };
    }

    private static net.minecraft.world.level.levelgen.blockpredicates.BlockPredicate mossBlockAboveAir() {
        return new net.minecraft.world.level.levelgen.blockpredicates.BlockPredicate() {
            @Override
            public boolean test(
                    net.minecraft.world.level.WorldGenLevel level,
                    net.minecraft.core.BlockPos pos
            ) {
                if (!level.getBlockState(pos).isAir()) {
                    return false;
                }
                BlockPos abovePos = pos.above();
                return level
                        .getBlockState(abovePos)
                        .is(net.minecraft.world.level.block.Blocks.MOSS_BLOCK);
            }

            @Override
            public net.minecraft.world.level.levelgen.blockpredicates.BlockPredicateType<
                    ?
                    > type() {
                return null;
            }
        };
    }

    private static void addFeatureToBiome(
            BiomeLoadingEvent event,
            ConfiguredFeature<?, ?> feature,
            int rarity
    ) {
        if (feature != null) {
            PlacedFeature placed = new PlacedFeature(
                    Holder.direct(feature),
                    List.of(
                            RarityFilter.onAverageOnceEvery(rarity),
                            InSquarePlacement.spread(),
                            HeightmapPlacement.onHeightmap(Heightmap.Types.WORLD_SURFACE_WG),
                            BlockPredicateFilter.forPredicate(
